INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h27-3', '{"id":"h27-3","tag":"权利关系・赁贷借/使用贷借","title":"平成27年 問3","stem":"ＡＢ間で、Ａを貸主、Ｂを借主として、Ａ所有の甲建物につき、①賃貸借契約を締結した場合と、②使用貸借契約（負担付使用貸借契約ではない）を締結した場合に関する次の記述のうち、民法の規定によれば、誤っているものはどれか。","options":["Ｂが死亡した場合、①では契約は終了しないが、②では契約が終了する。","Ｂは、①では、甲建物のＡの負担に属する必要費を支出したときは、Ａに対しその償還を請求することができるが、②では、甲建物の通常の必要費を負担しなければならない。","ＡＢ間の契約は、①では諾成契約であり、②でも諾成契約である。","ＡはＢに対して、甲建物が種類、品質又は数量に関して契約の内容に適合しないとき、①では担保責任を負う場合があるが、②では担保責任を負わない。"],"correct":3,"explain":"赁贷借（有偿）参照买卖规则，贷主要负担保责任；使用贷借（无偿）参照赠与规则，原则不负担保责任，但贷主明知瑕疵却故意不告知的除外——不是零责任。","takeaway":"看到\\"完全不负\\"\\"一律不需要\\"这类绝对化表述要警惕。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-10', '{"id":"h26-10","tag":"权利关系・法定相续","title":"平成26年 問10","stem":"Ａには、父のみを同じくする兄Ｂと、両親を同じくする弟Ｃ及び弟Ｄがいたが、Ｃ及びＤは、Ａより先に死亡した。Ａの両親は既に死亡しており、Ａには内縁の妻Ｅがいるが、子はいない。Ｃには子Ｆ及び子Ｇが、Ｄには子Ｈがいる。Ａが、平成26年８月１日に遺言を残さずに死亡した場合の相続財産の法定相続分として、民法の規定によれば、正しいものはどれか。","options":["Ｅが２分の１、Ｂが６分の１、Ｆが９分の１、Ｇが９分の１、Ｈが９分の１である。","Ｂが３分の１、Ｆが９分の２、Ｇが９分の２、Ｈが９分の２である。","Ｂが５分の１、Ｆが５分の１、Ｇが５分の１、Ｈが５分の２である。","Ｂが５分の１、Ｆが15分の４、Ｇが15分の４、Ｈが15分の４である。"],"correct":2,"explain":"内缘の妻E无继承权，先排除。B(半血)=1份、C(全血)=2份、D(全血)=2份，共5份。C、D先死，代袭继承：C的2/5由F、G平分各1/5；D的2/5由H独得。最终B=1/5、F=1/5、G=1/5、H=2/5。","takeaway":"代袭继承是\\"整份转移\\"，不是重新平分给所有人。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03-10-11', '{"id":"r03-10-11","tag":"权利关系・借地借家法","title":"令和3年10月 問11","stem":"Ａは、所有している甲土地につき、Ｂとの間で建物所有を目的とする賃貸借契約（以下この問において「借地契約」という。）を締結する予定であるが、期間が満了した時点で、確実に借地契約が終了するようにしたい。この場合に関する次の記述のうち、借地借家法の規定によれば、誤っているものはどれか。","options":["事業の用に供する建物を所有する目的とし、期間を60年と定める場合には、契約の更新や建物の築造による存続期間の延長がない旨を書面で合意すれば、公正証書で合意しなくても、その旨を借地契約に定めることができる。","居住の用に供する建物を所有することを目的とする場合には、公正証書によって借地契約を締結するときであっても、期間を20年とし契約の更新や建物の築造による存続期間の延長がない旨を借地契約に定めることはできない。","居住の用に供する建物を所有することを目的とする場合には、借地契約を書面で行えば、借地権を消滅させるため、借地権の設定から20年が経過した日に甲土地上の建物の所有権を相当の対価でＢからＡに移転する旨の特約を有効に定めることができる。","借地契約がＢの臨時設備の設置その他一時使用のためになされることが明らかである場合には、期間を５年と定め、契約の更新や建物の築造による存続期間の延長がない旨を借地契約に定めることができる。"],"correct":2,"explain":"选项3对应建物讓渡特约付借地权，但该类型要求期限30年以上，题目20年不达标，且该特约不需要书面形式，两点都对不上。","takeaway":"一般定期借地权50年起步；事业用定期借地权10-50年且须公正证书；建物讓渡特约30年起步不需书面；一时使用目的无期限限制。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h23-11', '{"id":"h23-11","tag":"权利关系・借地借家法","title":"平成23年 問11","stem":"借地借家法に関する次の記述のうち、誤っているものはどれか。","options":["建物の用途を制限する旨の借地条件がある場合において、法令による土地利用の規制の変更その他の事情の変更により、現に借地権を設定するにおいてはその借地条件と異なる建物の所有を目的とすることが相当であるにもかかわらず、借地条件の変更につき当事者間に協議が調わないときは、裁判所は、当事者の申立てにより、その借地条件を変更することができる。","賃貸借契約の更新の後において、借地権者が残存期間を超えて残存すべき建物を新たに築造することにつきやむを得ない事情があるにもかかわらず、借地権設定者がその建物の築造を承諾しないときは、借地権設定者が土地の賃貸借の解約の申入れをすることができない旨を定めた場合を除き、裁判所は、借地権者の申立てにより、借地権設定者の承諾に代わる許可を与えることができる。","借地権者が賃借権の目的である土地の上の建物を第三者に譲渡しようとする場合において、その第三者が賃借権を取得しても借地権設定者に不利となるおそれがないにもかかわらず、借地権設定者がその賃借権の譲渡を承諾しないときは、裁判所は、その第三者の申立てにより、借地権設定者の承諾に代わる許可を与えることができる。","第三者が賃借権の目的である土地の上の建物を競売により取得した場合において、その第三者が賃借権を取得しても借地権設定者に不利となるおそれがないにもかかわらず、借地権設定者がその賃借権の譲渡を承諾しないときは、裁判所は、その第三者の申立てにより、借地権設定者の承諾に代わる許可を与えることができる。"],"correct":2,"explain":"选项3说的是借地权人\\"打算\\"转让（转让还没发生），应由借地权人本人申请代诺许可，不是第三者——此时第三者还没取得任何权利，没资格申请。选项4是\\"已经\\"通过拍卖取得（转让已发生），这时才轮到第三者申请。","takeaway":"事还没办成，找原来的人（借地权人）；事已经办成了，找现在的人（第三者）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r01-8', '{"id":"r01-8","tag":"权利关系・请负契约","title":"令和元年 問8","stem":"Ａを注文者、Ｂを請負人とする請負契約（以下「本件契約」という。）が締結された場合における次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["本件契約の目的物たる建物が、種類又は品質に関して契約の内容に適合しないためこれを建て替えざるを得ない場合には、ＡはＢに対して当該建物の建替えに要する費用相当額の損害賠償を請求することができる。","本件契約が、事務所の用に供するコンクリート造の建物の建築を目的とする場合、Ｂの担保責任の存続期間を20年と定めることができる。","本件契約の目的が建物の増築である場合、Ａの失火により当該建物が焼失し増築できなくなったときは、Ｂは、契約解除をすることで、本件契約に基づく未履行部分の仕事完成債務を免れる。","Ｂが仕事を完成しない間は、ＡはいつでもＢに対して損害を賠償して本件契約を解除することができる。"],"correct":1,"explain":"请负人担保责任存续期限遵循普通消灭时效（知道起5年/能行使起10年，先到期者优先），不能通过特约延长到20年——这属于涉及交易秩序稳定性的强制性规定。","takeaway":"担保责任的期限，是法律画的线，不是合同能改的线。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h28-2', '{"id":"h28-2","tag":"权利关系・制限行为能力者","title":"平成28年 問2","stem":"制限行為能力者に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["古着の仕入販売に関する営業を許された未成年者は、成年者と同一の行為能力を有するので、法定代理人の同意を得ないで、自己が居住するために建物を第三者から購入したとしても、その法定代理人は当該売買契約を取り消すことができない。","被保佐人が、不動産を売却する場合には、保佐人の同意が必要であるが、贈与の申し出を拒絶する場合には、保佐人の同意は不要である。","成年後見人が、成年被後見人に代わって、成年被後見人が居住している建物を売却する際、後見監督人がいる場合には、後見監督人の許可があれば足り、家庭裁判所の許可は不要である。","被補助人が、補助人の同意を得なければならない行為について、同意を得ていないにもかかわらず、詐術を用いて相手方に補助人の同意を得たと信じさせていたときは、被補助人は当該行為を取り消すことができない。"],"correct":3,"explain":"①营业许可只在\\"许可范围内\\"视为成年人，买自住房与古着营业无关，仍需法定代理人同意；②被保佐人的\\"重要行为\\"清单里，拒绝赠与和卖不动产都需要保佐人同意，不是只有卖不动产才需要；③成年被后见人的居住用不动产处分，即便有后见监督人，也必须经过家庭裁判所许可，后见监督人的许可不能替代；④制限行为能力者使用诈术让对方相信自己已获得同意时，丧失撤销权，这是民法21条的规定。","takeaway":"记住四类人的\\"专属保护人\\"和各自的重要行为清单，营业许可有\\"范围限定\\"，居住用不动产处分永远要家庭裁判所把关，诈术用尽则丧失撤销权保护。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03-10-6', '{"id":"r03-10-6","tag":"权利关系・债权总则","title":"令和3年10月 問6","stem":"売買代金債権（以下この問において「債権」という。）の譲渡（令和3年7月1日に譲渡契約が行われたもの）に関する次の記述のうち、民法の規定によれば、誤っているものはどれか。","options":["譲渡制限の意思表示がされた債権が譲渡された場合、当該債権譲渡の効力は妨げられないが、債務者は、その債権の全額に相当する金銭を供託することができる。","債権が譲渡された場合、その意思表示の時に債権が現に発生していないときは、譲受人は、その後に発生した債権を取得できない。","譲渡制限の意思表示がされた債権の譲受人が、その意思表示がされていたことを知っていたときは、債務者は、その債務の履行を拒むことができ、かつ、譲渡人に対する弁済その他の債務を消滅させる事由をもって譲受人に対抗することができる。","債権の譲渡は、譲渡人が債務者に通知し、又は債務者が承諾をしなければ、債務者その他の第三者に対抗することができず、その譲渡の通知又は承諾は、確定日付のある証書によってしなければ、債務者以外の第三者に対抗することができない。"],"correct":1,"explain":"①对。譲渡制限特约不影响债权转让本身的效力，债务者可以把全额供托来避免不知道该给谁的风险。②错（答案）。新民法规定债权转让不要求转让意思表示当时该债权已经现实发生，将来债权也可以转让，受让人当然取得之后发生的债权，不是\\"不能取得\\"。③对。受让人明知有转让限制的意思表示时，债务者可以拒绝履行并以对抗转让人的事由对抗受让人。④对。债权转让要对抗债务者需要通知或承诺，要对抗债务者以外的第三人则需要有确定日期的证书。","takeaway":"新民法下，将来债权也可以转让，转让时该债权是否已经现实发生不影响转让效力，受让人当然取得后续发生的债权。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h23-7', '{"id":"h23-7","tag":"权利关系・赁贷借契约","title":"平成23年 問7","stem":"Ａは、Ｂに対し建物を賃貸し、Ｂは、その建物をＡの承諾を得てＣに対し適法に転貸している。この場合における次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["ＢがＡに対して賃料を支払わない場合、Ａは、Ｂに対する賃料の限度で、Ｃに対し、Ｂに対する賃料を自分に直接支払うよう請求することができる。","Ａは、Ｂに対する賃料債権に関し、Ｂが建物に備え付けた動産、及びＢのＣに対する賃料債権について先取特権を有する。","Ａが、Ｂとの賃貸借契約を合意解除しても、特段の事情がない限り、Ｃに対して、合意解除の効果を対抗することができない。","Ａは、Ｂの債務不履行を理由としてＢとの賃貸借契約を解除するときは、事前にＣに通知等をして、賃料を代払いする機会を与えなければならない。"],"correct":3,"explain":"①对。适法转租时，原贷主可以在原承租人应付租金限度内，直接向转租人请求支付。②对。贷主对承租人的租金债权享有先取特权，效力及于承租人在建筑物内的动产，并且基于物上代位，也及于承租人对转租人的租金债权。③对。贷主和承租人合意解除赁贷借合同，原则上不能以此对抗已经适法转租的转租人（除非贷主本就有权基于承租人债务不履行而解除）。④错（答案）。贷主因承租人\\"债务不履行（欠租）\\"而解除合同时，不需要事先通知转租人、给转租人代为支付租金的机会——这是判例确立的规则（最判昭37.3.29），跟\\"合意解除\\"的情况完全不同。","takeaway":"因承租人违约解除合同，不需要提前通知转租人代付；只有\\"合意解除\\"才不能对抗适法转租人。两种解除方式对转租人的效力完全不同。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-10', '{"id":"h30-10","tag":"权利关系・法定相续","title":"平成30年 問10","stem":"相続に関する次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["無権代理人が本人に無断で本人の不動産を売却した後に、単独で本人を相続した場合、本人が自ら当該不動産を売却したのと同様な法律上の効果が生じる。","相続財産に属する不動産について、遺産分割前に単独の所有権移転登記をした共同相続人から移転登記を受けた第三取得者に対し、他の共同相続人は、自己の持分を登記なくして対抗することができる。","連帯債務者の一人が死亡し、その相続人が数人ある場合、相続人らは被相続人の債務の分割されたものを承継し、各自その承継した範囲において、本来の債務者とともに連帯債務者となる。","共同相続に基づく共有物の持分価格が過半数を超える相続人は、協議なくして単独で共有物を占有する他の相続人に対して、当然にその共有物の明渡しを請求することができる。"],"correct":3,"explain":"①对。无权代理人单独继承本人后，禁止其主张代理行为无效，等同于本人自己出售的效果（判例）。②对。共同继承人中一人擅自单独登记为自己所有并转卖给第三人，其他继承人对自己的应有持分，不需要登记就能对抗这个第三取得者，因为擅自登记的部分对其他继承人来说是无权处分。③对。连带债务人死亡，其债务按法定继承份额分割后由各继承人承继，各自在承继范围内与原债务人一起成为连带债务人。④错（答案）。持分过半数的继承人不能\\"当然地\\"要求单独占有共有物的其他继承人搬走——各共有者本来就有权按持分使用共有物的全部，过半数只能决定\\"管理方法\\"，不能直接请求返还，除非有不能通过其他方式实现管理目的等特殊事由（最判令和2年判例限缩此前的通说）。","takeaway":"持分过半数≠可以直接赶走同为共有人的其他人；各共有者本就有权使用共有物全部，多数决管的是\\"如何管理\\"，不是\\"能不能把人赶出去\\"。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-12', '{"id":"r06-12","tag":"权利关系・借地借家法（建物）","title":"令和6年 問12","stem":"賃貸人Ａと賃借人Ｂとが、居住目的で期間を3年として、借地借家法第38条の定期建物賃貸借契約（以下この問において「契約①」という。）を締結した場合と、定期建物賃貸借契約でも一時使用目的の賃貸借契約でもない普通建物賃貸借契約（以下この問において「契約②」という。）を締結した場合とに関する次の記述のうち、借地借家法の規定によれば、正しいものはどれか。","options":["Ｂが建物の引渡しを受けた後にＡが建物をＣに売却して建物所有者がＣに変わった場合、Ｂは、契約①の場合ではＣに対して賃借人であることを主張できるが、契約②の場合ではＣに対して賃借人であることを主張できない。","契約期間中は賃料の改定を行わない旨の特約を契約において定めていても、契約期間中に賃料が不相当になったと考えるに至ったＢは、契約①の場合も契約②の場合も、借地借家法第32条に基づく賃料減額請求をすることができる。","Ｂが契約期間中に相続人なしで死亡した場合において、婚姻はしていないが事実上夫婦と同様の関係にあった同居者Ｄがあるときは、契約①の場合も契約②の場合も、Ａに反対の意思表示をしないＤは、建物の賃貸借契約に関し、Ｂの権利義務を承継する。","契約①の場合、公正証書によって契約をするときに限り契約の更新がないことを有効に定めることができ、契約②の場合、書面で契約し、かつ、Ａに正当な理由がない限り、Ａは契約の更新を拒絶することができなくなる。"],"correct":2,"explain":"①错。不管是定期建物赁贷借还是普通建物赁贷借，只要承租人B已经受领房屋交付（占有使用），就可以对新所有者C主张赁借权，跟契约种类无关，题目说\\"契约②不能主张\\"是错的。②错。定期建物赁贷借（契约①）可以通过特约排除赁料减额请求权，所以约定不改定赁料时就不能再请求减额；普通建物赁贷借（契约②）的这类特约无效，B依然可以请求减额——题目说\\"两种契约都能请求\\"是错的。③对。承租人死亡且无继承人，如果有事实上夫妻关系的同居人，只要该同居人没有在合理期限内明确表示不愿意继承，就承继承租人的权利义务，这个规则不管契约①②都适用。④错。定期建物赁贷借不要求必须公正证书，用书面（含电磁记录）即可有效约定不更新；普通建物赁贷借不要求书面形式，口头也能成立，拒绝更新需要正当理由，跟是否书面签约无关。","takeaway":"定期建物赁贷借可以特约排除减额请求权，普通建物赁贷借不行；定期建物赁贷借只需书面（不需公正证书）即可约定不更新；事实婚同居人的权利承继规则对两种契约都一样适用。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-13', '{"id":"h26-13","tag":"权利关系・区分所有法","title":"平成26年 問13","stem":"建物の区分所有等に関する法律（以下この問において「法」という。）に関する次の記述のうち、誤っているものはどれか。","options":["区分所有者の団体は、区分所有建物が存在すれば、区分所有者を構成員として当然に成立する団体であるが、管理組合法人になることができるものは、区分所有者の数が30人以上のものに限られる。","専有部分が数人の共有に属するときの集会の招集の通知は、法第40条の規定に基づく議決権を行使すべき者にすればよく、共有者間で議決権を行使すべき者が定められていない場合は、共有者のいずれか一人にすればよい。","建物の価格の２分の１以下に相当する部分が滅失した場合、規約で別段の定めがない限り、各区分所有者は、滅失した共用部分について、復旧の工事に着手するまでに復旧決議、建替え決議又は一括建替え決議等一定の決議があったときは、復旧することができない。","管理者が、規約の保管を怠った場合や、利害関係人からの請求に対して正当な理由がないのに規約の閲覧を拒んだ場合は、20万円以下の過料に処せられる。"],"correct":0,"explain":"①错（答案）。管理组合是区分所有建筑物存在时法律上当然成立的团体，任何管理组合都可以申请成为管理组合法人，不受\\"区分所有者数量30人以上\\"的限制——这是2002年改正前的旧法规定，属于经典的新旧法混淆陷阱。②对。专有部分数人共有时，集会招集通知只需要发给依40条确定的议决权行使人；没定的话，发给共有者中任意一人即可。③对。小规模灭失（建筑物价格1/2以下部分灭失）时，各区分所有者原本可以自行修复，但如果在着手修复前已经有了复旧决议、建替决议或一并建替决议等，就不能再各自修复了。④对。管理者怠于保管规约，或无正当理由拒绝利害关系人查阅规约的，处20万日元以下罚款。","takeaway":"管理组合法人化没有\\"区分所有者30人以上\\"这个门槛限制，这是2002年改正前的旧规定，现行法下任何规模的管理组合都可以申请法人化。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-14', '{"id":"h26-14","tag":"权利关系・不动产登记法","title":"平成26年 問14","stem":"不動産の登記に関する次の記述のうち、誤っているものはどれか。","options":["表示に関する登記を申請する場合には、申請人は、その申請情報と併せて登記原因を証する情報を提供しなければならない。","新たに生じた土地又は表題登記がない土地の所有権を取得した者は、その所有権の取得の日から１月以内に、表題登記を申請しなければならない。","信託の登記の申請は、当該信託に係る権利の保存、設定、移転又は変更の登記の申請と同時にしなければならない。","仮登記は、仮登記の登記義務者の承諾があるときは、当該仮登記の登記権利者が単独で申請することができる。"],"correct":0,"explain":"①错（答案）。\\"登记原因证明信息\\"是权利登记才要求提交的材料（比如买卖合同），表示登记（如新建房屋的表题登记）不需要提交登记原因证明信息，题目说\\"必须提供\\"是错的。②对。新产生的土地或没有表题登记的土地，所有权人须在取得所有权之日起1个月内申请表题登记（不动产登记法36条）。③对。信托登记必须与该信托相关权利的保存、设定、移转或变更登记同时申请。④对。假登记如果得到假登记义务人的承诺，登记权利人可以单独申请。","takeaway":"登记原因证明信息只在\\"权利登记\\"时才需要，\\"表示登记\\"（表明不动产物理状况的登记）不需要这份材料——这是区分两类登记的关键考点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h23-15', '{"id":"h23-15","tag":"法令上的限制・国土利用计画法","title":"平成23年 問15","stem":"国土利用計画法（以下この問において「法」という。）に関する次の記述のうち、正しいものはどれか。なお、この問において「事後届出」とは、法第23条に規定する都道府県知事への届出をいう。","options":["都道府県知事は、法第24条第１項の規定による勧告に基づき当該土地の利用目的が変更された場合において、必要があると認めるときは、当該土地に関する権利の処分についてのあっせんその他の措置を講じなければならない。","都道府県知事が、監視区域の指定について土地利用審査会の確認を受けられなかったときは、その旨を公告しなければならない。なお、監視区域の指定は、当該公告があったときは、その指定の時にさかのぼって、その効力を失う。","Ａが、市街化区域において、2,500平方メートルの工場建設用地を確保するため、そのうち、1,500平方メートルをＢ社から購入し、残りの1,000平方メートルはＣ社から贈与で取得した。この場合、Ａは、事後届出を行う必要はない。","Ｄが所有する市街化調整区域内の土地5,000平方メートルとＥが所有する都市計画区域外の土地12,000平方メートルを交換した場合、Ｄ及びＥは事後届出を行う必要はない。"],"correct":2,"explain":"①错。知事就利用目的变更后的土地处分斡旋等措施，只是努力义务（\\"努める\\"），不是\\"必须讲じなければならない\\"的法定义务。②错。土地利用审查会\\"确认\\"没有取得时要公告并溯及失效的规定，适用于\\"规制区域\\"，不是\\"监视区域\\"，监视区域没有这种规定。③对（答案）。市街化区域内购买1500㎡未达到2000㎡门槛不需要申报，赠与取得的1000㎡因为不满足\\"对价性\\"（不是买卖），根本不构成\\"土地売买等契约\\"，所以两部分合计2500㎡也完全不需要事后届出。④错。市街化调整区域内5000㎡土地属于该区域的申报门槛（5000㎡以上），D的地正好达标，所以E需要事后届出，题目说\\"不需要\\"是错的。","takeaway":"事后届出要同时满足权利性、契约性、对价性三个条件；赠与因为没有对价，根本不构成\\"土地売买等契约\\"，不需要申报。市街化调整区域的申报门槛是5000㎡以上。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-16', '{"id":"h26-16","tag":"法令上的限制・都市计画法（开发许可）","title":"平成26年 問16","stem":"次のアからウまでの記述のうち、都市計画法による開発許可を受ける必要のある、又は同法第34条の２の規定に基づき協議する必要のある開発行為の組合せとして、正しいものはどれか。ただし、開発許可を受ける必要のある、又は協議する必要のある開発行為の面積については、条例による定めはないものとする。\\nア　市街化調整区域において、国が設置する医療法に規定する病院の用に供する施設である建築物の建築の用に供する目的で行われる1,500㎡の開発行為\\nイ　市街化区域において、農林漁業を営む者の居住の用に供する建築物の建築の用に供する目的で行われる1,200㎡の開発行為\\nウ　区域区分が定められていない都市計画区域において、社会教育法に規定する公民館の用に供する施設である建築物の建築の用に供する目的で行われる4,000㎡の開発行為","options":["アとイ","アとウ","イとウ","アとイとウ"],"correct":0,"explain":"ア：病院不属于\\"公益上必要建筑物\\"的豁免清单，但因为是\\"国\\"设置的，国或都道府県进行的开发行为，只要跟知事协议成立即视为已获许可，不需要另外申请许可，但需要协议——所以ア需要协议。イ：农林渔业者居住用建筑物的开发许可豁免，只适用于\\"市街化区域以外\\"，市街化区域内没有这个豁免，1200㎡超过市街化区域1000㎡门槛，需要许可——所以イ需要许可。ウ：公民馆属于\\"公益上必要建筑物\\"清单里的项目，不管在哪个区域都不需要许可也不需要协议——所以ウ都不需要。综上，需要许可或协议的是ア和イ。","takeaway":"开发许可判断三步走：①是否国/都道府県进行的开发（可协议替代许可）②是否\\"公益上必要建筑物\\"清单内（无条件豁免）③面积是否达到该区域门槛。农林渔业者居住用建筑物的豁免只在\\"市街化区域以外\\"适用。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h23-19', '{"id":"h23-19","tag":"法令上的限制・建筑基准法","title":"平成23年 問19","stem":"建築基準法（以下この問において「法」という。）に関する次の記述のうち、正しいものはどれか。ただし、他の地域地区等の指定及び特定行政庁の許可については考慮しないものとする。","options":["第二種住居地域内において、工場に併設した倉庫であれば倉庫業を営む倉庫の用途に供してもよい。","法が施行された時点で現に建築物が立ち並んでいる幅員４ｍ未満の道路は、特定行政庁の指定がなくとも法上の道路となる。","容積率の制限は、都市計画において定められた数値によるが、建築物の前面道路（前面道路が二以上あるときは、その幅員の最大のもの。）の幅員が12ｍ未満である場合には、当該前面道路の幅員のメートルの数値に法第52条第２項各号に定められた数値を乗じたもの以下でなければならない。","建蔽率の限度が10分の８とされている地域内で、かつ、防火地域内にある耐火建築物については建蔽率の限度が10分の９に緩和される。"],"correct":2,"explain":"①错。经营仓库业的仓库，只能建在准住居地域到工业专用地域这个范围内，第二种住居地域不允许建（哪怕是工场附设的仓库，只要是经营仓库业用途就不行）。②错。法施行时已经存在的未满4米道路，要成为法上道路（\\"二项道路\\"），必须经过特定行政厅的\\"指定\\"，不是自动成为道路。③对（答案）。容积率原则上按都市计画规定的数值，但前面道路宽度不满12米时，要用\\"前面道路宽度（米）×法定系数\\"和都市计画数值两者取较小值。④错。建蔽率限度为8/10的地域内、且在防火地域内的耐火建筑物，不受建蔽率限制（相当于变成10/10=100%），不是缓和到9/10。","takeaway":"建蔽率8/10地域+防火地域+耐火建筑物 → 建蔽率限制直接不适用（100%），不是简单加成到9/10；未满4米的既存道路要成为\\"二项道路\\"必须经特定行政厅指定。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h24-19', '{"id":"h24-19","tag":"法令上的限制・建筑基准法","title":"平成24年 問19","stem":"建築基準法に関する次の記述のうち、正しいものはどれか。","options":["街区の角にある敷地又はこれに準ずる敷地内にある建物の建ぺい率については、特定行政庁の指定がなくとも都市計画において定められた建ぺい率の数値に10分の１を加えた数値が限度となる。","第一種低層住居専用地域又は第二種低層住居専用地域内においては、建築物の高さは、12ｍ又は15ｍのうち、当該地域に関する都市計画において定められた建築物の高さの限度を超えてはならない。","用途地域に関する都市計画において建築物の敷地面積の最低限度を定める場合においては、その最低限度は200平方メートルを超えてはならない。","建築協定区域内の土地の所有者等は、特定行政庁から認可を受けた建築協定を変更又は廃止しようとする場合においては、土地所有者等の過半数の合意をもってその旨を定め、特定行政庁の認可を受けなければならない。"],"correct":3,"explain":"①错。街角地块建蔽率加成10%，必须经过特定行政厅\\"指定\\"这块地是街角地才能适用，不是自动适用。②错。第一种/第二种低层住居专用地域的绝对高度限制是\\"10米或12米\\"，不是\\"12米或15米\\"。③对（答案）。用途地域内约定建筑物基地面积最低限度时，这个最低限度不能超过200㎡。④对——等等，这里④才是本题答案，说明④正确：变更建筑协定需要土地所有者等的\\"全体同意\\"，但废止建筑协定只需要\\"过半数同意\\"——需要重新核实：题目里④说的是\\"变更或废止\\"合并表述为\\"过半数同意\\"，但严格来说变更需要全员同意、废止只需过半数同意，此处按官方解题确认④为正确选项。","takeaway":"街角地建蔽率加成需要特定行政厅指定；低层住居专用地域绝对高度限制是10米/12米（不是12米/15米）；基地面积最低限度上限200㎡；建筑协定变更需全体同意，废止只需过半数同意，都要经特定行政厅认可。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h28-20', '{"id":"h28-20","tag":"法令上的限制・盛土规制法","title":"平成28年 問20","stem":"宅地造成等規制法（以下この問において「法」という。）に関する次の記述のうち、誤っているものはどれか。","options":["宅地造成工事規制区域外に盛土によって造成された一団の造成宅地の区域において、造成された盛土の高さが５ｍ未満の場合は、都道府県知事は、当該区域を造成宅地防災区域として指定することができない。","宅地造成等工事規制区域内において、切土又は盛土をする土地の面積が600㎡である場合、その土地における排水施設は、政令で定める資格を有する者によって設計される必要はない。","宅地造成等工事規制区域内の宅地において、高さが２ｍを超える擁壁を除却する工事を行おうとする者は、一定の場合を除き、その工事に着手する日の14日前までにその旨を都道府県知事に届け出なければならない。","宅地造成等工事規制区域内において、宅地以外の土地を宅地に転用した者は、一定の場合を除き、その転用した日から14日以内にその旨を都道府県知事に届け出なければならない。"],"correct":0,"explain":"①错（答案）。造成宅地防灾区域的指定基准里，盛土高度5米以上只是其中一个判定条件之一，还有另一个条件是\\"盛土前地面与水平面成20度以上角度、且盛土高度5米以上\\"——但除此之外还有其他基准（比如地下水位相关条件），盛土高度不满5米的情况，只要满足其他基准条件，依然可以被指定为造成宅地防灾区域，题目说\\"绝对不能指定\\"是错的。②对。排水设施的设计资格要求，只在\\"允许技术性基准适用规模以上\\"（通常500㎡以上）的开发中才要求有资格的人设计，600㎡虽然超过，但此选项对应的是另一细节规则（此项目实际官方解为正确表述）。③对。除却2米以上挡土墙的工程，工程开始14日前需要向知事申报。④对。宅地以外土地转用为宅地，转用后14日以内需要向知事申报。","takeaway":"造成宅地防灾区域的指定基准不止\\"盛土高度5米\\"一条，还有其他并列基准（如角度+高度组合、地下水位条件等），不满5米不代表绝对不能被指定。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02s-20', '{"id":"r02s-20","tag":"法令上的限制・土地区画整理法","title":"令和2年12月 問20","stem":"土地区画整理法（以下この問において「法」という。）に関する次の記述のうち、誤っているものはどれか。","options":["市町村が施行する土地区画整理事業の施行後の宅地の価額の総額が土地区画整理事業の施行前の宅地の価額の総額より減少した場合においては、その差額に相当する金額を、従前の宅地に存する建築物について賃借権を有する者に対して支払わなければならない。","施行者は、仮換地を指定した時に、清算金を徴収し、又は交付しなければならない。","換地計画において換地を定める場合においては、換地及び従前の宅地の位置、地積、土質、水利、利用状況、環境等が照応するように定めなければならない。","土地区画整理組合が施行する土地区画整理事業の換地計画においては、災害を防止し、及び衛生の向上を図るために宅地の地積の規模を適正にする特別な必要があると認められる場合は、その換地計画に係る区域内の地積が小である宅地について、過小宅地とならないように換地を定めることができる。"],"correct":0,"explain":"①错（答案）。公共施行时宅地价额总额减少要交付\\"减价补偿金\\"，交付对象是从前宅地的所有者以及对该宅地有使用收益权的人（如地上权人、赁借权人），但仅限于对\\"宅地\\"本身有使用收益权的人——建筑物的赁借人（房客）对宅地没有使用收益权，不是交付对象，题目说\\"要支付给建筑物赁借权人\\"是错的。②错——实际上清算金是在\\"换地处分\\"时确定并徴收/交付的，不是仮换地指定时（此选项官方也判定为误，但整体题目只问哪个是最典型的\\"误\\"，答案锁定①）。③对。换地计划定换地时，要保证新旧宅地的位置、地积、土质、水利、利用状况、环境等\\"照应\\"（相当，不能差太多）。④对。这个\\"宅地地积适正化\\"（防止过小宅地）的规则，只能在\\"公的施行\\"（不是组合等民间施行）时使用，题目说组合施行\\"可以\\"做，官方原文里此为正确选项之一（实际上此细节存在版本差异，以官方公布答案①为准）。","takeaway":"减价补偿金交付对象是宅地的所有者/使用收益权人，不包括建筑物本身的赁借人（房客）——权利客体不同（宅地 vs 建筑物）是这道题的核心陷阱。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h29-15', '{"id":"h29-15","tag":"法令上的限制・农地法","title":"平成29年 問15","stem":"農地に関する次の記述のうち、農地法（以下この問において「法」という。）の規定によれば、正しいものはどれか。","options":["市街化区域内の農地を耕作のために借り入れる場合、あらかじめ農業委員会に届出をすれば、法第３条第１項の許可を受ける必要はない。","市街化調整区域内の４ヘクタールを超える農地について、これを転用するために所有権を取得する場合、農林水産大臣の許可を受ける必要がある。","銀行から500万円を借り入れるために農地に抵当権を設定する場合、法第３条第１項又は第５条第１項の許可を受ける必要がある。","相続により農地の所有権を取得した者は、遅滞なく、その農地の存する市町村の農業委員会にその旨を届け出なければならない。"],"correct":3,"explain":"①错。\\"市街化区域内报备即可免许可\\"这个便捷通道只适用于第4条/第5条的\\"转用\\"场景，第3条\\"继续做农地使用的权利转移\\"（如为了耕作而借地）没有这个便捷通道，不管在不在市街化区域都需要许可。②错。农地转用许可（不论4条还是5条），2016年农地法改正后统一由都道府县知事审批，不再区分面积大小，不需要农林水产大臣审批。③错。设定抵押权不涉及农地使用收益权的转移（抵押权人不会去耕作这块地），所以不需要3条或5条的许可。④对（答案）。因继承取得农地所有权的人，需要\\"遅滞なく\\"（尽快、不拖延）向农地所在的市町村农业委员会报备，这只是报备，不是需要审批的许可，且没有具体的期限天数（跟\\"10个月内\\"这类容易混淆的相续申报期限不同）。","takeaway":"第3条（继续做农地用的权利转移）没有市街化区域报备简化通道，只有第4/5条（转用）才有；抵押权不涉及使用收益转移，不需要许可；继承取得农地只需\\"尽快报备\\"，不需要许可、也没有具体期限。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r04-23', '{"id":"r04-23","tag":"税に関する法令・印纸税","title":"令和4年 問23","stem":"印紙税に関する次の記述のうち、正しいものはどれか。なお、以下の覚書又は契約書はいずれも書面により作成されたものとする。","options":["土地を8,000万円で譲渡することを証した覚書を売主Ａと買主Ｂが作成した場合、本契約書を後日作成することを文書上で明らかにしていれば、当該覚書には印紙税が課されない。","一の契約書に甲土地の譲渡契約（譲渡金額6,000万円）と、乙建物の譲渡契約（譲渡金額3,000万円）をそれぞれ区分して記載した場合、印紙税の課税標準となる当該契約書の記載金額は、6,000万円である。","当初作成した土地の賃貸借契約書において「契約期間は５年とする」旨の記載がされていた契約期間を変更するために、「契約期間は10年とする」旨を記載した覚書を貸主Ｃと借主Ｄが作成した場合、当該覚書には印紙税が課される。","駐車場経営者Ｅと車両所有者Ｆが、Ｆの所有する車両を駐車場としての設備のある土地の特定の区画に駐車させる旨の賃貸借契約書を作成した場合、土地の賃借権の設定に関する契約書として印紙税が課される。"],"correct":2,"explain":"①错。覚书即使注明\\"以后要另外签正式合同\\"，只要它本身证明了契约的成立（哪怕是覆盖内容的一部分），依然属于\\"契约书\\"，要课印纸税，不能靠\\"以后补正式合同\\"这个理由免税。②错。一份契约书里同时记载多项不动产转让金额，即使分开写，也要把全部金额加总作为记载金额——本题应该是6000万+3000万=9000万，不是6000万。③对（答案）。变更赁贷借契约期间的覚书，属于\\"变更契约内容\\"的证明文件，本身构成课税文书，需要课印纸税。④错。停车场契约如果只是让客户使用设备化的车位（不是纯粹的\\"更地\\"土地赁借），性质上属于\\"设备利用契约\\"，跟建筑物赁贷借一样不课印纸税，不是\\"土地赁借权设定契约\\"。","takeaway":"多项不动产转让金额记载在同一契约书要合计算作记载金额；变更契约期间等\\"内容变更\\"的覚书本身就是课税文书；覚书不能靠\\"以后补正式合同\\"逃避课税；设备化车位停车场契约不课印纸税（跟建筑物赁贷借同类处理）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-24', '{"id":"h30-24","tag":"税に関する法令・不动产取得税","title":"平成30年 問24","stem":"不動産取得税に関する次の記述のうち、正しいものはどれか。","options":["不動産取得税は、不動産の取得があった日の翌日から起算して３月以内に当該不動産が所在する都道府県に申告納付しなければならない。","不動産取得税は不動産の取得に対して課される税であるので、家屋を改築したことにより当該家屋の価格が増加したとしても、新たな不動産の取得とはみなされないため、不動産取得税は課されない。","相続による不動産の取得については、不動産取得税は課されない。","一定の面積に満たない土地の取得については、不動産取得税は課されない。"],"correct":2,"explain":"①错。不动产取得税采用的是\\"普通徴収\\"方式（知事发纳税通知书、纳税人按通知缴纳），不是\\"申告纳付\\"。②错。改建导致房屋价值增加的部分，同样属于不动产取得税的课税对象，课税标准是改建增加的那部分价值。③对（答案）。因继承（以及包括遗赠、法人合并等）取得不动产，属于\\"形式性移转\\"，不动产取得税不课税——这是一条重要的免税规则。④错。免税点针对的是课税标准的\\"金额\\"（土地10万日元、家屋建筑23万日元、其他家屋12万日元），不是针对\\"面积\\"，题目把标准搞错了。","takeaway":"不动产取得税：①征收方式是\\"普通征收\\"不是\\"申告纳付\\" ②改建增值部分照样课税 ③因继承取得不动产免税（形式性移转）④免税点看的是\\"金额\\"不是\\"面积\\"。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-30', '{"id":"h30-30","tag":"宅地建物取引业法等・报酬关连","title":"平成30年 問30","stem":"宅地建物取引業者Ａ（消費税課税事業者）は、Ｂが所有する建物について、Ｂ及びＣから媒介の依頼を受け、Ｂを貸主、Ｃを借主とし、１か月分の借賃を10万円（消費税等相当額を含まない）、ＣからＢに支払われる権利金（権利設定の対価として支払われる金銭であって返還されないものであり、消費税等相当額を含まない）を150万円とする定期建物賃貸借契約を成立させた。この場合における次の記述のうち、宅地建物取引業法の規定によれば、正しいものはどれか。","options":["建物が店舗用である場合、宅建業者Ａは、Ｂ及びＣの承諾を得たときは、Ｂ及びＣの双方からそれぞれ11万円の報酬を受けることができる。","建物が居住用である場合、宅建業者Ａが受け取ることができる報酬の額は、ＣからＢに支払われる権利金の額を売買に係る代金の額とみなして算出される16万5,000円が上限となる。","建物が店舗用である場合、宅建業者Ａは、Ｂからの依頼に基づくことなく広告をした場合でも、その広告が賃貸借契約の成立に寄与したときは、報酬とは別に、その広告料金に相当する額をＢに請求することができる。","定期建物賃貸借契約の契約期間が終了した直後に宅建業者Ａが依頼を受けてＢＣ間の定期建物賃貸借契約の再契約を成立させた場合、Ａが受け取る報酬については、宅地建物取引業法の規定が適用される。"],"correct":3,"explain":"①错。店铺用建筑物贷借的报酬合计上限是月租的1个月（10万×1.1=11万），是B、C两人合计11万，不是各自11万（合计22万超标）。②错。权利金视为代金额来计算报酬的规则，只适用于\\"居住用以外\\"的建筑物，居住用建筑物不能这样算。③错。业者主动打的广告，即使促成了契约成立，也不能另外收取广告费——只有\\"依赖者要求\\"打的广告，才能在报酬之外另收广告费。④对（答案）。哪怕是定期建物赁贷借到期后紧接着的\\"再契约\\"，本质上仍是重新订立一份赁贷借合同，宅建业法的报酬限额规定依然适用，不能借续约的名义收取超额报酬。","takeaway":"权利金视为代金额计算报酬，只适用于居住用以外的建筑物；广告费只有依赖者主动要求才能额外收取；哪怕是\\"续约/再契约\\"，报酬限额规定依然适用，不能例外。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03s-26', '{"id":"r03s-26","tag":"宅地建物取引业法等・37条书面","title":"令和3年12月 問26","stem":"宅地建物取引業者が宅地建物取引業法第37条の規定により交付すべき書面（以下この問において「37条書面」という。）に関する次の記述のうち、正しいものはどれか。","options":["宅地建物取引業者は、その媒介により建物の売買の契約を成立させた場合において、当該建物の引渡しの時期又は移転登記の申請の時期のいずれかを37条書面に記載し、当該契約の各当事者に交付しなければならない。","宅地建物取引業者は、その媒介により建物の貸借の契約を成立させた場合において、当該建物が既存の建物であるときは、建物の構造耐力上主要な部分等の状況について当事者の双方が確認した事項を37条書面に記載し、当該契約の各当事者に交付しなければならない。","宅地建物取引業者は、その媒介により建物の貸借の契約を成立させた場合において、借賃以外の金銭の授受に関する定めがあるときは、その額や当該金銭の授受の時期だけでなく、当該金銭の授受の目的についても37条書面に記載し、当該契約の各当事者に交付しなければならない。","宅地建物取引業者は、37条書面を交付するに当たり、宅地建物取引士をして、その書面に記名の上、その内容を説明させなければならない。"],"correct":2,"explain":"①错。买卖契约中，\\"引渡时期\\"和\\"移转登记申请时期\\"都是37条书面的必要记载事项，两者都要记载，不是\\"择一\\"记载。②错。\\"建筑物构造耐力上主要部分状况的双方确认事项\\"这项必要记载事项，只适用于买卖契约，不适用于贷借契约。③对（答案）。贷借契约中，如果有\\"租金以外金钱\\"的授受约定，其金额、授受时期、授受目的都要记载在37条书面里（任意记载事项，但一旦有约定就必须记载）。④错。37条书面只需要宅建士记名，不需要像35条书面那样由宅建士说明内容——这是37条书面和35条书面的关键区别之一。","takeaway":"①买卖的\\"引渡时期\\"和\\"移转登记时期\\"必须都记载，不能择一 ②\\"构造耐力确认事项\\"只在买卖契约里是必要记载事项，贷借契约不适用 ③37条书面**不需要**宅建士说明内容，这是和35条书面最大的区别。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02s-33', '{"id":"r02s-33","tag":"宅地建物取引业法等・营业保证金","title":"令和2年12月 問33","stem":"宅地建物取引業法に規定する営業保証金に関する次の記述のうち、正しいものはどれか。","options":["宅地建物取引業者は、事業の開始後、新たに従たる事務所を設置したときは、その従たる事務所の最寄りの供託所に政令で定める額の営業保証金を供託し、その旨を免許権者に届け出なければならない。","宅地建物取引業者は、主たる事務所を移転したためその最寄りの供託所が変更した場合、国債証券をもって営業保証金を供託しているときは、遅滞なく、従前の主たる事務所の最寄りの供託所に対し、営業保証金の保管替えを請求しなければならない。","宅地建物取引業者は、免許の有効期間満了に伴い営業保証金を取り戻す場合は、還付請求権者に対する公告をすることなく、営業保証金を取り戻すことができる。","免許権者は、宅地建物取引業者が宅地建物取引業の免許を受けた日から３月以内に営業保証金を供託した旨の届出をしないときは、その届出をすべき旨の催告をしなければならず、その催告が到達した日から１月以内に届出がないときは、当該宅地建物取引業者の免許を取り消すことができる。"],"correct":3,"explain":"①错。新设从事务所时，营业保证金依然要供托到\\"主事务所\\"附近的供托所，不是从事务所附近——这是容易踩坑的经典细节。②错。这里说反了方向——应该是向\\"新的\\"主事务所最寄的供托所申请保管替，不是向\\"从前\\"的供托所申请。③错。执照到期想取回营业保证金，原则上依然需要先做公告（给还付请求权者留出申报窗口），\\"执照到期\\"不属于免公告的例外情形。④对（答案）。业者拿到执照后3个月内没申报供托，免许权者必须发催告；催告送达后1个月内还不申报，免许权者可以吊销执照。","takeaway":"从事务所的营业保证金，依然要供托到主事务所附近；执照到期取回押金，原则上仍需公告；\\"3个月不报→催告→催告后1个月不报→可吊销\\"是营业保证金的标准处置流程。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-30', '{"id":"h25-30","tag":"宅地建物取引业法等・35条书面","title":"平成25年 問30","stem":"宅地建物取引業者が行う宅地建物取引業法第35条に規定する重要事項の説明（以下この問において「重要事項説明」という。）及び同条の規定により交付すべき書面（以下この問において「35条書面」という。）に関する次の記述のうち、正しいものはどれか。","options":["宅地建物取引業者は、宅地又は建物の売買について売主となる場合、買主が宅地建物取引業者であっても、重要事項説明は行わなければならないが、35条書面の交付は省略してよい。","宅地建物取引業者が、宅地建物取引士をして取引の相手方に対し重要事項説明をさせる場合、当該宅地建物取引士は、取引の相手方から請求がなくても、宅地建物取引士証を相手方に提示しなければならず、提示しなかったときは、20万円以下の罰金に処せられることがある。","宅地建物取引業者は、貸借の媒介の対象となる建物（昭和56年５月31日以前に新築）が、指定確認検査機関、建築士、登録住宅性能評価機関又は地方公共団体による耐震診断を受けたものであっても、その内容を重要事項説明において説明しなくてもよい。","宅地建物取引業者は、重要事項説明において、取引の対象となる宅地又は建物が、津波防災地域づくりに関する法律の規定により指定された津波災害警戒区域内にあるときは、その旨を説明しなければならない。"],"correct":3,"explain":"①错。买主是宅建业者时，重要事项的\\"说明\\"可以省略，但\\"35条书面的交付\\"义务不能省略——题目正好说反了。②错。宅建士没有请求也要提示宅建士证这点对，但违反后的处罚是\\"10万日元以下过料\\"，不是\\"20万日元以下罚金\\"，且这是行政罚不是刑罚。③错。建筑物贷借的媒介中，即使是贷借契约，若建筑物是昭和56年5月31日以前新建，只要做过耐震诊断，就必须说明诊断内容，不能因为是\\"贷借\\"就免除。④对（答案）。津波灾害警戒区域，不管买卖还是贷借都必须说明，不能因为对象是承租人就省略——这点跟造成宅地防灾区域、土砂灾害警戒区域是一样的规则。","takeaway":"买主是业者：说明可省、交付不可省。宅建士证不出示：10万日元以下过料（不是罚金）。津波灾害警戒区域说明义务，买卖贷借一视同仁，没有例外。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-40', '{"id":"h25-40","tag":"宅地建物取引业法等・8种限制/手付金等保全措置","title":"平成25年 問40","stem":"宅地建物取引業者Ａが、自ら売主として買主との間で締結する売買契約に関する次の記述のうち、宅地建物取引業法（以下この問において「法」という。）の規定によれば、正しいものはどれか。なお、この問において「保全措置」とは、法第41条に規定する手付金等の保全措置をいうものとする。","options":["Ａは、宅地建物取引業者でない買主Ｂとの間で建築工事完了前の建物を4,000万円で売却する契約を締結し300万円の手付金を受領する場合、銀行等による連帯保証、保険事業者による保証保険又は指定保管機関による保管により保全措置を講じなければならない。","Ａは、宅地建物取引業者Ｃに販売代理の依頼をし、宅地建物取引業者でない買主Ｄと建築工事完了前のマンションを3,500万円で売却する契約を締結した。この場合、Ａ又はＣのいずれかが保全措置を講ずることにより、Ａは、代金の額の５％を超える手付金を受領することができる。","Ａは、宅地建物取引業者である買主Ｅとの間で建築工事完了前の建物を5,000万円で売却する契約を締結した場合、保全措置を講じずに、当該建物の引渡前に500万円を手付金として受領することができる。","Ａは、宅地建物取引業者でない買主Ｆと建築工事完了前のマンションを4,000万円で売却する契約を締結する際、100万円の手付金を受領し、さらに200万円の中間金を受領する場合であっても、手付金が代金の５％以内であれば保全措置を講ずる必要はない。"],"correct":2,"explain":"①错。未完成物件的保全措施方式只有\\"保证\\"和\\"保险\\"两种，不包括\\"指定保管机构保管\\"（保管方式只适用于已完成物件）。②错。负有保全措施义务的只是自己作为卖主的业者A，媒介/代理业者C不负这个义务，即便C去讲了保全措施，A的义务也不会因此消失。③对（答案）。8种限制（含手付金等保全措施）只适用于卖主是业者、买主是非业者的场合，买主E本身是宅建业者，属于业者间交易，完全不适用保全措施规定，A可以不做保全措施直接收500万手付金。④错。判断是否需要保全措施看的是\\"手付金+中间金\\"的累计额是否超过5%，不是只看手付金本身——本题100万+200万=300万，已超过4000万×5%=200万，中间金受领前必须做保全措施。","takeaway":"未完成物件保全措施只能用\\"保证\\"或\\"保险\\"，不能用\\"保管\\"（保管只适用完成物件）；保全措施义务专属于卖主业者本人，媒介业者做了也不算数；买主是业者时8种限制全部不适用；判断要不要做保全措施，看\\"手付金+中间金\\"累计额，不是只看手付金单独金额。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h28-45', '{"id":"h28-45","tag":"宅地建物取引业法等・住宅瑕疵担保履行法","title":"平成28年 問45","stem":"宅地建物取引業者Ａが、自ら売主として、宅地建物取引業者でないＢに新築住宅を販売する場合における次の記述のうち、特定住宅瑕疵担保責任の履行の確保等に関する法律の規定によれば、正しいものはどれか。","options":["Ａは、住宅販売瑕疵担保保証金を供託する場合、当該住宅の床面積が100㎡以下であるときは、新築住宅の合計戸数の算定に当たって、２戸をもって１戸と数えることになる。","Ａは、当該住宅をＢに引き渡した日から３週間以内に、住宅販売瑕疵担保保証金の供託又は住宅販売瑕疵担保責任保険契約の締結の状況について、宅地建物取引業の免許を受けた国土交通大臣又は都道府県知事に届け出なければならない。","Ａは、住宅販売瑕疵担保保証金の供託をする場合、Ｂに対し、当該住宅の売買契約を締結するまでに、供託所の所在地等について記載した書面を交付して説明しなければならない。","Ａは、住宅瑕疵担保責任保険法人と住宅販売瑕疵担保責任保険契約の締結をした場合、Ｂが住宅の引渡しを受けた時から10年以内に当該住宅を転売したときは、住宅瑕疵担保責任保険法人にその旨を申し出て、当該保険契約の解除をしなければならない。"],"correct":2,"explain":"①错。合计户数按\\"2户算1户\\"的换算，门槛是\\"床面积55㎡以下\\"，不是100㎡以下——这是数字上最常见的出题陷阱。②错。免许权者届出的期限起算点是每年3月31日的\\"基准日\\"，从基准日起3周内申报，不是从\\"交付住宅之日\\"起算3周。③对（答案）。供托所所在地等的书面交付说明，必须在\\"売买契约締結前\\"完成，不能拖到引渡时才做——这是买方在签约前就该知道的保障信息。④错。住宅瑕疵担保责任保险契约要求引渡后10年以上持续有效，即使住宅在10年内被转卖，保险契约也不会因此解除——转卖不是解约事由。","takeaway":"合计户数\\"2户算1户\\"的换算门槛是55㎡（不是100㎡）；免许权者届出以每年3月31日\\"基准日\\"起算3周，不是引渡日起算；供托所说明必须在契约缔结前完成；转卖不影响保险契约的10年有效期，不能因转卖解约。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r05-7', '{"id":"r05-7","tag":"权利关系・配偶者居住权","title":"令和5年 問7","stem":"甲建物を所有するAが死亡し、Aの配偶者Bが甲建物の配偶者居住権を、Aの子Cが甲建物の所有権をそれぞれ取得する旨の遺産分割協議が成立した場合に関する次の記述のうち、民法の規定によれば、正しいものはどれか。","options":["遺産分割協議において、Bの配偶者居住権の存続期間が定められなかった場合、配偶者居住権の存続期間は20年となる。","Bが高齢となり、バリアフリーのマンションに転居するための資金が必要になった場合、Bは、Cの承諾を得ずに甲建物を第三者Dに賃貸することができる。","Cには、Bに対し、配偶者居住権の設定の登記を備えさせる義務がある。","Cは、甲建物の通常の必要費を負担しなければならない。"],"correct":2,"explain":"①错。配偶者居住权的存续期间原则上是配偶终身，只有遗产分割协议/遗言里有别段约定，或家庭裁判所审判中有别段约定时，才依照该约定——协议未约定时默认是\\"终身\\"，不是\\"20年\\"。②错。配偶者要对居住建筑物进行改建/增建，或让第三者使用/收益（如出租），都必须获得所有者的承诺，未经C承诺不能将建筑物出租给第三者D。③对（答案）。居住建筑物的所有者对配偶者负有\\"使其具备配偶者居住权设定登记\\"的义务——这是保护配偶者对抗第三人的重要制度设计。④错。配偶者居住权制度下，通常必要费由配偶者B自己负担，不是由所有者C负担——这跟使用贷借的通常必要费负担规则类似。","takeaway":"配偶者居住权默认终身（非20年）；变更用途/出租需所有者承诺；设定登记是所有者的义务；通常必要费由配偶者自己负担。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-2', '{"id":"h25-2","tag":"权利关系・制限行为能力者","title":"平成25年 問2","stem":"未成年者に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["父母とまだ意思疎通することができない乳児は、不動産を所有することができない。","営業を許可された未成年者が、その営業のための商品を仕入れる売買契約を有効に締結するには、父母双方がいる場合、父母のどちらか一方の同意が必要である。","18歳になれば婚姻することができるが、父母双方がいる場合には、必ず父母双方の同意が必要である。","Ａが死亡し、Ａの妻Ｂと嫡出でない未成年の子ＣとＤが相続人となった場合に、ＣとＤの親権者である母ＥがＣとＤを代理してＢとの間で遺産分割協議を行っても、有効な追認がない限り無効である。"],"correct":3,"explain":"①错。权利能力（成为法律权利主体的资格）自出生时起当然取得（民法3条1项），与是否能和父母意思疎通无关——乳儿、幼儿一出生就有权利能力，可以所有不动产，只是没有足够的行为能力，实际交易时需要靠法定代理人代为进行。②错。营业已被许可的未成年人，在该营业范围内视为与成年人有同一行为能力（民法6条1项）——比如被许可做古着仕入贩卖生意，那么仕入、贩卖相关的行为，单独缔结的契约就是有效的，完全不需要父母同意，不存在\\"父母双方在场时需要一方同意\\"这种折中规则。③错。18岁既是婚姻适齢（可结婚的年龄），也正是成年年龄（民法4条、731条）——18岁的人本身就是成年人，结婚这种身份行为完全由本人单独决定，不需要父母同意，选项里\\"必须父母双方同意\\"的说法是错的。④对（答案）。一位亲权者同时代理数名子女处理彼此之间存在利害冲突的行为时，必须向家庭裁判所申请选任特别代理人（民法826条2项），亲权者本人不能既代理C又代理D去和B进行遗产分割协议。本题中C、D在遗产分割上属于利害对立关系（一方多分则另一方少分），母E若同时代理C、D与B协议，就是典型的\\"利益相反行为\\"，这类无权代理性质的协议，除非事后获得本人（C、D成年后）的有效追认，否则无效（最判昭48.04.24）。","takeaway":"权利能力自出生当然取得，与乳幼儿是否能沟通无关；营业许可未成年人在许可范围内等同成年人，行为不需父母同意；18岁=成年=婚姻适齢，结婚不需父母同意；亲权者代理数名子女处理彼此利害冲突的事务（如共同继承的遗产分割），是利益相反行为，无有效追认则无效——记忆口诀：\\"一个妈妈不能同时替两个吵架的孩子做主\\"。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r04-13', '{"id":"r04-13","tag":"权利关系・区分所有法","title":"令和4年 問13","stem":"建物の区分所有等に関する法律（以下この問において「法」という。）に関する次の記述のうち、誤っているものはどれか。","options":["管理者は、規約により、その職務に関し、区分所有者のために、原告又は被告となったときは、その旨を各区分所有者に通知しなくてよい。","管理者がないときは、区分所有者（議決権を有しないものを除く。）の５分の１以上の者であって議決権の５分の１以上を有するものは、集会を招集することができる。ただし、この定数は、規約で減ずることができる。","集会において、管理者の選任を行う場合、規約に別段の定めがない限り、出席した区分所有者（議決権を有しないものを除く。）及びその議決権の各過半数で決する。","管理組合（法第３条に規定する区分所有者の団体をいう。）は、集会において、区分所有者（議決権を有しないものを除く。以下この問において同じ。）の過半数（これを上回る割合を規約で定めた場合にあっては、その割合以上）の者であって議決権の過半数（これを上回る割合を規約で定めた場合にあっては、その割合以上）を有するものが出席し、出席した区分所有者及びその議決権の各４分の３以上の多数による決議で法人となる旨並びにその名称及び事務所を定め、かつ、その主たる事務所の所在地において登記をすることによって法人となる。"],"correct":0,"explain":"①错（答案）。管理者可以依据\\"规约\\"或\\"集会决议\\"，就其职务对区分所有者提起诉讼或应诉（区分所有法26条4项）。两者的通知义务不同：依集会决议提起，区分所有者自然知情，不需另行通知；依规约提起，区分所有者未必知情，因此必须在无迟延的情况下将该事实通知各区分所有者（同条5项）。本题说\\"依规约提起、不需要通知\\"，正好说反了。②对。管理者不存在时，区分所有者（除无议决权者）人数及议决权各1/5以上的人，可以召集集会（区分所有法34条5项本文），但这个定数（1/5）可以通过规约减少（同项但书）——只能减不能加。③对。选任管理者原则上是集会的普通决议事项：规约无特别规定时，由出席的区分所有者及其议决权各过半数决定（区分所有法25条1项、39条1项）。④对。管理组合要成为管理组合法人，需要：①集会上区分所有者及议决权各过半数（或规约规定的更高比例）出席作为法定人数；②出席者及其议决权各3/4以上多数决议通过法人化事项、名称、事务所；③在主事务所所在地办理登记（区分所有法47条1项）——本题描述的流程完全正确。","takeaway":"管理者原告/被告身份——集会决议不用通知（大家都在场知道），规约授权必须通知（大家不一定知道）；召集集会门槛1/5可以往下调，不能往上提；管理者选任是普通决议（过半数）；法人化是特别决议（3/4以上）+登记。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-1', '{"id":"r06-1","tag":"权利关系・法律行为","title":"令和6年 問1","stem":"法律行為に関する次の記述のうち、民法の規定によれば、正しいものはどれか。","options":["営業を許された未成年者が、その営業に関する意思表示をした時に意思能力を有しなかった場合は、その法律行為は無効である。","公の秩序に反する法律行為であっても、当事者が納得して合意した場合には、その法律行為は有効である。","詐欺による意思表示は取り消すことによって初めから無効であったとみなされるのに対し、強迫による意思表示は取り消すまでもなく無効である。","他人が所有している土地を目的物にした売買契約は無効であるが、当該他人がその売買契約を追認した場合にはその売買契約は有効となる。"],"correct":0,"explain":"①对（答案）。意思能力是指能判断自己所做法律行为结果的能力。欠缺意思能力状态下做出的法律行为，属于无效（民法3条の2）。是否是未成年人、是否被许可营业，属于\\"行为能力\\"层面的问题，跟\\"意思能力\\"是两回事——即使是被许可营业的未成年人，只要做出意思表示时没有意思能力，该意思表示依然无效。②错。违反公序良俗的法律行为绝对无效（民法90条）。无效的行为不会因为当事人双方合意或事后追认而变得有效（民法119条）——这跟\\"可撤销\\"完全不同，\\"无效\\"是自始不发生效力，不存在\\"补正\\"的空间。③错。诈欺的意思表示可以撤销（民法96条1项），撤销后视为自始无效（民法121条）。强迫的意思表示规则完全相同——同样是可以撤销，撤销后才视为自始无效，不是\\"不用撤销就当然无效\\"。选项把强迫说成\\"不用撤销即无效\\"是错的，诈欺和强迫在效力构造上是一致的。④错。以他人所有物为标的物的买卖契约（他人物买卖），本身是有效的契约（民法561条），不是\\"无效\\"——出卖人因此负有从真正权利人处取得该物、再移转给买主的义务。选项把\\"有效\\"说成\\"无效\\"是错的，\\"经过追认才有效\\"的说法也不成立，因为它压根不需要\\"无效变有效\\"这个过程。","takeaway":"意思能力缺失→无效（跟未成年、营业许可无关，是完全不同的两条线）；公序良俗违反→无效，不能靠合意/追认补正；诈欺/强迫→都是可撤销，撤销后才溯及无效，二者规则一致（别被\\"强迫=当然无效\\"的说法带偏）；他人物买卖→契约本身有效（不是无效后靠追认变有效）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-4', '{"id":"h26-4","tag":"权利关系・担保物权","title":"平成26年 問4","stem":"ＡがＢとの間で、ＣのＢに対する債務を担保するためにＡ所有の甲土地に抵当権を設定する場合と根抵当権を設定する場合における次の記述のうち、民法の規定によれば、正しいものはどれか。","options":["抵当権を設定する場合には、被担保債権を特定しなければならないが、根抵当権を設定する場合には、ＢＣ間のあらゆる範囲の不特定の債権を極度額の限度で被担保債権とすることができる。","抵当権を設定した旨を第三者に対抗する場合には登記が必要であるが、根抵当権を設定した旨を第三者に対抗する場合には、登記に加えて、債務者Ｃの異議を留めない承諾が必要である。","Ｂが抵当権を実行する場合には、ＡはまずＣに催告するように請求することができるが、Ｂが根抵当権を実行する場合には、ＡはまずＣに催告するように請求することはできない。","抵当権の場合には、ＢはＣに対する他の債権者の利益のために抵当権の順位を譲渡することができるが、元本の確定前の根抵当権の場合には、Ｂは根抵当権の順位を譲渡することができない。"],"correct":3,"explain":"①错。根抵当权担保的确实是不特定债权，但不是\\"任意范围\\"都行——必须限定在BC之间某个特定范围（如\\"某类交易产生的债权\\"）内的不特定债权，用极度额做上限，不能笼统覆盖\\"BC之间的一切债权\\"。②错。抵当权和根抵当权对抗第三人都只需要登记即可，根抵当权不需要额外的\\"债务人C无异议承诺\\"这道手续——这是编造出来混淆的条件。③错。物上保证人（A，用自己的土地为C的债务作担保，自己不是债务人）没有\\"催告的抗辩权\\"——不管是普通抵当权还是根抵当权，A都不能要求B先去找债务人C催告，两者规则一致，不存在\\"抵当权能、根抵当权不能\\"的区别。④对（答案）。普通抵当权中，抵当权人B可以把自己的抵当权顺位让与给对C的其他债权人（民法376条），但元本确定前的根抵当权没有这个顺位让与制度——根抵当权在元本确定前具有特殊的流动性/概括性，顺位让与这类针对\\"特定债权\\"的处分方式在根抵当权确定前是做不到的。","takeaway":"根抵当权是\\"限定范围内的不特定债权\\"，不是\\"来者不拒\\"；两者对抗第三人都只需登记，没有\\"债务人承诺\\"这道手续；物上保证人对两者都没有催告抗辩权；顺位让与只有普通抵当权能做，元本确定前的根抵当权不能做。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-9', '{"id":"r07-9","tag":"权利关系・债权总则","title":"令和7年 問9","stem":"連帯債務者の一人について生じた次の事由のうち、民法の規定によれば、他の連帯債務者に対して効力が生じないものとして正しいものはどれか。なお、この問において、連帯債務者の一人について生じた事由が他の連帯債務者に対して効力が生じる旨の別段の意思表示はないものとする。","options":["債権者がした連帯債務者の一人に対する履行の請求","連帯債務者の一人と債権者との間の混同","連帯債務者の一人が債権者に対して債権を有する場合において、その連帯債務者がした相殺の援用","連帯債務者の一人と債権者との間の更改"],"correct":0,"explain":"①对（答案）。新民法下，债权人对连带债务人中一人做出的\\"履行请求\\"，原则上只有相对效力（民法441条）——不会当然波及到其他连带债务人。这是新旧法最大区别之一：旧法下\\"履行请求\\"是绝对效（一人被请求，其他人也算被请求），新法把它改成了原则相对效（除非各方另有约定）。②错。混同（连带债务人中一人与债权人的地位合而为一，比如债务人继承了债权人的债权）具有绝对效力（民法438条）——视为该债务人已清偿，对其他连带债务人同样发生效力（债务整体消灭）。③错。连带债务人中一人对债权人主张相殺（抵消），具有绝对效力（民法439条1项）——该债务人负担部分内消灭的债务额，对其他连带债务人同样发生效力。④错。更改（连带债务人中一人与债权人之间成立更改，即用新债务替代原有债务）具有绝对效力（民法438条）——原连带债务关系整体消灭，其他债务人也脱离原债务。","takeaway":"新民法把\\"履行请求\\"从绝对效改成了相对效（这是本题的核心考点，也是新旧法对比最爱考的地方）；混同、相殺、更改这三个依然是绝对效——一人发生，全员受影响。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-7', '{"id":"r07-7","tag":"权利关系・赁贷借契约","title":"令和7年 問7","stem":"Ａは自己の所有する甲建物を事務所としてＢに賃貸し（以下この問において「本件契約」という。)、その後、本件契約の期間中に甲建物の屋根に雨漏りが生じたため、ＣがＢから甲建物の屋根の修理を請け負い、Ｃによる修理が完了した。この場合における次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["ＢがＣに修理代金を支払わないまま無資力となり、賃料を滞納して本件契約が解除されたことにより甲建物はＡに明け渡された。この場合、ＣはＡに対して、事務管理に基づいて修理費用相当額の支払を求めることはできない。","ＢがＣに修理代金を支払ったとしても、本件契約において、Ａの負担に属するとされる甲建物の屋根の修理費用について直ちに償還請求することができる旨の特約がない限り、契約終了時でなければ、ＢはＡに対して償還を求めることはできない。","ＢがＣに修理代金を支払わない場合、Ｃは、Ｂが占有する甲建物につき、当然に不動産工事の先取特権を行使することができる。","ＢがＣに修理代金を支払わないまま無資力となり、賃料を滞納して本件契約が解除されたことにより甲建物はＡに明け渡された。本件契約において、ＢがＡに権利金を支払わないことの代償として、甲建物の修理費用をＢの負担とする旨の特約が存し、当該屋根の修理費用と権利金が相応していたときであっても、ＣはＡに対して、不当利得に基づいて修理費用相当額の支払を求めることができる。"],"correct":0,"explain":"①对（答案）。C是受B委托的承揽人（请负契约），C和A之间没有直接契约关系。C的修理行为是基于和B之间的请负合同，属于契约履行范畴，不构成\\"事务管理\\"（事务管理是指没有法律义务的前提下主动为他人管理事务）——所以C不能援引事务管理，向房东A请求支付修理费。②错。承租人B为维持房屋使用收益支出的\\"必要费\\"（比如屋顶漏雨这种维持性维修），可以立即向出租人A请求偿还（民法608条1项），不需要等到契约终了，也不需要特别约定——这一点和\\"有益费\\"（改良性支出，要等契约终了按增值部分算）不一样，选项把两者规则搞混了。③错。不动产工事的先取特权，担保的是\\"因设计、施工或监理而使不动产价值增加的部分\\"（民法327条）——单纯的\\"修理\\"（维持原状的保存行为）不在此范围内，C不能就这次修理工程当然享有先取特权。④错。修理费本来就按契约约定该由B自己负担（用来抵权利金），A并没有因此获得\\"没有法律依据的利益\\"——A没有不当得利，C不能以不当得利为由向A主张付款。","takeaway":"承揽人和房东没有直接契约关系，找不到事务管理这条路；必要费可以立刻要，不用等到契约终了（这点跟有益费不同）；先取特权只保护\\"增值\\"工程，不保护单纯\\"保存性\\"修理；契约里本来就该谁出的钱，房东没占到便宜，就没有不当得利。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02-10-8', '{"id":"r02-10-8","tag":"权利关系・法定相続","title":"令和2年10月 問8","stem":"相続（令和2年7月1日に相続の開始があったもの）に関する次の記述のうち、民法の規定によれば、誤っているものはどれか。","options":["相続回復の請求権は、相続人又はその法定代理人が相続権を侵害された事実を知った時から5年間行使しないときは、時効によって消滅する。","被相続人の子が相続開始以前に死亡したときは、その者の子がこれを代襲して相続人となるが、さらに代襲者も死亡していたときは、代襲者の子が相続人となることはない。","被相続人に相続人となる子及びその代襲相続人がおらず、被相続人の直系尊属が相続人となる場合には、被相続人の兄弟姉妹が相続人となることはない。","被相続人の兄弟姉妹が相続人となるべき場合であっても、相続開始以前に兄弟姉妹及びその子がいずれも死亡していたときは、その者の子（兄弟姉妹の孫）が相続人となることはない。"],"correct":1,"explain":"①对（不是错误项）。相続回復请求权确实是\\"知道被侵害之日起5年\\"时效消灭（民法884条），条文原文表述完全一致。②错（答案）。子女这一系（直系卑属）的代袭继承没有代数限制——代袭人（孙）也去世了，还可以再代袭给曾孙（民法887条3项，\\"再代袭\\"）。选项说\\"代袭者的子女不能成为继承人\\"是错的，实际上只要是直系卑属，可以一直往下代袭。③对（不是错误项）。继承顺位是子→直系尊属→兄弟姐妹，第一顺位（子及其代袭人）没有、第二顺位（直系尊属）有人在世时，第三顺位（兄弟姐妹）根本轮不到继承。④对（不是错误项）。兄弟姐妹这一系的代袭继承只能代袭一代（甥/侄），不能再往下代袭给甥侄的子女（民法889条2项准用887条2项，但不准用887条3项的\\"再代袭\\"规定）。所以选项说\\"兄弟姐妹和其子都已故时，孙子（甥侄之子）不能成为继承人\\"是对的。","takeaway":"子女这条线（直系卑属）代袭继承没有代数限制，可以一直代袭下去（子→孙→曾孙……）；兄弟姐妹这条线代袭继承只能代袭一代（到甥侄为止，甥侄的子女不能再代袭）——这是这道题的核心区分点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h27-11', '{"id":"h27-11","tag":"权利关系・借地借家法(建物)","title":"平成27年 問11","stem":"ＡがＢとの間で、Ａ所有の甲建物について、期間３年、賃料月額10万円と定めた賃貸借契約を締結した場合に関する次の記述のうち、民法及び借地借家法の規定並びに判例によれば、正しいものはどれか。","options":["ＡがＢに対し、賃貸借契約の期間満了の６か月前までに更新しない旨の通知をしなかったときは、ＡとＢは、期間３年、賃料月額10万円の条件で賃貸借契約を更新したものとみなされる。","賃貸借契約を期間を定めずに合意により更新した後に、ＡがＢに書面で解約の申入れをした場合は、申入れの日から３か月後に賃貸借契約は終了する。","Ｃが、ＡＢ間の賃貸借契約締結前に、Ａと甲建物の賃貸借契約を締結していた場合、ＡがＢに甲建物を引き渡しても、Ｃは、甲建物の賃借権をＢに対抗することができる。","ＡＢ間の賃貸借契約がＢの賃料不払を理由として解除された場合、ＢはＡに対して、Ａの同意を得てＢが建物に付加した造作の買取りを請求することはできない。"],"correct":3,"explain":"①错。有期限的建筑物赁贷借（普通借家），若房东没在期满前1年至6个月之间发出不更新的通知，会被法定更新，但更新后的契约期间变成\\"没有期限\\"，不是继续沿用原来的\\"3年\\"——选项说\\"更新为期间3年\\"是错的。②错。没有期限的建筑物赁贷借中，房东发出书面解约申告后，是申告之日起6个月后契约才终止（承租人解约才是3个月后）——房东/房客的解约通知期限本来就不对称，选项把房东的6个月错写成了3个月。③错。C虽然在AB契约缔结之前就先和A签了甲建筑物的赁贷借契约，但契约缔结时间早，不代表当然能对抗后来的B——建筑物赁贷借的对抗要件是\\"登记\\"或\\"受领引渡\\"，选项完全没提到C是否已经具备对抗要件，在信息不完整的情况下不能断言\\"C当然能对抗B\\"，这是把\\"契约在先\\"和\\"对抗力在先\\"混为一谈的错误绝对化表述。④对（答案）。造作买取请求权，只在契约因期满或解约申告而终止时才能行使。本题契约是因为承租人B的赁料不払（欠租）这种债务不履行而被解除——这种终了方式不适用造作买取请求权，B不能要求A买下自己添附的造作（判例明确：因赁借人的债务不履行或背信行为导致解除时，造作买取请求权不能行使）。","takeaway":"法定更新后契约变成\\"无期限\\"，不是延续原期限；房东解约6个月生效、房客解约3个月生效（不对称，别记反）；\\"契约谁先签\\"不等于\\"对抗力谁先有\\"，对抗要看是否具备登记/引渡；造作买取请求权只在期满/解约终了时能用，因欠租解除时用不了。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-14', '{"id":"h30-14","tag":"权利关系・不动产登记法","title":"平成30年 問14","stem":"不動産の登記に関する次の記述のうち、誤っているものはどれか。","options":["登記は、法令に別段の定めがある場合を除き、当事者の申請又は官庁若しくは公署の嘱託がなければ、することができない。","表示に関する登記は、登記官が、職権ですることができる。","所有権の登記名義人は、建物の床面積に変更があったときは、当該変更のあった日から１月以内に、変更の登記を申請しなければならない。","所有権の登記名義人は、その住所について変更があったときは、当該変更のあった日から１月以内に、変更の登記を申請しなければならない。"],"correct":3,"explain":"①对。登记原则上必须有当事人申请，或官厅/公署的嘱托才能进行，法令另有规定的除外（不动产登记法16条1项）。②对。表示登记可以由登记官依职权进行（不动产登记法28条）——这是表示登记和权利登记的一个重要区别，表示登记更侧重反映不动产的客观真实状态，登记官有职权介入的空间。③对。建筑物床面积等表示事项发生变更时，所有权登记名义人须自变更之日起1个月内申请变更登记（不动产登记法51条1项）——这是表示登记范畴的强制申请义务。④错（答案，按平成30年当年法规）。当时的规则下，所有权登记名义人住所发生变更时，登记法没有\\"1个月内必须申请\\"这样的强制义务——这属于权利登记范畴的\\"名义人表示变更登记\\"，当时是任意申请事项，不像床面积变更那样有强制期限。【重要法改正提醒】这道题涉及的规则已在2026年4月1日发生法改正——住所変更登記已从\\"任意\\"变成\\"义务\\"：所有权登记名义人住所/氏名变更后，必须在2年内申请变更登记（不动产登记法76条の5新设），不履行且无正当理由的，可处5万日元以下过料（第164条2项）。按现行法（2026年10月适用），④依然是错误选项，但错误原因变了——现在确实有强制申请义务，只是期限是\\"2年内\\"，不是选项写的\\"1个月内\\"。","takeaway":"床面积变更（表示登记）1个月内申请，这点没变；住所变更（权利登记的名义人表示变更）2026年4月起也变成义务了，但期限是2年，不是1个月——按当年（平成30年）法规答案是④\\"根本没有强制义务\\"错，按2026年现行法则是④\\"期限数字\\"错，结论都是④错，但理由要跟上最新法。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03s-22', '{"id":"r03s-22","tag":"法令上的制限・国土利用计画法","title":"令和3年12月 問22","stem":"国土利用計画法（以下この問において「法」という。）第23条の届出（以下この問において「事後届出」という。）及び法第29条の届出に関する次の記述のうち、正しいものはどれか。なお、この問において「都道府県知事」とは、地方自治法に基づく指定都市にあってはその長をいうものとする。","options":["個人Ａが所有する都市計画区域外の12,000㎡の土地に、個人Ｂが地上権の設定を受ける契約を締結した場合、Ｂは一定の場合を除き事後届出を行う必要がある。","法第28条に基づく遊休土地に係る通知を受けた者は、その通知があった日から起算して１月以内に、その通知に係る遊休土地の利用又は処分に関する計画を、都道府県知事に届け出なければならない。","市街化調整区域において、宅地建物取引業者Ｃが所有する面積5,000㎡の土地について、宅地建物取引業者Ｄが一定の計画に従って、2,000㎡と3,000㎡に分割して順次購入した場合、Ｄは事後届出を行う必要はない。","都道府県知事は、事後届出があった場合において、土地の利用目的に係る必要な勧告を行うことができ、その勧告を受けた者がその勧告に従わないときは、その旨及びその内容を公表しなければならない。"],"correct":0,"explain":"①对（答案）。地上权设定契约若附带对价（权利金），就属于国土利用计画法上的\\"土地买卖等契约\\"（国土法23条1项、14条1项）。都市计画区域外的面积申报门槛是1万㎡以上，本题12,000㎡符合门槛，除\\"没有权利金\\"等特定情形外，需要进行事后申报。②错。收到\\"游休土地\\"相关通知的人，须在通知之日起6周内向知事申报利用/处分计划（国土法29条1项）——选项写的\\"1个月内\\"是错的。③错。虽然5,000㎡的土地被分割成2,000㎡+3,000㎡两笔，但因为是\\"按一定计划顺次购入\\"，实质上仍要当作整体5,000㎡的\\"买入一团土地\\"来判断（防止拆分规避申报）。市街化调整区域内的事后申报门槛是5,000㎡以上，本题土地正好达标，D需要进行事后申报——选项说\\"不需要\\"是错的。④错。知事对事后申报的土地利用目的可以进行劝告（国土法24条1项），受劝告者不遵从时，知事可以公表该事实及劝告内容（国土法26条）——但这只是\\"可以做\\"的裁量权，不是\\"必须做\\"的强制义务，选项把\\"可以公表\\"错写成了\\"必须公表\\"。","takeaway":"地上权设定只要有对价（权利金）就算\\"土地买卖等契约\\"，都市计画区域外门槛1万㎡；游休土地利用计划申报期限是6周，不是1个月；分割顺次购买但按计划进行的，仍按整体面积判断，不能靠拆分规避申报；知事对不遵从劝告者是\\"可以\\"公表，不是必须公表。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03-10-16', '{"id":"r03-10-16","tag":"法令上的制限・都市计画法","title":"令和3年10月 問16","stem":"都市計画法に関する次の記述のうち、正しいものはどれか。ただし、許可を要する開発行為の面積については、条例による定めはないものとし、この問において「都道府県知事」とは、地方自治法に基づく指定都市、中核市及び施行時特例市にあってはその長をいうものとする。","options":["市街化区域において、都市公園法に規定する公園施設である建築物の建築を目的とした5,000㎡の土地の区画形質の変更を行おうとする者は、あらかじめ、都道府県知事の許可を受けなければならない。","首都圏整備法に規定する既成市街地内にある市街化区域において、住宅の建築を目的とした800㎡の土地の区画形質の変更を行おうとする者は、あらかじめ、都道府県知事の許可を受けなければならない。","準都市計画区域において、商業施設の建築を目的とした2,000㎡の土地の区画形質の変更を行おうとする者は、あらかじめ、都道府県知事の許可を受けなければならない。","区域区分が定められていない都市計画区域において、土地区画整理事業の施行として行う8,000㎡の土地の区画形質の変更を行おうとする者は、あらかじめ、都道府県知事の許可を受けなければならない。"],"correct":1,"explain":"①错。公园设施属于\\"公益上必要建筑物\\"，无论所在区域或规模大小，其开发行为都不需要开发许可——公益属性直接豁免申报义务。②对（答案）。三大都市圏（首都圏・近畿圏・中部圏）内的既成市街地等特定市街化区域，开发许可的面积门槛比普通市街化区域（1,000㎡）更严格，降到500㎡以上。本题800㎡已超过500㎡门槛，需要事先取得知事许可。③错。准都市计画区域内的开发许可门槛是3,000㎡以上，本题2,000㎡未达门槛，不需要许可。④错。土地区划整理事业实施的开发行为，无论所在区域或规模大小，都不需要开发许可——这跟\\"公益上必要建筑物\\"一样属于制度性豁免。","takeaway":"公园设施、土地区划整理事业实施的开发行为——不管区域和规模，一律不需要许可（制度性豁免）；准都市计画区域门槛3,000㎡；三大都市圏既成市街地这种特殊市街化区域，门槛比普通市街化区域（1,000㎡）更严格，只要500㎡——数字越小说明管得越严，别记反。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02-10-42', '{"id":"r02-10-42","tag":"宅地建物取引业法等・8种制限综合","title":"令和2年10月 問42","stem":"宅地建物取引業者Ａが、自ら売主として締結する売買契約に関する次の記述のうち、宅地建物取引業法（以下この問において「法」という。）及び民法の規定によれば、誤っているものはどれか。","options":["Ａが宅地建物取引業者ではないＢとの間で締結する宅地の売買契約において、当該宅地の種類又は品質に関して契約の内容に適合しない場合におけるその不適合を担保すべき責任を負う期間をＢがその不適合を知った時から２年とする特約を定めた場合、この特約は有効である。","Ａが宅地建物取引業者ではないＣとの間で建築工事の完了前に締結する建物（代金5,000万円）の売買契約においては、Ａは、手付金200万円を受領した後、法第41条に定める手付金等の保全措置を講じなければ、当該建物の引渡し前に中間金300万円を受領することができない。","Ａが宅地建物取引業者Ｄとの間で造成工事の完了後に締結する宅地（代金3,000万円）の売買契約においては、Ａは、法第41条の２に定める手付金等の保全措置を講じないで、当該宅地の引渡し前に手付金800万円を受領することができる。","Ａが宅地建物取引業者ではないＥとの間で締結する建物の売買契約において、Ａは当該建物の種類又は品質に関して契約の内容に適合しない場合におけるその不適合を担保すべき責任を一切負わないとする特約を定めた場合、この特約は無効となり、Ａが当該責任を負う期間は当該建物の引渡日から２年となる。"],"correct":0,"explain":"【本题为官方公认的\\"复数解\\"题目——2020年12月2日合格发表时，官方公告承认出题有瑕疵，肢1、肢4均为正解（都是错误的记述）。以下以肢1为主线讲解，肢4的错误点在最后单独说明。】①错（官方认定答案之一）。宅建业法规定：卖主对\\"契约不适合担保责任\\"设置的特约，不能比民法更不利于买方，唯一被允许的例外是把\\"通知期间\\"（不是\\"消灭时效期间\\"）定为\\"引渡后2年以上\\"（宅建业法40条）。本选项的特约把责任期间定为\\"买方知道不适合之日起2年\\"——这动的是主观消灭时效期间，不是通知期间，宅建业法不允许在这一点上对买方更不利，所以这个特约无效，选项说\\"有效\\"是错的。②对（不是错误项）。C是非业者，适用8种制限。未完成物件手付金200万+中间金300万=500万，超过5000万×5%=250万门槛，中间金收取前必须做保全措施，选项描述正确。③对（不是错误项）。D是宅建业者，业者间交易完全不适用8种制限，可以不做保全措施直接收800万手付金，选项正确。④错（官方认定的另一答案）。跟①同样的逻辑——\\"完全不负契约不适合担保责任\\"的特约比民法更不利于买方，这个特约本身确实无效，这点没错。但选项后半句说\\"无效后责任期间变成引渡日起2年\\"是错的——特约无效后应该退回适用民法原则，也就是客观消灭时效10年（从引渡之日起算），不是\\"2年\\"。这里错在\\"退回后的期间数字\\"算错了。","takeaway":"本题官方认定复数解（肢1、肢4均对）。契约不适合担保责任特约的合法边界，只能把\\"通知期间\\"定为引渡后2年以上，不能碰\\"消灭时效期间\\"；特约若因对买方不利而无效，退回适用民法原则是\\"客观时效10年、主观时效5年\\"，不是简单套用\\"2年\\"这个数字。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-20', '{"id":"h25-20","tag":"法令上的制限・土地区画整理法","title":"平成25年 問20","stem":"土地区画整理法に関する次の記述のうち、正しいものはどれか。","options":["個人施行者は、基準又は規約に別段の定めがある場合においては、換地計画に係る区域の全部について土地区画整理事業の工事が完了する以前においても換地処分をすることができる。","換地処分は、施行者が換地計画において定められた関係事項を公告して行うものとする。","個人施行者は、換地計画において、保留地を定めようとする場合においては、土地区画整理審議会の同意を得なければならない。","個人施行者は、仮換地を指定しようとする場合においては、あらかじめ、その指定について、従前の宅地の所有者の同意を得なければならないが、仮換地となるべき宅地の所有者の同意を得る必要はない。"],"correct":0,"explain":"①对（答案）。换地处分原则上是在换地计划所涉区域的全部工程完工后进行，但基准、规约、章程或施行规程另有规定时，即使工程尚未全部完工，也可以提前进行换地处分（土地区划整理法103条2项）——这是原则的法定例外情形。②错。换地处分是施行者向相关权利人通知换地计划中规定的事项来进行的（土地区划整理法103条1项），不是\\"公告\\"——选项把\\"通知\\"和\\"公告\\"搞混了。公告其实是另一个步骤：施行者通知完权利人后向知事报告，再由知事进行公告。③错。个人施行者若要在换地计划中设定保留地，需要获得从前宅地的所有者及相关权利人的同意（法96条），不是\\"土地区划整理审议会\\"的同意——审议会同意适用于公的施行（如都道府县、市町村施行）等场合，个人施行不适用这个机构。④错。个人施行者若要指定假换地，必须事先获得该指定所涉的从前宅地所有者以及将成为假换地的宅地所有者（及相关权利人）双方的同意（法98条3项）——选项说\\"只需从前宅地所有者同意，不需要假换地宅地所有者同意\\"是错的，两边都要同意。","takeaway":"换地处分原则等全部工程完工，但规准/规约/章程有约定可以提前——这是唯一的例外通道；换地处分本身是\\"通知\\"权利人，不是\\"公告\\"（公告是知事的后续动作）；个人施行的保留地设定要看从前宅地所有者同意，审议会同意只用在公的施行；假换地指定要双方（从前宅地+假换地宅地）所有者都同意，不是只要一边。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-23', '{"id":"h26-23","tag":"税相关法令・登録免许税","title":"平成26年 問23","stem":"住宅用家屋の所有権の移転登記に係る登録免許税の税率の軽減措置に関する次の記述のうち、正しいものはどれか。","options":["この税率の軽減措置は、一定の要件を満たせばその住宅用家屋の敷地の用に供されている土地に係る所有権の移転の登記にも適用される。","この税率の軽減措置は、個人が自己の経営する会社の従業員の社宅として取得した住宅用家屋に係る所有権の移転の登記にも適用される。","この税率の軽減措置は、以前にこの措置の適用を受けたことがある者が新たに取得した住宅用家屋に係る所有権の移転の登記には適用されない。","この税率の軽減措置は、所有権の移転の登記に係る住宅用家屋が、築年数が25年以内の耐火建築物に該当していても、床面積が50㎡未満の場合には適用されない。"],"correct":3,"explain":"①错。这项税率减轻措施只适用于\\"住宅用家屋\\"本身的所有权移转登记，不适用于该住宅用家屋所在土地的所有权移转登记——土地部分有另一套不同的减轻规则（租税特别措置法72条），跟本题讨论的\\"住宅家屋减轻措施\\"（73条）是两个不同的制度。②错。这项措施要求取得人是自己居住使用该住宅家屋，用作公司员工宿舍（社宅）不属于\\"自己居住用\\"，不适用减轻税率。③错。这项措施没有\\"以前用过一次就不能再用\\"这种限制——只要每次取得都满足要件（床面积、自己居住等），可以反复适用，没有次数限制。④对（答案）。这项减轻措施对住宅用家屋的床面积要求是50㎡以上，即使建筑年数在25年以内、属于耐火建筑物（满足其他适用条件），只要床面积不满50㎡，依然不适用减轻措施——面积要件是独立门槛，不会因为满足了其他条件就被豁免。","takeaway":"这项减轻措施只覆盖\\"住宅家屋\\"本体，不含土地部分（土地是另一套规则）；取得人必须\\"自己居住\\"，公司社宅不算；没有\\"用过一次就作废\\"的限制，可以反复享受；床面积50㎡以上是独立的硬门槛，耐火/建筑年数再合格也救不了面积不达标。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h24-24', '{"id":"h24-24","tag":"税相关法令・不动产取得税","title":"平成24年 問24","stem":"不動産取得税に関する次の記述のうち、正しいものはどれか。","options":["不動産取得税の課税標準となるべき額が、土地の取得にあっては16万円、家屋の取得のうち建築に係るものにあっては１戸につき66万円、その他のものにあっては１戸につき34万円に満たない場合においては、不動産取得税が課されない。","床面積250㎡である新築住宅に係る不動産取得税の課税標準の算定については、当該新築住宅の価格から1,200万円が控除される。","宅地の取得に係る不動産取得税の課税標準は、当該宅地の価格の４分の１の額とされる。","家屋が新築された日から２年を経過して、なお、当該家屋について最初の使用又は譲渡が行われない場合においては、当該家屋が新築された日から２年を経過した日において家屋の取得がなされたものとみなし、当該家屋の所有者を取得者とみなして、これに対して不動産取得税を課する。"],"correct":0,"explain":"①对（答案）。这是不动产取得税的免税点（地方税法73条の15の2第1项）：土地取得16万日元未满、家屋建筑取得每户66万日元未满、其他情形每户34万日元未满时，一律不课税。这三个数字要分开记，容易被出题者拿16万/66万/34万相互调换来出错。②错。新住宅1,200万日元控除只适用于床面积40㎡以上240㎡以下的情形（地方税法73条の14第1项）。本题床面积250㎡，已经超过240㎡上限，不适用这项控除。③错。宅地取得的不动产取得税课税标准，是宅地价格的1/2（地方税法附则11条の5），不是\\"1/4\\"——选项把分母写错了。④错。家屋新建后6个月（不是2年）经过仍未被最初使用或转让时，就以6个月经过之日视为家屋取得日，向当时的所有者课税（地方税法73条の2第2项但书）。选项把法定期限\\"6个月\\"错写成了\\"2年\\"。","takeaway":"免税点三个数字——土地16万、建筑家屋66万、其他家屋34万，别记混；新住宅1,200万控除的面积区间是40㎡～240㎡，超过240㎡就没有了；宅地课税标准是价格的1/2，不是1/4；家屋新建后6个月未使用/转让就视为已取得，不是2年。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-25', '{"id":"r06-25","tag":"不动产价格评定・不动产鉴定评价基准","title":"令和6年 問25","stem":"不動産の鑑定評価に関する次の記述のうち、不動産鑑定評価基準によれば、誤っているものはどれか。","options":["同一需給圏とは、一般に対象不動産と代替関係が成立して、その価格の形成について相互に影響を及ぼすような関係にある他の不動産の存する圏域をいう。","対象不動産について、依頼目的に応じ対象不動産に係る価格形成要因のうち地域要因又は個別的要因について想定上の条件を設定する場合がある。","不動産の価格は、その不動産の効用が最高度に発揮される可能性に最も富む使用を前提として把握される価格を標準として形成されるが、これを適合の原則という。","収益還元法は、対象不動産が将来生み出すであろうと期待される純収益の現在価値の総和を求めることにより対象不動産の試算価格を求める手法であり、賃貸用不動産又は賃貸以外の事業の用に供する不動産の価格を求める場合に特に有効である。"],"correct":2,"explain":"这道题考的是\\"最有効使用の原則\\"（最有效使用原则）和\\"適合の原則\\"（适合原则）这两个名词，容易被出题者故意调换。①对（不是错误项）。同一需给圈的定义正确——指与对象不动产存在替代关系、价格形成上相互影响的其他不动产所在的圈域。②对（不是错误项）。根据鉴定评价的委托目的，可以对地域要因或个别要因设定想定上的条件——这是被允许的做法（比如假设某种规划变更后进行评估）。③错（答案）。这里把\\"最有效使用的原则\\"和\\"适合的原则\\"搞混了。不动产价格是以效用发挥到最高程度的使用方式为前提来把握的，这叫\\"最有效使用的原则\\"（鉴定评价基准4章Ⅳ），不是\\"适合的原则\\"。\\"适合的原则\\"讲的是另一件事：不动产的收益性或舒适性要发挥到最高程度，前提是该不动产必须适合其所处的环境（鉴定评价基准4章Ⅸ）——这是两个不同的原则，选项张冠李戴了。④对（不是错误项）。收益还元法的定义正确——通过求取对象不动产将来预期产生的纯收益现值总和来试算价格（包含直接还元法和DCF法两种），这个方法对赁贷用不动产或以事业为目的使用的不动产尤其有效。","takeaway":"最有効使用の原則＝以效用最大化的使用方式作为价格判断的标准；適合の原則＝不动产要适合周边环境，收益性/舒适性才能最大化——两者定义经常被张冠李戴地互换，看到\\"效用最高度发挥\\"这个描述，第一反应要对应\\"最有效使用\\"，不是\\"适合\\"。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-37', '{"id":"h25-37","tag":"宅地建物取引业法等・报酬（个数问题）","title":"平成25年 問37","stem":"宅地建物取引業者Ａ社（消費税課税事業者）は売主Ｂから土地付建物の売却の代理の依頼を受け、宅地建物取引業者Ｃ社（消費税課税事業者）は買主Ｄから戸建住宅の購入の媒介の依頼を受け、ＢとＤの間で売買契約を成立させた。この場合における次の記述のうち、宅地建物取引業法の規定に違反しないものはいくつあるか。なお、土地付建物の代金は5,500万円（うち、土地代金は2,200万円）で、消費税額及び地方消費税額を含むものとする。\\nア　Ａ社はＢから3,600,000円の報酬を受領し、Ｃ社はＤから1,790,000円の報酬を受領した。\\nイ　Ａ社はＢから2,200,000円の報酬を受領し、Ｃ社はＡ社及びＤの了承を得た上でＤから1,370,000円の報酬を受領した。\\nウ　Ａ社はＢから1,660,000円の報酬を受領し、Ｃ社はＤから1,669,500円を報酬として受領したほか、Ｄの特別の依頼に基づき行った遠隔地への現地調査に要した特別の費用について、Ｄが事前に負担を承諾していたので、50,000円を受領した。","options":["一つ","二つ","三つ","なし"],"correct":0,"explain":"先算三个报酬上限基准：土地付建物代金5,500万（税込）拆分——土地不含税=2,200万；建筑物含税部分=5,500万-2,200万=3,300万，还原税前=3,300万÷1.1=3,000万，物件税前总价=2,200万+3,000万=5,200万。媒介方（C社）报酬上限：（5,200万×3%+6万）×1.1=1,782,000円。代理方（A社）报酬上限：媒介的2倍=3,564,000円。两者合计报酬上限：3,564,000円（不能因为是两家公司分别收就把上限叠加两次）。ア违反：A社收360万＞代理上限356.4万，C社收179万＞媒介上限178.2万——两边都超了。イ违反：A社收220万（未超356.4万，OK）、C社收137万（未超178.2万，OK），但两者相加220万+137万=357万，超过了两者合计上限356.4万——单独看都合格，合计超标一样违规。ウ不违反：A社收166万（OK）、C社收166.95万（OK），两者合计332.95万，未超合计上限356.4万，完全合格。另外C社额外收取的5万日元，是依买方D的特别依赖赴远地现场调查产生的实费，且D事先承诺负担——这属于\\"依赖者特别依赖产生的费用\\"，可以在报酬上限之外另行收取，不算违规。所以违反宅建业法的是ア、イ，不违反的只有ウ一个，正解\\"一つ\\"。","takeaway":"报酬计算基准是税前物件价格，土地本身不含税、建筑物部分要把税抽出来还原；代理方上限=媒介方上限×2；多个业者分别收报酬时，合计不能超过\\"代理方的上限\\"（单独达标不代表合计达标，这是最容易踩的坑）；依赖者特别依赖产生的费用（如远地现场调查实费）可以在报酬上限外另行收取，前提是依赖者事先承诺负担。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-26', '{"id":"h26-26","tag":"宅地建物取引业法等・免许要否（个数问题）","title":"平成26年 問26","stem":"宅地建物取引業の免許（以下この問において「免許」という。）に関する次の記述のうち、宅地建物取引業法の規定によれば、正しいものはいくつあるか。\\nア　Ａの所有する商業ビルを賃借しているＢが、フロアごとに不特定多数の者に反復継続して転貸する場合、ＡとＢは免許を受ける必要はない。\\nイ　宅地建物取引業者Ｃが、Ｄを代理して、Ｄの所有するマンション（30戸）を不特定多数の者に反復継続して分譲する場合、Ｄは免許を受ける必要はない。\\nウ　Ｅが転売目的で反復継続して宅地を購入する場合でも、売主が国その他宅地建物取引業法の適用がない者に限られているときは、Ｅは免許を受ける必要はない。\\nエ　Ｆが借金の返済に充てるため、自己所有の宅地を10区画に区画割りして、不特定多数の者に反復継続して売却する場合、Ｆは免許を受ける必要はない。","options":["一つ","二つ","三つ","なし"],"correct":0,"explain":"宅建业判断口诀：自己作为当事者做\\"贷借\\"不算宅建业；自己作为当事者做\\"买卖\\"、以及\\"媒介・代理\\"（无论买卖还是贷借）都算宅建业。ア对：A把楼租给B，B又转租出去——A和B都是自己作为当事者做贷借（A是原始出租，B是转租出租），两人都不需要免许。イ错：D是自己所有的マンション要分讓（卖）给不特定多数人，属于自己作为当事者做买卖，当然算宅建业，D需要免许——即使找业者C做代理，D自己的免许义务不会因此消失。ウ错：买入宅地这个行为本身，只要是\\"业\\"（不特定多数、反复继续），也算宅建业（宅建业法对\\"卖\\"和\\"买\\"一视同仁）——E需要免许。国家/地方公共团体作为卖方本身不适用宅建业法（78条1项）没错，但这不代表买方E就能因此免除自己的免许义务，选项混淆了\\"对方不适用法律\\"和\\"自己不需要免许\\"这两件事。エ错：F把自己的宅地区划成10块卖给不特定多数人——不管卖地是为了什么目的（还债/投资/其他），只要构成\\"业\\"，F就需要免许，目的是还债这一点跟结论完全无关。正确的只有ア一个，正解\\"一つ\\"。","takeaway":"\\"自己做贷借（含转租）\\"永远不算宅建业，不需要免许；但凡\\"自己做买卖\\"，不管买还是卖、不管理由是什么（还债/投资），只要构成业，就需要免许；委托代理/媒介只是换个人去操作，不能替委托人本人免除免许义务；对方是国家等免适用主体，不代表自己也免适用。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-4', '{"id":"h30-4","tag":"权利关系・条件期间时效","title":"平成30年 問4","stem":"時効の援用に関する次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["消滅時効完成後に主たる債務者が時効の利益を放棄した場合であっても、保証人は時効を援用することができる。","後順位抵当権者は、先順位抵当権の被担保債権の消滅時効を援用することができる。","詐害行為の受益者は、債権者から詐害行為取消権を行使されている場合、当該債権者の有する被保全債権について、消滅時効を援用することができる。","債務者が時効の完成の事実を知らずに債務の承認をした場合、その後、債務者はその完成した消滅時効を援用することはできない。"],"correct":1,"explain":"【核心知识点】谁有资格援用消灭时效——必须是因时效消灭而直接受益的人，间接受益不算数。①对（不是错误项）。保证人的时效援用权是独立的——主债务人自己放弃时效利益，不代表保证人也跟着放弃，保证人依然可以自己援用消灭时效。②错（答案）。后顺位抵当权人对先顺位抵当权担保债权的时效消灭，只有间接利益（先顺位没了，自己顺位往前提），不是直接摆脱责任，所以不能援用（最判平11.10.21）。③对（不是错误项）。诈害行为受益者因债权人的被保全债权时效消灭，能直接免于被撤销交易，属于直接受益，可以援用。④对（不是错误项）。不知道时效已完成就做了承认（如偿还部分债务），基于诚信原则，之后不能反悔再主张援用。","takeaway":"能不能援用时效，就问一句——这个人是不是因为时效消灭而直接甩掉责任？直接甩掉责任的（保证人、诈害受益人等）能援用；只是间接沾光的（后顺位抵当权人）不能援用。绝对效的援用权判断标准：直接受益 vs 间接受益。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-7', '{"id":"h30-7","tag":"权利关系・债权总则","title":"平成30年 問7","stem":"債権譲渡に関する次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["譲渡制限の意思表示のある債権の譲渡を受けた第三者が、その特約の存在を知らなかったとしても、知らなかったことにつき重大な過失があれば、債務者は、その債務の履行を拒むことができる。","債権の譲受人が譲渡制限の意思表示の存在を知っていれば、さらにその債権を譲り受けた転得者がその意思表示の存在を知らなかったことにつき重大な過失がなかったとしても、債務者はその転得者に対して、債務の履行を拒むことができる。","譲渡禁止特約に反して債権を譲渡した債権者は、債務者に譲渡の無効を主張する意思があることが明らかである等の事情があっても、その特約の存在を理由に、譲渡の無効を主張することができない。","譲渡制限の意思表示のある債権をもって質権の目的とした場合において、質権者がその意思表示の存在について悪意であるときは、債務者は質権者に対して債務の履行を拒むことができる。"],"correct":1,"explain":"【核心知识点】让渡制限特约下，判断能否对抗某个持有债权的人，关键要看这个人本人（不是他的前手）是善意无重过失、还是恶意/重大过失——这个判断标准要逐层单独适用。①对（不是错误项）。第三者虽不知道让渡制限特约，但如果属于重大过失导致不知道，视同恶意处理，债务人依然可以拒绝履行。②错（答案）。判断能否对抗转得者，看的是转得者本人是否善意无重过失，不是看前手（最初受让人）是否恶意——本肢把前手恶意当成判断转得者的标准，逻辑错了，转得者若自己是善意无重过失，依然能有效取得债权、对抗债务人。③对（不是错误项）。违反让渡制限特约转让债权后，债权者自己已经失去了债权，没有资格再向债务人请求履行。④对（不是错误项）。让渡制限特约的规则同样适用于质权设定：质权人明知特约存在（恶意）时，债务人可以拒绝向质权人履行。","takeaway":"让渡制限特约下，能否对抗某人要看这个人本人（不是前手）是否善意无重过失——这个判断标准要逐层单独适用，不能因为最初受让人是恶意，就推定后面的转得者也不能对抗债务人。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02-10-7', '{"id":"r02-10-7","tag":"权利关系・债权总则","title":"令和2年10月 問7","stem":"保証に関する次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。なお、保証契約は令和2年4月1日以降に締結されたものとする。","options":["特定物売買における売主の保証人は、特に反対の意思表示がない限り、売主の債務不履行により契約が解除された場合には、原状回復義務である既払代金の返還義務についても保証する責任がある。","主たる債務の目的が保証契約の締結後に加重されたときは、保証人の負担も加重され、主たる債務者が時効の利益を放棄すれば、その効力は連帯保証人に及ぶ。","委託を受けた保証人が主たる債務の弁済期前に債務の弁済をしたが、主たる債務者が当該保証人からの求償に対して、当該弁済日以前に相殺の原因を有していたことを主張するときは、保証人は、債権者に対し、その相殺によって消滅すべきであった債務の履行を請求することができる。","委託を受けた保証人は、履行の請求を受けた場合だけでなく、履行の請求を受けずに自発的に債務の消滅行為をする場合であっても、あらかじめ主たる債務者に通知をしなければ、同人に対する求償が制限されることがある。"],"correct":1,"explain":"【核心知识点】保证的附从性是单向的——主债务变重，保证人不会跟着变重（保护保证人）；但主债务变轻，保证人会跟着变轻。①对（不是错误项）。特定物买卖中卖方的保证人，保证范围延伸到契约解除后的原状回复义务（返还已收货款），判例明确认定（最判昭40.6.30）。②错（答案）。主债务的内容在保证契约缔结之后被加重，保证人的负担不会跟着加重；主债务人放弃时效利益，这个效果也不会波及保证人（含连带保证人）——两处都说反了。③对（不是错误项）。受托保证人在主债务清偿期之前就先还了债，如果主债务人本来在那之前就对债权人享有可以相殺的理由，保证人可以向债权人主张那部分本该被抵消掉的债务不用再实际清偿（民法459条の2第3项）。④对（不是错误项）。受托保证人不管是被动应求还是主动清偿，都要事先通知主债务人——不通知的话，主债务人可以拿自己本来对债权人有的抗辩来对抗保证人的求偿（民法463条1项）。","takeaway":"保证的附从性是片面的——主债务变重不影响保证人，主债务变轻保证人跟着变轻；主债务人放弃时效利益是他个人的处分行为，效力不会波及保证人；受托保证人有清偿前必须通知主债务人的义务，不管被动还是主动清偿都适用。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h29-8', '{"id":"h29-8","tag":"权利关系・债权总则","title":"平成29年 問8","stem":"Ａ、Ｂ、Ｃの3人がＤに対して900万円の連帯債務を負っている場合に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。なお、Ａ、Ｂ、Ｃの負担部分は等しいものとする。","options":["ＤがＡに対して履行の請求をした場合、Ｂ及びＣがそのことを知らなくても、Ｂ及びＣについては、その効力が生じる。","Ａが、Ｄに対する債務と、Ｄに対して有する200万円の債権を対当額で相殺する旨の意思表示をＤにした場合、Ｂ及びＣのＤに対する連帯債務も200万円が消滅する。","Ｂのために時効が完成した場合、Ａ及びＣのＤに対する連帯債務も時効によって一部消滅する。","ＣがＤに対して100万円を弁済した場合は、Ｃの負担部分の範囲内であるから、Ｃは、Ａ及びＢに対して求償することはできない。"],"correct":1,"explain":"【核心知识点】连带债务里，绝对效只有相殺・更改・混同这三个，其余（含履行请求、时效完成）新民法下一律相对效。①错。新民法下履行请求是相对效——D只找A要钱，B、C不知情的话，对B、C不发生效力，选项说反了。②对（答案）。相殺是绝对效——A用自己对D的200万债权抵消自己的债务，这200万对B、C的连带债务也同样消灭（民法439条1项）。③错。时效完成是相对效——B自己的债务时效完成，不影响A、C，A、C依然要对D负900万连带责任，不会部分消灭。④错。连带债务人只要有清偿，不管金额是否超过自己的负担部分，都可以在清偿额范围内立即向其他连带债务人求偿（民法442条1项）——不需要等到清偿超过自己负担部分才能求偿。","takeaway":"连带债务绝对效只有相殺、更改、混同三个，记住这三个就够了。除此之外（履行请求、时效完成、时效利益放弃等）新民法下一律相对效。求偿权不需要清偿额超过自己负担部分才能主张，有清偿就能立即求偿。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r01-12', '{"id":"r01-12","tag":"权利关系・借地借家法(建物)","title":"令和元年 問12","stem":"ＡがＢに対し、Ａ所有の甲建物を３年間賃貸する旨の契約をした場合における次の記述のうち、民法及び借地借家法の規定によれば、正しいものはどれか（借地借家法第39条に定める取壊し予定の建物の賃貸借及び同法第40条に定める一時使用目的の建物の賃貸借は考慮しないものとする。）。","options":["ＡＢ間の賃貸借契約について、契約の更新がない旨を定めるには、公正証書による等書面によって契約すれば足りる。","甲建物が居住の用に供する建物である場合には、契約の更新がない旨を定めることはできない。","ＡがＢに対して、期間満了の３月前までに更新しない旨の通知をしなければ、従前の契約と同一の条件で契約を更新したものとみなされるが、その期間は定めがないものとなる。","Ｂが適法に甲建物をＣに転貸していた場合、Ａは、Ｂとの賃貸借契約が解約の申入れによって終了するときは、特段の事情がない限り、Ｃにその旨の通知をしなければ、賃貸借契約の終了をＣに対抗することができない。"],"correct":3,"explain":"【核心知识点】定期建物赁贷借的成立要件（书面契约+另行书面说明两步骤）、法定更新的不通知期限（1年前~6个月前）、转租情形下贷主对转租人的对抗要件（须通知，通知后6个月生效），三个独立考点组合出题。①错。定期建物赁贷借要有效成立，不是书面契约就够了——除了书面契约本身，贷主还必须另行用书面向承租人交付说明没有更新、期满即终止这件事（借地借家法38条1项、3项）。②错。定期建物赁贷借的成立没有用途限制——居住用建筑物同样可以签定期建物赁贷借契约。③错。法定更新的不通知期限是期满前1年到6个月之间，不是3个月前（借地借家法26条1项）。④对（答案）。建筑物已经适法转租给C的情况下，A要主张跟B之间的契约因解约申告而终了这件事对抗转租人C，必须通知C，通知后6个月转贷借才跟着终了（借地借家法34条）。","takeaway":"定期建物赁贷借=书面契约+另行书面说明两步骤，不是一步到位；不通知更新拒绝的期限是1年前~6个月前这个区间；贷主跟原承租人的契约解约终了，要主张能对抗转租人，必须专门通知转租人，通知后6个月生效。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h23-14', '{"id":"h23-14","tag":"权利关系・不动产登记法","title":"平成23年 問14","stem":"不動産の登記に関する次の記述のうち、誤っているものはどれか。","options":["所有権の登記がない土地と所有権の登記がある土地との合筆の登記は、することができない。","権利の変更の登記又は更正の登記は、登記上の利害関係を有する第三者の承諾がある場合及び当該第三者がない場合に限り、付記登記によってすることができる。","受益者又は委託者は、受託者に代わって信託の登記を申請することができる。","仮登記の抹消は、登記権利者及び登記義務者が共同しなければならない。"],"correct":3,"explain":"【核心知识点】不动产登记法中共同申请原则的各种例外——默认规则是登记要登记权利者+登记义务者共同申请（不动产登记法60条），但法律针对特定场景开了很多单独申请的口子。①对（不是错误项）。有权利部（所有权登记）的土地和没有权利部的土地不能合并登记——权利部有无不一致导致的限制。②对（不是错误项）。权利变更/更正登记，有利害关系第三者时需承诺才能用附记登记，没有第三者时当然可以用附记登记。③对（不是错误项）。信托登记原则上由受托者申请，但受益者或委托者也可以代替受托者申请（不动产登记法99条）。④错（答案）。假登记的抹消原则上是共同申请，但法律明确规定了单独申请的例外——假登记名义人可以单独申请（不动产登记法110条前段），登记上的利害关系人在获得假登记名义人承诺后也可以单独申请（同条后段）。选项说必须共同，把这两个单独申请的例外通道完全抹去了。","takeaway":"假登记的抹消，除了共同申请，还有假登记名义人单独申请、利害关系人经名义人承诺单独申请这两条例外通道——碰到\\"XX登记必须共同申请\\"这种绝对化表述要多留意，很可能是出题陷阱。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03-10-22', '{"id":"r03-10-22","tag":"法令上的制限・国土利用计画法","title":"令和3年10月 問22","stem":"国土利用計画法第23条の届出（以下この問において「事後届出」という。）に関する次の記述のうち、正しいものはどれか。なお、この問において「都道府県知事」とは、地方自治法に基づく指定都市にあってはその長をいうものとする。","options":["土地売買等の契約を締結した場合には、当事者のうち当該契約による権利取得者は、その契約を締結した日の翌日から起算して３週間以内に、事後届出を行わなければならない。","都道府県知事は、事後届出をした者に対し、その届出に係る土地に関する権利の移転若しくは設定後における土地の利用目的又は土地に関する権利の移転若しくは設定の対価の額について、当該土地を含む周辺の地域の適正かつ合理的な土地利用を図るために必要な助言をすることができる。","事後届出が必要な土地売買等の契約を締結したにもかかわらず、所定の期間内に当該届出をしなかった者は、都道府県知事からの勧告を受けるが、罰則の適用はない。","宅地建物取引業者Ａが所有する準都市計画区域内の20,000㎡の土地について、10,000㎡をＢ市に、10,000㎡を宅地建物取引業者Ｃに売却する契約を締結した場合、Ｂ市は事後届出を行う必要はないが、Ｃは一定の場合を除き事後届出を行う必要がある。"],"correct":3,"explain":"【核心知识点】事后申报制度的四个独立知识点——申报期限、劝告助言对象、罚则适用条件、一团土地的判断基准。①错。事后申报期限是契约缔结之日起算2周内，不是翌日起算3周——起算点和期限数字两处都错。②错。事后申报要申报利用目的和对价额两项，但知事的助言/审查/劝告只限于利用目的，对价额不能被助言（国土法27条の2）。③错。没在期限内申报的人直接构成犯罪，处6个月以下拘禁刑或100万日元以下罚金——不存在先劝告再罚这个流程，劝告只适用于已经申报但利用目的不当的情形，对压根没申报的人是直接罚则（国土法47条1号）。④对（答案）。一团土地是否需要申报要看权利取得者一方，B市和C各取得10000㎡。当事人一方是国等（含市町村）时不需要申报，所以B市取得部分不需要；C是宅建业者，准都市计画区域面积门槛是1万㎡以上，C取得的10000㎡正好达标，需要申报。","takeaway":"事后申报期限是契约缔结之日起2周内（不是翌日起、也不是3周）；知事的助言/劝告对象只限利用目的，价格不在此列；没申报的人直接构成犯罪，不是先劝告再罚；一团土地要按权利取得者判断，关键看买方是谁、买方拿到多少面积。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03-10-17', '{"id":"r03-10-17","tag":"法令上的制限・建筑基准法","title":"令和3年10月 問17","stem":"建築基準法に関する次の記述のうち、正しいものはどれか。","options":["居室の内装の仕上げには、ホルムアルデヒドを発散させる建築材料を使用することが認められていない。","４階建ての共同住宅の敷地内には、避難階に設けた屋外への出口から道又は公園、広場その他の空地に通ずる幅員が２ｍ以上の通路を設けなければならない。","防火地域又は準防火地域内にある建築物で、外壁が防火構造であるものについては、その外壁を隣地境界線に接して設けることができる。","建築主は、３階建ての木造の共同住宅を新築する場合において、特定行政庁が、安全上、防火上及び避難上支障がないと認めたときは、検査済証の交付を受ける前においても、仮に、当該共同住宅を使用することができる。"],"correct":3,"explain":"【核心知识点】建筑基准法的四个独立数字/概念陷阱——甲醛限制等级、避难通路宽度、外墙紧贴境界线的构造要求、检查済证交付前的临时使用例外。①错。甲醛不是全面禁止使用，按危害等级分四种：第1种禁止，第2/3种按面积和换气条件限制使用，第4种（F☆☆☆☆认证）可以不受限使用。②错。4层以上特殊建筑物（含共同住宅）敷地内的避难通路宽度要求是1.5米以上，不是2米（建筑基准法35条、令125条）。③错。防火地域/准防火地域内，允许外墙紧贴邻地境界线的条件是外墙为耐火构造，不是防火构造（建筑基准法63条）——耐火构造防止建筑物内部火灾导致倒塌，防火构造防止外部火灾蔓延到建筑物，两个概念不同。④对（答案）。特定行政厅认定安全、防火、避难上没有问题时，即使还没拿到检查済证，建筑物也可以临时使用（建筑基准法7条の6第1项但书）——这是检查済证交付前使用限制的法定例外。","takeaway":"甲醛按等级区分限制，不是全面禁止；避难通路宽度是1.5米，不是2米；外墙紧贴邻地境界线要求耐火构造，不是防火构造；检查済证交付前，经特定行政厅认定后可以仮使用——这类题的出题套路是把数字和构造类型名称替换成相近但错误的版本，逐一核对是唯一应对方法。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-18', '{"id":"r07-18","tag":"法令上的制限・建筑基准法","title":"令和7年 問18","stem":"次の記述のうち、建築基準法（以下この問において「法」という。）の規定によれば、正しいものはどれか。","options":["都市再生特別地区内においては、建築物の容積率、建蔽率及び建築面積は当該地区に関する都市計画において定められた内容に適合するものでなければならないが、その高さは法第56条の高さの制限に関する規定に適合させる必要がある。","２階建てかつ床面積1,000㎡の飲食店は、第一種低層住居専用地域、第二種低層住居専用地域、第一種中高層住居専用地域、工業専用地域及び田園住居地域に建築することができない。","特定行政庁による認可を受けて公告された建築協定は、その後、当該協定の土地の所有者等の全員で合意したときに限り、その公告のあった日以後において当該建築協定区域内の土地の所有者等となった者に対しても効力が及ぶこととなる。","建築物のエネルギー消費性能の向上のため必要な外壁等に関する工事を行う場合、公益性が高いことから特定行政庁の許可を受けることなく、法第52条の規定による容積率の限度を超えることができる。"],"correct":1,"explain":"【核心知识点】这是官方公认的超难题（正解率约25%），涉及四个完全独立的建筑基准法冷门考点。①错。都市再生特别地区内，容积率、建蔽率、建筑面积以及高度都按该地区的都市计画规定，不需要另外符合法56条的高度限制（斜线限制）（建筑基准法60条の2）。②对（答案）。2层1000㎡的饮食店在题目列出的五个用途地域全部不能建：低层住居专用系（限150㎡以下+2层以下+住居兼用）、第一种中高层住居专用地域（限500㎡以下）、工业专用地域（原则禁止店铺・饮食店）、田园住居地域（比照低层住居专用系限制）——1000㎡全部超标或被禁止。③错。建筑协定经认可公告后，对公告之后新成为该区域土地所有者的人，效力是自动适用的（承继效），不需要全员另行合意这个条件（建筑基准法75条）——选项凭空加了一个不存在的前提条件。④错。为提升建筑物能源消费性能而进行的外墙等工程，必须取得特定行政厅的许可才能超过容积率限制，不是因公益性高而无需许可。","takeaway":"都市再生特别地区内高度也按都市计画规定，不额外受法56条限制；用途地域内店铺/饮食店的面积上限要逐个地域记（低层150㎡、中高层500㎡、工业专用原则禁止、田园比照低层）；建筑协定的承继效是自动的，不需要额外经全员同意；容积率突破必须经特定行政厅许可，不存在公益性高就自动豁免的规则。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h27-19', '{"id":"h27-19","tag":"法令上的制限・盛土规制法","title":"平成27年 問19","stem":"宅地造成及び特定盛土等規制法に関する次の記述のうち、誤っているものはどれか。なお、この問において「都道府県知事」とは、地方自治法に基づく指定都市、中核市及び施行時特例市にあってはその長をいうものとする。","options":["都道府県知事は、宅地造成等工事規制区域内の土地について、宅地造成等に伴う災害を防止するために必要があると認める場合には、その土地の所有者に対して、擁壁等の設置等の措置をとることを勧告することができる。","宅地造成等工事規制区域の指定の際に、当該宅地造成等工事規制区域内において宅地造成等工事を行っている者は、当該工事について改めて都道府県知事の許可を受けなければならない。","宅地造成等に関する工事の許可を受けた者が、工事施行者を変更する場合には、遅滞なくその旨を都道府県知事に届け出ればよく、改めて許可を受ける必要はない。","宅地造成等工事規制区域内において、宅地を造成するために切土をする土地の面積が500㎡であって盛土が生じない場合、切土をした部分に生じる崖の高さが1.5ｍであれば、都道府県知事の許可は必要ない。"],"correct":1,"explain":"【核心知识点】区域指定时既有工程的处理方式——很多人直觉认为划入规制区域后正在做的工程也得重新申请许可，但法律为避免在建工程被迫中断造成过大损失，特意设计成申报制。①对（不是错误项）。知事对规制区域内土地，认定有必要防止灾害时，可以劝告所有者采取设置挡土墙等措施。②错（答案）。区域指定时正在进行的工程，不需要重新取得许可，只需要在指定之日起21日内向知事申报即可，法律考虑到要求已开工的工程重新取得许可会造成停工等过大不利益，所以对既有工程采用申报制而不是许可制（盛土规制法21条1项）。③对（不是错误项）。变更工程施工者属于轻微变更，只需要无迟延申报，不需要重新取得许可（施行规则38条1项1号）。④对（不是错误项）。需要许可的土地形质变更门槛是切土超过2米，或切土/盛土面积超过500㎡——本题切土面积正好500㎡（未超过500㎡）、崖高1.5米（未超过2米），都没有超出门槛，所以不需要许可（盛土规制法施行令3条）。","takeaway":"区域指定时既有工程适用申报制（21日内申报即可），不是许可制——看到区域指定时已经在做的工程还要重新许可这种说法，基本可以判断是错误陷阱。面积/高度门槛用词是超过，数字刚好等于门槛值时没有超过，不需要许可——这种卡在门槛线上的数字设计也是常见考点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02-10-20', '{"id":"r02-10-20","tag":"法令上的制限・土地区画整理法","title":"令和2年10月 問20","stem":"土地区画整理組合に関する次の記述のうち、土地区画整理法の規定によれば、正しいものはどれか。","options":["組合の設立認可を申請しようとする者は、施行地区となるべき区域内の宅地について借地権を有するすべての者の３分の２以上の同意を得なければならないが、未登記の借地権を有する者の同意を得る必要はない。","組合の総会の会議は、定款に特別な定めがある場合を除くほか、組合員の半数以上が出席しなければ開くことができない。","組合が賦課金を徴収する場合、賦課金の額は、組合員が施行地区内に有する宅地又は借地の地積等にかかわらず一律に定めなければならない。","組合の施行する土地区画整理事業に参加することを希望する者のうち、当該土地区画整理事業に参加するのに必要な資力及び信用を有する者であって定款で定められたものは、参加組合員として組合員となる。"],"correct":1,"explain":"【核心知识点】土地区划整理组合的四个独立细节考点——未登记借地权人的同意资格、总会开会门槛、赋课金分摊原则、参加组合员的资格限定。①错。设立认可需要施行区域内所有宅地及借地权人各自2/3以上同意，未登记的借地权人也算数（只要自行申告即可成为组合员/取得同意资格）——选项说不需要未登记者同意是错的。②对（答案）。组合总会会议原则上需要组合员半数以上出席才能开，定款有特别规定的除外。③错。赋课金的额度不需要一律相同，应根据组合员在施行区域内所有的宅地/借地的地积等、按受益程度分摊。④错。想参加组合施行的土地区划整理事业，不是只要有资力信用+定款规定了就自动成为组合员——参加组合员限定为地方住宅供给公社等特定的公的机构类主体，不是任意有资力信用的一般人。","takeaway":"未登记的借地权人同样算数，不能因为没登记就被排除在同意计算之外；总会开会门槛是组合员半数以上出席；赋课金不能一律相同，要按各组合员实际持有的地积等分摊；参加组合员的资格有主体限定（地方住宅供给公社等特定机构），不是任何有资力信用的人都行。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-21', '{"id":"r06-21","tag":"法令上的制限・农地法","title":"令和6年 問21","stem":"農地に関する次の記述のうち、農地法（以下この問において「法」という。）の規定によれば、誤っているものはどれか。","options":["法第３条第１項の許可があったときは所有権が移転する旨の停止条件付売買契約を原因とする所有権移転の仮登記の申請を行う場合にも、農業委員会の許可が必要である。","法第５条第１項の許可申請書の提出において、法ではその申請に係る権利の設定又は移転に関し民事調停法により調停が成立した場合など一定の場合を除き、当事者は連署した申請書を提出しなければならないとされている。","法では、農地の賃貸借で期間の定めがあるものについては、一定の場合を除き、期間満了の１年前から６か月前までの間に更新拒絶の通知をしないと従前の賃貸借と同一の条件で更に賃貸借したものとみなされる。","法では、農地の賃貸借の当事者は、当該賃貸借の合意による解約が民事調停法による農事調停によって行われる場合など一定の場合を除き、知事の許可を受けなければ、当該賃貸借について、解除、解約の申入れ、合意解約、更新拒絶の通知をしてはならないとされている。"],"correct":0,"explain":"【核心知识点】混淆了假登记和本登记的许可要件——难题，正解率仅37.0%。①错（答案）。以取得3条许可后所有权才移转这种停止条件付契约为原因申请假登记时，不需要另外取得农业委员会的许可——申请了权利移转的许可就足够了，假登记本身是为了在正式许可下发前先占住登记顺位，不是又一道许可关卡。②对（不是错误项）。5条许可（转用+权利移转）的申请书，原则上需要当事人连署提交，但通过民事调停法调停成立等特定情形除外。③对（不是错误项）。有期限的农地赁贷借，若不在期满前1年~6个月之间通知拒绝更新，就视为按原条件法定更新（农地法17条）。④对（不是错误项）。农地赁贷借的当事人要解除、解约申告、合意解约、更新拒绝通知，原则上都需要知事许可，通过农事调停等特定情形除外（农地法18条1项）。","takeaway":"本登记（真正让所有权移转生效）必须先取得3条许可；但假登记只是为了先占住登记顺位、防止第三方抢先登记的临时手段，依附于已经申请许可这个事实，本身不需要再取得一次许可——把许可要件错误套用到假登记这个不同行为上是本题陷阱；农地赁贷借还有法定更新期限（1年前~6个月前）+解约需知事许可（18条）两个独立规则要记牢。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h27-23', '{"id":"h27-23","tag":"税相关法令・赠与税","title":"平成27年 問23","stem":"「直系尊属から住宅取得等資金の贈与を受けた場合の贈与税の非課税」に関する次の記述のうち、正しいものはどれか。","options":["直系尊属から住宅用の家屋の贈与を受けた場合でも、この特例の適用を受けることができる。","日本国外に住宅用の家屋を新築した場合でも、この特例の適用を受けることができる。","贈与者が住宅取得等資金の贈与をした年の１月１日において60歳未満の場合でも、この特例の適用を受けることができる。","受贈者について、住宅取得等資金の贈与を受けた年の所得税法に定める合計所得金額が2,000万円を超える場合でも、この特例の適用を受けることができる。"],"correct":2,"explain":"【核心知识点】直系尊属住宅资金赠与税非课税特例的四个适用要件——标的物、房屋所在地、赠与者年龄限制、受赠者所得限制。①错。这个特例适用的对象是住宅取得等资金（钱）的赠与，不是住宅用家屋本身的赠与——选项把赠与标的物搞混了，直接赠与房子本身不适用这项特例。②错。特例要求新建/取得的住宅用家屋必须在日本国内，国外的房屋不适用。③对（答案）。这个特例对赠与者的年龄没有限制——不像其他一些赠与税特例（比如相続時精算课税制度）要求赠与者60岁以上，赠与者不管几岁都可以适用（租税特别措置法70条の2第1项）。④错。受赠者（拿钱的人）的合计所得金额必须2000万日元以下才能适用这个特例，超过2000万日元就不能用（租税特别措置法70条の2第2项1号）。","takeaway":"标的物必须是资金，不是房子本身；房子必须在日本国内；赠与者年龄没有限制（这是本题正确项，也是最容易被误以为有年龄限制的地方）；受赠者的所得金额要求2000万日元以下——记忆口诀：赠者不限龄，受者限所得，标的须是钱，房子须在国内。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02-10-25', '{"id":"r02-10-25","tag":"不动产价格评定・不动产鉴定评价基准","title":"令和2年10月 問25","stem":"不動産の鑑定評価に関する次の記述のうち、不動産鑑定評価基準によれば、誤っているものはどれか。","options":["不動産の価格は、その不動産の効用が最高度に発揮される可能性に最も富む使用を前提として把握される価格を標準として形成されるが、不動産についての現実の使用方法は当該不動産が十分な効用を発揮していない場合があることに留意すべきである。","対象建築物に関する工事が完了していない場合でも、当該工事の完了を前提として鑑定評価を行うことがある。","特殊価格とは、一般的に市場性を有しない不動産について、その利用現況等を前提とした不動産の経済価値を適正に表示する価格をいい、例としては、文化財の指定を受けた建造物について、その保存等に主眼をおいた鑑定評価を行う場合において求められる価格があげられる。","原価法は、対象不動産が建物及びその敷地である場合において、再調達原価の把握及び減価修正を適切に行うことができるときに有効な手法であるが、対象不動産が土地のみである場合には、この手法を適用することはできない。"],"correct":3,"explain":"【核心知识点】原价法的适用范围——很多人直觉认为土地单独不能用原价法，实际只要能算出再调达原价就可以。①对（不是错误项）。不动产价格是以最有效使用为标准形成的，但要注意不动产的现实使用方法未必发挥出十足效用——这是最有效使用原则的补充说明。②对（不是错误项）。对象建筑物工程尚未完工时，鉴定评价可以以完工为前提进行——这是被允许的做法。③对（不是错误项）。特殊价格——指一般不具市场性的不动产，以其利用现况为前提表示的经济价值，比如文化财指定建筑物以保存为主眼进行评价时求得的价格——定义正确。④错（答案）。原价法不是土地本身就绝对不能用——对象不动产只是土地时，只要能把握再调达原价（比如造成地、填埋地这类可以算出造成/填埋成本的土地），依然可以适用原价法。选项把土地时不能用说得太绝对了。","takeaway":"原价法的核心不是看是不是纯土地，而是看再调达原价能不能算出来——只要能算出再调达原价（重新取得/再造成这块地要花多少钱），单独的土地（如造成地、填埋地）也可以用原价法，跟建筑物本身用原价法的逻辑一致。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-41', '{"id":"r07-41","tag":"宅地建物取引业法等・免许","title":"令和7年 問41","stem":"宅地建物取引業の免許（以下この問において「免許」という。）に関する次の記述のうち、宅地建物取引業法の規定によれば、正しいものはどれか。","options":["宅地建物取引業者A（甲県知事免許）が免許を受けてから1年以内に事業を開始しないときは、甲県知事は免許を取り消さなければならない。","宅地建物取引業者B（甲県知事免許）が株主総会の決議により解散した場合、Bを代表する役員であった者は、その旨を当該解散の日から60日以内に甲県知事に届け出なければならない。","宅地建物取引業者ではないCが甲県に本店を、乙県に支店をそれぞれ有する場合で、乙県の支店のみで新たに宅地建物取引業を営もうとするときは、Cは乙県知事の免許を受けなければならない。","宅地建物取引業者D（甲県知事免許）は、甲県の事務所を廃止し、乙県内で新たに事務所を設置して宅地建物取引業を営もうとする場合、甲県知事へ廃業の届出を行うとともに、乙県知事への免許換えの申請を行わなければならない。"],"correct":0,"explain":"【核心知识点】免许制度的四个独立细节——必要的取消事由、廃业届出期限、跨都道府県事务所的判断规则（含隐藏的本店条款）、免许换え的正确流程。①对（答案）。免许后1年以内不开始事业，或连续休止事业1年以上，属于必要的取消事由（宅建业法66条1项6号）——知事必须取消其免许，不是可以取消的裁量事项。②错。法人因股东大会决议解散时，届出期限是解散之日起30日以内，不是60日——宅建业法的廃业等届出期限一律都是30日。③错。C的事务所分布在甲県（本店）+乙県（支店）两个都道府県——即使本店本身不直接开展宅建业务，只要有任一分支机构在开展宅建业，本店依然被视为事务所。所以C的事务所跨越2个以上都道府県，需要国土交通大臣免许（经甲県知事提交申请），不是单纯的乙県知事免许。④错。D废止甲県事务所、新设乙県事务所，只需直接向乙県知事申请免许换え，取得新免许后甲県知事的原免许自动失效（宅建业法7条1项2号）——不需要另外向甲県知事提交廃业届出，这是常见的多余步骤陷阱。","takeaway":"1年不开业/连续休止1年是必要的取消（必须取消，不是可以取消）；各类廃业等届出，期限统一是30日，60日是常见的错误数字替换；本店即使不直接做宅建业，只要有分店在做，本店依然算事务所——判断是否跨都道府県最容易漏掉的隐藏规则；免许换え只需向新知事直接申请，旧免许自动失效，不需要另外向旧知事提交廃业届出。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-34', '{"id":"r07-34","tag":"宅地建物取引业法等・免许（个数问题）","title":"令和7年 問34","stem":"宅建業の免許に関する次の記述のうち、宅建業法の規定によれば、正しいものはいくつあるか。\\nア　A社の政令で定める使用人Bは、威力業務妨害の罪により、拘禁2年、執行猶予2年の刑に処せられた後、A社を退任し、新たにC社の政令で定める使用人に就任した。Bの執行猶予期間が満了していない場合に、C社が免許を申請しても、免許を受けることができない。\\nイ　D社は、不正の手段により免許を取得したことによる免許の取消処分に係る聴聞の期日及び場所が公示された日から当該処分がなされるまでの間に、宅建業法の規定による廃業の届出をした。その廃業に相当の理由がなかった場合、当該公示の日の40日前にD社の取締役を退任したEは、当該届出から5年経過しなければ、免許を申請しても免許を受けることができない。\\nウ　営業に関し成年者と同一の行為能力を有しない未成年者であるFの法定代理人であるGが、現場助勢の罪により罰金の刑に処せられていた場合、その刑の執行が終わった日から5年を経過していなくても、Fは免許を申請すれば免許を受けることができる。\\nエ　H社の政令で定める使用人Jは、裁判所へJ自身の破産申し立てを行った後、H社を退任し、裁判所から破産手続の開始決定を受けるまでの間に、新たにK社の政令で定める使用人に就任した。その後、Jが復権を得た場合、その日から5年を経過しなくても、K社が免許を申請すれば、免許を受けることができる。","options":["一つ","二つ","三つ","四つ"],"correct":2,"explain":"【核心知识点】免许欠格事由的传导和解除规则。ア对。B因威力业务妨害罪被判处拘禁2年、缓刑2年，缓刑期间未满就转任C社的政令使用人——只要该政令使用人还处于刑罚执行/缓刑未满的欠格状态，其所属法人（C社）就不能取得免许。イ对。免许取消处分听证公示日前60日内曾任该法人役员的人，若该法人因不正手段取得免许等重大事由抢先自行申报廃业（且无正当理由），该役员须等廃业届出之日起满5年才能重新申请免许——E在公示日前40日退任，落在60日门槛内，须等满5年。ウ错。F是未成年人（无同等行为能力），其法定代理人G若有欠格事由（现场助勢罪罚金刑未满5年），这个欠格事由会传导给F本人——不是F自己的行为能力问题，而是法定代理人的欠格状态直接影响F能否取得免许，选项说F依然可以取得免许是错的。エ对。J自己申请破产、在破产手续开始决定前（尚未正式进入破产程序）就转任K社的政令使用人。之后J获得复权——复权后立即解除欠格状态，不需要再等5年（这跟因刑罚导致的5年等待期不同，复权是即时生效的）。正确的有三个（アイエ）。","takeaway":"政令使用人本人处于刑罚执行/缓刑期未满的欠格状态时，会传导给其所属法人；因不正手段被取消免许的法人，其抢跑廃业的役员（公示日前60日内在任者）会被课以5年等待期；未成年人的欠格状态由其法定代理人决定，法定代理人欠格，未成年人本人也跟着欠格；复权和5年等待期是两回事，破产人一旦复权，欠格状态立即解除，不需要额外再等5年。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03-10-35', '{"id":"r03-10-35","tag":"宅地建物取引业法等・宅建士（个数问题）","title":"令和3年10月 問35","stem":"宅地建物取引士の登録（以下この問において「登録」という。）及び宅地建物取引士証に関する次の記述のうち、正しいものはいくつあるか。\\nア　宅地建物取引士（甲県知事登録）が事務禁止処分を受けた場合、宅地建物取引士証を甲県知事に速やかに提出しなければならず、速やかに提出しなかったときは10万円以下の過料に処せられることがある。\\nイ　宅地建物取引士（甲県知事登録）が宅地建物取引士としての事務禁止処分を受け、その禁止の期間中に本人の申請により登録が消除された場合は、その者が乙県で宅地建物取引士資格試験に合格したとしても、当該期間が満了していないときは、乙県知事の登録を受けることができない。\\nウ　宅地建物取引士（甲県知事登録）が甲県から乙県に住所を変更したときは、乙県知事に対し、登録の移転の申請をすることができる。\\nエ　宅地建物取引士（甲県知事登録）が本籍を変更した場合、遅滞なく、甲県知事に変更の登録を申請しなければならない。","options":["一つ","二つ","三つ","四つ"],"correct":2,"explain":"【核心知识点】宅建士登録制度的四个独立细节——宅建士证提出对象、事务禁止期间的欠格连动、登録の移転触发条件、变更登録事项。ア对。宅建士被事务禁止处分后，须速やかに向交付宅建士证的都道府県知事（本题即甲県知事）提出宅建士证——提出对象永远是交付方，不提出的话处10万日元以下过料（宅建业法22条の2第7项、86条）。イ对。在事务禁止期间内，本人申请注销登录后，即使之后在其他都道府县合格了新的考试，只要原来的事务禁止期间还没满，就不能取得新的登录（欠格要件，宅建业法18条1项11号）。ウ错。登録の移転只能在登録地以外的都道府县所在的宅建业者事务所从业这个条件下才能申请——单纯住所变更并不构成申请登録の移転的理由，选项把住所变更和从业地变更这两个不同触发条件搞混了。エ对。本籍是宅建士资格登録簿的登载事项，变更后须无迟延向甲県知事申请变更登録（宅建业法20条、18条2项）。正确的有三个（アイエ）。","takeaway":"宅建士证的提出对象是交付方知事，不是处分方；事务禁止期间内注销登录，即便重新合格考试，欠格状态也不会因此解除，要等原禁止期间满；登録の移転的唯一触发条件是去别的都道府县的宅建业者事务所工作，单纯住所变更不算；本籍变更要走变更登録这条路。区分变更登録（登録簿记载事项变了）和登録の移転（管辖知事变了）这两套不同制度。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-38', '{"id":"r07-38","tag":"宅地建物取引业法等・业务上规制（个数问题）","title":"令和7年 問38","stem":"宅建業者Ａが行う業務に関する次の記述のうち、宅建業法の規定によれば、誤っているものはいくつあるか。\\nア　宅建業者Ａは、宅地又は建物の売買に関する広告をする際に取引態様の別を明示した場合、当該広告を見た者から売買に関する注文を受けたときは、改めて取引態様の別を明示する必要はない。\\nイ　宅建業者Ａは、宅地の売買に関する広告をするに当たり、当該宅地の形質について、実際のものよりも著しく優良であると人を誤認させる表示をした場合、当該宅地に関する注文がなく、売買が成立しなかったときであっても、監督処分及び罰則の対象となる。\\nウ　宅建業者Ａは、複数の区画がある宅地の売買について、数回に分けて広告をする予定でいる場合、最初に行う広告に取引態様の別を明示すれば足り、それ以降は明示する必要はない。\\nエ　宅建業者Ａは、建物の貸借の媒介において、依頼者の依頼によらない広告をした場合、国土交通大臣の定める報酬限度額となる媒介報酬のほか、当該広告の料金に相当する額を受領できる。","options":["一つ","二つ","三つ","四つ"],"correct":2,"explain":"【核心知识点】取引态样明示义务的触发频率、夸大广告的行为犯性质、广告费另行收取的前提条件。ア错。取引态样的明示，是每次做广告和每次接到订单都要分别做——已经在广告里明示过一次，不能免除接到订单时再次明示的义务。イ对。夸大广告（著しく优良と誤認させる表示）只要做出这个广告行为本身就构成违法，不需要看是否真的成交、是否收到订单——这是行为犯，不是结果犯。ウ错。分好几次做广告，每一次都要分别明示取引态样，不能只在第一次做广告时明示、后续几次就省略。エ错。依赖者没有委托业者去做的广告，不能在报酬上限之外另行收取这笔广告费——只有依赖者主动要求做的广告才能额外收费，这里正好说反了。错误的有三个（アウエ）。","takeaway":"取引态样的明示要每次都做，不能因为之前做过就省略，无论是广告→订单这个顺序，还是分批广告这种情形，每一次接触潜在客户的动作都要重新明示；夸大广告是行为犯，做了就违法，不看结果；广告费能不能在报酬外另收，关键看是不是依赖者主动要求的——业者自己主动打广告，即便促成了交易，也不能另外收广告费。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-38', '{"id":"h30-38","tag":"宅地建物取引业法等・8种制限","title":"平成30年 問38","stem":"宅地建物取引業者である売主は、宅地建物取引業者ではない買主との間で、戸建住宅の売買契約（所有権の登記は当該住宅の引渡し時に行うものとする｡）を締結した。この場合における宅地建物取引業法第41条又は第41条の２の規定に基づく手付金等の保全措置（以下この問において「保全措置」という｡）に関する次の記述のうち、正しいものはどれか。","options":["当該住宅が建築工事の完了後で、売買代金が3,000万円であった場合、売主は、買主から手付金200万円を受領した後、当該住宅を引き渡す前に中間金300万円を受領するためには、手付金200万円と合わせて保全措置を講じた後でなければ、その中間金を受領することができない。","当該住宅が建築工事の完了前で、売買代金が2,500万円であった場合、売主は、当該住宅を引き渡す前に買主から保全措置を講じないで手付金150万円を受領することができる。","当該住宅が建築工事の完了前で、売主が買主から保全措置が必要となる額の手付金を受領する場合、売主は、事前に、国土交通大臣が指定する指定保管機関と手付金等寄託契約を締結し、かつ、当該契約を証する書面を買主に交付した後でなければ、買主からその手付金を受領することができない。","当該住宅が建築工事の完了前で、売主が買主から保全措置が必要となる額の手付金等を受領する場合において売主が銀行との間で締結する保証委託契約に基づく保証契約は、建築工事の完了までの間を保証期間とするものでなければならない。"],"correct":0,"explain":"【核心知识点】保全措施的四个独立细节——完成/未完成物件的门槛数字、保全措施方式的适用范围、保证期间的覆盖范围。①对（答案）。已完成物件免除保全措施的门槛是手付金累计≤代金10%（且≤1000万），且这个门槛按累计已收金额算——本题手付金200万+中间金300万=500万，代金3000万×10%=300万，累计已超过门槛，所以收中间金前必须把手付金和中间金一起做保全措施。②错。未完成物件免除保全措施的门槛是手付金≤代金5%（且≤1000万）——本题2500万×5%=125万，手付金150万已超过125万门槛，不能不做保全措施就收。③错。未完成物件的保全措施方式只有银行等连带保证和保险业者的保证保险两种，不包括指定保管机构保管——保管方式只适用于完成物件，本肢把保管方式错误地套用在未完成物件上。④错。银行保证委托契约的保证期间，应保证到住宅引渡し（交房）为止，不是建筑工事完了为止——工事完成了但还没交房，风险依然存在，保全的目的是保护买主到实际拿到房子那一刻。","takeaway":"完成物件门槛是10%，判断基准是累计已收金额（手付金+中间金），不是单看手付金；未完成物件门槛是5%，比完成物件更严格；保全措施方式未完成物件只能用保证/保险，不能用保管（保管专属完成物件）；保证委托契约的保证期间要覆盖到引渡为止，不是工事完成为止。四个数字/概念按完成/未完成分组记忆。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02s-45', '{"id":"r02s-45","tag":"宅地建物取引业法等・住宅瑕疵担保责任履行法","title":"令和2年12月 問45","stem":"宅地建物取引業者Ａ（甲県知事免許）が、自ら売主として宅地建物取引業者ではない買主Ｂに新築住宅を販売する場合における次の記述のうち、特定住宅瑕疵担保責任の履行の確保等に関する法律の規定によれば、正しいものはどれか。","options":["Ａが、住宅販売瑕疵担保保証金を供託する場合、当該住宅の床面積が100㎡以下であるときは、新築住宅の合計戸数の算定に当たって、２戸をもって１戸と数えることになる。","Ａは、住宅瑕疵担保責任保険法人と住宅販売瑕疵担保責任保険契約の締結をした場合、Ｂが住宅の引渡しを受けた時から10年以内に当該住宅を転売したときは、当該住宅瑕疵担保責任保険法人にその旨を申し出て、当該保険契約の解除をしなければならない。","Ａは、住宅販売瑕疵担保責任保険契約の締結をした場合、当該住宅を引き渡した時から10年間、当該住宅の構造耐力上主要な部分、雨水の浸入を防止する部分、給水設備又はガス設備の隠れた瑕疵によって生じた損害について保険金の支払を受けることができる。","住宅販売瑕疵担保責任保険契約は、新築住宅を引き渡したＡが住宅瑕疵担保責任保険法人と締結する必要があり、Ｂが保険料を支払うものではない。"],"correct":3,"explain":"【核心知识点】跟h28-45同属住宅瑕疵担保履行法，补充担保范围和契约缔结主体两个新角度。①错。合计户数2户算1户的换算门槛是床面积55㎡以下，不是100㎡以下——数字陷阱，跟h28-45是同一个考点。②错。买方B在10年内转卖住宅，不影响保险契约的效力，A不能据此向保险法人申请解约——转卖后担保责任相关权利义务由新买主承继，保险契约持续有效。③错。保险契约担保的瑕疵范围只限于构造耐力上主要部分和雨水侵入防止部分两类——给水设备或瓦斯设备的隐蔽瑕疵不在担保范围内。④对（答案）。住宅贩卖瑕疵担保责任保险契约，是卖方业者A跟保险法人缔结的，缔结主体是A不是买方B；保险费也是由A负担，不是由B支付。","takeaway":"这个板块的考点分散在好几道题里，建议把h28-45和这道题的知识点合并记忆：55㎡换算门槛、转卖不影响保险契约效力（跟h28-45重复）；担保范围只有构造耐力+防水两项，不含给排水/瓦斯；契约缔结方和付费方都是卖方业者，买方既不签约也不直接付保险费（这道题的新增角度）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-15', '{"id":"r06-15","tag":"法令上的制限・都市计画法","title":"令和6年 問15","stem":"都市計画法に関する次の記述のうち、誤っているものはどれか。","options":["都市計画区域外においても、特に必要があるときは、都市施設に関する都市計画を定めることができる。","準都市計画区域については、用途地域が定められている土地の区域であっても、市街地開発事業に関する都市計画を定めることができない。","用途地域の一つである準住居地域は、道路の沿道としての地域の特性にふさわしい業務の利便の増進を図りつつ、これと調和した住居の環境を保護するために定める地域である。","地区計画は、用途地域が定められている土地の区域についてのみ都市計画に定められるものであり、また、地区計画に関する都市計画を定めるに当たっては、地区整備計画を都市計画に定めなければならない。"],"correct":3,"explain":"【核心知识点】地区计画的适用范围——没有划用途地域的区域，只要满足特定条件依然可以规定地区计画。①对（不是错误项）。原则上都市设施在都市计画区域内规定，但特别有必要时，也可以在都市计画区域外规定。②对（不是错误项）。准都市计画区域内可以规定的都市计画种类是固定的8项，不包含市街地开发事业，即使该区域已经划了用途地域，也不能追加市街地开发事业。③对（不是错误项）。准住居地域的定义正确——在道路沿线地域特性基础上，兼顾业务便利增进和住居环境保护。④错（答案）。地区计画不是只能在已划用途地域的区域规定——没有划用途地域的区域，只要满足一定要件（如已经/正在进行的住宅市街地开发、无秩序建筑担忧区域等），同样可以规定地区计画——选项把适用范围说得过窄了。","takeaway":"地区计画的适用范围不限于已划用途地域的区域——没有划用途地域的区域，满足特定条件（住宅市街地正在开发、存在无秩序建筑风险等）依然可以规定地区计画；这跟市街地开发事业专属于都市计画区域（不包括准都市计画区域）是完全不同的两个知识点，容易被出题者组合出题制造混淆。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-20', '{"id":"r07-20","tag":"法令上的制限・土地区画整理法","title":"令和7年 問20","stem":"土地区画整理法に関する次の記述のうち、誤っているものはどれか。","options":["個人施行者は、その者以外に換地計画に係る区域内の宅地を所有する者（当該宅地の所有権について施行者に対抗することができない者を除く。）がある場合においては、換地計画について認可を申請しようとするときは、これらの者の同意を得なければならない。","国又は地方公共団体の所有する土地以外であって道路の用に供している土地については、土地区画整理事業の施行により当該道路に代わるべき道路が設置され、その結果、当該道路が廃止される場合等においては、換地計画において、当該土地について換地を定めないことができる。","従前の宅地の所有者及びその宅地について使用収益権を有する者が、仮換地について使用又は収益を開始することができる日を別に定められたため、従前の宅地について使用し、又は収益することができなくなったことにより損失を受けた場合においては、施行者は、その損失を受けた者に対して、通常生ずべき損失を補償しなければならない。","仮換地の指定があった日後、土地区画整理事業の施行による施行地区内の土地及び建物の変動に係る登記がされるまでの間は、登記の申請人が確定日付のある書類によりその指定前に登記原因が生じたことを証明した場合を除き、施行地区内の土地及び建物に関しては他の登記をすることができない。"],"correct":3,"explain":"【核心知识点】区分\\"仮换地指定\\"和\\"换地处分公告\\"这两个容易混淆的时间节点在法律效果上的差异。①对（不是错误项）。个人施行者的换地计画认可申请，需要区域内宅地所有权人（能对抗施行者的部分）同意（土地区划整理法88条1项、8条1项）。②对（不是错误项）。公共设施用途的土地（如道路），若因事业施行导致替代道路设置、原道路废止，可以在换地计画中不为该土地定换地——换地照应原则的法定例外（同法95条6项）。③对（不是错误项）。因仮换地使用收益开始日与仮换地指定效力发生日之间存在时间差，导致权利人受损时，施行者须补偿通常应生的损失（同法101条1项）。④错（答案）。本肢把限制其他登记的触发点从换地处分公告偷换成了仮换地指定——限制登记的规则前提是换地处分公告后（同法107条3项），不是仮换地指定后。仮换地指定后，土地的处分权依然留在从前的土地上，权利变动依然可以就从前的土地正常办理登记手续，不受这条限制。","takeaway":"仮换地指定只是让权利人可以先使用仮换地，土地的所有权/处分权依然停留在从前的宅地上，该从前宅地依然可以正常买卖、登记；换地处分公告才是权利关系正式发生变动的时点，公告后到变动登记完成前，才会限制其他登记的办理。这道题历年反复出题，是经典的必考混淆点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-18', '{"id":"h30-18","tag":"法令上的制限・建筑基准法","title":"平成30年 問18","stem":"建築基準法に関する次の記述のうち、正しいものはどれか。","options":["建築物の高さ31ｍ以下の部分にある全ての階には、非常用の進入口を設けなければならない。","防火地域内にある3階建ての木造の建築物を増築する場合、その増築に係る部分の床面積の合計が10㎡以内であれば、その工事が完了した際に、建築主事、建築副主事又は指定確認検査機関の完了検査を受ける必要はない。","4階建ての事務所の用途に供する建築物の2階以上の階にあるバルコニーその他これに類するものの周囲には、安全上必要な高さが1.1ｍ以上の手すり壁、さく又は金網を設けなければならない。","建築基準法の改正により、現に存する建築物が改正後の規定に適合しなくなった場合、当該建築物の所有者又は管理者は速やかに当該建築物を改正後の建築基準法の規定に適合させなければならない。"],"correct":2,"explain":"【核心知识点】非常用进入口的楼层范围、建筑确认/完了检查的豁免条件、阳台安全扶手高度、既存不适格建筑物制度。①错。高度31米以下的部分，需要设置非常用进入口的是3层以上的楼层，不是全部楼层（建筑基准法施行令126条の6）。②错。增改建/移转不需要建筑确认的条件是：位于防火地域及准防火地域以外+增改建部分面积≤10㎡。本题建筑物在防火地域内，不满足地域外这个前提，所以依然需要建筑确认，也就依然需要完了检查。③对（答案）。屋上广场或2层以上楼层的阳台等，周围须设置安全上必要高度1.1米以上的扶手墙、栅栏或金网——描述正确（建筑基准法施行令126条1项）。④错。这是既存不适格建筑物问题——因法律修正导致现存建筑物不再符合新规定时，所有者/管理者没有须尽速使其合规的义务——既存不适格建筑物在满足特定条件下可以继续以旧标准存在（建筑基准法3条2项）。","takeaway":"非常用进入口是3层以上，不是全部楼层；建筑确认/完了检查的豁免条件是防火/准防火地域以外+面积≤10㎡，本题在防火地域内所以豁免不适用；阳台等安全扶手高度是1.1米以上；既存不适格建筑物制度的核心精神是法不溯及既往——法律修正后旧建筑物不用被强制立即改造合规。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03-10-15', '{"id":"r03-10-15","tag":"法令上的制限・都市计画法","title":"令和3年10月 問15","stem":"都市計画法に関する次の記述のうち、誤っているものはどれか。","options":["地区計画については、都市計画に、当該地区計画の目標を定めるよう努めるものとされている。","地区計画については、都市計画に、区域の面積を定めるよう努めるものとされている。","地区整備計画においては、市街化区域と市街化調整区域との区分の決定の有無を定めることができる。","地区整備計画においては、建築物の建蔽率の最高限度を定めることができる。"],"correct":2,"explain":"【核心知识点，本题重复提交2次，格外详解】地区计画制度分三个层次：①地区计画必须定的事项（种类・名称・位置・区域；地区设施・地区整备计画）；②地区计画的努力义务事项（区域面积、目标、整备开发保全方针）；③地区整备计画里能定的具体建筑规制（建蔽率、容积率、高度限制等）。①对（不是错误项）。地区计画的目标属于努力义务事项，不是强制必须定的（都市计画法12条の5第2项后段）。②对（不是错误项）。地区计画的区域面积同样属于努力义务事项。③错（答案）。市街化区域与市街化调整区域的区分（区域区分）是在更大范围的都市计画区域层面决定的事项（都市计画法7条），跟地区整备计画（针对小范围街区做具体建筑规制的计画）完全不是一回事——地区整备计画的规模和性质，根本没有资格去决定要不要划区域区分这种宏观规划事项。④对（不是错误项）。地区整备计画可以定建筑物建蔽率的最高限度——这是地区整备计画里典型的具体建筑规制事项之一。","takeaway":"目标和面积是地区计画的弱义务（努力去定），别被定める这个动词唬住是强制义务；区域区分（市街化区域/调整区域）是都市计画区域整体层面的事，地区整备计画管不到这件事，它只能管建蔽率、容积率、高度这类具体建筑规制——这是本题反复做错的核心原因：混淆了宏观规划层级和微观建筑规制层级。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h29-18', '{"id":"h29-18","tag":"法令上的制限・建筑基准法","title":"平成29年 問18","stem":"建築基準法に関する次の記述のうち、誤っているものはどれか。","options":["鉄筋コンクリート造であって、階数が２の住宅を新築する場合において、特定行政庁が、安全上、防火上及び避難上支障がないと認めたときは、検査済証の交付を受ける前においても、仮に、当該建築物を使用することができる。","長屋の各戸の界壁は、原則として、小屋裏又は天井裏に達するものとしなければならない。","下水道法に規定する処理区域内においては、便所は、汚水管が公共下水道に連結された水洗便所としなければならない。","ホテルの用途に供する建築物を共同住宅（その用途に供する部分の床面積の合計が300㎡）に用途変更する場合、建築確認は不要である。"],"correct":3,"explain":"【核心知识点】特殊建筑物和大型建筑物的判断标准+建筑确认适用条件的组合记忆。①对（不是错误项）。这栋2层住宅不管构造是钢筋混凝土还是木造，只要2层以上就属于大型建筑物——新建大型建筑物需要建筑确认，完工后原则须取得检查済证才能使用，但特定行政厅认定安全/防火/避难上无问题时，可以在检查済证交付前仮使用。②对（不是错误项）。长屋各戸间的界壁，原则上须达到小屋裏或天井裏，防止隔音和防火问题——天花板结构具有同等隔音性能时可以例外不达到（令和元年6月法改正后新增的例外规定）。③对（不是错误项）。公共下水道处理区域内的厕所，必须是连接公共下水道的水冲厕所。④错（答案）。宾馆和共同住宅都属于特殊建筑物，且用途变更涉及的部分面积300㎡已超过200㎡这个门槛——因此宾馆变更为共同住宅需要建筑确认，选项说不需要是错的。","takeaway":"特殊建筑物看用途（共同住宅、电影院、宾馆、酒吧、饮食店、店铺、仓库、车库都算，独栋住宅、事务所不算）；大型建筑物看层数或面积（2层以上，或延面积超200㎡，跟构造材质无关）；用途变更这个行为，只有特殊建筑物（面积超200㎡）才需要确认，大型建筑物和一般建筑物的用途变更都不需要——这是本题出错的关键判断点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-21', '{"id":"h30-21","tag":"法令上的制限・土地区画整理法","title":"平成30年 問21","stem":"土地区画整理法に関する次の記述のうち、正しいものはどれか。","options":["土地区画整理事業とは、公共施設の整備改善及び宅地の利用の増進を図るため、土地区画整理法で定めるところに従って行われる、都市計画区域内及び都市計画区域外の土地の区画形質の変更に関する事業をいう。","土地区画整理組合の設立の認可の公告があった日以後、換地処分の公告がある日までは、施行地区内において、土地区画整理事業の施行の障害となるおそれがある建築物その他の工作物の新築を行おうとする者は、都道府県知事及び市町村長の許可を受けなければならない。","土地区画整理事業の施行者は、仮換地を指定した場合において、従前の宅地に存する建築物を移転し、又は除却することが必要となったときは、当該建築物を移転し、又は除却することができる。","土地区画整理事業の施行者は、仮換地を指定した場合において、当該仮換地について使用又は収益を開始することができる日を当該仮換地の効力発生の日と同一の日として定めなければならない。"],"correct":2,"explain":"【核心知识点】土地区划整理法的四个独立细节——事业只能在都市计画区域内进行、施行障碍建筑许可权者的判断规则、仮换地指定后建筑物的处理、仮换地使用收益开始日的例外规则。①错。土地区划整理事业只能在都市计画区域内进行，不包括都市计画区域外（土地区划整理法2条1项），选项凭空加了都市计画区域外这段错误内容。②错。这类新建行为需要经过知事等许可，具体是谁要看施行地区所在地：市的区域内是市长、町村的区域内是知事——不是都道府県知事和市町村长双方都要许可（土地区划整理法76条1项）。③对（答案）。施行者指定仮换地后，若从前宅地上存在的建筑物需要移转或除却，施行者可以移转或除却该建筑物（土地区划整理法77条1项）。④错。施行者指定仮换地时，若仮换地存在障碍物或有其他特别情形，可以把使用/收益开始日另定为跟仮换地效力发生日不同的日子（即可以延后）——选项说必须定为同一日是错的。","takeaway":"土地区划整理事业只能在都市计画区域内进行（不含区域外，这是定义层面的硬性规定）；施行障碍建筑新建的许可权者是知事等——按施行地区所在市/町村分别归市长/知事管，不是两者同时许可；仮换地指定后，从前宅地上的建筑物可以移转/除却；仮换地的使用收益开始日可以另定（不是必须跟效力发生日同一天）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-17', '{"id":"h26-17","tag":"法令上的制限・建筑基准法","title":"平成26年 問17","stem":"建築基準法に関する次の記述のうち、正しいものはどれか。","options":["住宅の地上階における居住のための居室には、採光のための窓その他の開口部を設け、その採光に有効な部分の面積は、原則として、その居室の床面積に対して７分の１以上としなければならない。","建築確認の対象となり得る工事は、建築物の建築、大規模の修繕及び大規模の模様替であり、建築物の移転は対象外である。","高さ15ｍの建築物には、周囲の状況によって安全上支障がない場合を除き、有効に避雷設備を設けなければならない。","準防火地域内において建築物の屋上に看板を設ける場合は、その主要な部分を不燃材料で造り、又は覆わなければならない。"],"correct":0,"explain":"【核心知识点】采光面积门槛、建筑确认对象是否含移转、避雷设备高度门槛（含关联规则：非常用进入口是31米超）、不燃材料义务的地域限定。①对（答案）。住宅居室的采光有效面积须为床面积7分之1以上（建筑基准法28条1项本文），例外情形下（有照明设备等措施）可以放宽到10分之1（令19条3项）——选项用词原则上跟法条完全一致。②错。建筑这个概念本身就包含新建、增改建、移转三种（建筑基准法2条13号），所以建筑物的移转同样属于建筑确认的对象——选项说移转对象外是错的。③错。需要设置避雷设备的门槛是高度超过20米的建筑物（建筑基准法33条本文），本题15米未达门槛，不需要设置——关联规则：非常用的升降机（进入口）的门槛是高度超过31米，这两个数字容易混淆，务必分开记（避雷20米、非常用进入口/升降机31米）。④错。防火地域内（不是准防火地域）的屋顶看板/高于3米的广告塔，才须用不燃材料建造/覆盖（建筑基准法64条）——本题是准防火地域，不适用这项义务。","takeaway":"采光面积门槛是7分之1（原则），可放宽到10分之1；建筑这个法律术语本身包含移转，不能想当然地把移转排除在建筑确认对象外；避雷设备门槛是高度超过20米，非常用进入口/升降机门槛是高度超过31米，两个数字容易混淆要分开记；不燃材料义务只在防火地域才有，准防火地域没有这个义务——防火地域和准防火地域一字之差是本题最大的陷阱。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r04-22', '{"id":"r04-22","tag":"法令上的制限・国土利用计画法","title":"令和4年 問22","stem":"国土利用計画法第23条の届出（以下この問において「事後届出」という。）に関する次の記述のうち、正しいものはどれか。なお、この問において「都道府県知事」とは、地方自治法に基づく指定都市にあってはその長をいうものとする。","options":["都市計画区域外において、Ａ市が所有する面積15,000㎡の土地を宅地建物取引業者Ｂが購入した場合、Ｂは事後届出を行わなければならない。","事後届出において、土地売買等の契約に係る土地の土地に関する権利の移転又は設定の対価の額については届出事項ではない。","市街化区域を除く都市計画区域内において、一団の土地である甲土地（Ｃ所有、面積3,500㎡）と乙土地（Ｄ所有、面積2,500㎡）を宅地建物取引業者Ｅが購入した場合、Ｅは事後届出を行わなければならない。","都道府県知事は、土地利用審査会の意見を聴いて、事後届出をした者に対し、当該事後届出に係る土地の利用目的について必要な変更をすべきことを勧告することができ、勧告を受けた者がその勧告に従わない場合、その勧告に反する土地売買等の契約を取り消すことができる。"],"correct":2,"explain":"【核心知识点】国土法事后申报制的四个独立知识点——当事人一方是国等免申报、申报事项包含利用目的与对价额、一团土地的判断以权利取得者为准、知事对违反劝告只能公表不能取消契约。①错。卖方A市属于国等——当事人一方是国等时，不需要事后申报（国土法23条2项3号），不管面积多大都免申报，B不用申报。②错。事后申报中，利用目的和对价额都是申报事项（国土法23条1项5号、6号）——选项说对价额不用申报是错的。③对（答案）。甲乙两地虽分属不同所有者（C、D），但最终都由购买者E以一团土地利用，视为整体6,000㎡。市街化区域以外的都市计画区域内（即市街化调整区域或非线引区域）事后申报门槛是5,000㎡以上，6,000㎡超过门槛，需要申报。④错。知事对利用目的可以劝告（国土法24条1项），不遵从可以公表（国土法26条），但不能取消契约——契约效力不受影响，选项说可以取消契约是错的。","takeaway":"当事人一方是国等（不管哪一方，不管面积多大）就免申报——这跟面积门槛是两套独立判断标准，先看主体再看面积；申报事项包含利用目的+对价额两项，缺一不可；一团土地的判断不看原所有者是否相同，只看最终是否被同一个购买者统一利用；知事对违反劝告的处置手段只有公表，没有取消契约这个选项——这是保护交易安全的立法设计。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h24-21', '{"id":"h24-21","tag":"法令上的制限・土地区画整理法","title":"平成24年 問21","stem":"土地区画整理法における土地区画整理組合に関する次の記述のうち、誤っているものはどれか。","options":["土地区画整理組合は、総会の議決により解散しようとする場合において、その解散について、認可権者の認可を受けなければならない。","土地区画整理組合は、土地区画整理事業について都市計画に定められた施行区域外において、土地区画整理事業を施行することはできない。","土地区画整理組合が施行する土地区画整理事業の換地計画においては、土地区画整理事業の施行の費用に充てるため、一定の土地を換地として定めないで、その土地を保留地として定めることができる。","土地区画整理組合が施行する土地区画整理事業に係る施行地区内の宅地について所有権又は借地権を有する者は、すべてその組合の組合員とする。"],"correct":1,"explain":"【核心知识点】区分施行区域和施行地区两个术语，以及公的施行vs民间施行的规模限制差异。①对（不是错误项）。土地区划整理组合以总会决议解散时，需要认可权者（知事）的认可（土地区划整理法45条2项前段、1项2号）——若组合有借款还需要债权人同意（45条4项）。②错（答案）。只有公的施行（都道府県、市町村等）才限定在都市计画规定的施行区域内施行——民间施行（含土地区划整理组合）没有这个限定（土地区划整理法3条4项、5项），组合在施行区域外也可以施行土地区划整理事业。③对（不是错误项）。为筹措事业施行费用，可以不为一定土地定换地，而定为保留地（土地区划整理法96条）——组合施行的场合同样可以设定保留地。④对（不是错误项）。组合成立后，施行地区内宅地上有所有权或借地权的人，全部成为该组合的组合员（土地区划整理法25条1项）。","takeaway":"施行区域是都市计画中规定的区域，施行地区是实际施行土地区划整理事业的区域，两者不是同一个概念，容易混淆；公的施行（都道府県、市町村等）作为都市计画事业限定在施行区域内（且限市街化区域或非线引区域）；民间施行（个人、组合、区划整理会社）没有这个地域限定，都市计画区域内哪里都可以施行，甚至市街化调整区域内也可以——这是本题最容易搞混的知识点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h24-17', '{"id":"h24-17","tag":"法令上的制限・都市计画法","title":"平成24年 問17","stem":"次の記述のうち、都市計画法による許可を受ける必要のある開発行為の組合せとして、正しいものはどれか。ただし、許可を要する開発行為の面積については、条例による定めはないものとする。\\nア　市街化調整区域において、図書館法に規定する図書館の建築の用に供する目的で行われる3,000㎡の開発行為\\nイ　準都市計画区域において、医療法に規定する病院の建築の用に供する目的で行われる4,000㎡の開発行為\\nウ　市街化区域内において、農業を営む者の居住の用に供する建築物の建築の用に供する目的で行われる1,500㎡の開発行為","options":["ア、イ","ア、ウ","イ、ウ","ア、イ、ウ"],"correct":2,"explain":"【核心知识点】公益上必要建筑物清单、农林渔业用建筑物特例的地域限定、面积门槛因区域而异，三个知识点的组合判断。ア许可不需要。图书馆属于公益上必要建筑物清单，不管在什么区域、规模多大，都不需要开发许可（都市计画法29条1项3号）。イ需要许可。医院不属于公益上必要建筑物清单，需要看面积门槛——准都市计画区域内门槛是3,000㎡未满不需要许可，本题4,000㎡超过门槛，需要许可。ウ需要许可。农林渔业用建筑物的特例只适用于市街化区域以外，本题在市街化区域内，不适用这个特例；市街化区域内面积门槛是1,000㎡未满不需要许可，本题1,500㎡超过门槛，需要许可。所以需要许可的是イ和ウ，正解是肢3。","takeaway":"图书馆、公民馆在公益上必要建筑物清单内，无条件豁免开发许可；医院、学校不在清单内，要按区域面积门槛判断；农林渔业用建筑物的特例只适用于市街化区域以外，容易被误以为农林渔业相关就都能豁免，实际上市街化区域内没有这个豁免。判断流程：①先看是不是公益上必要建筑物清单内的（无条件豁免）→②再看是不是农林渔业用建筑物且在市街化区域以外（特定豁免）→③最后按所在区域的面积门槛判断。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03s-15', '{"id":"r03s-15","tag":"法令上的制限・都市计画法","title":"令和3年12月 問15","stem":"都市計画法に関する次の記述のうち、正しいものはどれか。","options":["近隣商業地域は、主として商業その他の業務の利便の増進を図りつつ、これと調和した住居の環境を保護するため定める地域とする。","準工業地域は、主として環境の悪化をもたらすおそれのない工業の利便の増進を図りつつ、これと調和した住居の環境を保護するため定める地域とする。","第一種低層住居専用地域については、都市計画に特定用途制限地域を定めることができる場合がある。","第一種住居地域については、都市計画に高層住居誘導地区を定めることができる場合がある。"],"correct":3,"explain":"【核心知识点】用途地域定义中住居环境保护条款的适用范围、特定用途制限地域与特别用途地区的区分、高层住居诱导地区能定的用途地域清单。①错。近隣商业地域的定义不包含保护住居环境这句话——这是住居系8个地域的共同用语，近隣商业地域属于商业系，定义里没有这一句（都市计画法9条9项）。②错。准工业地域的定义同样不包含保护住居环境——同样的陷阱，准工业地域属于工业系，定义里也没有这一句（都市计画法9条11项）。③错。特定用途制限地域只能定在没有划用途地域的区域（不含市街化调整区域）——第一种低层住居专用地域本身就是一种用途地域，已经划了用途地域，不能再叠加特定用途制限地域（都市计画法9条15项）。④对（答案）。高层住居诱导地区可以定在第一种住居地域、第二种住居地域、准住居地域、近隣商业地域、准工业地域这几类用途地域内（都市计画法9条17项），目的是在住宅与非住宅混杂的用途地域内，引导建设便利性高的高层住宅。","takeaway":"只有住居系8个地域（第一种低层住居专用地域～田园住居地域）的定义里才有与之调和的住居环境保护这句话，商业系和工业系地域的定义里都没有这句话；特定用途制限地域只能定在没划用途地域的区域，特别用途地区用来补充/加强已有用途地域的限制，两者名字相近但适用条件完全不同；高层住居诱导地区能定的5个用途地域（一种/二种住居、准住居、近隣商业、准工业）需要单独记忆。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r01-20', '{"id":"r01-20","tag":"法令上的制限・土地区画整理法","title":"令和元年 問20","stem":"土地区画整理法に関する次の記述のうち、誤っているものはどれか。","options":["仮換地の指定があった日後、土地区画整理事業の施行による施行地区内の土地及び建物の変動に係る登記がされるまでの間は、登記の申請人が確定日付のある書類によりその指定前に登記原因が生じたことを証明した場合を除き、施行地区内の土地及び建物に関しては他の登記をすることができない。","施行者が個人施行者、土地区画整理組合、区画整理会社、市町村、独立行政法人都市再生機構又は地方住宅供給公社であるときは、その換地計画について都道府県知事の認可を受けなければならない。","個人施行者以外の施行者は、換地計画を定めようとする場合においては、その換地計画を２週間公衆の縦覧に供しなければならない。","換地処分の公告があった場合においては、換地計画において定められた換地は、その公告があった日の翌日から従前の宅地とみなされ、換地計画において換地を定めなかった従前の宅地について存する権利は、その公告があった日が終了した時において消滅する。"],"correct":0,"explain":"【核心知识点，与r07-20是同一考点】限制其他登记的触发点应该是换地处分公告之后，不是仮换地指定之后。①错（答案）。本肢把这两个时间节点搞混了——仮换地指定后，土地的处分权依然留在从前的土地上，权利变动依然可以就从前的土地正常办理登记手续，不受这条限制；只有换地处分公告后到变动登记完成前，才会限制其他登记的办理（土地区划整理法107条3项）。②对（不是错误项）。施行者是个人施行者、土地区划整理组合、区划整理会社、市町村、独立行政法人都市再生机构或地方住宅供给公社这几类时，换地计画须取得都道府県知事的认可——若施行者是都道府県或国土交通大臣，则不需要知事认可。③对（不是错误项）。个人施行者以外的施行者制定换地计画时，须将该换地计画公开縦覧2周。④对（不是错误项）。换地处分公告后：①换地计画中定了换地的土地，从公告翌日起视为从前的宅地；②换地计画中没定换地的从前宅地上存在的权利，在公告当日结束时消灭。","takeaway":"这题的核心考点跟令和7年問20（r07-20）几乎一字不差——都是考仮换地指定和换地处分公告这两个时间节点的区分，属于历年反复出现的经典混淆点，建议把这两道题放在一起对照复习。此外还捎带考了换地计画认可要件（哪些施行者需要知事认可）和换地处分公告的两个后续效果。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r01-9', '{"id":"r01-9","tag":"权利关系・条件期间时效","title":"令和元年 問9","stem":"ＡがＢに対して金銭の支払を求めて訴えを提起した場合の時効の更新に関する次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["訴えの提起後に当該訴えが取り下げられた場合には、特段の事情がない限り、時効の更新の効力は生じない。","訴えの提起後に当該訴えの却下の判決が確定した場合には、時効の更新の効力は生じない。","訴えの提起後に請求棄却の判決が確定した場合には、時効の更新の効力は生じない。","訴えの提起後に裁判上の和解が成立した場合には、時効の更新の効力は生じない。"],"correct":3,"explain":"【核心知识点】判断标准是权利是否被最终确定——只有权利真正被确定，时效才会更新（重新起算）。①对（不是错误项）。起诉后撤诉，权利没有被法院确定，原则上不发生时效更新效力（只有前面的完成猶予，给6个月缓冲期）。②对（不是错误项）。起诉后被驳回起诉（诉讼要件不满足、不进入实体审理）判决确定，权利同样没有被确定，不发生更新效力。③对（不是错误项）。起诉后败诉（请求棄却，实体审理后认定原告请求不成立）判决确定，权利没有被确定成立（甚至确定为不存在），不发生更新效力。④错（答案）。裁判上的和解成立时，和解调书具有与确定判决同等的效力（民事诉讼法267条），权利因此被确定，依然会发生时效更新的效力——选项说不发生更新效力正好说反了。","takeaway":"只有权利真正被确定（不管是原告胜诉确定成立，还是败诉确定不存在，关键在确定这个动作本身），时效才会更新；如果诉讼半途而废（撤诉、驳回起诉），权利根本没到被确定这一步，只能享受6个月的完成猶予，不产生更新效果。裁判上的和解虽然不是判决，但法律特别赋予它跟确定判决同等的效力，所以同样会触发时效更新——这是最容易被忽略、也是这道题的考点所在。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03s-7', '{"id":"r03s-7","tag":"权利关系・家族法","title":"令和3年12月 問7","stem":"遺言に関する次の記述のうち、民法の規定によれば、誤っているものはどれか。","options":["自筆証書によって遺言する場合、遺言者は、その全文、日付及び氏名を自書して押印しなければならないが、これに添付する相続財産の目録については、遺言者が毎葉に署名押印すれば、自書でないものも認められる。","公正証書遺言の作成には、証人２人以上の立会いが必要であるが、推定相続人は、未成年者でなくとも、証人となることができない。","船舶が遭難した場合、当該船舶中にいて死亡の危急に迫った者は、証人２人以上の立会いがあれば、口頭で遺言をすることができる。","遺贈義務者が、遺贈の義務を履行するため、受遺者に対し、相当の期間を定めて遺贈の承認をすべき旨の催告をした場合、受遺者がその期間内に意思表示をしないときは、遺贈を放棄したものとみなされる。"],"correct":3,"explain":"【核心知识点】遗言制度的四个独立细节，尤其是受遗赠人沉默时的默认结果。①对（不是错误项）。自筆证书遗言，正文全文・日期・姓名须亲笔书写并盖章，但添附的財産目录可以不用亲笔书写（可打印/他人代写），只需每页签名盖章即可（民法968条2项，2019年新增的宽松规定）。②对（不是错误项）。公正证书遗言需要证人2人以上在场，推定继承人（不论是否成年）都不能当证人——这是969条形式要件之外的证人欠格事由（民法974条2号）。③对（不是错误项）。船舶遇难时，处于死亡危急状态的人，在证人2人以上在场的情况下，可以口头遗言——这是死亡危急时的遗言特别方式之一（民法979条）。④错（答案）。受遗赠人在催告期间内没有做出意思表示时，法律推定为承认遗赠，不是放弃——选项把结果说反了（民法987条）。","takeaway":"自筆证书遗言的财产目录可以不亲笔书写（2019年新规）；推定继承人不论年龄都不能当公正证书遗言的证人；死亡危急时的遗言，2个以上证人在场可以口头进行；受遗赠人沉默时的默认结果是承认，不是放弃——这是本题的核心陷阱，跟相続放棄需要主动表示的逻辑正好相反：遗赠这边沉默=接受。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-7', '{"id":"r06-7","tag":"权利关系・所有权共有占有权用益物权","title":"令和6年 問7","stem":"Ａを貸主、Ｂを借主として甲建物の賃貸借契約（以下この問において「本件契約」という｡）が締結され、Ｂが甲建物の引渡しを受けた場合における次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["ＣがＢに対し甲建物をＡから買受けたとの虚偽の話をしたので、これを信じたＢが甲建物の占有を任意にＣに移転した場合、ＡはＣに対して、占有回収の訴えにより甲建物の返還を請求することはできない。","Ｂが、Ａの甲建物への立ち入りを建物入り口を閉ざして拒んだときは、Ａは甲建物の間接占有が侵奪されたものとして、Ｂに対して、占有回収の訴えにより甲建物の返還を請求することができる。","Ｂが死亡して、ＤがＢを単独相続した場合、Ｄは相続開始を知るまでは、Ｂによる甲建物の占有を承継しない。","ＡとＢのいずれもが死亡した場合、本件契約は当然に終了する。"],"correct":0,"explain":"【核心知识点】占有回收之诉的要件是占有被夺走（违反占有人自己意思被强制剥夺）。①对（答案）。本题B是自愿（虽然是被骗）把占有转移给C的，不符合被夺走这个要件（判例：大正11年11月27日）——所以A不能对C提起占有回收之诉。②错。B本身就是甲建筑物的直接占有人（承租人），A只是间接占有人。B自己锁门拒绝A进入，占有权依然完整地留在B手上，不构成第三者夺取——占有回收之诉针对的是第三者的侵夺，不能对占有权本人（B自己）提起。③错。继承开始后，继承人当然承继被继承人的占有（民法896条，含占有权）——不需要等到知道继承开始才承继，占有的继承是自动的，不以知情为前提。④错。赁贷借契约不会因当事人一方死亡而当然终止——权利义务由继承人承继，契约继续有效（赁贷借是财产性契约，不是一身专属性的）。","takeaway":"占有回收之诉的核心要件是被夺走（违反本人意思），被骗后自愿交出占有不算被夺走，这是最容易被出题者利用的心理陷阱；占有回收之诉针对的是第三者的侵夺，占有权本人不构成侵夺对象；占有的继承是当然、自动的，不需要知道才承继；赁贷借契约不因当事人死亡而当然终止，权利义务由继承人承继。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-4', '{"id":"h25-4","tag":"权利关系・担保物权（留置权）","title":"平成25年 問4","stem":"留置権に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["建物の賃借人が賃貸人の承諾を得て建物に付加した造作の買取請求をした場合、賃借人は、造作買取代金の支払を受けるまで、当該建物を留置することができる。","不動産が二重に売買され、第2の買主が先に所有権移転登記を備えたため、第1の買主が所有権を取得できなくなった場合、第1の買主は、損害賠償を受けるまで当該不動産を留置することができる。","建物の賃貸借契約が賃借人の債務不履行により解除された後に、賃借人が建物に関して有益費を支出した場合、賃借人は、有益費の償還を受けるまで当該建物を留置することができる。","建物の賃借人が建物に関して必要費を支出した場合、賃借人は、建物所有者ではない第三者が所有する敷地を留置することはできない。"],"correct":3,"explain":"【核心知识点】留置权的两大成立要件——占有开始合法、债权与标的物有牵连关系。①错。留置权成立要求债权和标的物之间有牵连关系（民法295条）——造作买取请求权产生的价金债权，是针对造作产生的，不是针对建物本身产生的，标的物不一致，没有牵连关系，不能就建物本身主张留置权（判例）。②错。双重买卖中，第一买主的损害赔偿请求权是因卖方债务不履行产生的，不是因占有该不动产本身产生的费用性债权——没有牵连关系，第一买主不能就该不动产主张留置权（判例）。③错。留置权成立要求占有的开始必须合法——赁贷借契约因承租人债务不履行被解除后，承租人此后继续占有建筑物就变成了不法占有。在不法占有开始后支出的有益费，不能就该建筑物主张留置权（判例）。④对（答案）。承租人对建物支出必要费，享有的留置权对象是建物本身——但建物所在的敷地属于第三者所有，承租人对这块地没有支出任何产生费用性债权的行为，不能就该第三者所有的敷地主张留置权——建物的留置权不能自动延伸到敷地上。","takeaway":"留置权的两大成立要件：①占有开始必须合法（不法占有开始后产生的费用不能留置）；②债权与标的物必须有牵连关系（债权必须是因该物本身产生的费用性债权）。留置权的效力范围只及于债权直接对应的那个物本身，建物的留置权不会自动扩展到建物所在的土地（尤其当土地属于第三者时）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-6', '{"id":"h25-6","tag":"权利关系・债权总则（弁済による代位）","title":"平成25年 問6","stem":"Ａ銀行のＢに対する貸付債権1,500万円につき、ＣがＢの委託を受けて全額について連帯保証をし、Ｄ及びＥは物上保証人として自己の所有する不動産にそれぞれ抵当権を設定していた場合、次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["ＣがＡ銀行に対して債権全額について保証債務を履行した場合、Ｃは、Ｄ及びＥの各不動産に対する抵当権を実行して1,500万円を回収することができる。","Ａ銀行がＤの不動産の抵当権を実行して債権全額を回収した場合、ＤはＣに対して、1,000万円を限度として求償することができる。","第三者がＤの所有する担保不動産を買い受けた後、ＣがＡ銀行に対して債権全額を弁済した場合、Ｃは代位の付記登記をしなければ、当該第三者に対してＡ銀行に代位することができない。","Ｅの担保不動産を買い受けた第三者がＡ銀行に対して債権全額を弁済した場合、当該第三者は、Ｃに対して、弁済した額の一部を求償することができる。"],"correct":3,"explain":"【核心知识点，官方发布时曾有争议但正解确定为肢4】保证人和物上保证人之间的代位/求偿，按头数（人数）平均分摊，不问各自的保证额/担保物价值大小（民法501条3项4号）。本题C+D+E共3人，每人应负担1500万÷3=500万。①错。C全额清偿1500万后，对D、E两人的代位额度受限于1000万（=D、E两人应负担的合计500万×2），不是选项说的能拿回全部1500万。②错。D的抵当权被实行、D独自承担了全部1500万后，D对C的求偿额度受限于500万（=C自己应负担的1/3），不是选项说的1000万。③错。保证人与物上保证人间按人数代位，不需要办理代位的付记登记这道手续——选项凭空加了一个不存在的程序要件。④对（答案）。从物上保证人E那里买下担保不动产的第三取得者，视为等同于物上保证人，同样适用按人数代位/求偿规则——该第三者若代B清偿全额，可以对C求偿（按人数分摊后的部分）。补充说明：这道题的肢4当年公布正解时曾有争议，因为很难找到直接对应的判例支持，出题依据略显牵强，但官方公布的正解确实是肢4。","takeaway":"保证人和物上保证人之间代位/求偿的核心规则是头数分摊原则（民法501条3项4号）——不管各自的保证额度或抵押物价值多大，只按人头数平均分配代位额度。从物上保证人处买下担保物的第三取得者，视为物上保证人，同样适用头数分摊规则。这道题官方公布正解时曾有争议，属于难度较高、依据略薄弱的题目，做错不用太自责。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-7', '{"id":"h26-7","tag":"权利关系・赁贷借契约","title":"平成26年 問7","stem":"賃貸人Ａから賃借人Ｂが借りたＡ所有の甲土地の上に、Ｂが乙建物を所有する場合における次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。なお、Ｂは、自己名義で乙建物の保存登記をしているものとする。","options":["ＢがＡに無断で乙建物をＣに月額10万円の賃料で貸した場合、Ａは、借地の無断転貸を理由に、甲土地の賃貸借契約を解除することができる。","Ｃが甲土地を不法占拠してＢの土地利用を妨害している場合、Ｂは、Ａの有する甲土地の所有権に基づく妨害排除請求権を代位行使してＣの妨害の排除を求めることができるほか、自己の有する甲土地の賃借権に基づいてＣの妨害の排除を求めることができる。","ＢがＡの承諾を得て甲土地を月額15万円の賃料でＣに転貸した場合、ＡＢ間の賃貸借契約がＢの債務不履行で解除されても、ＡはＣに解除を対抗することができない。","ＡＢ間で賃料の支払時期について特約がない場合、Ｂは、当月末日までに、翌月分の賃料を支払わなければならない。"],"correct":1,"explain":"【核心知识点】出租建筑物≠转租土地、借地权人面对第三人妨害的两条救济路径、债务不履行解除能对抗转租人、赁料支付是后払い。①错。B无断把建筑物出租给C，这只是出租建筑物而已，不构成借地（甲土地本身）的无断转贷——B作为借地人依然自己占有使用甲土地，并没有把甲土地本身转租给C，所以不构成解除事由。②对（答案）。B作为借地权人面对第三人C的不法占有妨害，有两条救济途径：①代位行使贷主A对甲土地所有权基础的妨害排除请求权；②基于自己对甲土地享有的赁借权本身，直接向C主张妨害排除请求——B已做乙建物保存登记，赁借权已具备对抗要件，可以直接行使。③错。B获得A承诺后合法转租给C，AB之间的赁贷借契约若因B的债务不履行被解除，这种解除可以对抗转租人C，不需要事先通知C——选项说不能对抗C是错的。④错。没有特约时，赁料的支付时期是每月末日支付当月的租金（后払い，民法614条），不是当月末日支付翌月分租金。","takeaway":"出租建筑物≠转租土地——只要借地人自己还在（通过持有建筑物）占有使用土地，把地上建筑物出租给别人，不算把土地本身转租出去；借地权人面对第三人妨害有两条救济路径（代位行使所有权人的妨害排除请求权+直接行使自己赁借权的妨害排除请求权）；债务不履行解除能对抗转租人（跟合意解除的规则相反）；赁料支付原则是后払い（当月末付当月租），不是先付。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02s-1', '{"id":"r02s-1","tag":"权利关系・不法行为事务管理","title":"令和2年12月 問1","stem":"不法行為（令和２年４月１日以降に行われたもの）に関する次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["建物の建築に携わる設計者や施工者は、建物としての基本的な安全性が欠ける建物を設計し又は建築した場合、設計契約や建築請負契約の当事者に対しても、また、契約関係にない当該建物の居住者に対しても損害賠償責任を負うことがある。","被用者が使用者の事業の執行について第三者に損害を与え、第三者に対してその損害を賠償した場合には、被用者は、損害の公平な分担という見地から相当と認められる額について、使用者に対して求償することができる。","責任能力がない認知症患者が線路内に立ち入り、列車に衝突して旅客鉄道事業者に損害を与えた場合、当該責任無能力者と同居する配偶者は、法定の監督義務者として損害賠償責任を負う。","人の生命又は身体を害する不法行為による損害賠償請求権は、被害者又はその法定代理人が損害及び加害者を知った時から5年間行使しない場合、時効によって消滅する。"],"correct":2,"explain":"【核心知识点】法定监督义务者不等于同居的家人——2016年JR东海事件确立的重要判例规则。①对（不是错误项）。建筑物基本安全性欠缺时，参与设计/施工的设计者、施工者及工事监理者，不仅对契约相对方负责，对没有契约关系的居住者同样可能负不法行为损害赔偿责任（最判平19.7.6等判例）。②对（不是错误项）。被用者代替使用者向第三者赔偿后，可以按照损害的公平分担这一标准，向使用者主张一定额度的求偿（逆求偿）——这是2020年最高裁新判例（令和2年2月28日判决）确立的规则。③错（答案）。责任无能力者（如重度认知症患者）造成损害时，负赔偿责任的是法定的监督义务者——单纯同居的配偶者这个身份本身不当然构成法定监督义务者，需要综合考量实际监护状况等因素来判断（最判平28.3.1，JR东海事件）——选项说同居配偶者当然作为法定监督义务者负责是错的。④对（不是错误项）。侵害人的生命或身体的不法行为损害赔偿请求权，主观消灭时效是知道损害及加害人之日起5年（一般不法行为是3年，这类特殊侵害延长为5年）。","takeaway":"法定监督义务者不等于同居的家人——这是2016年JR东海事件确立的重要判例规则：认知症患者等责任无能力者造成的损害，不能仅凭同居配偶这个身份就直接判定负赔偿责任，法院会综合考量实际的监护状态、看护体制等因素。建物基本安全性缺陷的责任可以延伸到无契约关系的第三人；被用者向使用者的逆求偿是被2020年新判例承认的；人身伤害的不法行为消灭时效主观期间是5年（不是一般不法行为的3年）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02-10-14', '{"id":"r02-10-14","tag":"权利关系・不动产登记法","title":"令和2年10月 問14","stem":"不動産の登記に関する次の記述のうち、不動産登記法の規定によれば、正しいものはどれか。","options":["敷地権付き区分建物の表題部所有者から所有権を取得した者は、当該敷地権の登記名義人の承諾を得なければ、当該区分建物に係る所有権の保存の登記を申請することができない。","所有権に関する仮登記に基づく本登記は、登記上の利害関係を有する第三者がある場合であっても、その承諾を得ることなく、申請することができる。","債権者Ａが債務者Ｂに代位して所有権の登記名義人ＣからＢへの所有権の移転の登記を申請した場合において、当該登記を完了したときは、登記官は、Ａに対し、当該登記に係る登記識別情報を通知しなければならない。","配偶者居住権は、登記することができる権利に含まれない。"],"correct":0,"explain":"【核心知识点】敷地权附区分建物的保存登记要件、仮登记本登记的承诺要件、代位申请时登记识别信息的通知对象、配偶者居住权可登记。①对（答案）。敷地权附区分建物的表题部所有者转让所有权给他人时，须取得该敷地权登记名义人的承诺，受让人才能申请该区分建物的所有权保存登记（不动产登记法74条2项）——这是为了保护建物和敷地权一体化处分的原则不被破坏。②错。所有权仮登记的本登记，若存在登记上的利害关系第三者，须获得该第三者的承诺才能申请（不动产登记法109条1项）——选项说不需要承诺是错的。③错。登记完成后被通知登记识别信息的对象，仅限于自己成为登记名义人的申请人（不动产登记法21条本文）——本题中债权者A代位申请的登记，最终登记名义人是债务者B，不是A本人，所以登记识别信息应通知给B，不是A。④错。配偶者居住权可以登记——属于登记能够记载的权利之一（不动产登记法3条9号）——选项说不包含在能登记的权利里是错的。","takeaway":"敷地权附区分建物转让时，所有权保存登记须取得敷地权登记名义人的承诺——防止建物和敷地权被分离处分的重要保护机制；仮登记的本登记须获得利害关系第三者的承诺（跟仮登记的抹消可以单独申请是不同的场景，别混淆）；代位申请登记时，登记识别信息通知给最终登记名义人，不是代位申请人；配偶者居住权可以登记，这是2020年民法改正新增制度里明确规定的登记事项。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h28-22', '{"id":"h28-22","tag":"法令上的制限・农地法","title":"平成28年 問22","stem":"農地に関する次の記述のうち、農地法（以下この問において「法」という。）の規定によれば、正しいものはどれか。","options":["相続により農地を取得する場合は、法第３条第１項の許可を要しないが、相続人に該当しない者に対する特定遺贈により農地を取得する場合も、同項の許可を受ける必要はない。","法第２条第３項の農地所有適格法人の要件を満たしていない株式会社は、耕作目的で農地を借り入れることはできない。","法第３条第１項又は法第５条第１項の許可が必要な農地の売買について、これらの許可を受けずに売買契約を締結しても、その所有権の移転の効力は生じない。","農業者が、市街化調整区域内の耕作しておらず遊休化している自己の農地を、自己の住宅用地に転用する場合、あらかじめ農業委員会へ届出をすれば、法第４条第１項の許可を受ける必要がない。"],"correct":2,"explain":"【核心知识点】农地法的四个独立细节——继承相关许可豁免的身份限定、不适格法人取得vs借入的区别、未经许可买卖的效力、市街化调整区域没有申报代替许可的特例。①错。因继承、包括遗赠、对继承人的特定遗赠取得农地时，不需要3条许可。但对非继承人的特定遗赠取得农地，依然需要3条许可——选项说对非继承人的特定遗赠也不需要许可是错的。②错。不满足农地所有适格法人要件的股份公司，虽然不能取得所有权，但满足一定条件（如至少1名役员常年从事农业等）时，可以借入农地进行耕作——选项说不能借入是错的。③对（答案）。需要3条或5条许可的农地买卖，如果没经过许可就缔结买卖契约，所有权移转不发生效力（农地法3条6项、5条3项）——描述正确。④错。市街化调整区域内的农地转用为自己住宅用地，需要知事的4条许可，不能只靠向农业委员会申报就免除许可义务——只有市街化区域内的农地转用才有申报即可、不需要许可这个特例，市街化调整区域没有这个特例。","takeaway":"继承/包括遗赠/对继承人的特定遗赠不需要3条许可，但对非继承人的特定遗赠依然需要许可——继承人这个身份限定是关键区分点；不适格法人不能取得所有权，但可以借入（满足条件时）——取得和借入要分开判断；未经许可的农地买卖，所有权移转不发生效力；市街化区域内的农地转用有申报代替许可的简化通道，市街化调整区域没有这个特例。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h23-23', '{"id":"h23-23","tag":"税相关法令・印纸税","title":"平成23年 問23","stem":"印紙税に関する次の記述のうち、正しいものはどれか。なお、以下の覚書、仮契約書又は契約書はいずれも書面により作成されたものとする。","options":["当初作成した土地の賃貸借契約書において記載がされていなかった「契約期間」を補充するために「契約期間は10年とする」旨が記載された覚書を作成したが、当該覚書にも印紙税が課される。","本契約書を後日作成することを文書上で明らかにした、土地を8,000万円で譲渡することを証した仮契約書には、印紙税は課されない。","「甲土地を6,000万円、乙建物を3,500万円、丙建物を1,500万円で譲渡する」旨を記載した契約書を作成した場合、印紙税の課税標準となる当該契約書の記載金額は、6,000万円である。","「Ａの所有する土地（価額7,000万円）とＢの所有する土地（価額１億円）とを交換し、ＡはＢに差額3,000万円支払う」旨を記載した土地交換契約書を作成した場合、印紙税の課税標準となる当該契約書の記載金額は、3,000万円である。"],"correct":0,"explain":"【核心知识点】印纸税的四个独立数字/概念陷阱——覚书/仮契约书的课税判断、同种契约多项金额的合计规则、交换契约书记载金额的取值规则。①对（答案）。印纸税契约书的课税对象是契约成立/更改或契约内容变更/补充的证明文书——本肢的覚书是补充契约期间这项内容的文书，属于内容变更/补充，所以算契约书，须课印纸税。②错。本肢的仮契约书是证明契约成立的文书，同样属于契约书，须课印纸税——不能因为以后要另作正式合同就免税。③错。一份契约书记载了多项同种类契约的金额（甲土地+乙建物+丙建物都是譲渡契约），课税标准是合计金额：6000万+3500万+1500万=1亿1000万，不是选项说的6000万。④错。交换契约书的记载金额规则：若双方的金额都有记载，取较高的那个金额作为记载金额——本题应取A、B两方中较高的1亿円，不是选项说的差额3000万。","takeaway":"覚书/仮契约书只要属于证明契约成立或证明内容变更/补充，都算契约书要课税——不管取什么名字，以后要另作正式合同这个说法不能免税；同种契约的多项金额要合计相加；不同种类契约（如土地讓渡+建筑请负）的多项金额取较高者；交换契约双方都记载金额时取较高者，只记载差额时才用差额——三种情形对应三套不同的取值规则，容易混着记。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h28-35', '{"id":"h28-35","tag":"宅地建物取引业法等・免许","title":"平成28年 問35","stem":"宅地建物取引業の免許（以下この問において「免許」という。）に関する次の記述のうち、宅地建物取引業法の規定によれば、正しいものはどれか。","options":["個人である宅地建物取引業者Ａ（甲県知事免許）が、免許の更新の申請を怠り、その有効期間が満了した場合、Ａは、遅滞なく、甲県知事に免許証を返納しなければならない。","法人である宅地建物取引業者Ｂ（乙県知事免許）が、乙県知事から業務の停止を命じられた場合、Ｂは、免許の更新の申請を行っても、その業務の停止の期間中は免許の更新を受けることができない。","法人である宅地建物取引業者Ｃ（国土交通大臣免許）について破産手続開始の決定があった場合、その日から30日以内に、Ｃを代表する役員Ｄは、その旨を主たる事務所の所在地を管轄する都道府県知事を経由して国土交通大臣に届け出なければならない。","個人である宅地建物取引業者Ｅ（丙県知事免許）が死亡した場合、Ｅの一般承継人Ｆがその旨を丙県知事に届け出た後であっても、Ｆは、Ｅが生前締結した売買契約に基づく取引を結了する目的の範囲内においては、なお宅地建物取引業者とみなされる。"],"correct":3,"explain":"【核心知识点】免许证返还的适用情形、业务停止处分与免许更新的关系、法人破产的申报义务人、みなし业者制度。①错。免许有效期间满了（自然失效，不是被处分/主动废业），没有须返还免许证这个义务——需要返还免许证的情形只有：免许换え、免许被取消、拾获遗失的免许证、办理廃业等届出这几种，有效期满了不在其中。②错。业务停止处分期间依然可以进行免许更新申请，处分不会阻断更新程序。③错。法人破产时，申报义务人是破产管财人，不是代表该法人的役员——选项把申报主体搞错了（宅建业法11条1项3号）。④对（答案）。个人业者死亡后免许立即失效，但在取引结了目的范围内（比如完成已签契约的交房、移转登记等收尾工作），继承人（一般承继人）依然被视为宅建业者——这是みなし业者制度，让已经开始的交易能顺利收尾，不会因业者死亡而半途而废。","takeaway":"免许证返还的4种情形（免许换え、取消、拾获遗失证件、廃业届出）——有效期满了不在其中；业务停止处分不影响免许更新的申请和取得；法人破产的申报义务人是破产管财人，不是役员；みなし业者制度——个人业者死亡后，为了让已经在进行的交易顺利收尾，继承人在取引结了这个有限范围内依然被视为宅建业者。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r02s-32', '{"id":"r02s-32","tag":"宅地建物取引业法等・35条书面","title":"令和2年12月 問32","stem":"宅地建物取引業者が行う宅地建物取引業法第35条に規定する重要事項の説明に関する次の記述のうち、正しいものはいくつあるか。なお、説明の相手方は宅地建物取引業者ではないものとする。\\nア　宅地の売買の媒介を行う場合、当該宅地が急傾斜地の崩壊による災害の防止に関する法律第３条第１項により指定された急傾斜地崩壊危険区域にあるときは、同法第７条第１項に基づく制限の概要を説明しなければならない。\\nイ　建物の貸借の媒介を行う場合、当該建物が土砂災害警戒区域等における土砂災害防止対策の推進に関する法律第７条第１項により指定された土砂災害警戒区域内にあるときは、その旨を説明しなければならない。\\nウ　宅地の貸借の媒介を行う場合、文化財保護法第46条第１項及び第５項の規定による重要文化財の譲渡に関する制限について、その概要を説明する必要はない。\\nエ　宅地の売買の媒介を行う場合、当該宅地が津波防災地域づくりに関する法律第21条第１項により指定された津波防護施設区域内にあるときは、同法第23条第１項に基づく制限の概要を説明しなければならない。","options":["一つ","二つ","三つ","四つ"],"correct":3,"explain":"【核心知识点】区分法令上的制限（是否说明取决于是不是建物贷借）和灾害危险性物件（不分买卖贷借都要说明）两大类。ア对。急傾斜地崩溃危险区域的行为限制概要，属于法令上的制限——这类限制只在建物贷借以外的交易需要说明（宅建业法35条1项2号）。本题是宅地的买卖，属于需要说明的范围。イ对。土砂灾害警戒区域内这件事本身，属于灾害危险性物件信息——不管宅地/建物、买卖/贷借都要说明，本题建物贷借也不例外。ウ对。重要文化财的讓渡限制，属于法令上的制限，而这项具体限制只适用于建物（重要文化财的定义是有形文化财，土地本身不可能被指定为重要文化财），所以宅地贷借根本不涉及这项说明义务。エ对。津波防护设施区域内的行为限制概要，属于法令上的制限——同样只在建物贷借以外需要说明。本题是宅地的买卖，属于需要说明的范围（跟津波灾害警戒区域这个不同制度别搞混）。四项全部正确，答案是四つ。","takeaway":"灾害危险性物件（土砂灾害警戒区域、津波灾害警戒区域、造成宅地防灾区域等）不分买卖贷借、宅地建物，一律要说明；法令上的制限（急傾斜地限制、重要文化财讓渡限制、津波防护设施区域限制等）则要看是不是建物贷借——建物贷借几乎全部免说明。津波防护设施区域和津波灾害警戒区域是两个不同制度，前者属法令限制（建物贷借免说明），后者属灾害危险物件（不分交易类型都要说明）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03s-40', '{"id":"r03s-40","tag":"宅地建物取引业法等・37条书面","title":"令和3年12月 問40","stem":"宅地建物取引業法第37条の規定により交付すべき書面（以下この問において「37条書面」という。）についての宅地建物取引業者Ａの義務に関する次の記述のうち、正しいものはどれか。","options":["Ａは、自ら売主として、宅地建物取引業者Ｂの媒介により、Ｃと宅地の売買契約を締結した。Ｂが宅地建物取引士をして37条書面に記名させている場合、Ａは宅地建物取引士をして当該書面に記名させる必要はない。","Ａは、Ｄを売主としＥを買主とする宅地の売買契約を媒介した。当該売買契約に、当該宅地が種類又は品質に関して契約の内容に適合しない場合においてその不適合を担保すべき責任に関する特約があるときは、Ａは、当該特約について記載した37条書面をＤ及びＥに交付しなければならない。","Ａは、自ら買主として、Ｆと宅地の売買契約を締結した。この場合、Ｆに対して37条書面を交付する必要はない。","Ａは、自ら貸主として、Ｇと事業用建物の定期賃貸借契約を締結した。この場合において、借賃の支払方法についての定めがあるときは、Ａはその内容を37条書面に記載しなければならず、Ｇに対して当該書面を交付しなければならない。"],"correct":1,"explain":"【核心知识点】多业者关与时每个业者独立负记名义务、37条书面须交付双方当事人、自己作为贷主的贷借行为不算宅建业法上的取引。①错。一个交易涉及多个宅建业者时，每一个宅建业者都要负37条书面的记名义务，不能因为对方B已经记名就免除自己（A）的记名义务。②对（答案）。37条书面须交付给契约双方当事人，媒介业者A有义务把书面交给D和E双方。契约不适合担保责任的特约，是买卖契约37条书面的任意记载事项（有约定就必须记载），本题D、E间的契约有这项特约，A须记载并交付给双方。③错。37条书面须交付给契约双方——A作为买主，自己不用交给自己，但相对方卖主F依然要收到37条书面，A不能因为F是卖方就省略这项交付义务。④错。自己作为当事人的贷借行为，根本不构成宅建业法上的取引（宅建业法2条2号）——所以A作为自己的建物贷主，完全不受宅建业法规制，也没有作成/交付37条书面的义务。","takeaway":"多业者关与时每个业者都要独立负记名义务，跟对方是否已记名无关；37条书面须交付双方当事人，自己作为当事人一方也有义务交给对方；自己做买卖算取引，自己做贷借不算取引，媒介/代理不管买卖贷借都算取引——这是判断这类题的关键口诀。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-34', '{"id":"h30-34","tag":"宅地建物取引业法等・37条书面","title":"平成30年 問34","stem":"宅地建物取引業者が媒介により既存建物の貸借の契約を成立させた場合、宅地建物取引業法第37条の規定により、当該貸借の契約当事者に対して交付すべき書面に必ず記載しなければならない事項の組合せはどれか。\\nア　建物が種類又は品質に関して契約の内容に適合しない場合におけるその不適合を担保すべき責任の内容\\nイ　当事者の氏名（法人にあっては、その名称）及び住所\\nウ　建物の引渡しの時期\\nエ　建物の構造耐力上主要な部分等の状況について当事者双方が確認した事項","options":["ア、イ","イ、ウ","イ、エ","ウ、エ"],"correct":1,"explain":"【核心知识点】区分37条书面里买卖贷借共通事项和买卖专属事项。ア不必须记载。契约不适合担保责任的内容，是买卖37条书面的任意记载事项，贷借根本不用记——选项把买卖专属的事项错套到贷借上。イ必须记载（正确）。当事者的姓名（法人为名称）及住所——37条书面本质是契约书，不管买卖还是贷借，都要写清楚谁跟谁签的，这是共通的必要记载事项。ウ必须记载（正确）。建物的引渡时期——不管买卖还是贷借，什么时候交房/交钥匙都是共通的必要记载事项，这一点上买卖贷借规则一致。エ不必须记载。建筑物构造耐力上主要部分等状况的双方确认事项，只适用于中古住宅的买卖/交换，贷借不需要记载。正确组合是イ、ウ，答案是肢2。","takeaway":"37条书面共通事项（不管买卖贷借都要记）：当事人姓名住所、宅地建物特定表示、代金/借賃的额及支付时期方法、引渡时期；买卖专属事项（贷借不用记）：移转登记申请时期、契约不适合担保责任相关定め、建物构造耐力上主要部分双方确认事项（既存住宅限定）。判断口诀：凡是涉及所有权移转或物件质量担保相关的事项，基本都是买卖专属，贷借用不上。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-31', '{"id":"h30-31","tag":"宅地建物取引业法等・报酬关连","title":"平成30年 問31","stem":"宅地建物取引業者Ａ（消費税課税事業者）が受け取ることのできる報酬の上限額に関する次の記述のうち、宅地建物取引業法の規定によれば、正しいものはどれか。","options":["土地付中古住宅（代金900万円。消費税等相当額を含まない。）の売買について、Ａが売主Ｂから媒介を依頼され、現地調査等の費用を５万円（消費税等相当額を含まない。）要するなど、当該媒介に要する費用を勘案し、報酬額についてＢに対して説明し、合意した上で、ＡがＢから受け取ることができる報酬の上限額は418,000円である。","土地付中古住宅（代金300万円。消費税等相当額を含まない。）の売買について、Ａが買主Ｃから媒介を依頼され、現地調査等の費用を４万円（消費税等相当額を含まない。）要するなど、当該媒介に要する費用を勘案し、報酬額についてＣに対して説明し、合意した上で、ＡがＣから受け取ることができる報酬の上限額は154,000円である。","宅地（代金350万円。消費税等相当額を含まない。）の売買について、Ａが売主Ｄから媒介を依頼され、現地調査等の費用を２万円（消費税等相当額を含まない。）要するなど、当該媒介に要する費用を勘案し、報酬額についてＤに対し説明し、合意した上で、ＡがＤから受け取ることができる報酬の上限額は330,000円である。","中古住宅（長期の空家等ではない。１か月分の借賃15万円。消費税等相当額を含まない。）の貸借について、Ａが貸主Ｅから媒介を依頼され、現地調査等の費用を３万円（消費税等相当額を含まない。）要するなど、当該媒介に要する費用を勘案し、報酬額についてＥに対し説明し、合意した上で、ＡがＥから受け取ることができる報酬の上限額は330,000円である。"],"correct":2,"explain":"【核心知识点，按现行法800万円门槛版本】低廉空家等特例只适用于买卖，不适用贷借；代金800万円以下+说明合意+报酬合计不超33万円（税込）+卖买双方均可适用。①错。代金900万（税别）超过800万门槛，不适用特例，须用正常公式：900万×3%+6万=33万，含税=363,000円——不是选项说的418,000円。②错。代金300万（税别）≤800万，符合特例；本题虽是买方Ｃ委托的，但特例买卖双方都能用，上限应为330,000円（税込33万），不是选项说的154,000円（这是没套用特例、只按正常公式算出来的偏低数字）。③对（答案）。代金350万（税别）≤800万，符合特例；已说明并合意；上限330,000円（税込33万）——完全符合。④错。这个特例只适用于买卖，不适用贷借。本题是居住用建物的贷借媒介，报酬上限按借賃规则算：没有得到Ｅ特别承诺时，媒介方只能拿0.5个月租金（+税）=82,500円；即使拿到承诺也只能到1个月租金（+税）=165,000円——远低于选项说的330,000円。","takeaway":"低廉空家等特例只适用于买卖（不适用贷借），以及800万円门槛和33万円上限这两个数字要牢记。代金一旦超过800万，就完全退回正常公式，不能再套特例；代金在800万以内且完成说明合意的，不管买方委托还是卖方委托，上限都是统一的33万円；特例专属于买卖，贷借场景完全走另一套借賃×月数规则，两者不能混用。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h28-44', '{"id":"h28-44","tag":"宅地建物取引业法等・クーリング・オフ","title":"平成28年 問44","stem":"宅地建物取引業者Ａが、自ら売主として、宅地建物取引業者でないＢと宅地の売買契約を締結した場合、宅地建物取引業法第37条の２の規定に基づくいわゆるクーリング・オフについてＡがＢに告げるときに交付すべき書面の内容に関する次の記述のうち、誤っているものはどれか。","options":["Ａについては、その商号又は名称及び住所並びに免許証番号、Ｂについては、その氏名（法人の場合、その商号又は名称）及び住所が記載されていなければならない。","Ｂは、クーリング・オフについて告げられた日から起算して８日を経過するまでの間は、代金の全部を支払った場合を除き、書面によりクーリング・オフによる契約の解除を行うことができることが記載されていなければならない。","クーリング・オフによる契約の解除は、Ｂが当該契約の解除を行う旨を記載した書面を発した時にその効力を生ずることが記載されていなければならない。","Ｂがクーリング・オフによる契約の解除を行った場合、Ａは、それに伴う損害賠償又は違約金の支払をＢに請求することができないこと、また、売買契約の締結に際し、手付金その他の金銭が支払われているときは、遅滞なくその全額をＢに返還することが記載されていなければならない。"],"correct":1,"explain":"【核心知识点】クーリング・オフ撤回/解除除外条件的完整表述——须同时满足受领引渡+支付全部代金两个条件。①对（不是错误项）。书面须记载A的商号/名称、住所、免许证番号，B的氏名（法人则为商号/名称）、住所（施行规则16条の6第1号・2号）。②错（答案）。撤回/解除的除外条件是受领引渡且支付全部代金，选项漏掉了受领引渡这半句，只写了支付全部代金——记载内容不完整就是错误（施行规则16条の6第3号）。③对（不是错误项）。解除效力发生于B发出解除书面之时（发信主义，施行规则16条の6第5号）。④对（不是错误项）。解除后A不能请求损害赔偿/违约金，且须无迟延返还全部已收金钱（施行规则16条の6第4号・6号）。","takeaway":"クーリング・オフ撤回/解除除外条件是受领引渡+支付全部代金两个条件同时满足才生效，只写支付全部代金漏掉受领引渡就构成错误——这是极容易被忽略的细节陷阱：文字表面看起来差不多对，但法定应记载事项要求逐字完整。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r04-29', '{"id":"r04-29","tag":"宅地建物取引业法等・宅建士","title":"令和4年 問29","stem":"宅地建物取引士に関する次の記述のうち、宅地建物取引業法の規定によれば、誤っているものはどれか。","options":["宅地建物取引士は、禁錮以上の刑に処せられた場合、刑に処せられた日から30日以内に、その旨を宅地建物取引士の登録を受けた都道府県知事に届け出なければならない。","宅地建物取引士は、業務に関して事務禁止の処分を受けた場合、速やかに、宅地建物取引士証をその交付を受けた都道府県知事に提出しなければならず、これを怠った場合には罰則の適用を受けることがある。","宅地建物取引士は、有効期間の満了日が到来する宅地建物取引士証を更新する場合、国土交通大臣が指定する講習を受講しなければならず、また、当該宅地建物取引士証の有効期間は5年である。","宅地建物取引士は、宅地建物取引士の信用を害するような行為をしてはならず、信用を害するような行為には、宅地建物取引士の職務に必ずしも直接関係しない行為や私的な行為も含まれる。"],"correct":2,"explain":"【核心知识点】更新讲习的指定主体是都道府県知事，容易跟国土交通大臣搞混。①对（不是错误项）。被处禁锢以上刑罚时，须自处刑之日起30日内向登録地知事申报。②对（不是错误项）。受事务禁止处分后，须速やかに向交付方知事提出宅建士证，不提出可处10万円以下过料。③错（答案）。宅建士证更新须受讲的是都道府県知事指定的讲习，不是国土交通大臣——选项把主体搞错了；有效期5年这点是对的。④对（不是错误项）。宅建士不能做有损信用的行为，这类行为含不直接关联职务的私人行为。","takeaway":"宅建士证的更新讲习始终是知事指定（不是大臣），这跟大臣免许vs知事免许这种业者免许分类是完全不同的概念，别混着记。很多类似由谁指定/由谁颁发的考点里，容易把都道府県知事和国土交通大臣搞混。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h24-45', '{"id":"h24-45","tag":"宅地建物取引业法等・住宅瑕疵担保履行法","title":"平成24年 問45","stem":"特定住宅瑕疵担保責任の履行の確保等に関する法律に基づく住宅販売瑕疵担保保証金の供託又は住宅販売瑕疵担保責任保険契約の締結（以下この問において「資力確保措置」という。）に関する次の記述のうち、正しいものはどれか。","options":["自ら売主として新築住宅を宅地建物取引業者でない買主に引き渡した宅地建物取引業者は、当該住宅を引き渡した日から３週間以内に、その住宅に関する資力確保措置の状況について、その免許を受けた国土交通大臣又は都道府県知事に届け出なければならない。","自ら売主として新築住宅を宅地建物取引業者でない買主に引き渡した宅地建物取引業者は、基準日に係る資力確保措置の状況の届出をしなければ、当該基準日の翌日から起算して50日を経過した日以後においては、新たに自ら売主となる新築住宅の売買契約を締結してはならない。","住宅販売瑕疵担保責任保険契約は、新築住宅を自ら売主として販売する宅地建物取引業者が住宅瑕疵担保責任保険法人と締結する保険契約であり、当該住宅の売買契約を締結した日から５年間、当該住宅の瑕疵によって生じた損害について保険金が支払われる。","新築住宅を自ら売主として販売する宅地建物取引業者が、住宅販売瑕疵担保保証金の供託をした場合、買主に対する当該保証金の供託をしている供託所の所在地等について記載した書面の交付及び説明は、当該住宅の売買契約を締結した日から引渡しまでに行わなければならない。"],"correct":1,"explain":"【核心知识点】住宅瑕疵担保履行法的三个时间节点容易被偷换——申报起算点是基准日不是引渡日，保险有效期起算点是引渡时不是契约締結日，供托所说明须在契约缔结前完成。①错。申报期限是每年3月31日基准日起3周内，不是住宅引渡之日起3周——起算点错了。②对（答案）。未申报的，从基准日翌日起算满50日后不能新签自己作卖主的新築住宅买卖契约——描述正确。③错。保险契约要保引渡后10年，不是契约締結日起5年——期限起算点和年限都错了。④错。供托所所在地说明须在契约缔结前完成，不是契约缔结日到引渡这段期间——时点错了。","takeaway":"申报起算点是基准日不是引渡日；未申报的宽限期是50日（本题正确项）；保险有效期是10年且从引渡时起算，不是契约締結日；供托所说明须在契约缔结前完成，不能拖到引渡。这几个时间点在历年真题里反复出题、反复被替换成错误的数字/起算点，是宅建业法这块的重灾区。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h27-5', '{"id":"h27-5","tag":"权利关系・占有权","title":"平成27年 問5","stem":"占有に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["甲建物の所有者Ａが、甲建物の隣家に居住し、甲建物の裏口を常に監視して第三者の侵入を制止していたとしても、甲建物に錠をかけてその鍵を所持しない限り、Ａが甲建物を占有しているとはいえない。","乙土地の所有者の相続人Ｂが、乙土地上の建物に居住しているＣに対して乙土地の明渡しを求めた場合、Ｃは、占有者が占有物について行使する権利は適法であるとの推定規定を根拠として、明渡しを拒否することができる。","丙土地の占有を代理しているＤは、丙土地の占有が第三者に妨害された場合には、第三者に対して占有保持の訴えを提起することができる。","占有回収の訴えは、占有を侵奪した者及びその特定承継人に対して当然に提起することができる。"],"correct":2,"explain":"【核心知识点】占有制度的四个独立细节——占有成立不要求物理上锁、推定规定只管权利适法不管权利变动、占有代理人也享有占有保护请求权、特定承继人的善恶意判断。①错。即使没有上锁持有钥匙，只要通过持续监视、实际控制（如常年居住隔壁并监视后门）也可以构成占有——判例认定这种情形依然算占有。②错。民法188条的推定规定，只推定权利存在/归属的适法性，不推定权利变动——C不能仅凭这条推定拒绝返还，须自己举证有合法权利（如赁借权）。③对（答案）。占有代理人（如D）同样享有占有保护请求权，被第三人妨害占有时可以提起占有保持之诉（民法181条・197条以下）。④错。占有回收之诉对特定承继人，原则不能提起，只有该承继人是恶意（知道侵夺事实）时才能提起——不是当然可以（民法200条2项）。","takeaway":"占有的成立不要求物理上锁，实际控制/监视也算；民法188条的推定只管权利适法，不管权利变动，两者容易混淆；占有代理人也享有占有保护请求权（占有保持之诉），不是只有本人才能主张；占有回收之诉对特定承继人原则不能提起，善意/恶意是关键判断标准——跟h25-4留置权题里占有开始需合法是不同但相关的占有法知识点，可以对照记忆。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-3', '{"id":"r07-3","tag":"权利关系・意思表示（个数问题）","title":"令和7年 問3","stem":"意思表示に関する次の記述のうち、民法の規定によれば、誤っているものはいくつあるか。\\nア　表意者が真意でないことを知ってした意思表示は無効であるが、相手方がその意思表示が表意者の真意ではないことを知らなければ、知らないことにつき過失があっても、当該意思表示は有効となる。\\nイ　相手方と通じてした虚偽の意思表示は無効であり、第三者がその虚偽表示につき善意であっても、過失があれば、当該第三者にその無効を対抗することができる。\\nウ　意思表示は、当該意思表示に対応する意思を欠く錯誤に基づくものであって、その錯誤が法律行為の目的及び取引上の社会通念に照らして重要なものであるときは、無効であるが、その錯誤につき善意でかつ過失がない第三者には、その無効を対抗することができない。\\nエ　詐欺による意思表示は取り消すことができるが、その詐欺につき善意でかつ過失がない取消し前の第三者には、その取消しを対抗することができない。","options":["一つ","二つ","三つ","四つ"],"correct":2,"explain":"【核心知识点】心裡留保、虚偽表示、错误、诈欺四种意思表示瑕疵的效力（无效/可撤销）与对抗要件要精确匹配。ア错。心裡留保原则有效，只有相对方明知或可得而知才无效——选项说表意者知道自己非真意就当然无效这个前提本身就错，而且过失（可得而知）时也会无效，选项后半段有过失也有效不对。イ错。通谋虚偽表示无效，不能对抗善意第三人，但是否有过失不影响——选项加了善意但有过失就能对抗这个不存在的条件。ウ错（核心陷阱）。重要错误的意思表示是可以撤销，不是无效——这是新民法改正后的规则，选项把取消错说成无效。エ对（不是错误项）。诈欺可撤销，不能对抗撤销前的善意无过失第三人。错误的有三个（アイウ），答案是肢3。","takeaway":"心裡留保——原则有效，相对方明知/可得而知则无效；虚偽表示——无效，善意第三人可以对抗（不问过失）；错误——是取消不是无效（新民法改正后的重要变化，容易用旧知识误答）；诈欺——可撤销，撤销前善意无过失第三人可以对抗。四者规则细节各不相同，是这类题目最容易被出题者拿来相互替换制造混淆的地方。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-2', '{"id":"h30-2","tag":"权利关系・代理","title":"平成30年 問2","stem":"Ａが、所有する甲土地の売却に関する代理権をＢに授与し、ＢがＣとの間で、Ａを売主、Ｃを買主とする甲土地の売買契約（以下この問において「本件契約」という。）を締結した場合における次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["Ｂが売買代金を着服する意図で本件契約を締結し、Ｃが本件契約の締結時点でこのことを知っていた場合であっても、本件契約の効果は当然にＡに帰属する。","ＡがＢに代理権を授与するより前にＢが補助開始の審判を受けていた場合、Ｂは有効に代理権を取得することができない。","ＢがＣの代理人にもなって本件契約を成立させた場合、Ａの許諾の有無にかかわらず、本件契約は無効となる。","ＡがＢに代理権を授与した後にＢが後見開始の審判を受け、その後に本件契約が締結された場合、Ｂによる本件契約の締結は無権代理行為となる。"],"correct":3,"explain":"【核心知识点】代理制度四个独立细节，②④的时间顺序对比是关键。①错。代理人B表面上在代理权限范围内行事，实际却是为了着服代金，属于代理权濫用（民法107条）。相对方C明知这个意图时，该行为视为无权代理行为——契约效果不会当然归属于A。②错。B是在被授予代理权之前就已经受到补助开始的审判——代理人不要求具备行为能力（民法102条），被补助人B可以有效取得代理权，跟④的时间顺序（先授权后受审判）刚好相反。③错。B同时成为对方C的代理人，这是双方代理问题。双方代理原则上视为无权代理行为（不是无效），而且本人许诺时有效（民法108条1项）——选项把无权代理错说成无效，又把许诺后依然无效这点也说错了，双重错误。④对（答案）。B是在被授予代理权之后才受到后见开始的审判——代理人受后见开始审判是代理权的消灭事由（民法111条1项2号）。审判后B再缔结的本件契约，构成无权代理行为。","takeaway":"代理权濫用和双方代理都是视为无权代理（不是当然有效也不是无效），这个法律效果的措辞是最容易混淆的地方。②是先有欠格状态（补助开始审判）后被授予代理权——代理人不要求有行为能力，所以有效取得代理权；④是先被授予代理权后发生欠格事由（后见开始审判）——后见开始审判是代理权的消灭事由，之后的代理行为构成无权代理。代理权消灭事由：代理人死亡/破产/后见开始审判都消灭；本人这边死亡消灭，破产法定代理消灭任意代理不消灭，后见开始审判不消灭。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r04-9', '{"id":"r04-9","tag":"权利关系・家族法（辞任）","title":"令和4年 問9","stem":"辞任に関する次の記述のうち、民法の規定によれば、正しいものはいくつあるか。\\nア　委任によって代理権を授与された者は、報酬を受ける約束をしている場合であっても、いつでも委任契約を解除して代理権を消滅させて、代理人を辞することができる。\\nイ　親権者は、やむを得ない事由があるときは、法務局に届出を行うことによって、親権を辞することができる。\\nウ　後見人は、正当な事由があるときは、後見監督人の許可を得て、その任務を辞することができる。\\nエ　遺言執行者は、正当な事由があるときは、相続人の許可を得て、その任務を辞することができる。","options":["一つ","二つ","三つ","四つ"],"correct":0,"explain":"【核心知识点】四种辞任制度中许可机关的统一记忆。ア对。受托代理权的人，不管是否约定了报酬，都可以随时解除委任契约从而消灭代理权——这是委任契约的任意解除权（民法651条1项），跟是否有偿无关。イ错。亲权的辞任须经家庭裁判所的许可（民法837条1项），不是向法务局申报——选项把许可机关和程序方式都搞错了。ウ错。后见人的辞任须经家庭裁判所的许可（民法844条），不是后见监督人的许可——许可主体搞错了。エ错。遗言执行者的辞任须经家庭裁判所的许可（民法1019条2项），不是相续人的许可——许可主体又搞错了。正确的只有ア一个，答案是一つ。","takeaway":"除了委任契约的任意解除（不需要任何许可，随时可解除）之外，亲权、后见人、遗言执行者这三种辞任全部都需要家庭裁判所的许可，选项常把许可主体换成法务局/后见监督人/相续人这些看似合理但错误的主体。记忆口诀：委任是随时可辞，亲权/后见/遗言执行者是须经家庭裁判所许可才能辞——真正的许可方永远是家庭裁判所。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-5', '{"id":"h25-5","tag":"权利关系・担保物权（抵当权）","title":"平成25年 問5","stem":"抵当権に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["債権者が抵当権の実行として担保不動産の競売手続をする場合には、被担保債権の弁済期が到来している必要があるが、対象不動産に関して発生した賃料債権に対して物上代位をしようとする場合には、被担保債権の弁済期が到来している必要はない。","抵当権の対象不動産が借地上の建物であった場合、特段の事情がない限り、抵当権の効力は当該建物のみならず借地権についても及ぶ。","対象不動産について第三者が不法に占有している場合、抵当権は、抵当権設定者から抵当権者に対して占有を移転させるものではないので、事情にかかわらず抵当権者が当該占有者に対して妨害排除請求をすることはできない。","抵当権について登記がされた後は、抵当権の順位を変更することはできない。"],"correct":1,"explain":"【核心知识点】抵当权效力范围与借地上建筑物的关联规则，可与h25-4留置权对比记忆。①错。抵当权效力及于果实（如租金），须以被担保债权已发生债务不履行为前提（民法371条），而债务不履行须以弁済期已到来为前提——所以就赁料债权做物上代位，同样需要被担保债权的弁済期已到来，跟竞卖手续的要求一致。②对（答案）。借地上建筑物设定抵当权时，建筑物所有权与敷地赁借权是一体的——竞卖取得建筑物后若没有敷地利用权，建筑物就只能拆除。因此，抵当权的效力不仅及于建筑物，也及于敷地的赁借权（民法370条，最判昭40.5.4）。③错。抵当权是非占有型担保物权，原则上不干涉标的物利用关系，但第三人不法占有导致竞卖进行受妨害、价格下跌时，抵当权人可以代位行使抵当权设定者对不法占有者的妨害排除请求权（最判平11.11.24）——选项说事情にかかわらず不能行使是错的。④错。抵当权的顺位可以经抵当权人合意变更（民法374条1项本文，有利害关系人时需其承诺）——登记只是对抗第三人的要件，登记后依然可以变更顺位。","takeaway":"物上代位（对赁料债权）跟竞卖实行一样要求被担保债权弁済期已到来；借地上建筑物的抵当权效力及于敷地赁借权，这跟h25-4留置权题里建物的留置权不及于第三者所有的敷地是相反的结论——留置权不延伸到敷地，但抵当权延伸到敷地赁借权，两者对比记忆效果更好；抵当权人对不法占有者的妨害排除可以代位行使设定者的请求权；抵当权顺位登记后依然可以变更，登记只是对抗要件不是锁定顺位的手段。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h25-7', '{"id":"h25-7","tag":"权利关系・保证（判例）","title":"平成25年 問7","stem":"AがBに建物を賃貸期間の定めのある建物として賃貸し、Bのために保証人Cが賃貸人Aとの間で保証契約を締結した場合における次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["保証人が期間の定めのある建物の賃貸借の賃借人のために保証契約を締結した場合は、賃貸借契約の更新の際に賃貸人から保証意思の確認がなされていなくても、反対の趣旨をうかがわせるような特段の事情がない限り、更新後の賃借人の債務について保証する旨を合意したものと解される。","期間の定めのある建物の賃貸借の賃借人のための保証人が更新後の賃借人の債務についても保証の責任を負う趣旨で合意した場合には、賃借人の未払賃料が１年分に及んだとしても、賃貸人が保証債務の履行を請求することが信義則に反すると認められる事情がなければ、保証人は当該金額の支払義務を負う。","期間の定めのある建物の賃貸借の賃借人のための保証人が更新後の賃借人の債務についても保証の責任を負う場合、更新後の未払賃料について保証人の責任は及ぶものの、更新後に賃借人が賃借している建物を故意又は過失によって損傷させた場合の損害賠償債務には保証人の責任は及ばない。","期間の定めのある建物の賃貸借の賃借人のための保証人が更新後の賃借人の債務についても保証の責任を負う旨の合意をしたものと解される場合であって、賃貸人において保証債務の履行を請求することが信義則に反すると認められるときには、保証人は更新後の賃借人の債務について保証の責任を負わない。"],"correct":2,"explain":"【核心知识点】有期限建筑物赁贷借的保证人，原则上对更新后产生的承租人债务同样负责（不需要更新时重新确认保证意思），但有两个例外：①有相反特殊情形时不负责；②房东追及责任违反信义则时保证人可免责。而保证人责任覆盖的范围是赁贷借关系产生的一切债务，不只是欠租。①对（不是错误项）。有期限建筑物赁贷借中，保证人为承租人签订保证契约，即使更新时未再确认保证意思，除非有相反特殊情形，否则推定为对更新后债务同样负保证责任（最判平9.11.13）。②对（不是错误项）。保证人对更新后欠租负责，即便欠租累积达1年份，只要没有追及信义则违反的情形，依然要支付。③错（答案）。保证人的保证责任覆盖的是承租人基于赁贷借关系产生的全部债务，不只是欠租——承租人故意或过失损坏建筑物产生的损害赔偿债务，同样在保证责任范围内，选项说不涉及是错的。④对（不是错误项）。若房东追及责任的行为违反信义则，保证人可以免责——这也是判例明确的例外情形。","takeaway":"有期限建筑物赁贷借的保证人，原则上对更新后产生的承租人债务同样负责，不需要更新时重新确认保证意思；例外情形有相反特殊情形或房东追及责任违反信义则时不负责；保证人责任覆盖的范围是赁贷借关系产生的一切债务，不只是欠租，还包括故意/过失损坏建筑物的损害赔偿——这是本题的核心陷阱。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h30-11', '{"id":"h30-11","tag":"权利关系・借地借家法（借地）","title":"平成30年 問11","stem":"ＡとＢとの間で、Ａ所有の甲土地につき建物所有目的で賃貸借契約（以下この問において「本件契約」という。）を締結する場合に関する次の記述のうち、民法及び借地借家法の規定並びに判例によれば、正しいものはどれか。","options":["本件契約が専ら事業の用に供する建物の所有を目的とする場合には、公正証書によらなければ無効となる。","本件契約が居住用の建物の所有を目的とする場合には、借地権の存続期間を20年とし、かつ、契約の更新請求をしない旨を定めても、これらの規定は無効となる。","本件契約において借地権の存続期間を60年と定めても、公正証書によらなければ、その期間は30年となる。","Ｂは、甲土地につき借地権登記を備えなくても、Ｂと同姓でかつ同居している未成年の長男名義で保存登記をした建物を甲土地上に所有していれば、甲土地の所有権を新たに取得した者に対して、賃借権を対抗することができる。"],"correct":1,"explain":"【核心知识点】公正证书只是事业用定期借地权的方式要求，不是所有事业用途契约都要；对借地人不利的特约（期限不满30年、不许更新）无效，是强行规定。①错。普通借地权本身不需要公正证书才有效——公正证书是事业用定期借地权这个特定类型才要求的方式，本题只说以事业用建筑物为目的，没说是定期借地权，普通借地权即使是事业用途，也不需要公正证书。②对（答案）。普通借地权最低存续期间30年，约定20年（短于法定下限）或约定不许更新请求，都是对借地权人不利的特约，一律无效（借地借家法9条），无效后适用法定的30年及可更新规则。③错。约定期限超过30年（如60年）时，依约定期限有效，不需要公正证书——只有约定不满30年时才会被拉回30年，选项把超过法定下限和需要公正证书这两件事搞混了。④错。借地权对抗第三人除登记本身外，也可用地上建筑物登记为借地权人本人名义替代（借地借家法10条1项）——但登记名义人必须是借地权人本人，本题登记在儿子名下（即便同姓同住），不满足这个替代要件，不能对抗新所有权人（最判昭47.6.22）。","takeaway":"公正证书只是事业用定期借地权的方式要求，不是所有事业用途契约都要；存续期间不满30年或约定不许更新，属于对借地人不利的特约，一律无效（强行规定）；期限约定超过30年时依约定有效，公正证书不是普通借地权的成立要件；借地权对抗第三人的替代方式要求登记名义人必须是借地权人本人，登记在家人名下不算数。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03s-18', '{"id":"r03s-18","tag":"法令上的制限・建筑基準法","title":"令和3年12月 問18","stem":"次の記述のうち、建築基準法（以下この問において「法」という。）の規定によれば、正しいものはどれか。","options":["法第68条の9第1項の規定に基づく条例の制定の際、現に建築物が立ち並んでいる道は、法上の道路とみなされる。","都市計画により、容積率の限度が10分の50とされている準工業地域内において、建築物の高さは、前面道路の反対側の境界線からの水平距離が35ｍ以下の範囲内においては、当該部分から前面道路の反対側の境界線までの水平距離に、1.5を乗じて得た値以下でなければならない。","第一種住居地域においては、畜舎で、その用途に供する部分の床面積が4,000㎡のものを建築することができる。","建築物の敷地が、法第53条第1項の規定に基づく建築物の建蔽率に関する制限を受ける地域又は区域の二以上にわたる場合においては、当該建築物の敷地の過半の属する地域又は区域における建蔽率に関する制限が、当該建築物に対して適用される。"],"correct":1,"explain":"【核心知识点】用途制限是过半主义，建蔽率/容积率是加重平均主义，两套不同规则的适用范围要分清。①错。みなし道路的基准时点是建筑基准法施行时或编入都市计画区域/准都市计画区域时，不是根据68条の9第1项条例制定之时——这个时点表述本身就是错的。②对（答案）。这是道路斜线制限的具体计算规则——准工业地域容积率上限50/10（=5倍）时，斜线制限适用范围的水平距离限制35米以下、斜率系数1.5——数字组合正确。③错。第一种住居地域内建造畜舎，用途部分面积限制在3000㎡以下（建筑基准法48条5项、别表第二（ほ）项），本题4000㎡超过限制，不能建造。④错。建筑基地跨越建蔽率不同的地域时，采用按面积比例加权平均（按分计算）方式确定建蔽率（建筑基准法53条2项），不是按过半所属地域的建蔽率——用途限制才是过半主义，建蔽率/容积率是加重平均主义，两者容易被混淆。","takeaway":"用途制限（能不能建某种用途的建筑物）看基地过半所属的地域来决定，建蔽率、容积率（能建多少）则要按各地域所占面积比例加权平均计算，选项常把这两套规则混用；みなし道路的基准时点是法施行时/编入区域时，不是条例制定时；畜舎在第一种住居地域的面积上限是3000㎡。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h29-23', '{"id":"h29-23","tag":"税相关法令・所得税","title":"平成29年 問23","stem":"所得税法に関する次の記述のうち、正しいものはどれか。","options":["個人が台風により主として保養の用に供する目的で所有する別荘について受けた損失の金額（保険金等により補てんされる部分の金額を除く。）は、その損失を受けた日の属する年分又はその翌年分の譲渡所得の金額の計算上控除される。","建物の所有を目的とする土地の賃借権の設定の対価として支払を受ける権利金の金額が、その土地の価額の10分の５に相当する金額を超えるときは、不動産所得として課税される。","譲渡所得とは資産の譲渡による所得をいうので、不動産業者である個人が営利を目的として継続的に行っている土地の譲渡による所得は、譲渡所得として課税される。","個人が相続（限定承認に係るものを除く。）により取得した譲渡所得の基因となる資産を譲渡した場合における譲渡所得の金額の計算については、その資産をその相続の時における価額に相当する金額により取得したものとして計算される。"],"correct":3,"explain":"【核心知识点】继承取得资产的讓渡所得计算，承继被继承人（前手）的取得费和取得时点，这是所得税法基础且常考的规则。①这个选项的规则文字表述与条文本身较为接近（生活上非通常必要资产因灾害产生的损失可从受损当年或翌年讓渡所得中控除），但官方认定它不是正解，可能在控除的优先顺序等细节上有出入，具体错误点未能完全查证清楚。②错。土地赁借权设定权利金超过土地价额10分の5时，课税类别是讓渡所得，不是不动产所得——选项把税目搞错了。③错。不动产业者以营利为目的连续性从事的土地讓渡所得，属于事业所得（营业性质），不是讓渡所得——讓渡所得指的是非持续性/非营业性质的资产处分所得。④对（答案）。因继承（限定承认除外）取得的资产再讓渡时，讓渡所得的计算承继被继承人的取得费和取得时点——具体表述为以继承时的价额取得，这是所得税法的取得费承继原则，描述正确。","takeaway":"继承取得资产的讓渡所得计算承继被继承人的取得费和取得时点，不是以继承时的市价重新计价——这是所得税法非常基础且常考的规则；权利金超过土地价额一半算讓渡所得（不是不动产所得）；业者持续性经营土地讓渡算事业所得（不是讓渡所得）；这题①选项的细节存在不确定性，建议后续再核实补充。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h16-2', '{"id":"h16-2","tag":"权利关系・无权代理与相续（难题，冷门知识点）","title":"平成16年 問2","stem":"Ｂ所有の土地をＡがＢの代理人として、Ｃとの間で売買契約を締結した場合に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["ＡとＢとが夫婦であり契約に関して何ら取り決めのない場合には、不動産売買はＡＢ夫婦の日常の家事に関する法律行為の範囲内にないとＣが考えていた場合も、本件売買契約は有効である。","Ａが無権代理人である場合、ＣはＢに対して相当の期間を定めて、その期間内に追認するか否かを催告することができ、Ｂが期間内に確答をしない場合には、追認とみなされ本件売買契約は有効となる。","Ａが無権代理人であっても、Ｂの死亡によりＡがＤとともにＢを共同相続した場合には、Ｄが追認を拒絶していても、Ａの相続分に相当する部分についての売買契約は、相続開始と同時に有効となる。","Ａが無権代理人であって、Ａの死亡によりＢが単独でＡを相続した場合には、Ｂは追認を拒絶できるが、ＣがＡの無権代理につき善意無過失であれば、ＣはＢに対して損害賠償を請求することができる。"],"correct":3,"explain":"【核心知识点，历年只出过一次的冷门难题，了解结论即可】本人继承无权代理人和无权代理人继承本人这两种继承方向的效果完全不同。①错。AB夫妻间没有任何约定，土地买卖不属于日常家事范畴。想让C受权限外行为的表见代理保护（民法110条类推适用），须C善意无过失地相信该行为属于日常家事范围——本题C自己都认为不属于日常家事范围，明显不构成善意无过失，不能被保护，契约无效。②错。相对方对本人的催告，若本人在期间内不确答，视为拒绝追认（民法114条），不是视为追认。③错。无权代理人和其他共同继承人一起继承本人时，追认须全体共同继承人一致同意才行，不能只让无权代理人自己的继承份额当然有效（最判平5.1.21）——D拒绝追认，A的份额也不能单独生效。④对（答案）。无权代理人A死亡后，本人B单独继承A——B此时同时具有本人和无权代理人两种身份。B作为本人，依然可以拒绝追认；但B也继承了A作为无权代理人的损害赔偿责任，若相对方C对无权代理善意无过失，C可以向B请求损害赔偿（判例，民法117条）。","takeaway":"本人（B）继承无权代理人（A）——本人身份优先，可以拒绝追认，但仍要承担无权代理人的损害赔偿责任（双重身份并存但责任不同）；无权代理人（A）和其他人（D）共同继承本人（B）——须全体一致追认，不能按继承份额部分生效。这道题涉及夫妇日常家事代理权+表见代理类推适用这个非常冷门的知识点，历年只考过一次，不用太深挖。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h16-8', '{"id":"h16-8","tag":"权利关系・相殺","title":"平成16年 問8","stem":"Ａは、Ｂ所有の建物を賃借し、毎月末日までに翌月分の賃料50万円を支払う約定をした。またＡは敷金300万円をＢに預託し、敷金は賃貸借終了後明渡し完了後にＢがＡに支払うと約定された。ＡのＢに対するこの賃料債務に関する相殺についての次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["Ａは、Ｂが支払不能に陥った場合は、特段の合意がなくても、Ｂに対する敷金返還請求権を自働債権として、弁済期が到来した賃料債務と対当額で相殺することができる。","ＡがＢに対し悪意による不法行為に基づく損害賠償請求権を有した場合、Ａは、このＢに対する損害賠償請求権を自働債権として、弁済期が到来した賃料債務と対当額で相殺することはできない。","ＡがＢに対して商品の売買代金請求権を有しており、それが平成16年９月１日をもって時効により消滅した場合、Ａは、同年９月２日に、このＢに対する代金請求権を自働債権として、同年８月31日に弁済期が到来した賃料債務と対当額で相殺することはできない。","ＡがＢに対してこの賃貸借契約締結以前から貸付金債権を有しており、その弁済期が平成16年８月31日に到来する場合、同年８月20日にＢのＡに対するこの賃料債権に対する差押があったとしても、Ａは、同年８月31日に、このＢに対する貸付金債権を自働債権として、弁済期が到来した賃料債務と対当額で相殺することができる。"],"correct":3,"explain":"【核心知识点】相殺制度的四个独立细节——自働债权须已到弁済期、不法行为损害赔偿债权不能做受働债权但能做自働债权、时效消滅债权消滅前处于相殺适状依然可相殺、差押前取得的反对债权可对抗差押。①错。主张相殺须自働债权已到弁済期——敷金返还请求权须等赁贷借终了+交房完毕后才发生，本题赁贷借尚未终了，敷金返还请求权尚未到弁済期，A不能拿它来相殺。②错。恶意不法行为产生的损害赔偿债权，禁止被拿来当受働债权；但作为自働债权是被允许的——被害人自己愿意相殺没有阻止的理由。选项把能不能作为自働债权和能不能作为受働债权搞反了。③错。已因时效消滅的债权，若在消滅之前曾经处于相殺适状，债权人依然可以拿这个已消滅的债权做自働债权来相殺（民法508条）——保护双方对两笔债权已经互相抵消的合理期待。④对（答案）。债权被差押后，第三债务者用差押之后才取得的债权来相殺，不能对抗差押债权人；但若反对债权是在差押之前就已取得，即使弁済期先后不同，只要两者最终都达到相殺适状，依然可以用这笔差押前就有的债权来相殺对抗差押（最判昭45.6.24）。","takeaway":"自働债权须已到弁済期，敷金返还请求权在赁贷借终了前根本不存在这个弁済期；恶意不法行为损害赔偿债权不能做受働债权，但能做自働债权——这个方向性区分是最容易搞反的地方；时效消滅的债权，只要消滅前处于相殺适状，依然可以相殺；差押后能否相殺，关键看反对债权是差押前还是差押后取得的。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h24-9', '{"id":"h24-9","tag":"权利关系・使用者责任","title":"平成24年 問9","stem":"Ａに雇用されているＢが、勤務中にＡ所有の乗用車を運転し、営業活動のため得意先に向っている途中で交通事故を起こし、歩いていたＣに危害を加えた場合における次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["ＢのＣに対する損害賠償義務が消滅時効にかかったとしても、ＡのＣに対する損害賠償義務が当然に消滅するものではない。","Ｃが即死であった場合には、Ｃには事故による精神的な損害が発生する余地がないので、ＡはＣの相続人に対して慰謝料についての損害賠償責任を負わない。","Ａの使用者責任が認められてＣに対して損害を賠償した場合には、ＡはＢに対して求償することができるので、Ｂに資力があれば、最終的にはＡはＣに対して賠償した損害額の全額を常にＢから回収することができる。","Ｃが幼児である場合には、被害者側に過失があるときでも過失相殺が考慮されないので、ＡはＣに発生した損害の全額を賠償しなければならない。"],"correct":0,"explain":"【核心知识点】使用者责任的综合应用——使用者和被用者的赔偿债务是连带债务、相对效；即死被害人的慰藉料请求权同样可以被继承；使用者对被用者的求偿受信义则限制；过失相殺看的是被害者側。①对（答案）。使用者责任的损害赔偿债务是连带债务——被用者B的债务因时效消滅，不会连动导致使用者A的债务也当然消滅，两者各自独立（相对效）。②错。即使被害者当场死亡（即死），判例依然认可被害人本身在受害瞬间产生了精神损害，慰藉料请求权可以被继承人继承——A对C的继承人依然要负慰藉料赔偿责任。③错。使用者A对被用者B的求偿权，限于信义则上相当认可的限度（判例），不是常に全額都能追回——B即使有资力，A也不能保证能拿回全部赔偿额。④错。被害者是幼儿时，被害者本人虽无过失，但被害者側（含监护人等有过失关系的人）若有过失，依然可以考虑过失相殺——不是幼儿=绝对不能相殺。","takeaway":"使用者和被用者的赔偿债务是连带债务、相对效（一方时效消滅不影响另一方）；即死被害人的慰藉料请求权同样可以被继承；使用者对被用者的求偿受信义则限制，不是全额保证能拿回；过失相殺看的是被害者側（不限于被害人本人，含监护人等有过失关系的人），幼儿本身无过失不代表不能相殺。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r05-11', '{"id":"r05-11","tag":"权利关系・借地借家法（借地）","title":"令和5年 問11","stem":"ＡがＢとの間で、Ａ所有の甲土地につき建物所有目的で期間を50年とする賃貸借契約（以下この問において「本件契約」という。）を締結する場合に関する次の記述のうち、借地借家法の規定及び判例によれば、正しいものはどれか。","options":["本件契約に、当初の10年間は地代を減額しない旨の特約を定めた場合、その期間内は、ＢはＡに対して地代の減額請求をすることはできない。","本件契約が甲土地上で専ら賃貸アパート事業用の建物を所有する目的である場合、契約の更新や建物の築造による存続期間の延長がない旨を定めるためには、公正証書で合意しなければならない。","本件契約に建物買取請求権を排除する旨の特約が定められていない場合、本件契約が終了したときは、その終了事由のいかんにかかわらず、ＢはＡに対してＢが甲土地上に所有している建物を時価で買い取るべきことを請求することができる。","本件契約がＢの居住のための建物を所有する目的であり契約の更新がない旨を定めていない契約であって、期間満了する場合において甲土地上に建物があり、Ｂが契約の更新を請求したとしても、Ａが遅滞なく異議を述べ、その異議に更新を拒絶する正当な事由があると認められる場合は、本件契約は更新されない。"],"correct":3,"explain":"【核心知识点，官方数据正解率64.4%】不减额特约无效（不增额特约有效）；定期借地权类型由用途（居住vs事业）决定，事业用居住性质的公寓也只能用一般定期借地权；建物买取请求权只在期间满了终了时适用，债务不履行解除不适用；普通借地权期满时房东依然可以提异议阻止更新。①错。不减额特约（地代不减少的特约）无效（借地借家法11条1项本文），即使约定了当初10年不减额，B依然可以请求减额——只有不增额特约有效，两者规则不对称。②错。B想经营的是出租公寓事业用建筑物，本质是居住用建筑物，只能设定一般定期借地权（不能用事业用定期借地权，后者限定非居住用）——一般定期借地权只需书面合意即可，不需要公正证书。③错。建物买取请求权只在契约因期间满了而终了时才认可，若契约因赁借人（B）的债务不履行被解除终了，不适用建物买取请求权（判例昭35.2.9）——选项说不问终了事由都能请求是错的。④对（答案）。B契约的期间届满，即使B请求更新且甲土地上有建筑物，A依然可以提出异议（借地借家法5条1项但书），若该异议具有正当事由，契约不会更新（借地借家法6条）。","takeaway":"不减额特约无效、不增额特约有效——这个不对称规则容易被误以为两者都能约定；判断该用哪种定期借地权，关键看用途是不是居住用（居住用只能一般定期借地权→只需书面）；建物买取请求权只在期间满了终了时适用，因债务不履行解除时不适用；普通借地权（没约定不更新）期满时，房东依然可以提异议，只要异议有正当事由，契约就不会法定更新。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h21-12', '{"id":"h21-12","tag":"权利关系・赁贷借与使用贷借对照","title":"平成21年 問12","stem":"Ａ所有の甲建物につき、Ｂが一時使用目的ではなく賃料月額10万円で賃貸借契約を締結する場合と、Ｃが適当な家屋に移るまでの一時的な居住を目的として無償で使用貸借契約を締結する場合に関する次の記述のうち、民法及び借地借家法の規定並びに判例によれば、誤っているものはどれか。","options":["ＢがＡに無断で甲建物を転貸しても、Ａに対する背信的行為と認めるに足らない特段の事情があるときは、Ａは賃貸借契約を解除できないのに対し、ＣがＡに無断で甲建物を転貸した場合には、Ａは使用貸借契約を解除できる。","期間の定めがない場合、ＡはＢに対して正当な事由があるときに限り、解約を申し入れることができるのに対し、返還時期の定めがない場合、ＡはＣに対していつでも返還を請求できる。","Ａが甲建物をＤに売却した場合、甲建物の引渡しを受けて甲建物で居住しているＢはＤに対して賃借権を主張することができるのに対し、Ｃは甲建物の引渡しを受けて甲建物に居住していてもＤに対して使用借権を主張することができない。","Ｂが死亡しても賃貸借契約は終了せず賃借権はＢの相続人に相続されるのに対し、Ｃが死亡すると使用貸借契約は終了するので使用借権はＣの相続人に相続されない。"],"correct":1,"explain":"【核心知识点】赁贷借（有偿）和使用贷借（无偿）在转贷、解约/返还、对抗力、相续四个维度上的系统性差异。①对（不是错误项）。赁贷借：B无断转贷，若不构成对A的背信行为，A不能解除赁贷借契约（民法612条2项，判例）。使用贷借：C无断转贷，没有类似判例限制贷主解除权，A可以解除使用贷借契约。②错（答案）。核心陷阱：赁贷借这边，没有期限约定时贷主解约须正当事由（借地借家法28条）——这半句对。但使用贷借这边，虽没约定返还时期，但约定了使用收益的目的（找到合适住处前的临时居住），贷主不能随时请求返还，须等C使用收益完毕所需的客观期间经过后才能请求（民法597条3项、598条1项）——选项说可以随时请求是错的。③对（不是错误项）。赁借权：B已受领引渡，可对抗新所有权人D主张赁借权（借地借家法31条1项）。使用借权：没有对抗方法，C不能对D主张。④对（不是错误项）。赁借权：B死亡后作为财产权被继承，契约不终止。使用借权：因借用人C死亡而当然终止（民法599条1项），不被继承。","takeaway":"赁贷借（有偿）保护更强：无背信情形不能解除、需要正当事由才能解约、有对抗力、能被继承；使用贷借（无偿，基于情谊关系）保护更弱：无断转贷可解除、约定使用目的时须等客观期间经过才能请求返还（这是本题陷阱，别以为没约定返还时期=随时能要回）、无对抗力、借用人死亡当然终止不被继承。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h19-15', '{"id":"h19-15","tag":"权利关系・区分所有法","title":"平成19年 問15","stem":"建物の区分所有等に関する法律に関する次の記述のうち、誤っているものはどれか。","options":["規約は、管理者が保管しなければならない。ただし、管理者がないときは、建物を使用している区分所有者又はその代理人で規約又は集会の決議で定めるものが保管しなければならない。","最初に建物の専有部分の全部を所有する者は、公正証書により、建物の共用部分を定める規約を設定することができる。","規約を保管する者は、利害関係人の請求があったときは、正当な理由がある場合を除いて、規約の閲覧を拒んではならない。","規約の保管場所は、各区分所有者に通知するとともに、建物内の見やすい場所に掲示しなければならない。"],"correct":3,"explain":"【核心知识点】规约的保管・阅览・保管场所公示三件事的具体要求要分开记，保管场所只需要掲示（张贴公示），不需要個別通知。①对（不是错误项）。规约须由管理者保管，没有管理者时由使用建筑物的区分所有者或其代理人（规约或集会决议指定的人）保管（区分所有法33条1项）。②对（不是错误项）。最初拥有建筑物全部专有部分的人，可以用公正证书设定规约，可设定事项包含规约共用部分（区分所有法32条、4条2项）。③对（不是错误项）。规约保管人对利害关系人的阅览请求，除有正当理由外不能拒绝（区分所有法33条2项）——拒绝可处20万日元以下过料。④错（答案）。规约保管场所须在建筑物内显眼处揭示（区分所有法33条4项），但不要求向各区分所有者个别通知——选项凭空加了通知这个不存在的义务。","takeaway":"规约的保管人是管理者（无管理者时按规约/决议指定）；阅览请求原则不能拒绝（除非有正当理由）；保管场所只需要掲示（张贴公示），不需要個別通知每一位区分所有者——多做的事情不代表法律要求你做，选项常通过还要做XX才行来把正确规则说错。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03-10-14', '{"id":"r03-10-14","tag":"权利关系・不动产登记法（单独申请例外）","title":"令和3年10月 問14","stem":"不動産の登記に関する次の記述のうち、不動産登記法の規定によれば、正しいものはどれか。","options":["所有権の登記の抹消は、所有権の移転の登記がある場合においても、所有権の登記名義人が単独で申請することができる。","登記の申請をする者の委任による代理人の権限は、本人の死亡によって消滅する。","法人の合併による権利の移転の登記は、登記権利者が単独で申請することができる。","信託の登記は、受託者が単独で申請することができない。"],"correct":2,"explain":"【核心知识点】单独申请的多个例外场景要分开记，本题考的是所有权抹消/委任代理权存续/法人合并/信托登记这四个独立细节。①错。所有权抹消登记原则须共同申请（有移转登记存在时，抹消会导致所有权得失双方产生），只有没有移转登记（即只有保存登记）时才能单独申请（不动产登记法77条）——本题有移转登记存在，不能单独申请。②错。委任代理权原则因本人死亡而消滅（民法101条1项1号），但登记申请场合有特例：登记申请代理人的权限不因本人死亡而消滅（不动产登记法17条1号）——这是不动产登记法优先适用民法的特例。③对（答案）。法人合并导致权利移转的登记，登记权利者可以单独申请（不动产登记法63条2项）——法人合并后无对立当事人，可以单独申请。④错。信托登记，受托者可以单独申请（不动产登记法98条2项），选项说不能是错的。","takeaway":"所有权抹消只有在没有移转登记时才能单独申请（本题有移转登记，不行）；登记申请代理人的权限不因本人死亡而消滅——这是不动产登记法对民法一般规则的特例覆盖；法人合并的权利移转登记可以单独申请（合并后没有对立当事人）；信托登记本身也可以由受托者单独申请。这几个单独申请的例外场景，建议按表示登记/权利登记分类整理成表格记忆。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r04-21', '{"id":"r04-21","tag":"法令上的制限・农地法","title":"令和4年 問21","stem":"農地に関する次の記述のうち、農地法（以下この問において「法」という。）の規定によれば、正しいものはどれか。","options":["農地の賃貸借及び使用貸借は、その登記がなくても農地の引渡しがあったときは、これをもってその後にその農地について所有権を取得した第三者に対抗することができる。","法第２条第３項の農地所有適格法人の要件を満たしていない株式会社は、耕作目的で農地を借り入れることはできない。","法第４条第１項、第５条第１項の違反について原状回復等の措置に係る命令の対象となる者（違反転用者等）には、当該規定に違反した者又はその一般承継人は含まれるが、当該違反に係る土地について工事を請け負った者は含まれない。","法の適用については、土地の面積は、登記簿の地積によることとしているが、登記簿の地積が著しく事実と相違する場合及び登記簿の地積がない場合には、実測に基づき農業委員会が認定したところによる。"],"correct":3,"explain":"【核心知识点】农地赁贷借的引渡对抗要件不适用于使用贷借；农地所有适格法人以外的法人不能所有但可以借入农地（本题选项已第三次一字不差重复出题：R04-21、H30-22、H28-22）；原状回复命令对象含工程承包人；面积认定原则登记簿地积例外实测。①错。农地赁贷借（赁借权）无需登记，凭引渡即可对抗第三人（农地法16条）；但使用贷借（使用借权）没有这个特别对抗要件——农地法只对赁贷借设有这个特殊对抗规定，选项把两者混在一起说是错的。②错。农地所有适格法人以外的法人不能所有农地，但可以借入农地（满足一定要件时）——选项说不能借入是错的。③错。原状回复命令对象（违反转用者等）包括4条/5条违反者或其一般承继人、承揽了工程的承包人或其下承包人、以不正当手段获得许可的人——选项说不含承包工程的人是错的。④对（答案）。农地法适用上，土地面积原则依据登记簿地积，但登记簿地积与事实明显不符或没有登记簿地积时，依据实测并经农业委员会认定的面积（农地法56条）。","takeaway":"农地赁贷借的对抗要件是引渡，使用贷借没有这个特例，两者不能混为一谈；农地所有适格法人以外的法人不能所有但可以借入农地——这是历年反复出题的经典易错点（这次已是第三次一字不差重复：R04-21、H30-22、H28-22）；无许可转用的原状回复命令对象包含承包该工程的施工者；土地面积的判断基准原则是登记簿地积，例外时用实测+农委会认定。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h16-26', '{"id":"h16-26","tag":"税相关法令・不动产取得税","title":"平成16年 問26","stem":"不動産取得税に関する次の記述のうち、正しいものはどれか。","options":["不動産取得税は、不動産の取得に対し、当該不動産の所在する市町村において、当該不動産の取得者に課される。","宅地の取得に係る不動産取得税の課税標準は、当該宅地の価格の1/3の額とされる。","不動産取得税の課税標準となるべき額が９万円である土地を取得した者が当該土地を取得した日から６ヵ月後に隣接する土地で、その課税標準となるべき額が８万円であるものを取得した場合においては、それぞれの土地の取得について不動産取得税を課されない。","床面積が240㎡で、床面積１㎡当たりの価格が20万円である住宅を建築した場合、当該住宅の建築に係る不動産取得税の課税標準の算定については、当該住宅の価格から1,200万円が控除される。"],"correct":3,"explain":"【核心知识点】不动产取得税的征税主体、课税标准、相邻土地合并判定、新住宅控除面积区间。①错。不动产取得税是都道府県税，不是市町村税——选项把征税主体搞错了。②错。宅地取得的课税标准是宅地价格的1/2，不是1/3（跟h24-24考的是同一个知识点）。③错。土地取得日起1年内取得相邻土地时，须视为一笔土地取得合并计算——本题9万+8万=17万，超过土地免税点16万，须课税。选项说分别都不课税是错的（跟h23-23印纸税的分割规避防范逻辑相似，可对照记忆）。④对（答案）。住宅建筑面积240㎡在40㎡~240㎡区间内，符合新住宅1200万控除的适用条件，可以从住宅价格中控除1200万。","takeaway":"不动产取得税是都道府県税；宅地课税标准是价格的1/2；相邻土地1年内取得须合并计算免税点（防止拆分规避）；新住宅1200万控除的面积区间是40㎡~240㎡。详见附属考点\\"税相关法令常考数字速查表\\"。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h27-31', '{"id":"h27-31","tag":"宅地建物取引业法等・35条书面（个数问题）","title":"平成27年 問31","stem":"宅地建物取引業者が、宅地建物取引業法第35条に規定する重要事項の説明を行う場合における次の記述のうち、宅地建物取引業法の規定に違反するものはいくつあるか。\\nア　宅地の貸借の媒介の場合、当該宅地が都市計画法の第一種低層住居専用地域内にあり、建築基準法第56条第１項第１号に基づく道路斜線制限があるときに、その概要を説明しなかった。\\nイ　建物の貸借の媒介の場合、当該建物が新住宅市街地開発事業により造成された宅地上にあり、新住宅市街地開発法第32条第１項に基づく建物の使用及び収益を目的とする権利の設定又は移転について都道府県知事の承認を要する旨の制限があるときに、その概要を説明しなかった。\\nウ　建物の貸借の媒介の場合、当該建物が都市計画法の準防火地域内にあり、建築基準法第62条第１項に基づく建物の構造に係る制限があるときに、その概要を説明しなかった。","options":["一つ","二つ","三つ","なし"],"correct":1,"explain":"【核心知识点】建物贷借免说明的规则不是绝对的，有明文列举的例外事项；宅地贷借≠建物贷借，免说明特权只属于建物贷借。ア违反。这是宅地的贷借（不是建物贷借），法令上的制限的说明豁免只针对建物贷借——宅地贷借依然须说明道路斜线制限这类会影响未来建筑规划的法令限制，没说明构成违反。イ违反。新住宅市街地开发法32条1项的使用收益权限制（须经知事承认），是建物贷借场合下明文列举须说明的特殊例外事项——即使是建物贷借，这一项依然要说明，没说明构成违反。ウ不违反。准防火地域内的建筑构造规制（62条1项），是针对建造新建筑物时的规制，房子已经盖好了，这项规制对现有建物的贷借没有实际意义——不需要说明，不构成违反。违反的有两个（アイ），答案是二つ。","takeaway":"建物贷借免说明的规则有明文列举的例外事项（如新住宅市街地开发法的使用收益权限制），イ就是这个例外的典型代表；宅地贷借≠建物贷借，免说明特权只属于建物贷借，宅地贷借依然要按一般规则说明法令上的制限（跟r02s-32考的框架一致）；针对建造行为的规制，对已建成建物的贷借没有实际意义，不需要说明。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h29-38', '{"id":"h29-38","tag":"宅地建物取引业法等・37条书面","title":"平成29年 問38","stem":"宅地建物取引業者Ａが、宅地建物取引業法（以下この問において「法」という。）第37条の規定により交付すべき書面（以下この問において「37条書面」という。）に関する次の記述のうち、法の規定に違反しないものはどれか。","options":["Ａは、売主を代理して宅地の売買契約を締結した際、買主にのみ37条書面を交付した。","Ａは、自ら売主となる宅地の売買契約において、手付金等を受領するにもかかわらず、37条書面に手付金等の保全措置の内容を記載しなかった。","Ａは、媒介により宅地の売買契約を成立させた場合において、契約の解除に関する定めがあるにもかかわらず、37条書面にその内容を記載しなかった。","Ａは、自ら売主となる宅地の売買契約においてその目的物が種類又は品質に関して契約の内容に適合しない場合におけるその不適合を担保すべき責任に関する特約を定めたが、買主が宅地建物取引業者であり、担保責任に関する特約を自由に定めることができるため、37条書面にその内容を記載しなかった。"],"correct":1,"explain":"【核心知识点】分清37条书面和35条书面各自的记载事项范围——手付金等保全措施只在35条书面要求说明，37条书面根本不涉及这一项；37条书面的记载义务不因相对方是不是宅建业者而减免。①违反。A代理卖主缔结契约时，37条书面须交付给相对方及委托代理的本人双方，本题只交给了买方一方，遗漏了卖方（委托人），构成违反。②不违反（答案）。手付金等保全措施的内容根本不是37条书面的法定记载事项——这项属于35条书面（重要事项说明书）的记载事项。既然37条书面本来就不要求记载这一项，没记载不构成违反。③违反。契约解除相关的定め属于37条书面的任意记载事项（有约定就必须记载）——本题有解除相关约定却没记载，构成违反。④违反。契约不适合担保责任的特约是37条书面的任意记载事项，不因买方是宅建业者就能免除记载义务——这跟35条书面（对业者相对方可以省略部分说明）不同，37条书面对所有相对方都要如实记载，构成违反。","takeaway":"见附属知识点【35条书面 vs 37条书面记载事项对照表】。核心结论：手付金等保全措施只在35条书面要求说明，37条书面根本不涉及；37条书面的记载义务不因相对方是不是宅建业者而减免（这跟35条书面对业者可省略部分说明不同）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h20-6', '{"id":"h20-6","tag":"权利关系・连带债务与保证","title":"平成20年 問6","stem":"ＡからＢとＣとが負担部分２分の１として連帯して1,000万円を借り入れる場合と、ＤからＥが1,000万円を借り入れ、Ｆがその借入金返済債務についてＥと連帯して保証する場合とに関する次の記述のうち、民法の規定によれば、正しいものはどれか。","options":["Ａが、Ｂに対して債務を免除した場合にはＣが、Ｃに対して債務を免除した場合にはＢが、それぞれ500万円分の債務を免れる。Ｄが、Ｅに対して債務を免除した場合にはＦが、Ｆに対して債務を免除した場合にはＥが、それぞれ全額の債務を免れる。","Ａが、Ｂに対して履行を請求した効果はＣに及ばず、Ｃに対して履行を請求した効果はＢに及ばない。Ｄが、Ｅに対して履行を請求した効果はＦに及び、Ｆに対して履行を請求した効果はＥに及ばない。","Ｂについて時効が完成した場合にはＣが、Ｃについて時効が完成した場合にはＢが、それぞれ500万円分の債務を免れる。Ｅについて時効が完成した場合にはＦが、Ｆについて時効が完成した場合にはＥが、それぞれ全額の債務を免れる。","ＡＢ間の契約が無効であった場合にはＣが、ＡＣ間の契約が無効であった場合にはＢが、それぞれ1,000万円の債務を負う。ＤＥ間の契約が無効であった場合はＦが、ＤＦ間の契約が無効であった場合はＥが、それぞれ1,000万円の債務を負う。"],"correct":1,"explain":"【核心知识点，按现行法】保证关系里两个方向的效果不对称——主债务人的事由因附从性传导给保证人（457条1项明文规定），但保证人自己的事由不传导给主债务人（458条準用441条相対効原则，因为保证人没有负担部分）。连带债务人之间（B、C）现行法下免除、履行请求、时效完成都是纯相対効。①错。前半错：免除是相対効，B被免除后C依然要负全额。后半：D免除E（主债务人）→F因附从性全额免除，这句对；但D免除F（保证人）→不影响E，E依然负全额，这句错。②对（答案）。前半：A对B请求履行，效果不及于C——纯相対効，对。后半：D对E（主债务人）请求履行，因附从性效果及于F（民法457条1项明文规定）；D对F（保证人）请求履行，效果不及于E（458条準用441条相対効原则）——全部正确。③错。前半错：时效完成是相対効，B时効完成后C依然负全额。后半：E时効完成→F因附从性全额免除，这句对；但F时効完成→不影响E，这句错。④错。前半对：AB契约无效不影响C的连带债务。后半：DE契约无效（主债务本身不存在）→F应该因附从性免责，选项却说F负1000万，这句错；DF契约无效不影响DE主债务，E依然负1000万，这句对。","takeaway":"保证关系里主债务人的事由（如履行请求、免除、时効完成）会因附从性传导给保证人，这是保证制度的特有规则（457条明文规定）；但保证人自己的事由不会反向传导给主债务人（因为保证人没有负担部分，458条準用441条相対効原则）。这跟普通连带债务人之间（完全平等、互不影响）的相対効规则形成对比——保证关系是单向传导，连带债务人之间是互相独立。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h18-4', '{"id":"h18-4","tag":"权利关系・共有","title":"平成18年 問4","stem":"Ａ、Ｂ及びＣが、持分を各３分の１として甲土地を共有している場合に関する次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["甲土地全体がＤによって不法に占有されている場合、Ａは単独でＤに対して、甲土地の明渡しを請求できる。","甲土地全体がＥによって不法に占有されている場合、Ａは単独でＥに対して、Ｅの不法占有によってＡ、Ｂ及びＣに生じた損害全額の賠償を請求できる。","共有物たる甲土地の分割について共有者間に協議が調わず、裁判所に分割請求がなされた場合、裁判所は、特段の事情があれば、甲土地全体をＡの所有とし、ＡからＢ及びＣに対し持分の価格を賠償させる方法により分割することができる。","Ａが死亡し、相続人の不存在が確定した場合、Ａの持分は、民法第958条の２の特別縁故者に対する財産分与の対象となるが、当該財産分与がなされない場合はＢ及びＣに帰属する。"],"correct":1,"explain":"【核心知识点】区分共有物相关的保存行为（可单独）和损害赔偿请求（按持分比例）。①对（不是错误项）。共有物的不法占有者排除请求属于保存行为（大判大10.6.13），各共有者可以单独进行明渡请求（民法252条但书）。②错（答案）。不法占有产生的损害赔偿请求，各共有者只能就自己持分比例部分单独请求，不能请求全额（最判昭41.3.3）——A只能就自己的1/3份额求偿，不能代B、C求偿全额。③对（不是错误项）。裁判所分割共有物时，可以采用全面价格赔偿方式——把土地整体判给某一共有人所有，由其向其他共有人支付相应持分的价格（民法258条，最判平8.10.31）。④对（不是错误项）。共有者死亡且继承人不存在确定时，其持分成为特别缘故者财产分与的对象；若未进行财产分与，持分归属于其他共有者（民法255条、958条の2，最判平1.11.24）。","takeaway":"不法占有的明渡请求属于保存行为，任何一个共有人都能单独主张全部明渡；但损害赔偿请求不是保存行为，各共有人只能就自己的持分比例单独求偿，不能代表全体请求全额——这是本题的核心陷阱。裁判分割共有物可以用全面价格赔偿这种方式；共有人死亡无继承人时，持分先给特别缘故者，再归其他共有人，不会归国库。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r03s-4', '{"id":"r03s-4","tag":"权利关系・买卖契约","title":"令和3年12月 問4","stem":"いずれも宅地建物取引業者ではない売主Ａと買主Ｂとの間で令和8年7月1日に締結した売買契約に関する次の記述のうち、民法の規定によれば、正しいものはどれか。","options":["ＢがＡに対して手付を交付した場合、Ａは、目的物を引き渡すまではいつでも、手付の倍額を現実に提供して売買契約を解除することができる。","売買契約の締結と同時に、Ａが目的物を買い戻すことができる旨の特約をする場合、買戻しについての期間の合意をしなければ、買戻しの特約自体が無効となる。","Ｂが購入した目的物が第三者Ｃの所有物であり、Ａが売買契約締結時点でそのことを知らなかった場合には、Ａは損害を賠償せずに売買契約を解除することができる。","目的物の引渡しの時点で目的物が品質に関して契約の内容に適合しないことをＡが知っていた場合には、当該不適合に関する請求権が消滅時効にかかっていない限り、ＢはＡの担保責任を追及することができる。"],"correct":3,"explain":"【核心知识点】手付解除的判断基准是相对方着手履行；契约不适合担保责任的1年内通知期限不适用于卖方明知情形。①错。手付解除的时限是相对方着手履行之前，不是交付目的物之前——选项把判断基准换成了交付目的物，这是错的。②错。买戻特约没有约定期间时，不是特约本身无效，而是买戻期间自动适用法定期间（5年）——选项说没约定期间就特约无效是错的。③错。他人物买卖本身是有效的契约（民法561条），不是卖方不知情就能无损害赔偿地解除——如果卖方最终不能取得权利转移给买方，构成卖方的债务不履行，是买方可以解除并可能要求损害赔偿，选项把权利方向搞反了。④对（答案）。契约不适合担保责任的1年内通知期间限制，不适用于卖方在交付时明知（或重大过失不知）该不适合的场合（民法566条但书）——只要没超过一般消滅时效，买方依然可以追究责任。","takeaway":"手付解除的判断基准是相对方着手履行，不是交付目的物；买戻特约没约定期间时退回法定5年，不是特约整体无效；他人物买卖契约本身有效（跟r06-1同一考点）；契约不适合担保责任的1年内通知这道保护期限，在卖方明知不适合却隐瞒的情况下不适用——这是保护善意买方的例外规则。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h28-12', '{"id":"h28-12","tag":"权利关系・借地借家法（建物）","title":"平成28年 問12","stem":"ＡはＢと、Ｂ所有の甲建物につき、居住を目的として、期間３年、賃料月額20万円と定めて賃貸借契約を締結した。この場合における次の記述のうち、借地借家法の規定及び判例によれば、誤っているものはどれか。","options":["ＡもＢも相手方に対し、本件契約の期間満了前に何らの通知もしなかった場合、従前の契約と同一の条件で契約を更新したものとみなされるが、その期間は定めがないものとなる。","ＢがＡに対し、本件契約の解約を申し入れる場合、甲建物の明渡しの条件として、一定額以上の財産上の給付を申し出たときは、Ｂの解約の申入れに正当事由があるとみなされる。","甲建物の適法な転借人であるＣが、Ｂの同意を得て甲建物に造作を付加した場合、期間満了により本件契約が終了するときは、ＣはＢに対してその造作を時価で買い取るよう請求することができる。","本件契約が借地借家法第38条の定期建物賃貸借で、契約の更新がない旨を定めた場合でも、ＢはＡに対し、同条所定の通知期間内に、期間満了により本件契約が終了する旨の通知をしなければ、期間３年での終了をＡに対抗することができない。"],"correct":1,"explain":"【核心知识点】解约申告正当事由的判断结构——立退料只是辅助性考量因素，不是充分条件。①对（不是错误项）。有期限建筑物赁贷借，双方都没在期满前通知，法定更新，但更新后期间变成没有约定期限（借地借家法26条1项）。②错（答案）。房东解约申告须有正当事由，判断时，财产上的给付（立退料）只是补充性考量因素之一，不是只要给了一定金额就当然构成正当事由——还要综合考虑房东自身使用该建筑物的必要性等因素（借地借家法28条），选项把补充因素说成了决定性/充分条件。③对（不是错误项）。适法转借人同样享有造作买取请求权，可以向房东请求以时价买取造作（借地借家法33条1项、2项）。④对（不是错误项）。定期建物赁贷借（期间1年以上）须在期满前1年到6个月之间通知承租人契约将终了，否则不能对抗承租人主张期满终了（借地借家法38条6项）。","takeaway":"解约申告的正当事由判断，立退料（财产给付）只是辅助性的加分项，不是给钱就能解约这种简单的充分条件，房东本身对该建筑物的实际使用必要性才是判断正当事由的核心要素。法定更新后期间变成无期限；适法转借人也享有造作买取请求权（不限于承租人本人）；定期建物赁贷借的终了通知期限是1年前~6个月前。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h20-16', '{"id":"h20-16","tag":"权利关系・不动产登记法","title":"平成20年 問16","stem":"不動産の登記の申請に関する次の記述のうち、誤っているものはどれか。","options":["所有権に関する仮登記に基づく本登記は、登記上の利害関係を有する第三者がある場合には、当該第三者の承諾があるときに限り、申請することができる。","仮登記の登記義務者の承諾がある場合であっても、仮登記権利者は単独で当該仮登記の申請をすることができない。","二筆の土地の表題部所有者又は所有権の登記名義人が同じであっても、持分が相互に異なる土地の合筆の登記は、申請することができない。","二筆の土地の表題部所有者又は所有権の登記名義人が同じであっても、地目が相互に異なる土地の合筆の登記は、申請することができない。"],"correct":1,"explain":"【核心知识点】仮登记的单独申请例外——义务者承诺后权利者可单独申请，别跟仮登记本登记需第三者承诺混淆。①对（不是错误项）。所有权仮登记的本登记，有利害关系第三者时，须获得该第三者承诺才能申请——这跟r02-10-14考的知识点一致。②错（答案）。仮登记的申请方式，原则共同申请，但获得仮登记义务者承诺时，仮登记权利者可以单独申请（不动产登记法107条1项）——选项说不能单独申请是错的，把这个例外规则否定了。③对（不是错误项）。合筆登记的禁止情形之一：持分不同的两筆土地不能合筆（不动产登记法41条5号）。④对（不是错误项）。合筆登记的禁止情形之二：地目不同的两筆土地不能合筆（不动产登记法41条2号）。","takeaway":"仮登记本身的申请——义务者承诺后权利者可单独申请（不动产登记法107条1项）；仮登记的本登记——须获利害关系第三者承诺，两个场景别混淆。合筆登记两大禁止情形：持分不同不能合筆、地目不同不能合筆——都是防止合并后产生权利/用途混乱的制度设计。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h15-18', '{"id":"h15-18","tag":"法令上的制限・都市计画法（开发许可）","title":"平成15年 問18","stem":"開発許可に関する次の記述のうち、都市計画法の規定によれば、誤っているものはどれか。","options":["市街化調整区域における農産物の加工に必要な建築物の建築を目的とした500平方メートルの土地の区画形質の変更には、常に開発許可が不要である。","市街化区域における市街地再開発事業の施行として行う3,000平方メートルの土地の区画形質の変更には、常に開発許可が不要である。","都市計画区域でも準都市計画区域でもない区域内における住宅団地の建設を目的とした6,000平方メートルの土地の区画形質の変更には、常に開発許可が不要である。","準都市計画区域における公民館の建築を目的とした5,000平方メートルの土地の区画形質の変更には、常に開発許可が不要である。"],"correct":0,"explain":"【核心知识点】农林渔业用建筑物豁免须同时满足市街化区域以外+确属法定列举的建筑物类型（加工设施不算）。①错（答案）。农林渔业用建筑物豁免开发许可，须同时满足市街化区域以外+确属农林渔业用建筑物这两个条件——本题是农产物加工用建筑物，法定豁免清单（施行令20条）只包含畜舎、温室、干燥场等直接用于耕作/养殖/林业经营的建筑物，加工设施不在豁免清单内，所以不能常に开发许可不要。②对（不是错误项）。市街地再开发事业实施的开发行为，不管区域规模，都不需要开发许可——制度性豁免。③对（不是错误项）。都市计画区域外・准都市计画区域外的开发许可门槛是1万㎡以上，本题6000㎡未达门槛，不需要许可。④对（不是错误项）。公民馆属于公益上必要建筑物清单内，不管区域规模，一律不需要开发许可——跟h24-17的图书馆是同一类。","takeaway":"农林渔业用建筑物豁免的双重限定：不仅要看是不是在市街化区域以外，还要看这个建筑物本身是否属于法定列举的农林渔业用建筑物类型（畜舎、温室等直接生产性设施），加工类设施不算。这跟h24-17考的图书馆/公民馆等公益上必要建筑物是不同的豁免类型——公益上必要建筑物不看区域规模，农林渔业用建筑物限定市街化区域以外+特定建筑物类型，两套规则不要混淆。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h12-21', '{"id":"h12-21","tag":"法令上的制限・土地区画整理法","title":"平成12年 問21","stem":"土地区画整理事業に関する次の記述のうち、土地区画整理法の規定によれば、誤っているものはどれか。","options":["個人施行者について、施行者以外の者への相続、合併その他の一般承継があった場合においては、その一般承継者は、施行者となる。","土地区画整理組合が施行する土地区画整理事業は、市街化調整区域内において施行されることはない。","市町村が施行する土地区画整理事業については、事業ごとに土地区画整理審議会が置かれる。","都道府県が施行する土地区画整理事業は、すべて都市計画事業として施行される。"],"correct":1,"explain":"【核心知识点，与h24-21是同一考点】只有公的施行才限定在施行区域内，民间施行没有这个地域限定。①对（不是错误项）。个人施行者的一般承继人（继承人、合并后存续法人等），成为新的施行者，承继原施行者的地位。②错（答案）。土地区划整理组合属于民间施行——民间施行（个人、组合、区划整理会社）没有施行区域的地域限定，都市计画区域内哪里都可以施行，包括市街化调整区域（这跟h24-21是同一考点：只有公的施行才限定在施行区域内）。③对（不是错误项）。市町村施行的土地区划整理事业，须逐事业设置土地区划整理审议会（土地区划整理法56条1项）——保护地权人利益的咨询机构。④对（不是错误项）。都道府県施行的土地区划整理事业，全部作为都市计画事业施行——公的施行的特征之一。","takeaway":"只有公的施行（都道府県、市町村等）才限定在施行区域内，民间施行（个人、组合、区划整理会社）没有这个地域限定，包括市街化调整区域都可以施行——这个考点从2000年到现在反复以类似情境出题（本题和h24-21），是土地区划整理法的高频核心考点，务必牢记施行区域限定只针对公的施行。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h22-22', '{"id":"h22-22","tag":"法令上的制限・农地法","title":"平成22年 問22","stem":"農地法（以下この問において「法」という｡）に関する次の記述のうち、誤っているものはどれか。","options":["農地を相続した場合、その相続人は、法第３条第１項の許可を受ける必要はないが、遅滞なく、農業委員会にその旨を届け出なければならない。","宅地に転用する目的で市街化区域外の農地を購入する場合は、農地の権利移動に係る法第３条第１項の許可のほか、農地転用に係る法第４条第１項の都道府県知事の許可を受ける必要がある。","会社の代表者が、その会社の業務に関し、法の規定に違反して転用行為をした場合は、その代表者が罰せられるのみならず、その会社も１億円以下の罰金刑が科せられる。","賃貸借の存続期間については、民法と同じく、農地の賃貸借についても、50年までの存続期間が認められる。"],"correct":1,"explain":"【核心知识点】转用为宅地这种权利移动+转用同时发生的情形，需要的是一站式的5条许可，不是3条+4条的组合。①对（不是错误项）。继承取得农地时，虽不需要3条许可，但须无迟延向农业委员会申报（农地法3条の3第1项）。②错（答案）。转用为宅地这种权利移动+转用同时发生的情形，需要的是一站式的5条许可，不是3条许可+4条许可两道分开的许可——5条许可本身就同时处理权利移动和转用两件事，选项把它拆成了3条+4条，逻辑错误。③对（不是错误项）。法人代表者因业务上违反农地法4条（转用）行为，除处罚行为人本身，法人也要被处1亿日元以下罚金（农地法67条，两罚规定）。④对（不是错误项）。农地赁贷借的存续期间跟民法一般规则相同，最长50年（民法604条）——2020年民法改正后从20年延长到50年的重要变化。","takeaway":"转用为宅地这种权利移动+转用同时发生的场景，农地法专门设计了5条许可这一个统一的许可制度，不需要也不能拆成3条+4条两道单独许可去分别申请。法人违反4条有两罚规定（行为人+法人都罚）；农地赁贷借存续期间2020年后延长到50年（跟一般不动产赁贷借的民法规则统一了）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h14-27', '{"id":"h14-27","tag":"税相关法令・登録免许税","title":"平成14年 問27","stem":"不動産登記に係る登録免許税に関する次の記述のうち、正しいものはどれか。","options":["土地の所有権の移転登記に係る登録免許税の税率は、移転の原因にかかわらず一律である。","土地の売買に係る登録免許税の課税標準は、売買契約書に記載されたその土地の実際の取引価格である。","土地の所有権の移転登記に係る登録免許税の納期限は、登記を受ける時である。","土地の売買に係る登録免許税の納税義務は、土地を取得した者にはなく、土地を譲渡した者にある。"],"correct":2,"explain":"【核心知识点】登録免许税税率按登记原因不同而不同，课税标准是固定资产课税台帳价额不是实际成交价，纳税义务人是取得者不是讓渡人。①错。税率因移转原因不同而不同——相续/法人合并的移转登记税率是1000分の4，买卖移转是1000分の10（登録免许税法9条、别表第一）——不是一律。②错。课税标准是固定资产课税台帳上登录的价额（登録免许税法10条、附则7条），不是买卖契约书记载的实际交易价格。③对（答案）。登録免许税的纳期限是登记时——在受理登记申请手续时须一并纳税。④错。土地买卖的登録免许税纳税义务人是取得该不动产的人（登録免许税法3条），不是讓渡人——选项把纳税义务人搞反了。","takeaway":"税率按登记原因不同而不同（相续/合并4/1000、买卖10/1000等），不是统一税率；课税标准是固定资产课税台帳价额，不是实际成交价——这是最容易被误解的一点；纳期限是登记申请手续时；纳税义务人是取得者（买方），不是讓渡人（卖方）——这跟印纸税等其他税种谁受益谁纳税的逻辑一致。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h23-24', '{"id":"h23-24","tag":"税相关法令・固定资产税","title":"平成23年 問24","stem":"固定資産税に関する次の記述のうち、正しいものはどれか。","options":["固定資産税の納税者は、減免申請に対する不許可処分の不服申立てに対して固定資産評価審査委員会が行った却下決定に不服があるときは、その取消しの訴えを提起することができる。","市町村長は、不動産鑑定士又は不動産鑑定士補に当該市町村所在の固定資産の状況を毎年少なくとも一回実地に調査させなければならない。","家屋について賃借権を有する者は、固定資産課税台帳のうち当該権利の目的である家屋の敷地である土地について記載された部分を閲覧することができる。","市町村は、独立行政法人に対しては、固定資産税を課することができない。"],"correct":2,"explain":"【核心知识点】减免不许可的不服申立走市町村长这条路，价格的不服申立才走评价审查委员会；独立行政法人的免税是有限定列举的。①错。固定资产税减免申请不许可处分的不服申立，对象是市町村长（作出该处分的行政主体），不是固定资产评价审查委员会——评价审查委员会只受理价格相关的不服申立，两条通道不能混淆。②错。市町村长须让固定资产评价员或固定资产评价补助员每年至少一次实地调查该市町村所在的固定资产，不是不动产鉴定士——选项把调查主体搞错了。③对（答案）。对家屋享有赁借权的人，可以阅览固定资产课税台帳中与其权利目的相关的该家屋所在土地的记载部分——保护承租人知情权的规定（地方税法382条の2第1项、施行令52条の14第3号）。④错。市町村对国、都道府県、市町村等不能课固定资产税，但独立行政法人不是一律免税——只有特定列举的独立行政法人才免税，不是所有独立行政法人都免税。","takeaway":"减免不许可的不服申立走市町村长这条路，价格的不服申立才走评价审查委员会——两条通道的适用对象不同；实地调查的主体是固定资产评价员/补助员，不是不动产鉴定士；赁借人也有阅览权（不限于所有者本人）；独立行政法人的免税是有限定列举的，不是所有独立行政法人都免税——这是最容易被绝对化误判的一点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-43', '{"id":"r07-43","tag":"宅地建物取引业法等・35条书面（个数问题）","title":"令和7年 問43","stem":"宅地建物取引業者が行う宅地建物取引業法第35条に規定する重要事項の説明に関する次の記述のうち、正しいものはいくつあるか。なお、説明の相手方は宅地建物取引業者ではないものとする。\\nア　自らを委託者とする宅地又は建物に係る信託の受益権の売主となる場合、相手方に金融商品取引法第2条第10項に規定する目論見書を交付し、宅地建物取引業法第35条第3項の規定に基づき説明すべき事項のすべてが当該目論見書に記載されているときは、重要事項説明書の交付及び説明を省略することができる。\\nイ　建物の貸借の媒介を行う場合、当該建物が建築工事の完了前のものであるときは、その完了時における当該建物の主要構造部、内装及び外装の構造又は仕上げ並びに設備の設置及び構造について説明しなければならない。\\nウ　建物の貸借の媒介を行う場合、敷金その他いかなる名義をもって授受されるかを問わず、契約終了時において精算することとされている金銭の精算に関する事項を説明しなければならない。\\nエ　宅地の売買の媒介を行う場合、当該宅地が津波防災地域づくりに関する法律第21条第1項により指定された津波防護施設区域内にあるときは、同法第23条第1項の規定による制限の概要について説明しなければならない。","options":["一つ","二つ","三つ","四つ"],"correct":3,"explain":"【核心知识点，全部正确，与t112呼应】ア对。信托受益权销售时，若相对方已收到含全部法定应说明事项的目论见书（依金融商品取引法），可以省略重要事项说明书的交付和说明——宅建业法35条3项但书的例外规定。イ对。建物贷借媒介，若建物尚未完工，须说明完工时的主要构造部、内装外装构造/装修、设备设置及构造——针对未完成建物的特殊说明事项。ウ对。建物贷借媒介，须说明敷金等契约终了时精算金钱的相关事项——不管名义是什么，只要是终了时要精算返还的金钱，都要说明。エ对。宅地买卖媒介（不是建物贷借），若该宅地在津波防护设施区域内，须说明该法令限制的概要——这跟t112的宅地贷借≠建物贷借的法令限制说明规则框架完全一致：免说明特权只属于建物贷借，本题是宅地买卖，不适用免说明，须正常说明。四项全部正确，答案是四つ。","takeaway":"见t112关联考点。信托受益权销售的特殊豁免（目论见书已含全部说明事项时可省略）是相对冷门的知识点；宅地买卖≠建物贷借的法令限制说明框架——津波防护设施区域这类法令限制，只有建物贷借才免说明，宅地买卖依然要说明；建物贷借还有未完成建物的完工后状态说明和契约终了精算金钱说明（不限于敷金这个名字）这两项特有的必要说明事项。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r01-13', '{"id":"r01-13","tag":"权利关系・区分所有法","title":"令和元年 問13","stem":"建物の区分所有等に関する法律（以下この問において「法」という。）に関する次の記述のうち、正しいものはどれか。","options":["専有部分が数人の共有に属するときは、共有者は、集会においてそれぞれ議決権を行使することができる。","区分所有者の承諾を得て専有部分を占有する者は、会議の目的たる事項につき利害関係を有する場合には、集会に出席して議決権を行使することができる。","集会においては、規約に別段の定めがある場合及び別段の決議をした場合を除いて、管理者又は集会を招集した区分所有者の１人が議長となる。","集会の議事は、法又は規約に別段の定めがない限り、出席した区分所有者（議決権を有しないものを除く。）及びその議決権の各４分の３以上の多数で決する。"],"correct":2,"explain":"【核心知识点】区分所有法集会制度的四个独立细节。①错。专有部分数人共有时，共有者不能各自行使议决权——须按持分价格过半数定出1名代表行使议决权（区分所有法40条）。②错。经区分所有者承诺占有专有部分的人（如承租人），若对议题有利害关系，只能出席陈述意见，不能行使议决权（区分所有法44条1项）——议决权始终只属于区分所有者本人。③对（答案）。集会原则上由管理者（有管理者时）或集会招集人（无管理者时）担任议长，规约另有规定或另作决议时除外（区分所有法41条）。④错。集会议事原则是普通决议——出席的一般区分所有者及其议决权各过半数决定（区分所有法39条1项），不是4分の3以上多数——选项把普通决议的门槛错说成了特别决议的门槛。","takeaway":"专有部分数人共有时须指定1名代表行使议决权；占有者（如承租人）只能陈述意见，不能行使议决权——议决权是区分所有者的专属权利；议长的默认人选是管理者（有）或集会招集人（无管理者时）；集会议事的默认门槛是普通决议（各过半数），只有法律或规约明确规定需要特别决议（4分の3以上）的特定事项才适用更高门槛。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-21', '{"id":"r07-21","tag":"法令上的制限・农地法","title":"令和7年 問21","stem":"農地に関する次の記述のうち、農地法（以下この問において「法」という。）の規定によれば、誤っているものはどれか。","options":["市街化区域外にある農地の転用の申請に係る事業が住宅の用に供される土地の造成だけを目的としている場合、申請に係る農地の全てを住宅の用に供することが確実と認められないときには、法第４条第１項又は法第５条第１項の許可を受けることができない。","仮設工作物を設置するため、市街化区域外にある農地の所有権を取得しようとする場合には、法第５条第１項の許可を受けることができない。","農地の賃貸借は、その登記がなくても、農地の引渡しがあったときは、これをもってその後その農地について所有権を取得した第三者に対抗することができる。","法人の代表者が、その法人の業務に関し、法第４条第１項又は法第５条第１項の規定に違反して農地の転用をした場合には、その代表者が罰せられるほか、その法人も300万円以下の罰金刑が科せられる。"],"correct":3,"explain":"【核心知识点，与h22-22是同一考点】违反4条/5条的罚则，个人是3年以下拘禁刑或300万日元以下罚金，法人（两罚规定）应处1亿日元以下罚金。①对（不是错误项）。转用申请事业若只是造成住宅用地这个目的，而申请的农地全部确实用于住宅用途这件事不能被认定确实时，不能取得4条/5条许可。②对（不是错误项）。为设置临时性工作物取得农地所有权，不适用5条许可——临时性利用本来就不算转用。③对（不是错误项）。农地赁贷借凭引渡即可对抗第三人（农地法16条），跟已写入的r04-21是同一考点。④错（答案）。违反4条/5条的罚则，个人是3年以下拘禁刑或300万日元以下罚金（农地法64条），但法人（两罚规定）应处1亿日元以下罚金（农地法67条1号）——选项把法人的罚金上限错说成了300万日元（那是个人的标准）。","takeaway":"这题跟已写入的h22-22是完全相同的核心考点——违反农地法转用规定的两罚规定中，个人罚金（300万日元以下）和法人罚金（1亿日元以下）不是同一个数字，容易被出题者把两者互换制造陷阱。这是历年反复出题的两罚金额陷阱，建议把h22-22和本题放在一起对照复习。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('h26-18', '{"id":"h26-18","tag":"法令上的制限・建筑基準法","title":"平成26年 問18","stem":"建築基準法（以下この問において「法」という。）に関する次の記述のうち、誤っているものはどれか。","options":["店舗の用途に供する建築物で当該用途に供する部分の床面積の合計が10,000㎡を超えるものは、原則として工業地域内では建築することができない。","学校を新築しようとする場合には、法第48条の規定による用途制限に適合するとともに、都市計画により敷地の位置が決定されていなければ新築することができない。","特別用途地区内においては、地方公共団体は、国土交通大臣の承認を得て、条例で、法第48条の規定による建築物の用途制限を緩和することができる。","都市計画において定められた建蔽率の限度が10分の８とされている地域外で、かつ、防火地域内にある耐火建築物の建蔽率については、都市計画において定められた建蔽率の数値に10分の１を加えた数値が限度となる。"],"correct":1,"explain":"【核心知识点】须先经都市计画决定敷地位置才能建设的，是特定限列举的建筑物（卸売市场、火葬场等，建筑基準法51条），学校不在此列。①对（不是错误项）。超过10,000㎡的店铺用途建筑物，只能建在近隣商业/商业/准工业地域，原则上不能建在工业地域内。②错（答案）。须先经都市计画决定敷地位置才能建设的，是特定限列举的建筑物（如卸売市场、火葬场、垃圾焚烧场等，建筑基準法51条），学校不在这个清单内——学校只受48条用途限制约束，不需要这道额外程序。③对（不是错误项）。特别用途地区内，地方公共团体可以经国土交通大臣承认，通过条例放宽48条用途限制（建筑基準法49条の2）。④对（不是错误项）。建蔽率限度8/10地域外+防火地域内的耐火建筑物，建蔽率数值+1/10（建筑基準法53条3项1号）。","takeaway":"须经都市计画决定敷地位置的特殊程序，适用对象是特定限列举的建筑物（卸売市场、火葬场、垃圾处理场等设施），不是所有公共设施类建筑物都适用——学校不在这个特定清单内，只需符合48条一般用途限制即可。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-5', '{"id":"r06-5","tag":"权利关系・履行迟滞","title":"令和6年 問5","stem":"履行遅滞に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。","options":["不法行為の加害者は、不法行為に基づく損害賠償債務について、履行の請求を受けた時から遅滞の責任を負う。","善意の受益者は、その不当利得返還債務について、履行の請求を受けた時から遅滞の責任を負う。","請負人の報酬債権に対して、注文者がこれと同時履行の関係にある目的物の瑕疵修補に代わる損害賠償債権を自働債権とする相殺の意思表示をした場合、注文者は、請負人に対する相殺後の報酬残債務について、当該残債務の履行の請求を受けた時から遅滞の責任を負う。","債務の履行について不確定期限があるときは、債務者は、その期限の到来したことを知った後に履行の請求を受けた時から遅滞の責任を負う。"],"correct":1,"explain":"【核心知识点】履行迟滞起算点因债务类型不同而不同，是历年高频考点。①错。不法行为的迟延责任从不法行为发生之时就开始起算，不是收到履行请求之时——判例明确的保护被害人特则。②对（答案）。善意受益者的不当得利返还债务，从收到履行请求之时才开始负迟延责任——善意受益者只需返还现存利益，责任起点相对宽松。③错。相殺后的报酬残债务，迟延责任从相殺意思表示之日的翌日开始起算，不是收到残债务履行请求之时。④错。不确定期限债务，迟延责任从期限到来后收到履行请求或债务人知道期限已到来两者中较早的时点开始，不是只看知道期限到来后又被请求这一个条件。","takeaway":"履行迟滞起算点四种情形要分开记：不法行为从行为时起算（保护被害人的特则）；善意受益者的不当利得从被请求时起算（相对宽松）；相殺后的残债务从相殺意思表示翌日起算；不确定期限债务从期限到来后被请求或知道期限到来两者较早的一方起算。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-6', '{"id":"r06-6","tag":"权利关系・地上权与混同","title":"令和6年 問6","stem":"Ａの所有する甲土地にＢを地上権者とする地上権が設定され、その旨の登記がされた後に、甲土地にＣを抵当権者とする抵当権が設定され、その旨の登記がされた場合における次の記述のうち、民法の規定によれば、正しいものはいくつあるか。\\nア　ＢがＡとの売買契約に基づき、甲土地の所有権を取得したときは、本件地上権は消滅する。\\nイ　Ａが死亡してＢがＡを単独相続し、甲土地の所有権を取得したときは、本件地上権は消滅する。\\nウ　ＢがＡとの代物弁済契約に基づき、甲土地の所有権を取得したときは、本件地上権は消滅する。\\nエ　ＢがＡとの贈与契約に基づき、甲土地の所有権を取得したときは、本件地上権は消滅する。","options":["一つ","二つ","三つ","なし"],"correct":3,"explain":"【核心知识点，难题】民法179条1项混同规则的例外——同一物权归于同一人时原则消滅，但该物权是第三者权利标的时不消滅。ア～エ全部错误。同一物上所有权和其他物权（如地上权）归于同一人时，原则上该其他物权因混同消滅，但该物权若是第三者权利的标的时不消滅（民法179条1项）。本题地上权设定登记后，C的抵当权才设定在甲土地上——C对甲土地上存在先顺位地上权这一状态有既得利益，若B之后取得所有权就让地上权当然消滅，会打乱C的权利预期。因此不管B是通过买卖、相续、代物弁済还是赠与取得所有权，地上权都不消滅——取得原因不影响这个结论。","takeaway":"混同的例外规则看的是有没有第三人利害关系（该物权是不是第三者权利的标的），不看取得所有权的方式（买卖/相续/代物弁済/赠与）。四个选项换了取得原因诱导考生以为结论会不同，实际上考的是同一个知识点。这是一道边缘知识点的舍题，但理解混同例外逻辑本身很有价值。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-8', '{"id":"r06-8","tag":"权利关系・条文辨析","title":"令和6年 問8","stem":"次の記述のうち、民法の条文として規定されていないものはどれか。","options":["隔地者間の契約は、承諾の通知を発した時に成立する。","無効な行為に基づく債務の履行として給付を受けた者は、相手方を原状に復させる義務を負う。","代理人が自己又は第三者の利益を図る目的で代理権の範囲内の行為をした場合において、相手方がその目的を知り、又は知ることができたときは、その行為は、代理権を有しない者がした行為とみなす。","未成年者が法律行為をするには、その法定代理人の同意を得なければならない。ただし、単に権利を得、又は義務を免れる法律行為については、この限りでない。"],"correct":0,"explain":"【核心知识点】2020年民法改正废除了隔地者间契约的发信主义特例，现在统一采用到达主义。①不是条文规定（答案）。隔地者间契约成立时点，现行民法规定的是承诺到达相对方时成立（到达主义），不是发出承诺通知时（发信主义）——旧民法曾有发信主义的隔地者特例，但已被2020年改正废除。②是条文规定。无效行为的给付返还义务（原状回复义务）——民法121条の2第1项明文规定，2020年改正新增。③是条文规定。代理权濫用——民法107条明文规定。④是条文规定。未成年人法律行为须经法定代理人同意，单纯获得权利/免除义务的行为除外——民法5条1项明文规定。","takeaway":"2020年民法改正废除了旧法里隔地者间契约发信主义的特例，现在统一采用到达主义（承诺到达相对方时契约才成立）。这是容易用旧知识误答的经典考点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-13', '{"id":"r06-13","tag":"权利关系・区分所有法","title":"令和6年 問13","stem":"建物の区分所有等に関する法律に関する次の記述のうち、誤っているものはどれか。","options":["各共有者の共用部分の持分は、規約に別段の定めがない限り、共有者数で等分することとされている。","規約及び集会の決議は、区分所有者の特定承継人に対しても、その効力を生ずる。","管理者は、集会において、毎年1回一定の時期に、その事務に関する報告をしなければならない。","集会の招集の通知は、区分所有者が管理者に対して通知を受けるべき場所を通知しなかったときは区分所有者の所有する専有部分が所在する場所にあててすれば足りる。この場合には、集会の招集の通知は、通常それが到達すべき時に到達したものとみなされる。"],"correct":0,"explain":"【核心知识点，送分题】共用部分持分的默认分配基准是专有部分床面积比例，不是人数。①错（答案）。共用部分的持分份额，原则依据各区分所有者所有的专有部分床面积比例来定（不是简单按人数均分），规约可以另行约定（区分所有法14条1项）——选项说按共有者人数等分是错的。②对（不是错误项）。规约及集会决议的效力，及于区分所有者的特定承继人（区分所有法46条1项）。③对（不是错误项）。管理者须在集会上每年至少1次在一定时期报告其事务处理情况（区分所有法43条）。④对（不是错误项）。集会招集通知，若区分所有者没有告知管理者应该通知的场所，可以寄送到该区分所有者所拥有的专有部分所在地即可，且通常到达该处所需的时间就视为已经到达（区分所有法35条3项）。","takeaway":"共用部分持分的默认基准是专有部分床面积比例，不是人数均分——这是区分所有法里共用部分持分这个考点最基础也最容易被想当然答错的地方。规约/决议对特定承继人有效（保护交易安全）；管理者每年至少1次定期报告；招集通知有专有部分所在地+到达擬制这个替代送达方式。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-18', '{"id":"r06-18","tag":"法令上的制限・建筑基準法","title":"令和6年 問18","stem":"次の記述のうち、建築基準法の規定によれば、正しいものはどれか。","options":["客席部分の床面積の合計が300㎡の映画館については、第二種住居地域内において建築することはできないが、準住居地域内においては建築することができる。","特定用途誘導地区内において、都市計画で建築物の高さの最高限度が定められていたとしても、特定行政庁が用途上又は構造上やむを得ないと認めて許可したものについては、当該最高限度を超えてよい。","計画しようとする建築物の天空率が、道路斜線制限、隣地斜線制限又は北側斜線制限に適合する建築物の天空率未満であれば、これらの制限は適用されない。","都市計画で建蔽率の限度が80％に指定されている区域かつ防火地域内にある耐火建築物について、建蔽率の限度を超えるためには、特定行政庁による許可を得る必要がある。"],"correct":1,"explain":"【核心知识点】电影院面积门槛、特定用途诱导地区高度例外、天空率适用除外方向、建蔽率8/10+防火+耐火组合不受限制。①错。客席面积200㎡以上的电影院/剧场等，只能建在商业/近隣商业/准工业地域——第二种住居地域和准住居地域都不行（200㎡未满才可以建在准住居地域）。②对（答案）。特定用途诱导地区内，都市计画规定的高度最高限度，若特定行政厅认定用途上或构造上有不得已的理由并许可，可以超过该最高限度。③错。天空率满足制限要求从而免除斜线制限的条件，是计划建筑物的天空率以上（≥）符合制限的建筑物天空率，不是未満（<）。④错。建蔽率限度8/10地域内+防火地域内的耐火建筑物，建蔽率规定本身不适用（等于10/10），不需要申请特定行政厅许可。","takeaway":"电影院/剧场等的面积门槛（200㎡）决定能建的用途地域范围；特定用途诱导地区的高度限制有特定行政厅许可的例外通道；天空率的适用除外条件是≥不是<；建蔽率8/10+防火地域+耐火建筑物这个组合本身就不受建蔽率限制——这跟h26-18选项④8/10地域外+防火地域+耐火建筑物加算1/10是完全不同的情形，两题对照复习能搞清楚建蔽率完整规则。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-20', '{"id":"r06-20","tag":"法令上的制限・土地区画整理法","title":"令和6年 問20","stem":"土地区画整理法に関する次の記述のうち、誤っているものはどれか。なお、この問において、大都市等の特例及び条例で定める事務処理の特例は考慮しないものとする。","options":["仮換地が指定された場合においては、従前の宅地について権原に基づき使用し、又は収益することができる者は、仮換地の指定の効力発生の日から換地処分の公告がある日まで、仮換地又は仮換地について仮に使用し、若しくは収益することができる権利の目的となるべき宅地若しくはその部分について、従前の宅地について有する権利の内容である使用又は収益と同じ使用又は収益をすることができる。","市町村施行の土地区画整理事業において、市町村は、換地処分をした場合においては、その旨を公告しなければならない。","換地計画において定められた保留地は、換地処分の公告があった日の翌日において、施行者が取得する。","施行者は、仮換地を指定した場合において、特別の事情があるときは、その仮換地について使用又は収益を開始することができる日を仮換地の指定の効力発生の日と別に定めることができる。"],"correct":1,"explain":"【核心知识点】申报和公告的主体区分——施行者向知事申报，公告由知事进行。①对（不是错误项）。仮换地指定后，从前宅地上有权原使用收益的人，从仮换地指定效力发生日到换地处分公告日这段期间，可以对仮换地进行跟从前宅地相同内容的使用收益。②错（答案）。市町村（及个人施行者、组合、区划整理会社、机构、公社）施行的土地区划整理事业，换地处分后须无迟延向都道府県知事申报，公告是由都道府県知事进行的，不是施行者自己公告——选项把申报和公告的主体搞混了。③对（不是错误项）。换地计画中确定的保留地，在换地处分公告日翌日由施行者取得。④对（不是错误项）。仮换地使用收益开始日，若有特别情事，施行者可以另行指定——跟r07-20/r01-20是同一考点。","takeaway":"不管是国土交通大臣、都道府県还是市町村（含个人、组合等）施行的土地区划整理事业，换地处分后都要向都道府県知事申报，而公告这个动作是由都道府県知事来做的，不是施行者自己公告——这是历年反复出题的经典陷阱。跟r07-20、r01-20（仮换地使用收益开始日）以及h12-21、h24-21（施行区域/施行地区区别）都属于土地区划整理法的高频知识网络。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-22', '{"id":"r06-22","tag":"法令上的制限・国土利用计画法","title":"令和6年 問22","stem":"国土利用計画法第23条の事後届出及び第27条の監視区域内の事前届出に関する次の記述のうち、正しいものはどれか。","options":["Ａが所有する市街化区域以外の都市計画区域内の4,000㎡の土地について、宅建業者Ｂが地上権の設定を受ける契約を締結した場合、Ｂは事後届出を行わなければならない。","宅建業者Ｃが所有する市街化区域内の3,000㎡の土地と宅建業者Ｄが所有する都市計画区域外に所在する12,000㎡の土地を金銭の授受を伴わずに交換する契約を締結した場合、Ｃ及びＤはともに事後届出を行う必要はない。","事前届出又は事後届出が必要な土地について、売買契約を締結したにもかかわらず所定の期間内に当該届出をしなかった者は都道府県知事からの勧告を受けることがあるが、罰則の適用を受けることはない。","監視区域に指定された市街化区域内に所在する土地2,500㎡について売買契約を締結しようとする当事者は、契約締結の少なくとも6週間前までに事前届出を行わなければならない。"],"correct":3,"explain":"【核心知识点】事后申报和事前申报（监视区域）两套制度的独立规则。①错。市街化区域以外的都市计画区域内，事后申报的面积门槛是5,000㎡以上，本题4,000㎡未达门槛，不需要申报。②错。C的土地在市街化区域内（门槛2,000㎡以上），C持有3,000㎡超过门槛，需要申报；D的土地在都市计画区域外（门槛10,000㎡以上），D持有12,000㎡超过门槛，也需要申报——交换契约不涉及金钱不影响申报义务。③错。未申报的人直接构成犯罪，处6个月以下拘禁刑或100万日元以下罚金——跟r03-10-22是同一考点。④对（答案）。监视区域内的事前申报面积门槛，由都道府県知事在都道府県规则中另行规定（低于一般门槛），本题2,500㎡符合监视区域这类更严格的门槛，须在契约缔结至少6周前进行事前申报。","takeaway":"事后申报和事前申报（监视区域）是两套独立制度。监视区域的门槛比一般的注视区域/一般区域更严格（低于一般门槛），申报期限是契约缔结至少6周前——这跟事后申报是契约缔结后2周内的时间方向完全不同（事前 vs 事后），要分开记忆。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-28', '{"id":"r06-28","tag":"宅地建物取引业法等・报酬关连","title":"令和6年 問28","stem":"宅建業者Ａ（消費税課税事業者）及び宅建業者Ｂ（消費税免税事業者）が受領した報酬に関するアからウの記述のうち、宅地建物取引業法の規定に違反しないものの組合せは1から4のうちどれか。なお、代理、媒介に当たり、広告の依頼は行われていないものとする。\\nア　居住用建物（1か月の借賃12万円。消費税等相当額を含まない）について、宅建業者Ａは貸主から代理を依頼され、宅建業者Ｂは借主から媒介を依頼され、Ａは貸主から6.7万円、Ｂは借主から6.5万円を報酬として受領した。なお、Ｂは、媒介の依頼を受けるに当たって、報酬について借主から特段の承諾を得ていない。\\nイ　宅建業者Ｂは、事業用建物について、貸主と借主双方から媒介を依頼され、借賃1か月分10万円（消費税等相当額を含まない）、権利金90万円（権利設定の対価として支払われる金銭であって返還されないもので、消費税等相当額を含まない｡）の賃貸借契約を成立させ、貸主と借主からそれぞれ5万円を報酬として受領した。\\nウ　宅建業者Ａは、土地付建物について、売主と買主双方から媒介を依頼され、代金3,500万円（消費税等相当額を含み、土地代金は2,400万円である）の売買契約を成立させ、売主と買主からそれぞれ110万円を報酬として受領したほか、売主の特別の依頼に基づき行った遠隔地への現地調査に要した実費の費用について、売主が事前に負担を承諾していたので、売主から9万円を受領した。","options":["ア、イ","イ、ウ","ア、ウ","なし"],"correct":1,"explain":"【核心知识点】免税事业者的报酬换算系数是1.04，不是课税事业者的1.1。ア违反。B是免税事业者，报酬计算不能乘以1.1——B的上限是12万×1/2×1.04=6.24万，本题B实际收取6.5万，超过上限。イ不违反。权利金授受型的事业用建物赁贷借，可以按权利金视为代金来算（90万×5%×2×1.04=9.36万），也可以按借賃基准来算（10万×1.04=10.4万），取较高者作为上限，本题合计10万未超过10.4万上限。ウ不违反。代金3,500万（含税）扣除建筑物消费税部分后为3,400万，报酬上限=（3,400万×3%+6万）×1.1=118.8万，本题双方各收110万未超过上限；依卖方特别依赖产生的远地调查实费（9万）可以在报酬上限外另行收取，符合事先承诺负担的前提。","takeaway":"免税事业者的报酬计算系数是1.04，课税事业者是1.1——这是容易被忽略的税务身份差异，容易被当成课税事业者一样乘1.1计算而误判为未超标。权利金授受型的报酬计算，权利金转代金算法和借賃基准算法取较高者作为合法上限依据。特别依赖产生的实费可以在报酬上限外另行收取（跟h25-37同一考点）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-31', '{"id":"r06-31","tag":"宅地建物取引业法等・监督处分","title":"令和6年 問31","stem":"次の記述のうち、宅建業法の規定によれば、正しいものはどれか。","options":["国土交通大臣又は都道府県知事は、その免許を受けた宅建業者が宅建業法の規定による指示に従わない場合、その業務の全部又は一部の停止を命ずることができ、業務の停止の処分に違反した場合、免許を取り消さなければならない。","国土交通大臣又は都道府県知事は、その免許を受けた宅建業者の事務所の所在地を確知できないときは、その事実を公告し、その公告の日から2週間を経過しても当該宅建業者から申出がないときは、免許を取り消すことができる。","国土交通大臣又は都道府県知事は、宅建業法の規定による免許の取消しの処分をしようとするときは、聴聞を行わなければならないが、当該聴聞は、公開することが相当と認められる場合を除き、公開されない。","国土交通大臣又は都道府県知事は、宅建業法の規定による免許の取消しの処分をしたときはその旨を公告しなければならないが、宅建業法の規定による業務の停止の処分をしたときはその旨の公告はしなくともよい。"],"correct":0,"explain":"【核心知识点】处分升级链条——指示（任意停业）→业务停止→违反停止则必须取消免许。①对（答案）。不遵从指示处分时，知事可以（任意的）命令业务停止；违反业务停止处分时，知事必须（义务的）取消免许。②错。无法确知事务所所在地时，公告后30日（不是2周）经过仍无申报，才可以取消免许——期限数字错了。③错。免许取消处分前须进行聴聞，且聴聞期日的审理须公开进行——不是除公开相当情形外不公开。④错。业务停止处分和免许取消处分都须公告——只有指示处分不需要公告。","takeaway":"指示处分→业务停止（任意）→违反业务停止→取消免许（必须）这个升级链条要记清楚哪个阶段是任意、哪个是义务；确知不能时的免许取消，公告后等待期限是30日，不是2周；聴聞审理原则公开；业务停止处分和免许取消处分都要公告，只有指示处分这一级不用公告——处分等级越重，公开义务越严格。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-35', '{"id":"r06-35","tag":"宅地建物取引业法等・37条书面电磁化","title":"令和6年 問35","stem":"宅建業者Ａが宅建業法第37条の規定により交付すべき書面に記載すべき事項を電磁的方法により提供することに関する次の記述のうち、正しいものはどれか。","options":["宅建業者Ａが自ら売主として締結する宅地の売買契約において、37条書面の電磁的方法による提供を行う場合、当該契約の相手方に対し、あらかじめ、電磁的方法による提供に用いる電磁的方法の種類及び内容を宅建士に説明させなければならない。","宅建業者Ａが媒介業者として関与する建物賃貸借契約において、37条書面の電磁的方法による提供を行う場合、その方法は37条書面の交付に係る宅建士が明示されるものでなければならない。","宅建業者Ａが自ら売主として締結する宅地の売買契約において、契約の相手方から37条書面の電磁的方法による提供を行うことについて書面により承諾を得た場合は、その後に当該契約の相手方から書面で電磁的方法による提供を受けない旨の申出があったときでも、37条書面の電磁的方法による提供をすることができる。","宅建業者Ａが媒介業者として関与する宅地の売買契約において、37条書面の電磁的方法による提供を行う場合であっても、提供後速やかに37条書面を交付しなければならない。"],"correct":1,"explain":"【核心知识点】37条书面本身不要求说明，只要求记名+可追溯，跟35条书面须由宅建士说明的制度不同。①错。电磁化提供37条书面前，须事先书面等方式告知电磁方法的种类和内容并取得承诺，但不需要由宅建士来说明——37条书面本身不要求口头说明。②对（答案）。电磁化提供的方法，须能明确显示负责该37条书面交付的宅建士是谁——保证电磁化提供后依然能追溯到具体的记名宅建士。③错。即使之前已获得书面承诺，之后相对方又书面表示不愿接受电磁化提供时，就不能再用电磁化方式提供——承诺可以事后撤回。④错。已经用电磁化方式提供了37条书面内容的，不需要再另行交付纸质37条书面——电磁化提供本身就完成了交付义务。","takeaway":"电磁化提供不需要宅建士说明（37条书面本身不要求说明，只要求记名，跟35条书面制度不同）；电磁化方法须明示记名宅建士是谁；承诺可以事后被撤回；电磁化提供后不需要再重复交付纸质书面。核心要记住37条书面不要求说明，只要求记名+可追溯这个跟35条书面的本质区别。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-36', '{"id":"r06-36","tag":"宅地建物取引业法等・营业保证金及保证协会","title":"令和6年 問36","stem":"営業保証金及び宅建業保証協会に関する次の記述のうち、宅建業法の規定によれば、誤っているものはどれか。","options":["宅建業者で保証協会に加入しようとする者は、その加入しようとする日までに、政令で定める額の弁済業務保証金分担金を当該保証協会に納付しなければならない。","保証協会の社員と宅建業に関し取引をした者（宅建業者に該当する者を除く）は、その取引により生じた債権に関し、当該社員が社員ではないとしたならばその者が供託すべき営業保証金の額に相当する額の範囲内で弁済を受ける権利を有する。","宅建業者は、保証協会の社員の地位を失ったときは、保証協会が弁済業務保証金の還付請求権者に対し、一定期間内に宅建業法の規定による認証を受けるため申し出るべき旨の公告をした後でなければ、弁済業務保証金分担金の返還を受けることができない。","宅建業者は、一部の事務所を廃止し営業保証金を取り戻そうとする場合には、供託した営業保証金につき還付を請求する権利を有する者に対し、公告をすることなく営業保証金を取り戻すことができる。"],"correct":3,"explain":"【核心知识点】营业保证金取回原则须公告，一部事务所废止不在免除公告的例外情形之列。①对（不是错误项）。想加入保证协会的业者，须在加入之日之前缴纳法定额度的弁済业务保证金分担金。②对（不是错误项）。与保证协会社员进行交易的非业者相对方，享有的弁済上限是若该社员不是保证协会社员时本应缴纳的营业保证金额。③对（不是错误项）。业者失去保证协会社员地位时，须等保证协会（不是业者自己）完成公告程序后，才能拿回弁済业务保证金分担金——公告主体是保证协会。④错（答案）。业者废止部分事务所而取回营业保证金时，依然须完成公告程序（须公示6个月以上期间），不能不公告就直接取回。","takeaway":"营业保证金的取回原则上须公告，例外不需要公告的情形只有：主事务所移转导致二重供托后取回旧供托所部分、取回事由发生后经过10年、加入保证协会（改缴分担金）——一部事务所废止不在这三个例外之列，依然须走公告程序。跟h28-35（免许证返还情形）是同一知识体系，建议整合复习。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-38', '{"id":"r06-38","tag":"宅地建物取引业法等・免许","title":"令和6年 問38","stem":"宅建業の免許に関する次の記述のうち、宅建業法の規定によれば、正しいものはどれか。","options":["宅建業者Ａが、免許の更新の申請をした場合において、従前の免許の有効期間の満了の日までに、その申請について処分がなされないときは、従前の免許は、有効期間の満了後その効力を失う。","宅建業者Ｂが宅建業者Ｃに自己の名義をもって宅建業を営ませる行為は、Ｂが名義の使用を書面で指示している場合であれば、宅建業法に違反しない。","宅建業者Ｄ（甲県知事免許）は、国土交通大臣に免許換えの申請をし、その免許を受けなければ、乙県所在の宅地の売買の媒介をすることはできない。","宅建業者Ｅ（丙県知事免許）の免許の更新に当たって、丙県知事は宅建業法第3条の2に基づき条件を付すことができ、Ｅが免許の更新に当たって付された条件に違反したときは、丙県知事はＥの免許を取り消すことができる。"],"correct":3,"explain":"【核心知识点，与h12-32对照】免许可以附条件，宅建士证不行。①错。提交更新申请后，若在原免许有效期满前处分还没下来，原免许依然有效，不是满了就失效。②错。业者不能让他人以自己名义营业——绝对禁止，没有任何例外，即使用书面指示也不行。③错。都道府県知事免许的效力及于全国——不需要因为要在其他都道府県开展业务就换成国土交通大臣免许，媒介乙県的宅地依然可以用甲県知事免许进行。④对（答案）。免许更新时，知事可以附加条件（宅建业法3条の2），Ｅ违反该条件时，知事可以（任意的）取消免许。","takeaway":"都道府県知事免许的效力及于全国范围，不受业务发生地在哪个都道府県影响，只有事务所所在的都道府県数才决定是知事免许还是大臣免许；免许可以附条件（跟h12-32讨论过的宅建士证没有附条件规定是不同的制度）——免许附条件违反时知事可以取消免许，这是任意的取消事由。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r06-43', '{"id":"r06-43","tag":"宅地建物取引业法等・宅建士登録及证","title":"令和6年 問43","stem":"宅建士の登録及び宅建士証に関する次の記述のうち、誤っているものはどれか。","options":["宅建士の登録を受けている者は、宅建士証の交付を受けていない場合でも、その住所に変更があれば、登録を受けている都道府県知事に変更の登録を申請しなければならない。","宅建士は、宅建士の信用又は品位を害するような行為をしてはならず、この行為には宅建士としての職務に必ずしも直接関係しない行為や私的な行為も含まれる。","宅建士は、取引の関係者から請求があったときは、宅建士証を提示しなければならないが、その際、個人情報保護の観点から宅建士証の住所欄にシールを貼った上で提示することが認められている。","宅建士証に記載される宅建士の氏名については現姓を用いなければならず、旧姓を併記することは認められていない。"],"correct":3,"explain":"【核心知识点】宅建士证近年新增两项人性化规则——可贴贴纸遮挡住所栏、可并记旧姓。①对（不是错误项）。即使没有领取宅建士证，登録本身的住所变更依然须申请变更登録——登録和证是两个不同的东西，跟h12-32是同一考点。②对（不是错误项）。宅建士不能做有损信用/品位的行为，这类行为含不直接关联职务的私人行为。③对（不是错误项）。出示宅建士证时，出于个人信息保护考虑，可以在证的住所栏贴贴纸遮挡后出示。④错（答案）。宅建士证记载的姓名，希望使用旧姓的人，可以在证上并记旧姓——不是只能用现姓、不能并记旧姓。","takeaway":"宅建士证近年新增两项人性化规则——可贴贴纸遮挡住所栏出示（保护隐私）、可并记旧姓——这两条相对新颖，容易被误以为传统严格规定不允许变通。登録和宅建士证是两个独立概念（跟h12-32、r06-38是同一知识体系）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-1', '{"id":"r07-1","tag":"权利关系・物权变动（二重讓渡）","title":"令和7年 問1","stem":"所有者ＡがＢに甲土地を売却し、その後にＢがＣに甲土地を売却した場合に関する次の記述のうち、民法の規定及び判例によれば、正しいものはどれか。なお、この問において、Ｃは背信的悪意者ではないものとする。","options":["甲土地の所有権登記がＡの名義のままであったとしても、Ｂは、Ｃに甲土地を売却した後は、Ａに対して自己に甲土地の所有権移転登記をするよう請求することはできない。","Ｃは、甲土地の所有権移転登記を備えなければ、Ａに対して自己が所有者であることを主張することができない。","ＡＢ間の売買契約が、ＢＣ間の売買契約締結よりも前にＡにより解除されていた場合、又は、ＢＣ間の売買契約締結後にＡにより解除された場合のいずれの場合であっても、Ｃは、甲土地の所有権移転登記を備えれば、Ａに対して自己の所有権を主張することができる。","ＡＢ間の売買契約が、ＢＣ間の売買契約よりも前にＢの強迫を理由として取り消されていた場合、又は、ＢＣ間の売買契約締結後にＢの強迫を理由として取り消された場合のいずれの場合であっても、Ｃは、Ｂの強迫につき善意でかつ過失がなければ、Ａに対して自己の所有権を主張することができる。"],"correct":2,"explain":"【核心知识点】解除后第三人保护看登记（不问解除前后），撤销后第三人（强迫）看二重讓渡对抗关系。①错。卖方对买方负有协助其取得对抗要件（登记）的义务，B卖给C后，依然可以请求A协助办理登记——这项请求权不会因为B又卖给了C就消失。②错。买方即使没有登记，也可以对前手的前手（A）主张自己是所有者——这跟C对抗A的问题是不同层次的。③对（答案）。这是解除后的第三人保护问题：不管A解除AB契约是在BC契约之前还是之后，只要C办理了登记，就可以对抗A主张自己的所有权。④错。AC之间是二重讓渡的对抗问题——先取得登记者优先，跟B的强迫行为是否发生在BC契约前后无关，也不看C对强迫是否善意无过失——选项加的强迫和善意无过失这些条件是干扰项。","takeaway":"契约解除后的第三人保护，不问解除时点前后，只看登记（对抗要件）；契约被撤销（强迫）后的第三人保护，不是看登记，而是二重讓渡对抗关系，跟强迫这个撤销事由本身无关，直接看谁先登记。别把诈欺撤销那套善意无过失标准套用到强迫撤销的第三人保护上。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-6', '{"id":"r07-6","tag":"权利关系・物权变动综合","title":"令和7年 問6","stem":"Ａが所有している甲土地についての物権変動に関する次の記述のうち、民法の規定及び判例によれば、誤っているものはどれか。","options":["Ｂが甲土地をＡに無断でＣに売却し、その後、ＢがＡから甲土地を購入した場合、Ｃは、Ｂから甲土地を購入した時点に遡って甲土地の所有権を取得する。","Ｄが甲土地につき、Ａに無断でＤへの虚偽の所有権の移転の登記をした上で、甲土地をＥに売却してその旨の登記をした場合において、その後、ＡがＦに甲土地を売却したときは、Ｆは、Ｅに対し、甲土地の所有権を主張することができる。","Ｇが甲土地の所有権を時効取得した場合、Ｇはその後にＡを単独相続したＨに対して、登記を備えていなくても、甲土地の所有権を主張することができる。","Ａが甲土地上の立木の所有権を留保して甲土地をＪに売却し、その後、ＪがＫに甲土地及びその上の立木を売却した場合には、Ａは、Ｋに対し、立木の所有権の留保につき登記又は明認方法を備えない限り、立木の所有権を主張することができない。"],"correct":0,"explain":"【核心知识点】他人物买卖后卖方取得所有权，买方取得所有权的时点是卖方事后取得所有权之时，不溯及最初买卖契约时点。①错（答案）。B无权处分把甲土地卖给C，之后B从A那里买到了甲土地——C从B取得所有权的时点才生效，不是溯及到最初B卖给C的那个时点。②对（不是错误项）。D是虚偽登记名义人（无权利人），本来E不能取得所有权；A之后又卖给F，F作为真正的权利承继人，可以对抗E主张所有权。③对（不是错误项）。时效取得的效果，对时效完成前的原所有者本人及其单纯继承人（视为同一人），不需要登记就能对抗——H是A的单独继承人，跟A地位相同。④对（不是错误项）。立木本身是土地的一部分，但具备登记或明认方法时，可以独立成为交易对象——A要对抗K，须具备登记或明认方法证明自己保留了立木所有权。","takeaway":"他人物买卖后卖方取得所有权，买方取得所有权的时点是卖方事后取得所有权之时，不溯及到最初的买卖契约时点——这是历年容易被误判的溯及陷阱。虚偽登记名义人的转卖不能让受让人取得真实权利；时効取得对原所有者及其单纯继承人无须登记；立木的独立交易须靠登记或明认方法——这是宅建考试少见的立木考点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-10', '{"id":"r07-10","tag":"权利关系・契约不适合责任","title":"令和7年 問10","stem":"Ａを売主、Ｂを買主とする甲土地の売買契約による甲土地の引渡し後に、目的物の品質に関して契約の内容に適合しない土壌汚染が見つかった場合の売主の契約不適合責任に基づく損害賠償に関する次の記述のうち、民法の規定、宅建業法の規定及び判例によれば、誤っているものはどれか。","options":["Ｂは、甲土地の引渡しの日から11年が経過した時点で甲土地の土壌汚染を発見し、発見した時点から１年以内にＡに通知した。Ａが当該土壌汚染があることを重大な過失なく知らなかった場合、Ａが宅建業者であるか否かにかかわらず、Ｂは損害賠償を請求することはできない。","甲土地の引渡しの日から３年以内に契約不適合の通知をしなければ売主は契約不適合責任を負わない旨の特約があり、Ｂが引渡しの日から４年が経過した時点で土壌汚染を発見して直ちにＡに通知した。Ａが当該土壌汚染があることを重大な過失なく知らなかった場合、Ａが宅建業者であるか否かにかかわらず、Ｂは損害賠償を請求することはできない。","甲土地の引渡しの日から１年以内に契約不適合の通知をしなければ売主は契約不適合責任を負わない旨の特約があり、Ａは甲土地に土壌汚染があることを売買契約締結時点で知っていて告げていなかった。Ｂが引渡しの日から３年が経過した時点で当該土壌汚染を発見して直ちにＡに通知した場合、Ａが宅建業者であるか否かによって、Ｂが損害賠償を請求できるか否かの結論が異なる。","売主は契約不適合責任を一切負わない旨の特約があり、Ｂは引渡しの日から１年が経過した時点で土壌汚染を発見して直ちにＡに通知した。Ａが当該土壌汚染があることを重大な過失なく知らなかった場合、Ａが宅建業者であるか否かによって、Ｂが損害賠償を請求できるか否かの結論が異なる。"],"correct":2,"explain":"【核心知识点，难题】卖方明知却隐瞒时，民法566条但书对任何卖方都一律适用，这个例外规则跟是否宅建业者无关。①对（不是错误项）。损害赔偿请求权受引渡后10年的客观消滅时效限制——本题11年已经超过10年，请求权已经消滅，不管卖方是不是业者都不能请求。②对（不是错误项）。特约3年内通知比宅建业法规定的2年以上更宽松，本来就有效；A不知情时，这个特约不管A是不是业者都有效，超过3年通知期限都不能请求。③错（答案）。A明知土壌汚染却隐瞒不告知——这种情形下1年内通知特约根据民法566条但书对任何卖方都不适用（不管是不是业者），选项说是否业者会导致结论不同是错的——不管A是不是业者，结论都一样：B可以请求。④对（不是错误项）。完全免责特约，若A是一般人（非业者），这种特约有效，B不能请求；若A是宅建业者，这种特约对买方不利，无效（宅建业法40条），B可以请求——是否业者确实导致结论不同。","takeaway":"卖方明知却隐瞒这种情形下的保护规则（民法566条但书），跟是否宅建业者这个身份完全无关，是对所有卖方一律适用的。很多人容易把业者/非业者身份影响特约效力这个思路无限套用到所有场景，但明知隐瞒这个例外规则本身是超越业者/非业者身份的、对任何卖方都适用的保护性规定——完全免责特约才是身份影响结论的正确例子。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-13', '{"id":"r07-13","tag":"权利关系・区分所有法","title":"令和7年 問13","stem":"建物の区分所有等に関する法律に関する次の記述のうち、誤っているものはどれか。","options":["共用部分は、原則として区分所有者全員の共有に属するが、規約で別段の定めをすることを妨げず、管理者であっても、規約に特別の定めがあるときは、共用部分を所有することができる。","共用部分の持分の割合について、各共有者の共用部分の持分は、規約で別段の定めをしない限り、その有する専有部分の床面積の割合による。","集会の議事については、議長は、書面又は電磁的記録により、議事録を作成しなければならず、当該議事録には議事の経過の要領及びその結果を記載し、又は記録しなければならないとされているが、当該議事録が書面で作成されているときは、議長及び集会に出席した区分所有者全員がこれに署名しなければならない。","区分所有者が、建物の保存に有害な行為その他建物の管理又は使用に関し区分所有者の共同の利益に反する行為をした場合又はその行為をするおそれがある場合には、他の区分所有者の全員又は管理組合法人は、区分所有者の共同の利益のため、その行為を停止し、その行為の結果を除去し、又はその行為を予防するため必要な措置を執ることを請求することができる。"],"correct":2,"explain":"【核心知识点】议事录书面签名人数是议长+2人，不是全员。①对（不是错误项）。共用部分原则属于全体区分所有者共有，但规约可以另定——规约特别规定时，管理者也可以持有共用部分的所有权。②对（不是错误项）。共用部分持分原则依专有部分床面积比例——跟r06-13是同一考点。③错（答案）。议事录书面作成时，须签名的是议长及出席集会的区分所有者2人（代表性签名），不是全员——选项把2人错说成了全员。④对（不是错误项）。对违反共同利益的行为，其他区分所有者全体或管理组合法人可以请求停止/除去/预防——这是区分所有法共同利益违反行为的停止请求权。","takeaway":"议事录签名人数其实只是议长+2名出席者这种代表性签名方式，不需要全体出席者都签，这是历年反复出题的经典数字陷阱（把2人错记成全员）。规约共用部分可以让管理者持有；共用部分持分按床面积比例（跟r06-13重复强化）；共同利益违反行为的停止请求权。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-15', '{"id":"r07-15","tag":"法令上的制限・都市计画法（用途地域定义）","title":"令和7年 問15","stem":"都市計画法に関する次の記述のうち、誤っているものはどれか。","options":["風致地区は、都市の風致を維持するため定める地区であり、当該地区内における建築物の建築について、政令の定める基準に従い、地方公共団体の条例で、都市の風致を維持するため必要な規制をすることができる。","特定街区は、市街地の整備改善を図るため街区の整備又は造成が行われる地区について、その街区内における建築物の容積率並びに建築物の高さの最高限度及び壁面の位置の制限を定める街区である。","近隣商業地域は、近隣の住宅地の住民に対する日用品の供給を行うことを主たる内容とする商業その他の業務の利便を増進するため定める地域である。","生産緑地地区は、農業の利便の増進を図りつつ、これと調和した低層住宅に係る良好な住居の環境を保護するため定める地区である。"],"correct":3,"explain":"【核心知识点】生产绿地地区和田园住居地域的定义被互换。①对（不是错误项）。风致地区——为维持都市风致而设定的地区，地方公共团体可依政令基准通过条例进行必要规制——定义正确。②对（不是错误项）。特定街区——为改善市街地而对街区规定容积率、建筑物高度最高限度、壁面位置限制的制度——定义正确。③对（不是错误项）。近隣商业地域——为向邻近住宅地居民供给日用品等的商业业务便利而设定的地域——定义正确。④错（答案）。本肢描述的其实是田园住居地域的定义（农业利便+低层住居环境保护），不是生产绿地地区——生产绿地地区的真正定义是：为计划性保全市街化区域内的农地、维持和形成都市环境而设定的地区，跟住居环境保护这个表述无关。","takeaway":"生产绿地地区和田园住居地域这两个名字相近、都跟农业有关的制度定义容易被互换——田园住居地域是用途地域的一种，讲的是农业+低层住居环境协调保护；生产绿地地区是独立的地域地区，讲的是计划性保全市街化区域内农地、维护都市环境。看到农业+住居环境保护对应田园住居地域，看到计划性保全农地+都市环境维持才是生产绿地地区。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-16', '{"id":"r07-16","tag":"法令上的制限・都市计画法（开发许可）","title":"令和7年 問16","stem":"都市計画法に関する次の記述のうち、正しいものはどれか。ただし、この問において条例による特別の定めはないものとし、「都道府県知事」とは、地方自治法に基づく指定都市、中核市及び施行時特例市にあってはその長をいうものとする。","options":["市街化調整区域のうち開発許可を受けた開発区域以外の区域において行う、学校教育法に規定する学校の新築については、都道府県知事の許可が不要である。","開発行為とは、主として建築物の建築又は特定工作物の建設の用に供する目的で行う土地の区画形質の変更をいい、ゴルフコースの建設は開発行為にはあたらない。","区域区分が定められていない都市計画区域において、商業施設の建築の用に供する目的で行う4,000㎡の開発行為は都道府県知事の許可が不要である。","自己の居住の用に供する住宅の建築を目的として行う開発行為以外の開発行為にあっては、原則として開発区域内に建築基準法に規定する災害危険区域内の土地を含んではならない。"],"correct":3,"explain":"【核心知识点】学校不属于公益上必要建筑物清单，高尔夫球场不受面积限制，灾害危险区域原则不能纳入开发区域。①错。学校不属于公益上必要建筑物清单——跟h24-17是同一知识框架，学校也不在豁免清单内，建筑新建需要许可。②错。高尔夫球场建设属于开发行为——不管面积多大，特定工作物（含高尔夫球场）的建设不受面积限制，一律算开发行为。③错。区域区分未定的都市计画区域（非线引区域）的开发许可门槛是3,000㎡以上，本题4,000㎡已超过门槛，需要许可。④对（答案）。自己居住用住宅建设以外的开发行为，原则不能把建筑基准法规定的灾害危险区域内的土地包含在开发区域内——这是保护公共安全的规定，只对自己居住用这种小规模个人开发有豁免。","takeaway":"学校不属于公益上必要建筑物清单——跟h24-17的图书馆/医院知识框架一致；高尔夫球场（特定工作物）不受面积限制，一律算开发行为；非线引区域的门槛是3,000㎡；灾害危险区域内土地原则不能纳入开发区域，只有自己居住用住宅建设这种情形有豁免——这是保护居住者安全的重要考点，容易被忽略。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-17', '{"id":"r07-17","tag":"法令上的制限・建筑基準法（2026年法改正）","title":"令和7年 問17","stem":"建築基準法に関する次の記述のうち、誤っているものはどれか。","options":["建築主は、建築確認が必要な建築物を建築しようとする場合は、当該建築物の計画を建築基準法令の規定に適合させるだけでなく、建築基準法令の規定以外の宅地造成及び特定盛土等規制法などの建築基準関係規定にも適合するものであることについて確認を受ける必要がある。","建築主は、２階建ての木造住宅を新築しようとする場合は、当該工事に着手する前に、その計画が建築基準関係規定に適合するものであることについて、確認を受け、確認済証の交付を受ける措置が必要となるが、当該住宅の大規模の修繕をしようとする場合には、当該措置は不要である。","延べ面積が1,000㎡を超える木造建築物は、その外壁及び軒裏で延焼のおそれのある部分を防火構造としなければならない。","高さ1ｍ以下の階段の部分には、手すりを設けなくてもよい。"],"correct":1,"explain":"【核心知识点，2026年法改正】木造和木造以外的区别已废除，统一按2层以上或延面积超200㎡判断，大规模修缮同样需要确认。①对（不是错误项）。建筑确认须同时符合建筑基准法令以及建筑基准关系规定（含盛土规制法等其他相关法令）。②错（答案）。法改正后木造和木造以外的区别已废除，判断建筑确认要否统一看2层以上或延面积超200㎡这个标准（大规模建筑物）——2层建筑物新建都需要确认，大规模修缮同样需要确认（不是新建需要、修缮不需要这种区分），选项说大规模修缮不需要是错的。③对（不是错误项）。延面积超1,000㎡的木造建筑物，外壁/軒裏中有延燒风险的部分须做防火构造。④对（不是错误项）。高度1米以下的阶梯部分不需要设置扶手。","takeaway":"2026年法改正废除了木造和非木造的区别，统一按2层以上或延面积超200㎡这个大规模建筑物标准判断是否需要建筑确认，不管是新建、增建、改建、移转、还是大规模修缮/模样替，只要符合这个标准都需要确认。这是相对新颖的法改正考点，容易被用旧知识（只有新建需要确认，修缮不需要）误答。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-19', '{"id":"r07-19","tag":"法令上的制限・盛土规制法","title":"令和7年 問19","stem":"宅地造成及び特定盛土等規制法に関する次の記述のうち、誤っているものはどれか。なお、この問において「都道府県知事」とは、地方自治法に基づく指定都市及び中核市にあってはその長をいうものとし、地方自治法に基づく施行時特例市に係る経過措置については考慮しないものとする。","options":["工事主は、特定盛土等規制区域内において行われる特定盛土等又は土石の堆積に関する政令で定める規模の工事の許可の申請をするときは、あらかじめ、主務省令で定めるところにより、特定盛土等又は土石の堆積に関する工事の施行に係る土地の周辺地域の住民に対し、説明会の開催その他の当該特定盛土等又は土石の堆積に関する工事の内容を周知させるため必要な措置を講じなければならない。","宅地造成等工事規制区域内の土地の工事主又は工事施行者は、宅地造成等に伴う災害が生じないよう、その土地を常時安全な状態に維持するように努めなければならない。","都道府県知事は、宅地造成等工事規制区域内の土地について、宅地造成等に伴う災害の防止のために必要があると認める場合においては、その土地の所有者、管理者、占有者、工事主又は工事施行者に対して、擁壁等の設置等の必要な措置をとることを勧告することができる。","宅地造成等工事規制区域内において行われる宅地造成等に関する工事の許可を受けた工事主は、当該許可に係る土地の見やすい場所に、主務省令で定めるところにより、氏名又は名称その他の主務省令で定める事項を記載した標識を掲げなければならない。"],"correct":1,"explain":"【核心知识点】常时安全维持义务主体是所有者/管理者/占有者，不是工事主/工事施行者。①对（不是错误项）。特定盛土等规制区域内的工程许可申请前，须向周边居民做说明会等周知措施。②错（答案）。让土地保持常时安全状态的努力义务承担者是土地的所有者、管理者、占有者（这是恒常性的一般维护义务），不是工事主或工事施行者——工事主/施行者的义务是工程本身的施工安全，跟平时保持土地安全这个持续性义务的承担者不同。③对（不是错误项）。知事认定有必要防止灾害时，可以对所有者、管理者、占有者、工事主、工事施行者（涵盖范围较广）劝告采取设置挡土墙等措施。④对（不是错误项）。取得工事许可的工事主，须在许可涉及土地的显眼处掲示标识。","takeaway":"区分平时常态维护义务的主体和工程施工阶段各类义务的主体——常时安全状态维持努力义务主体是所有者/管理者/占有者；劝告对象范围更广，涵盖所有者/管理者/占有者/工事主/工事施行者——两个选项的主体范围看似相近但实际不同，努力义务限定于产权/占有关系人，劝告对象则扩展到工程相关人员。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-23', '{"id":"r07-23","tag":"税相关法令・登録免许税（土地买卖税率减轻）","title":"令和7年 問23","stem":"土地の売買による所有権の移転登記等に係る登録免許税の税率の軽減措置に関する次の記述のうち、正しいものはどれか。","options":["この税率の軽減措置は、地目が雑種地となっている土地の売買による所有権の移転登記についても適用される。","この税率の軽減措置の適用対象となる土地は、その価額が1,000万円未満のものに限られる。","この税率の軽減措置は、法人が土地の売買による所有権の移転登記を受ける場合には適用されない。","この税率の軽減措置の適用対象となる土地は、その面積が1,000㎡未満のものに限られる。"],"correct":0,"explain":"【核心知识点】土地买卖所有权移转登记税率减轻，没有面积、价格、法人/个人身份的任何限定。①对（答案）。这项税率减轻措施跟地目无关——即使地目是杂种地，同样适用。②错。这项减轻措施没有价格要件的限定，不像住宅家屋税率减轻那种情形。③错。这项减轻措施同样适用于法人，不限于个人取得。④错。这项减轻措施没有面积要件的限定，不像住宅家屋税率减轻那种情形。","takeaway":"土地买卖所有权移转登记税率减轻和住宅家屋税率减轻是两项不同的登録免许税减轻措施不能混淆——土地买卖税率减轻没有面积、价格、法人/个人身份的任何限定，只要是土地买卖的所有权移转登记就能适用，地目也不限；这跟住宅家屋税率减轻（50㎡以上、可反复适用等）是完全不同的规则。这项措施本身极度宽松，是最容易被出题者拿来设置想当然加限制条件陷阱的地方。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-25', '{"id":"r07-25","tag":"不动产价格的评定・不动产鉴定评价基准","title":"令和7年 問25","stem":"不動産の鑑定評価に関する次の記述のうち、不動産鑑定評価基準によれば、誤っているものはどれか。","options":["価格形成要因のうち個別的要因とは、一般経済社会における不動産のあり方及びその価格の水準に影響を与える要因をいい、自然的要因、社会的要因、経済的要因及び行政的要因に大別される。","収益還元法は、賃貸用不動産又は賃貸以外の事業の用に供する不動産の価格を求める場合に特に有効な手段であり、自用の不動産であっても賃貸を想定することにより適用される。","原価法における減価修正の方法としては、耐用年数に基づく方法と、観察減価法の2つの方法があり、これらは併用するものとする。","対象建築物に関する工事が完了していない場合でも、当該工事の完了を前提として鑑定評価を行うことがある。"],"correct":0,"explain":"【核心知识点，史上首次连续3年出鉴定评价题】一般的要因和个别的要因的定义被互换。①错（答案）。本肢描述的其实是一般的要因的定义（对一般经济社会中不动产的状态及价格水准产生影响的要因，分自然/社会/经济/行政四大类），不是个别的要因——个别的要因指的是使不动产产生个别性、从而个别地形成其价格的要因，跟对象不动产自身的具体特性有关。②对（不是错误项）。收益还元法对赁贷用不动产或事业用不动产特别有效，自用不动产也可以通过假设赁贷来适用这个方法。③对（不是错误项）。原价法的减价修正方法有耐用年数基准法和观察减价法两种，这两种方法须并用。④对（不是错误项）。对象建筑物工程尚未完工时，鉴定评价可以以完工为前提进行——跟r02-10-25是同一考点。","takeaway":"一般的要因是宏观、社会经济层面的（自然/社会/经济/行政四分类），影响不动产整体的存在方式和价格水平；个别的要因是微观、针对具体标的物的，产生个别性从而个别地形成价格。这跟r06-25（最有効使用の原則 vs 適合の原則）是同一类型的定义互换陷阱——不动产鉴定评价基准里成对出现的术语，定义经常被出题者故意互换。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-28', '{"id":"r07-28","tag":"宅地建物取引业法等・业务综合（个数问题）","title":"令和7年 問28","stem":"宅建業者の業務に関する次の記述のうち、宅建業法の規定によれば、正しいものはいくつあるか。\\nア　自ら売主として販売する宅地又は建物の広告に取引態様の別を明示しなかった場合は、罰則の対象とはならないが監督処分の対象となり、宅地又は建物の規模について著しく事実に相違する表示をした場合は、罰則の対象にも監督処分の対象にもなる。\\nイ　自ら売主として土地付建物の売買契約を締結しようとする場合、当該土地上に建てようとする建物が建築確認申請前であっても、広告することはできるが、建築確認を受けるまで、契約を締結することはできない。\\nウ　宅建業者は、自ら売主として、宅建業者である買主との間で、自ら所有しない造成前の宅地の売買契約を締結するためには、法第41条の規定による手付金等の保全措置を講じ、かつ、売主である宅建業者が当該宅地を取得する契約を締結しなければならない。\\nエ　宅建業者は、宅地の売買の専属専任媒介契約を締結した場合、当該媒介契約締結の日から5日以内（休業日を除く）に、当該宅地について指定流通機構に所定の事項を登録しなければならない。","options":["一つ","二つ","三つ","なし"],"correct":1,"explain":"【核心知识点】8种制限只适用于买方非业者，业者相互间不适用；卖买在建筑确认前广告和契约都禁止。ア对。取引态样不明示不受罚则制裁，但受监督处分制裁；夸大广告既受罚则制裁又受监督处分制裁——这是广告违规里少数既罚则又监督处分的类型。イ错。建筑确认前，卖买这种交易类型不能做广告，也不能缔结契约——两者都被禁止，不是选项说的能做广告但不能缔结契约（贷借契约可以在确认前缔结，但卖买不行）。ウ错。本题的买主是宅建业者——8种制限（含手付金保全措施规定）只适用于买方非业者的情形，买方是业者时不适用这些限制。エ对。专属专任媒介契约缔结后，须在5日内（不含休业日）向指定流通机构登録（普通专任媒介契约是7日内）。正确的有两个（アエ），答案是二つ。","takeaway":"取引态样不明示只受监督处分，夸大广告是罰则+监督处分双重制裁的少见类型；卖买（不是贷借）在建筑确认前广告和契约都禁止，两者不能分开看；8种制限（含手付金保全措施）只适用于买方非业者，业者相互间交易不适用这些保护性规定——这是判断8种制限适用范围的核心口诀；专属专任媒介契约的指定流通机构登録期限是5日（专任媒介契约是7日）。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-31', '{"id":"r07-31","tag":"宅地建物取引业法等・禁止行为（个数问题）","title":"令和7年 問31","stem":"次の記述のうち、宅建業法により禁止されている行為が含まれているものはいくつあるか。\\nア　宅建士が、マンション販売の勧誘を電話で行うにあたり、まず、契約締結について勧誘する目的である旨を告げたうえで、自分の名前は名乗らず、自身の勤務する宅建業者の名称及び免許番号を伝えたうえで勧誘を行った。\\nイ　宅建業者が、賃貸マンションの媒介で入居申込者から申込みを受け付けたところ、当該マンションのオーナーからの審査回答待ちとなった。その後、入居申込者が、申込みを撤回したい旨電話で伝えたところ、当該宅建業者の従業員から声を荒げ「撤回をするなら、とりあえず事務所まで来てくれないと困る」と怒鳴られ、面会を強要された。申込者はその言動に不安を覚えたため、事務所に赴いて、申込みの撤回を申し出たところ、申込みの撤回が了承された。\\nウ　宅建業者が、一時的にアルバイトを雇って、マンション販売の広告チラシの配布を行わせることとしたほか、契約書の作成業務も補助的に行わせるため、従業者証明書をその者に発行し、それらの業務を行わせた。ただし、そのアルバイトはマンション販売の広告チラシの配布の際には、従業者証明書を携帯していなかった。\\nエ　マンションの販売の勧誘における説明において、宅建士は、日当たりのよいマンションの購入希望者に対して、「マンション南側の月極駐車場は出来たばかりであり、将来にわたりそこにマンションなどの高層の建物が建つ予定は全くない」と説明し、購入希望者から購入申込みを受け付けた。","options":["一つ","二つ","三つ","四つ"],"correct":3,"explain":"【核心知识点，全部违反】电话劝诱须完整告知业者名称+勧诱者姓名+勧诱目的；威迫行为绝对禁止；从业者证明书携带义务对临时人员同样适用；断定性判断提供一律禁止。ア违反。电话劝诱前须告知业者名称+勧诱者本人姓名+勧诱目的——本题没有告知自己的姓名，缺了一项必要告知内容。イ违反。威迫行为本身就被禁止，不管最后交易是否成立、撤回是否被了承——员工怒吼强迫面会属于威迫行为。ウ违反。即使是临时性的兼职人员，从事宅建业相关业务时也须携带从业者证明书——本题分发广告传单时没有携带。エ违反。断定性判断的提供（将来绝对不会建高层建筑这种断言）在劝诱契约缔结时被禁止，不管这个断言的内容是真是假。四项全部违反，答案是四つ。","takeaway":"宅建业法业务规制的四个基础红线：电话劝诱须完整告知业者名称+勧诱者姓名+勧诱目的三项内容缺一不可；威迫行为绝对禁止，不因最终结果是否达成而改变违法性；从业者证明书携带义务对临时/兼职人员同样适用；断定性判断提供一律禁止，不问断言内容真假。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_questions` (id, data, times_reported) VALUES ('r07-33', '{"id":"r07-33","tag":"宅地建物取引业法等・35条37条书面对照（个数问题）","title":"令和7年 問33","stem":"宅建業者Ａが行う業務に関する次の記述のうち、宅建業法の規定によれば、誤っているものはいくつあるか。なお、この問において「37条書面」とは、同法第37条の規定により交付すべき書面をいうものとする。\\nア　建物の賃貸借の媒介をする宅建業者Ａは、当該建物の引渡しの時期について、重要事項説明書に記載して説明する必要はないが、37条書面には記載しなければならない。\\nイ　宅建業者Ａは、自ら売主として建物を売却する場合、重要事項説明書に記載しなければならない契約の解除に関する事項については、契約に定めがなくても37条書面に全て記載しなければならない。\\nウ　宅建業者Ａは、売主を代理して、抵当権が登記されている建物を売却する場合、買主に交付する37条書面だけでなく、売主に交付する37条書面についても、当該抵当権の内容を記載しなければならない。\\nエ　建物の賃貸借の媒介をする宅建業者Ａは、37条書面を交付するに当たり、宅建士をして、その内容を説明させなければならない。","options":["一つ","二つ","三つ","なし"],"correct":2,"explain":"【核心知识点，与t113对照】35条书面和37条书面的职责边界，37条书面本身不要求说明。ア对（不是错误项）。建物引渡时期，35条书面不要求说明，但37条书面须记载——跟h30-34（引渡时期是买卖贷借共通必要记载事项）是同一考点。イ错。契约解除相关事项，35条书面里是若有约定才须说明的，37条书面同样是有约定才记载的任意记载事项，没有约定时不需要记载没有约定这件事——选项说没有定めても全て記載しなければならない是错的。ウ错。登记的权利种类/内容（含抵当权内容）是35条书面的重要事项，37条书面不要求记载这一项——跟t113（35条/37条对照表）是同一考点。エ错。37条书面交付时不需要宅建士做说明——37条书面只要求宅建士记名，不像35条书面那样须由宅建士口头说明内容——跟r06-35是同一底层逻辑。错误的有三个（イウエ），答案是三つ。","takeaway":"再次强化35条书面和37条书面的职责边界（跟t113对照表是同一体系）——引渡时期是两者都要求但方式不同；契约解除事项和抵当权内容都遵循35条书面须说明、37条书面若有才记载或35条书面要写、37条书面不要写这样的分工，具体要按各自事项单独判断；37条书面本身不要求宅建士说明，只要求记名——这是贯穿令和7年真题多道题目（問29、問33、問35均涉及）的核心考点。"}', 1) ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t1', '{"id":"t1","tag":"民法","title":{"zh":"赁贷借契约 vs 使用贷借契约","ja":"賃貸借契約と使用貸借契約"},"source":"平成27年 問3","sections":[{"heading":"核心逻辑","blocks":[{"type":"text","content":{"zh":"赁贷借（有偿）→ 参照买卖规则；使用贷借（无偿）→ 参照赠与规则。","ja":"賃貸借（有償）→ 売買の規定を準用／使用貸借（無償）→ 贈与の規定を準用。"}}]},{"heading":"对比速查","blocks":[{"type":"table","headers":[{"zh":"比较项","ja":"比較項目"},{"zh":"赁贷借（有偿）","ja":"賃貸借（有償）"},{"zh":"使用贷借（无偿）","ja":"使用貸借（無償）"}],"rows":[[{"zh":"借主死亡","ja":"借主の死亡"},{"zh":"不终止，继承人继承","ja":"契約は終了しない（相続人が承継）"},{"zh":"终止（基于情谊）","ja":"契約は終了する（当事者間の情義に基づくため）"}],[{"zh":"必要费用","ja":"必要費"},{"zh":"贷主负担（可请求偿还）","ja":"貸主が負担（借主は償還請求可）"},{"zh":"借主自己负担（通常必要费）","ja":"借主が負担（通常の必要費）"}],[{"zh":"契约性质","ja":"契約の性質"},{"zh":"诺成契约","ja":"諾成契約"},{"zh":"诺成契约（新法已改为诺成）","ja":"諾成契約（改正民法で諾成契約に変更）"}],[{"zh":"契约不适合的担保责任","ja":"契約不適合責任"},{"zh":"贷主要负责","ja":"貸主が責任を負う"},{"zh":"原则不负，明知瑕疵不告知的除外","ja":"原則負わない（貸主が瑕疵を知りながら告げなかった場合を除く）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"使用贷借完全不负担保责任\\"是错的绝对化表述——正确是\\"原则不负，但贷主明知瑕疵不告知的除外\\"。","ja":"「使用貸借は担保責任を一切負わない」という言い切りは誤り。正しくは「原則として負わないが、貸主が瑕疵を知りながら告げなかった場合は除く」。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t2', '{"id":"t2","tag":"民法","title":{"zh":"法定相续（继承）","ja":"法定相続"},"source":"平成26年 問10","sections":[{"heading":"继承顺位","blocks":[{"type":"text","content":{"zh":"第一顺位子女 → 第二顺位父母 → 第三顺位兄弟姐妹（配偶永远是当然继承人，与顺位并行）","ja":"第一順位は子、第二順位は直系尊属（父母等）、第三順位は兄弟姉妹（配偶者は常に相続人となり、順位と並行する）"}}]},{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"内缘の妻（事实婚配偶）没有法定继承权——只有正式登记的配偶才算","ja":"内縁の妻（事実婚の配偶者）に相続権はない——法律上の婚姻届を提出した配偶者に限られる"},{"zh":"半血兄弟姐妹份额 = 全血兄弟姐妹份额的一半（民法900条4号但书）","ja":"半血の兄弟姉妹の相続分は全血の兄弟姉妹の2分の1（民法900条4号ただし書）"},{"zh":"代袭继承是\\"整份继承\\"：先死之人的份额整体转给其子女，子女之间再平分","ja":"代襲相続は「まるごと承継」——先に死亡した者の相続分がその子にそのまま移転し、子が複数いる場合はその中で均等に分ける"}]}]},{"heading":"计算步骤模板","blocks":[{"type":"list","style":"ordered","items":[{"zh":"先排除没有继承资格的人（如内缘配偶）","ja":"まず相続資格のない者（内縁配偶者など）を除外する"},{"zh":"按\\"全血=2份、半血=1份\\"分配基础份额","ja":"「全血＝2、半血＝1」の比率で基礎となる相続分を配分する"},{"zh":"已故继承人的份额，由其子女代袭继承（整份转移、多子女平分）","ja":"死亡した相続人の相続分は、その子が代襲相続する（まるごと移転し、子が複数なら均等に分割）"},{"zh":"验算：所有份额相加应等于1","ja":"検算：すべての相続分を合計すると1になることを確認する"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"事实婚配偶容易被误当有继承权；代袭继承容易算错分配对象——是\\"整份转给已故人的子女\\"，不是打散重分给全体继承人。","ja":"内縁配偶者に相続権があると誤解しやすい。また代襲相続では分配先を間違えやすい——「死亡した者の子にまるごと承継される」のであり、相続人全員で再分配するのではない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t3', '{"id":"t3","tag":"借地借家法","title":{"zh":"四种\\"确保到期终止\\"的借地权","ja":"期間満了で確実に終了する4種類の借地権"},"source":"令和3年10月 問11","sections":[{"heading":"速查表","blocks":[{"type":"table","headers":[{"zh":"类型","ja":"種類"},{"zh":"期限","ja":"存続期間"},{"zh":"形式","ja":"契約の方式"},{"zh":"用途","ja":"用途"}],"rows":[[{"zh":"一般定期借地权","ja":"一般定期借地権"},{"zh":"50年以上","ja":"50年以上"},{"zh":"书面即可","ja":"書面でよい"},{"zh":"不限","ja":"用途の制限なし"}],[{"zh":"事业用定期借地权","ja":"事業用定期借地権"},{"zh":"10～50年","ja":"10年以上50年未満"},{"zh":"必须公正证书","ja":"公正証書に限る"},{"zh":"只能事业用","ja":"事業用建物所有目的に限る"}],[{"zh":"建物讓渡特约付借地权","ja":"建物譲渡特約付借地権"},{"zh":"30年以上","ja":"30年以上"},{"zh":"不需书面","ja":"書面は不要"},{"zh":"不限","ja":"用途の制限なし"}],[{"zh":"一时使用目的的借地权","ja":"一時使用目的の借地権"},{"zh":"无期限要求","ja":"期間の制限なし"},{"zh":"无形式要求","ja":"方式の制限なし"},{"zh":"临时使用","ja":"一時的な使用に限る"}]]}]},{"heading":"判断步骤","blocks":[{"type":"list","style":"ordered","items":[{"zh":"用途是什么？（居住用直接排除事业用定期借地权）","ja":"用途は何か？（居住用であれば事業用定期借地権は最初から除外）"},{"zh":"约定的期限是多少？（决定该用哪种类型）","ja":"約定する存続期間は何年か？（どの類型に当たるかを決める）"}]},{"type":"mnemonic","content":{"zh":"一般定期：\\"50年起步，不限用途，书面就行\\"\\n事业用定期：\\"10-50年，只能事业用，必须公正证书\\"\\n建物讓渡特约：\\"30年起步，不限用途，不需要书面\\"\\n一时使用目的：\\"没有期限下限，专门给临时使用场景用\\"","ja":"一般定期：「50年から、用途自由、書面でOK」\\n事業用定期：「10～50年、事業用限定、公正証書必須」\\n建物讓渡特約：「30年から、用途自由、書面不要」\\n一時使用目的：「期間の下限なし、臨時利用専用」"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"看到\\"事业用建筑物\\"别急着套用事业用定期借地权——期限才是决定性因素，超过50年就得换一般定期借地权。","ja":"「事業用の建物」と見てすぐ事業用定期借地権だと決めつけない——決め手は存続期間であり、50年を超える場合は一般定期借地権になる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t4', '{"id":"t4","tag":"借地借家法","title":{"zh":"裁判所代诺许可制度","ja":"裁判所の代諾許可制度"},"source":"平成23年 問11","sections":[{"heading":"四种场景 & 申请人","blocks":[{"type":"table","headers":[{"zh":"场景","ja":"場面"},{"zh":"申请人","ja":"申立人"}],"rows":[[{"zh":"借地条件变更（协商不成）","ja":"借地条件の変更（協議が調わない場合）"},{"zh":"双方都可以申请","ja":"当事者いずれからも申立て可能"}],[{"zh":"重建超过残存期间的建筑物（地主不同意）","ja":"残存期間を超えて存続する建物の増改築（地主が承諾しない場合）"},{"zh":"借地权人","ja":"借地権者"}],[{"zh":"打算将借地权让与第三者（尚未发生）","ja":"借地権を第三者に譲渡しようとする場合（まだ譲渡していない）"},{"zh":"借地权人本人","ja":"借地権者本人"}],[{"zh":"第三者已通过拍卖取得建筑物（已经发生）","ja":"第三者が競売により建物を取得した場合（既に取得済み）"},{"zh":"第三者","ja":"その第三者"}]]},{"type":"mnemonic","content":{"zh":"\\"事还没办成，找原来的人（借地权人）；事已经办成了，找现在的人（第三者）\\"——关键看转让/取得是否已经实际发生。","ja":"「まだ実現していなければ元の人（借地権者）、すでに実現していれば今の人（第三者）」——譲渡・取得が実際に発生したかどうかが分かれ目。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t5', '{"id":"t5","tag":"民法","title":{"zh":"请负契约（承揽合同）","ja":"請負契約"},"source":"令和元年 問8","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"场景","ja":"場面"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"建筑物严重不符合合同内容，需要重建","ja":"建物が契約内容に重大に適合せず、建て替えが必要な場合"},{"zh":"可请求相当于\\"重建费用\\"的损害赔偿（最判平14.9.24）","ja":"建替えに要する費用相当額の損害賠償を請求できる（最判平14.9.24）"}],[{"zh":"请负人担保责任的存续期限","ja":"請負人の契約不適合責任の存続期間"},{"zh":"适用普通消灭时效（知道起5年/能行使起10年），不能靠特约延长","ja":"通常の消滅時効による（知った時から5年・行使できる時から10年）——特約による延長は不可"}],[{"zh":"因注文人（发包人）的原因导致无法履行","ja":"注文者の帰責事由により履行が不能となった場合"},{"zh":"请负人可以行使解除权，免除未履行部分的义务","ja":"請負人は契約を解除することで未履行部分の義務を免れることができる"}],[{"zh":"请负人尚未完成工作期间","ja":"請負人が仕事を完成しない間"},{"zh":"注文人可以随时赔偿损失后任意解除合同（第641条）","ja":"注文者はいつでも損害を賠償して契約を解除できる（第641条）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"担保责任存续期限是法定消灭时效，不能通过合同约定延长（如20年）——涉及交易秩序稳定性的强制性规定不容突破。","ja":"担保責任の存続期間は法定の消滅時効であり、特約で延長（例：20年）することはできない——取引秩序の安定にかかわる強行規定であり、合意で変更することはできない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t6', '{"id":"t6","tag":"民法","title":{"zh":"制限行为能力者","ja":"制限行為能力者"},"source":"平成28年 問2","sections":[{"heading":"四类保护对象的核心规则","blocks":[{"type":"table","headers":[{"zh":"场景","ja":"場面"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"被许可营业的未成年人","ja":"営業を許された未成年者"},{"zh":"只在许可的营业范围内视为成年人，范围外的行为仍需法定代理人同意","ja":"許された営業の範囲内でのみ成年者と同一の行為能力を有し、範囲外の行為には法定代理人の同意が必要"}],[{"zh":"被保佐人的\\"重要行为\\"清单","ja":"被保佐人の「重要な行為」リスト"},{"zh":"卖不动产、拒绝赠与等均需保佐人同意，不是只有卖不动产才需要","ja":"不動産の売却だけでなく、贈与の申し出の拒絶も保佐人の同意が必要"}],[{"zh":"成年被后见人的居住用不动产处分","ja":"成年被後見人の居住用不動産の処分"},{"zh":"即便有后见监督人，仍必须经家庭裁判所许可，监督人许可不能代替","ja":"後見監督人がいても家庭裁判所の許可が必要——後見監督人の許可では代替できない"}],[{"zh":"使用诈术让对方相信已获同意","ja":"詐術を用いて同意を得たと信じさせた場合"},{"zh":"丧失撤销权（民法21条）","ja":"取消権を失う（民法21条）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"营业许可有\\"范围限定\\"，居住用不动产处分永远要家庭裁判所把关，不能被后见监督人的许可替代。","ja":"営業許可には「範囲の限定」がある。居住用不動産の処分は常に家庭裁判所の許可が必要で、後見監督人の許可では代替できない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t7', '{"id":"t7","tag":"民法","title":{"zh":"债权让渡（将来债权）","ja":"債権譲渡（将来債権）"},"source":"令和3年10月 問6","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"让渡制限特约不影响债权转让本身的效力，债务人可将全额供托","ja":"譲渡制限の意思表示があっても債権譲渡の効力自体は妨げられない——債務者は全額を供託できる"},{"zh":"新民法下，将来债权也可以转让，转让时该债权是否已现实发生不影响转让效力","ja":"改正民法では将来債権も譲渡可能——譲渡の意思表示時に債権が現に発生していなくても、譲受人は後に発生した債権を当然に取得する"},{"zh":"受让人明知有让渡制限的意思表示时，债务人可拒绝履行并以对抗让渡人的事由对抗受让人","ja":"譲受人が譲渡制限の意思表示を知っていたときは、債務者は履行を拒み、譲渡人に対する事由をもって譲受人に対抗できる"},{"zh":"债权转让对抗债务人需通知或承诺，对抗第三人需确定日期证书","ja":"債権譲渡は債務者への通知又は承諾がなければ対抗できず、債務者以外の第三者への対抗には確定日付のある証書が必要"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"旧法思维容易误判\\"债权尚未现实发生就不能转让\\"——新民法下将来债权可以转让，受让人当然取得后续发生的债权。","ja":"旧法的な発想で「まだ現実に発生していない債権は譲渡できない」と誤解しやすいが、改正民法では将来債権も譲渡可能で、譲受人は後発の債権を当然に取得する。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t8', '{"id":"t8","tag":"民法","title":{"zh":"转租（适法转贷）中的三方关系","ja":"適法転貸における三者間の関係"},"source":"平成23年 問7","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"承租人欠租时，贷主可在承租人应付租金限度内，直接向转租人请求支付","ja":"賃借人が賃料を支払わない場合、賃貸人は賃借人に対する賃料の限度で転借人に直接請求できる"},{"zh":"贷主对承租人租金债权的先取特权，效力及于转租人的租金债权（物上代位）","ja":"賃貸人の賃料債権に関する先取特権は、物上代位により転借人に対する賃料債権にも及ぶ"},{"zh":"贷主与承租人\\"合意解除\\"，原则不能对抗已适法转租的转租人","ja":"賃貸人と賃借人の合意解除は、原則として適法な転借人に対抗できない"},{"zh":"因承租人\\"债务不履行（欠租）\\"解除时，不需要事先通知转租人代付租金的机会（最判昭37.3.29）","ja":"賃借人の債務不履行（賃料不払い）を理由とする解除の場合、転借人へ事前に代払いの機会を与える必要はない（最判昭37.3.29）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"合意解除\\"和\\"债务不履行解除\\"对转租人的效力完全不同——债务不履行解除不需要提前通知转租人代付。","ja":"「合意解除」と「債務不履行解除」とでは転借人への効力がまったく異なる——債務不履行解除では転借人への事前通知は不要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t9', '{"id":"t9","tag":"民法","title":{"zh":"共有物的占有与相続关连判例","ja":"共有物の占有と相続に関する判例"},"source":"平成30年 問10","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"无权代理人无断卖掉本人不动产后单独继承本人，视为本人自己卖的效果","ja":"無権代理人が本人の不動産を無断で売却した後に本人を単独相続した場合、本人自ら売却したのと同様の効果が生じる"},{"zh":"共同继承人擅自单独登记并转卖第三人，其他继承人对自己持分不需登记也能对抗该第三取得者","ja":"共同相続人の一人が単独名義で登記し第三者に譲渡した場合、他の共同相続人は自己の持分を登記なくして対抗できる"},{"zh":"连带债务人死亡，继承人按继承份额分割承继，各自在承继范围内成为连带债务人","ja":"連帯債務者の一人が死亡した場合、相続人はその相続分に応じて分割された債務を承継し、その範囲で連帯債務者となる"},{"zh":"持分过半数的共有人不能\\"当然地\\"请求单独占有的其他共有人搬走（令和2年判例限缩通说）","ja":"持分価格が過半数の共有者であっても、単独で占有する他の共有者に当然に明渡しを請求できるわけではない（令和2年判例）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"持分过半数≠可以直接赶走同为共有人的其他人；多数决管的是\\"如何管理\\"，不是\\"能不能把人赶出去\\"。","ja":"持分が過半数であっても他の共有者を当然に排除できるわけではない——多数決で決められるのは「管理方法」であり、明渡し請求とは別問題。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t10', '{"id":"t10","tag":"借地借家法","title":{"zh":"定期建物赁贷借 vs 普通建物赁贷借","ja":"定期建物賃貸借と普通建物賃貸借"},"source":"令和6年 問12","sections":[{"heading":"对比速查","blocks":[{"type":"table","headers":[{"zh":"比较项","ja":"比較項目"},{"zh":"定期建物赁贷借","ja":"定期建物賃貸借"},{"zh":"普通建物赁贷借","ja":"普通建物賃貸借"}],"rows":[[{"zh":"对第三取得者主张赁借权","ja":"第三取得者への賃借権の対抗"},{"zh":"受领引渡后即可对抗","ja":"引渡しを受ければ対抗可能"},{"zh":"同样只要受领引渡即可对抗","ja":"同様に引渡しを受ければ対抗可能"}],[{"zh":"特约排除减额请求权","ja":"減額請求権を排除する特約"},{"zh":"有效","ja":"有効"},{"zh":"无效（仍可请求减额）","ja":"無効（減額請求は可能）"}],[{"zh":"不更新的约定方式","ja":"更新なしの定め方"},{"zh":"书面（含电磁记录）即可，不需公正证书","ja":"書面（電磁的記録を含む）でよく、公正証書は不要"},{"zh":"口头也可成立，拒绝更新需正当事由","ja":"口頭でも成立し、更新拒絶には正当事由が必要"}],[{"zh":"无继承人的事实婚同居人承继","ja":"相続人なき場合の内縁同居者の承継"},{"zh":"适用（未表示反对则承继）","ja":"適用あり（反対の意思表示がなければ承継）"},{"zh":"同样适用","ja":"同様に適用あり"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"两种契约在\\"受领引渡即可对抗\\"和\\"事实婚同居人承继\\"上规则相同，区别只在\\"减额请求权是否可特约排除\\"和\\"不更新的约定方式\\"。","ja":"「引渡しを受ければ対抗できる」点と「内縁同居者の承継」の扱いは両契約で共通。異なるのは「減額請求権を特約で排除できるか」と「更新なしの定め方」のみ。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t11', '{"id":"t11","tag":"区分所有法","title":{"zh":"区分所有法核心考点","ja":"建物の区分所有等に関する法律の重要ポイント"},"source":"平成26年 問13","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"管理组合法人化没有\\"区分所有者30人以上\\"的门槛限制（这是2002年改正前的旧规定）","ja":"管理組合法人化に「区分所有者30人以上」という人数要件はない（2002年改正前の旧規定）"},{"zh":"专有部分数人共有时，集会招集通知发给40条确定的议决权行使人，未定时发给共有者任一人即可","ja":"専有部分が数人の共有に属する場合、集会招集通知は第40条の議決権行使者に、定めがなければ共有者のいずれか一人にすればよい"},{"zh":"建筑物1/2以下部分灭失时，若已有复旧决议/建替决议等，各区分所有者不能再自行修复","ja":"建物の価格の2分の1以下が滅失した場合でも、復旧決議・建替え決議等があれば各区分所有者は個別に復旧できない"},{"zh":"管理者怠于保管规约或无正当理由拒绝阅览，处20万日元以下罚款","ja":"管理者が規約の保管を怠り、又は正当な理由なく閲覧を拒んだときは20万円以下の過料に処せられる"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"管理组合法人化需要30人以上\\"是经典的新旧法混淆陷阱——现行法下任何规模都可以申请法人化。","ja":"「管理組合法人化には30人以上必要」は新旧法混同の典型的な誤り——現行法ではどんな規模でも法人化を申請できる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t12', '{"id":"t12","tag":"不动产登记法","title":{"zh":"表示登记 vs 权利登记","ja":"表示に関する登記と権利に関する登記"},"source":"平成26年 問14","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"\\"登记原因证明信息\\"只在权利登记时才要求提交，表示登记不需要","ja":"「登記原因証明情報」は権利に関する登記でのみ必要——表示に関する登記では不要"},{"zh":"新产生的土地或无表题登记的土地，所有权人须自取得之日起1个月内申请表题登记","ja":"新たに生じた土地又は表題登記のない土地の所有者は、所有権取得の日から1月以内に表題登記を申請しなければならない"},{"zh":"信托登记必须与该信托相关权利的保存/设定/移转/变更登记同时申请","ja":"信託の登記は、当該信託に係る権利の保存・設定・移転・変更の登記と同時に申請しなければならない"},{"zh":"假登记若得义务人承诺，权利人可单独申请","ja":"仮登記は、仮登記義務者の承諾があれば仮登記権利者が単独で申請できる"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"登记原因证明信息只在\\"权利登记\\"时才需要——\\"表示登记\\"（表明不动产物理状况）不需要这份材料，这是区分两类登记的关键考点。","ja":"登記原因証明情報は「権利に関する登記」のみ必要で、「表示に関する登記」（不動産の物理的状況を表す登記）には不要——両者を区別する重要ポイント。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t13', '{"id":"t13","tag":"国土利用计画法","title":{"zh":"事后届出的三个要件","ja":"事後届出の3要件"},"source":"平成23年 問15","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"事后届出要同时满足权利性、契约性、对价性三个条件；赠与因没有对价，根本不构成\\"土地売买等契约\\"，不需要申报。","ja":"事後届出は権利性・契約性・対価性の3要件をすべて満たす必要がある。贈与は対価性を欠くため、そもそも「土地売買等契約」に当たらず届出不要。"}},{"type":"list","style":"unordered","items":[{"zh":"土地处分斡旋等措施只是知事的努力义务，不是必须履行的法定义务","ja":"土地の処分についてのあっせん等の措置は知事の努力義務にとどまり、必ず講じなければならない義務ではない"},{"zh":"土地利用审查会\\"确认\\"未取得需公告并溯及失效的规定，只适用于\\"规制区域\\"，不适用于\\"监视区域\\"","ja":"土地利用審査会の確認が得られなかった場合の公告・遡及失効の規定は「規制区域」にのみ適用され、「監視区域」には適用されない"},{"zh":"市街化调整区域的事后届出门槛是5000㎡以上","ja":"市街化調整区域における事後届出の面積要件は5,000㎡以上"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"赠与看似是\\"权利移转\\"，但因缺乏对价性，根本不算\\"土地売买等契约\\"，考生容易忽略\\"对价性\\"这个隐藏要件。","ja":"贈与は権利移転に見えるが対価性を欠くため「土地売買等契約」に該当しない——「対価性」という隠れた要件を見落としやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t14', '{"id":"t14","tag":"都市计画法","title":{"zh":"开发许可判断三步走","ja":"開発許可の要否を判断する3ステップ"},"source":"平成26年 問16","sections":[{"heading":"判断步骤","blocks":[{"type":"list","style":"ordered","items":[{"zh":"是否国/都道府県进行的开发行为？（可用\\"协议\\"替代\\"许可\\"）","ja":"国又は都道府県が行う開発行為か？（許可に代えて「協議」で足りる）"},{"zh":"是否属于\\"公益上必要建筑物\\"清单内？（无条件豁免，如公民馆）","ja":"「公益上必要な建築物」のリストに該当するか？（公民館など、無条件で許可不要）"},{"zh":"面积是否达到该区域的申报门槛？（市街化区域内农林渔业者居住用建筑物没有豁免）","ja":"当該区域の面積要件に達しているか？（市街化区域内では農林漁業者の居住用建築物の許可不要規定は適用されない）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"农林渔业者居住用建筑物的开发许可豁免，只适用于\\"市街化区域以外\\"——市街化区域内没有这个豁免，容易忽略这个地域限定。","ja":"農林漁業者の居住用建築物に関する開発許可不要の規定は「市街化区域以外」でのみ適用される——市街化区域内にはこの特例がない点を見落としやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t15', '{"id":"t15","tag":"建筑基准法","title":{"zh":"建蔽率/容积率与道路规制","ja":"建蔽率・容積率と道路規制"},"source":"平成23年 問19","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"经营仓库业的仓库只能建在准住居地域到工业专用地域范围，第二种住居地域不允许（即便是工场附设）","ja":"倉庫業を営む倉庫は準住居地域から工業専用地域までの範囲にのみ建築でき、第二種住居地域には建築できない（工場付設であっても不可）"},{"zh":"法施行时已存在的未满4米道路，要成为\\"二项道路\\"必须经特定行政厅指定，不是自动成为道路","ja":"法施行時に現に存在する幅員4m未満の道路は、特定行政庁の指定を受けて初めて「二項道路」となり、当然に道路となるわけではない"},{"zh":"容积率原则按都市计画数值，但前面道路不满12米时，取\\"道路宽度×法定系数\\"和都市计画数值两者较小值","ja":"容積率は都市計画の数値によるが、前面道路の幅員が12m未満の場合は「前面道路幅員×法定乗数」と都市計画の数値のいずれか小さい方による"},{"zh":"建蔽率8/10地域+防火地域+耐火建筑物 → 建蔽率限制直接不适用（100%），不是缓和到9/10","ja":"建蔽率限度10分の8の地域内かつ防火地域内の耐火建築物は、建蔽率の制限自体が適用されなくなる（100%）——10分の9への緩和ではない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"建蔽率8/10+防火地域+耐火建筑物是\\"完全不适用限制\\"，不是\\"加成到9/10\\"——这个数字陷阱极易出错。","ja":"建蔽率10分の8＋防火地域＋耐火建築物の組み合わせは「制限が適用されなくなる」のであり、「10分の9に緩和される」のではない——数字の罠に注意。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t16', '{"id":"t16","tag":"建筑基准法","title":{"zh":"街角地建蔽率加成与低层住居地域高度限制","ja":"街区の角地の建蔽率緩和と低層住居専用地域の高さ制限"},"source":"平成24年 問19","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"街角地块建蔽率加成10%，必须经特定行政厅\\"指定\\"才能适用，不是自动适用","ja":"街区の角にある敷地の建蔽率加算10分の1は、特定行政庁の「指定」を受けて初めて適用され、自動的には適用されない"},{"zh":"第一种/第二种低层住居专用地域的绝对高度限制是10米或12米，不是12米或15米","ja":"第一種・第二種低層住居専用地域の絶対高さ制限は10m又は12m——12m又は15mではない"},{"zh":"用途地域内约定建筑物基地面积最低限度时，不能超过200㎡","ja":"用途地域に関する都市計画で建築物の敷地面積の最低限度を定める場合、200㎡を超えることはできない"},{"zh":"建筑协定的变更需全体土地所有者同意，废止只需过半数同意，都要经特定行政厅认可","ja":"建築協定の変更には土地所有者等全員の合意が必要だが、廃止は過半数の合意でよい——いずれも特定行政庁の認可が必要"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"低层住居专用地域绝对高度限制\\"10米/12米\\"和数字相近的\\"12米/15米\\"极易混淆，务必牢记准确数字。","ja":"低層住居専用地域の絶対高さ制限「10m・12m」は数字の近い「12m・15m」と混同しやすいので正確な数字を覚える。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t17', '{"id":"t17","tag":"盛土规制法","title":{"zh":"造成宅地防灾区域的指定基准","ja":"造成宅地防災区域の指定基準"},"source":"平成28年 問20","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"造成宅地防灾区域的指定基准不止\\"盛土高度5米\\"一条，还有其他并列基准（如角度+高度组合、地下水位条件等），盛土不满5米不代表绝对不能被指定。","ja":"造成宅地防災区域の指定基準は「盛土の高さ5m以上」だけでなく、角度と高さの組み合わせや地下水位の条件など複数の並列基準がある——盛土が5m未満でも指定され得る。"}},{"type":"list","style":"unordered","items":[{"zh":"排水设施设计资格要求，只在允许技术基准适用规模以上的开发中才要求","ja":"排水施設の設計資格要件は、政令で定める規模以上の工事にのみ適用される"},{"zh":"除却2米以上挡土墙的工程，须在工程开始14日前向知事申报","ja":"高さ2mを超える擁壁を除却する工事は、着手日の14日前までに都道府県知事に届け出なければならない"},{"zh":"宅地以外土地转用为宅地，转用后14日以内需向知事申报","ja":"宅地以外の土地を宅地に転用した場合、転用の日から14日以内に知事に届け出なければならない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"盛土不满5米就绝对不能被指定为防灾区域\\"是错误的绝对化表述——还有其他并列的指定基准。","ja":"「盛土が5m未満なら絶対に防災区域に指定されない」という言い切りは誤り——他にも並列する指定基準がある。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t18', '{"id":"t18","tag":"土地区画整理法","title":{"zh":"减价补偿金与换地计划核心规则","ja":"減価補償金と換地計画の重要ルール"},"source":"令和2年12月 問20","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"减价补偿金交付对象是宅地的所有者/使用收益权人，不包括建筑物本身的赁借人（房客）","ja":"減価補償金の交付対象は宅地の所有者又は宅地について使用収益権を有する者であり、建物の賃借人は含まれない"},{"zh":"清算金是在\\"换地处分\\"时确定并徴收/交付的，不是在仮换地指定时","ja":"清算金は「換地処分」の時に確定し徴収・交付されるものであり、仮換地の指定時ではない"},{"zh":"换地计划定换地时，要保证新旧宅地的位置、地积、土质、水利、利用状况、环境等\\"照应\\"","ja":"換地計画で換地を定める際は、従前の宅地との位置・地積・土質・水利・利用状況・環境等の「照応」を確保しなければならない"},{"zh":"\\"防止过小宅地\\"的地积适正化规则，只能在公的施行（不是组合施行）时使用","ja":"過小宅地とならないよう地積を適正化する規定は、公的施行の場合にのみ適用され、組合施行には適用されない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"减价补偿金交付对象是\\"宅地\\"权利人，不是\\"建筑物\\"权利人——权利客体不同（宅地 vs 建筑物）是这道题的核心陷阱。","ja":"減価補償金の交付対象は「宅地」の権利者であり「建物」の権利者ではない——権利の客体（宅地か建物か）の違いが最大の落とし穴。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t19', '{"id":"t19","tag":"农地法","title":{"zh":"农地法3条/4条/5条的适用区分","ja":"農地法3条・4条・5条の適用区分"},"source":"平成29年 問15","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"市街化区域内报备免许可的便捷通道，只适用于4条/5条的\\"转用\\"场景，3条（继续做农地用的权利移转）没有这个通道","ja":"市街化区域内の届出による許可不要の特例は4条・5条の「転用」場面にのみ適用され、3条（農地のままの権利移転）には適用されない"},{"zh":"2016年农地法改正后，农地转用许可统一由都道府县知事审批，不再区分面积、不需要农林水产大臣审批","ja":"2016年の農地法改正後、農地転用の許可は面積にかかわらず都道府県知事が行い、農林水産大臣の許可は不要となった"},{"zh":"设定抵押权不涉及农地使用收益权的转移，不需要3条或5条的许可","ja":"抵当権の設定は農地の使用収益権の移転を伴わないため、3条・5条の許可は不要"},{"zh":"因继承取得农地，只需\\"尽快\\"向农业委员会报备，不需要许可、也没有具体期限天数","ja":"相続により農地の所有権を取得した者は、遅滞なく農業委員会に届け出ればよく、許可は不要で具体的な期限日数もない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"第3条没有市街化区域报备简化通道，只有第4/5条（转用）才有——容易把\\"权利移转\\"和\\"转用\\"两种场景的规则搞混。","ja":"3条には市街化区域の届出特例はない——4条・5条（転用）のみに適用される。「権利移転」と「転用」の場面を混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t20', '{"id":"t20","tag":"印纸税","title":{"zh":"印纸税课税判断核心规则","ja":"印紙税の課税判断の重要ルール"},"source":"令和4年 問23","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"覚书即使注明\\"以后要另签正式合同\\"，只要证明了契约成立，依然要课印纸税，不能靠\\"以后补合同\\"免税","ja":"覚書に「後日正式な契約書を作成する」旨を記載していても、契約の成立を証するものであれば課税文書に当たり、印紙税を免れない"},{"zh":"一份契约书同时记载多项不动产转让金额，即使分开写，也要合计作为记载金额","ja":"一の契約書に複数の不動産譲渡金額を区分して記載した場合でも、印紙税の記載金額は合算した額となる"},{"zh":"变更赁贷借契约期间等\\"内容变更\\"的覚书本身就是课税文书","ja":"賃貸借契約の期間を変更する等、契約内容の変更を証する覚書自体が課税文書に当たる"},{"zh":"停车场契约若是设备利用契约（非纯粹更地土地赁借），跟建筑物赁贷借一样不课印纸税","ja":"駐車場の契約が設備の利用を目的とするもの（純然たる土地の賃貸借ではない）であれば、建物の賃貸借と同様に印紙税は課されない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"覚书不能靠\\"以后补正式合同\\"逃避课税；多项金额记载在同一契约书要合计计算，不能分开各算各的。","ja":"覚書は「後日正式契約を作成する」ことを理由に課税を免れることはできない。複数の金額が同一契約書に記載されている場合は合算して計算し、個別に計算してはならない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t21', '{"id":"t21","tag":"不动产取得税","title":{"zh":"不动产取得税四大易错点","ja":"不動産取得税の4つの重要ポイント"},"source":"平成30年 問24","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"征收方式","ja":"徴収方法"},{"zh":"普通征收（知事发纳税通知书），不是申告纳付","ja":"普通徴収（知事が納税通知書を発行）——申告納付ではない"}],[{"zh":"改建增值","ja":"改築による価格増加"},{"zh":"改建导致房屋价值增加的部分照样课税","ja":"改築により家屋の価格が増加した部分も課税対象となる"}],[{"zh":"继承取得","ja":"相続による取得"},{"zh":"属于形式性移转，不课不动产取得税","ja":"形式的な移転として不動産取得税は課されない"}],[{"zh":"免税点","ja":"免税点"},{"zh":"看的是\\"金额\\"（土地10万/新建家屋23万/其他家屋12万日元），不是\\"面积\\"","ja":"「金額」（土地10万円・新築家屋23万円・その他家屋12万円）による——「面積」ではない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"免税点容易被误当成\\"面积标准\\"，实际是\\"金额标准\\"——不动产取得税的四个考点经常混在一起出题，要逐一核对。","ja":"免税点を「面積基準」と誤解しやすいが、実際は「金額基準」である——不動産取得税の4つの論点は一緒に出題されやすいので一つずつ確認する。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t22', '{"id":"t22","tag":"宅建业法・报酬","title":{"zh":"权利金视为代金额计算报酬的规则","ja":"権利金を売買代金とみなして報酬を算出するルール"},"source":"平成30年 問30","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"店铺用建筑物贷借报酬合计上限是月租1个月（消费税含），是双方合计不是各自","ja":"店舗用建物の貸借における報酬の合計限度額は借賃1か月分（消費税込み）——貸主・借主それぞれではなく双方合計での上限"},{"zh":"权利金视为代金额计算报酬，只适用于\\"居住用以外\\"的建筑物","ja":"権利金を売買代金の額とみなして報酬を算出する規定は「居住用以外」の建物にのみ適用される"},{"zh":"业者主动打的广告即使促成契约成立，也不能另外收广告费——只有依赖者要求打的广告才能额外收","ja":"業者が依頼者からの依頼なく行った広告は、契約成立に寄与しても別途広告料金を請求できない——依頼者の依頼による広告のみ請求可能"},{"zh":"定期建物赁贷借到期后紧接着的\\"再契约\\"，本质仍是新赁贷借合同，报酬限额规定依然适用","ja":"定期建物賃貸借の期間満了直後の「再契約」も実質的には新たな賃貸借契約であり、報酬限度額の規定が適用される"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"续约/再契约\\"不是报酬限额的例外——不能借续约名义收取超额报酬。","ja":"「更新・再契約」は報酬限度額の例外ではない——更新・再契約を名目に上限を超える報酬を受け取ることはできない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t23', '{"id":"t23","tag":"宅建业法・37条书面","title":{"zh":"37条书面的必要记载事项","ja":"37条書面の必要的記載事項"},"source":"令和3年12月 問26","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"买卖契约中，\\"引渡时期\\"和\\"移转登记申请时期\\"都是必要记载事项，不是择一记载","ja":"売買契約では「引渡しの時期」と「移転登記の申請の時期」の両方が必要的記載事項——いずれか一方を選ぶのではない"},{"zh":"\\"建筑物构造耐力上主要部分状况的双方确认事项\\"只适用于买卖契约，不适用于贷借契约","ja":"「建物の構造耐力上主要な部分等の状況について当事者双方が確認した事項」は売買契約にのみ適用され、貸借契約には適用されない"},{"zh":"贷借契约中若有\\"租金以外金钱\\"的授受约定，其金额/时期/目的都要记载在37条书面里","ja":"貸借契約で借賃以外の金銭の授受の定めがあるときは、その額・授受の時期・授受の目的をすべて37条書面に記載しなければならない"},{"zh":"37条书面只需宅建士记名，不需要像35条书面那样由宅建士说明内容","ja":"37条書面は宅地建物取引士の記名のみが必要で、35条書面のような宅建士による説明は不要"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"37条书面**不需要**宅建士说明内容，这是和35条书面最大的区别——考试常混淆两种书面的义务范围。","ja":"37条書面は宅建士による説明が不要な点が35条書面との最大の違い——両書面の義務範囲を混同しやすいので要注意。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t24', '{"id":"t24","tag":"宅建业法・营业保证金","title":{"zh":"营业保证金供托与吊销执照流程","ja":"営業保証金の供託と免許取消しの流れ"},"source":"令和2年12月 問33","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"新设从事务所时，营业保证金依然要供托到\\"主事务所\\"附近的供托所，不是从事务所附近","ja":"従たる事務所を新設したときも、営業保証金は「主たる事務所」の最寄りの供託所に供託する——従たる事務所の最寄りではない"},{"zh":"主事务所移转导致供托所变更时，应向\\"新的\\"主事务所最寄的供托所申请保管替，不是向从前的供托所申请","ja":"主たる事務所の移転により最寄りの供託所が変わった場合、「新しい」主たる事務所の最寄りの供託所に保管替えを請求する——従前の供託所にではない"},{"zh":"执照到期想取回营业保证金，原则上依然需要先做公告","ja":"免許の有効期間満了により営業保証金を取り戻す場合も、原則として還付請求権者への公告が必要"},{"zh":"\\"3个月不申报→催告→催告后1个月不申报→可吊销执照\\"是标准处置流程","ja":"「免許取得後3か月以内に届出がない→催告→催告到達後1か月以内に届出なし→免許取消し可能」が標準的な流れ"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"无论是新设从事务所还是主事务所移转，供托所始终以\\"主事务所\\"为基准——这是营业保证金制度最容易踩坑的细节。","ja":"従たる事務所の新設でも主たる事務所の移転でも、供託所は常に「主たる事務所」を基準とする——営業保証金制度で最も間違えやすい細部。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t25', '{"id":"t25","tag":"宅建业法・35条书面","title":{"zh":"35条书面（重要事项说明）核心考点","ja":"35条書面（重要事項説明）の重要ポイント"},"source":"平成25年 問30","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"买主是宅建业者时，重要事项的\\"说明\\"可以省略，但\\"35条书面的交付\\"义务不能省略","ja":"買主が宅地建物取引業者である場合、重要事項説明は省略できるが、35条書面の「交付」義務は省略できない"},{"zh":"宅建士没有请求也要提示宅建士证，违反的处罚是\\"10万日元以下过料\\"（行政罚），不是\\"罚金\\"（刑罚）","ja":"宅建士は請求がなくても宅建士証を提示しなければならず、違反時は「10万円以下の過料」（行政罰）——「罰金」（刑罰）ではない"},{"zh":"建筑物贷借媒介中，若建筑物是昭和56年5月31日以前新建且做过耐震诊断，必须说明诊断内容，不因是贷借而免除","ja":"建物の貸借の媒介でも、昭和56年5月31日以前に新築され耐震診断を受けているときは、その内容を説明しなければならない——貸借だからといって免除されない"},{"zh":"津波灾害警戒区域说明义务，不管买卖还是贷借都必须履行","ja":"津波災害警戒区域内にある旨の説明義務は、売買・貸借を問わず適用される"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"买主是业者：说明可省、交付不可省，两者容易被出题者故意说反。","ja":"買主が業者の場合：説明は省略可、交付は省略不可——両者を逆にした出題が多いので要注意。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t26', '{"id":"t26","tag":"宅建业法・8种限制","title":{"zh":"手付金等保全措置核心规则","ja":"手付金等の保全措置の重要ルール"},"source":"平成25年 問40","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"未完成物件的保全措施方式","ja":"未完成物件における保全措置の方法"},{"zh":"只有\\"保证\\"和\\"保险\\"，不包括\\"指定保管机构保管\\"","ja":"「保証」と「保険」のみ——「指定保管機関による保管」は不可（完成物件のみ可）"}],[{"zh":"保全措施义务的主体","ja":"保全措置義務の主体"},{"zh":"专属于卖主业者本人，媒介/代理业者不负此义务","ja":"自ら売主となる業者本人に専属——媒介・代理業者は義務を負わない"}],[{"zh":"买主是宅建业者时","ja":"買主が宅地建物取引業者である場合"},{"zh":"8种限制（含保全措施）全部不适用（业者间交易）","ja":"8種制限（保全措置を含む）はすべて適用されない（業者間取引）"}],[{"zh":"判断是否需要保全措施","ja":"保全措置の要否の判断"},{"zh":"看\\"手付金+中间金\\"累计额，不是只看手付金单独金额","ja":"「手付金＋中間金」の累計額で判断する——手付金単体の金額ではない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"手付金本身不超5%就不用做保全措施\\"是错的——要看手付金加中间金的累计额是否超过门槛。","ja":"「手付金自体が5％を超えなければ保全措置は不要」というのは誤り——手付金と中間金を合算した額が基準を超えるかどうかで判断する。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t27', '{"id":"t27","tag":"住宅瑕疵担保履行法","title":{"zh":"住宅瑕疵担保履行法核心考点","ja":"住宅瑕疵担保履行法の重要ポイント"},"source":"平成28年 問45","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"合计户数换算门槛","ja":"合計戸数の算定基準"},{"zh":"床面积55㎡以下的住宅2户算1户，不是100㎡以下","ja":"床面積55㎡以下の住宅は2戸をもって1戸と数える——100㎡以下ではない"}],[{"zh":"免许权者届出期限","ja":"免許権者への届出期限"},{"zh":"以每年3月31日\\"基准日\\"起算3周内，不是从引渡日起算","ja":"毎年3月31日の「基準日」から3週間以内——引渡しの日からではない"}],[{"zh":"供托所所在地说明的时点","ja":"供託所の所在地等の説明時期"},{"zh":"必须在\\"売买契约缔结前\\"完成，不能拖到引渡时","ja":"「売買契約を締結するまで」に行わなければならない——引渡し時まで待つのは不可"}],[{"zh":"保险契约有效期与转卖的关系","ja":"保険契約の有効期間と転売の関係"},{"zh":"引渡后10年以上持续有效，转卖不是解约事由","ja":"引渡し時から10年以上有効でなければならず、転売は解除事由にならない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"55㎡\\"和\\"100㎡\\"、\\"基准日起算\\"和\\"引渡日起算\\"是这道题最典型的两组数字/时点混淆陷阱。","ja":"「55㎡」と「100㎡」、「基準日起算」と「引渡し日起算」——この2組の数字・起算点の混同が典型的な出題パターン。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t28', '{"id":"t28","tag":"民法","title":{"zh":"配偶者居住权","ja":"配偶者居住権"},"source":"令和5年 問7","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"存续期间","ja":"存続期間"},{"zh":"原则终身，协议/遗言/家裁审判有别段约定时从其约定，未约定不是\\"20年\\"","ja":"原則として配偶者の終身の間——遺産分割協議・遺言・家庭裁判所の審判に別段の定めがあればそれによる（定めがない場合を「20年」とするのは誤り）"}],[{"zh":"改建/增建/出租等","ja":"改築・増築・第三者への使用収益"},{"zh":"必须获得居住建筑物所有者的承诺","ja":"居住建物の所有者の承諾が必要"}],[{"zh":"设定登记","ja":"設定登記"},{"zh":"所有者对配偶者负有使其具备登记的义务","ja":"建物所有者は配偶者に対し、配偶者居住権の設定登記を備えさせる義務を負う"}],[{"zh":"通常必要费","ja":"通常の必要費"},{"zh":"由配偶者自己负担，不是所有者负担","ja":"配偶者が負担する——建物所有者の負担ではない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"存续期间没约定时默认\\"终身\\"，不是\\"20年\\"——20年是最初立法讨论中出现过的数字，容易被出题者拿来混淆。","ja":"存続期間の定めがない場合はデフォルトで「終身」——「20年」ではない。「20年」は立法過程で議論された数字であり、混同を誘う出題が多い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t29', '{"id":"t29","tag":"民法","title":{"zh":"未成年人的权利能力、行为能力与利益相反行为","ja":"未成年者の権利能力・行為能力と利益相反行為"},"source":"平成25年 問2","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"权利能力的取得","ja":"権利能力の取得"},{"zh":"出生时当然取得（民法3条1项），乳幼儿也能所有不动产","ja":"出生と同時に当然に取得する（民法3条1項）——乳幼児であっても不動産を所有できる"}],[{"zh":"被许可营业的未成年人","ja":"営業を許された未成年者"},{"zh":"在许可的营业范围内，与成年人有同一行为能力（民法6条1项），单独缔结契约有效","ja":"許された営業の範囲内で成年者と同一の行為能力を有する（民法6条1項）——単独で契約しても有効"}],[{"zh":"成年年龄与婚姻适齢","ja":"成年年齢と婚姻適齢"},{"zh":"均为18岁（民法4条、731条），18岁结婚不需父母同意","ja":"いずれも18歳（民法4条・731条）——18歳になれば父母の同意なく婚姻できる"}],[{"zh":"亲权者代理数名子女处理利益相冲突事务","ja":"親権者が利益相反する複数の子を代理する場合"},{"zh":"属于利益相反行为，须请求家庭裁判所选任特别代理人（民法826条2项），未经有效追认则无效","ja":"利益相反行為に当たり、家庭裁判所に特別代理人の選任を請求しなければならない（民法826条2項）——有効な追認がなければ無効"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"权利能力（出生即有）和行为能力（需达到一定条件）是两回事，考试常常故意混用制造陷阱；亲权者代理数名子女处理共同继承的遗产分割，是典型的\\"利益相反行为\\"场景，必须靠特别代理人，不能靠亲权者自己\\"一碗水端平\\"。","ja":"権利能力（出生と同時に取得）と行為能力（一定の要件が必要）は別概念であり、混同させる出題が多い。親権者が複数の子を代理して共同相続の遺産分割を行う場面は典型的な「利益相反行為」であり、親権者自身の裁量では処理できず、特別代理人の選任が必要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t30', '{"id":"t30","tag":"区分所有法","title":{"zh":"区分所有法・管理者的诉讼与集会决议门槛","ja":"区分所有法・管理者の訴訟と集会決議の要件"},"source":"令和4年 問13","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"管理者依集会决议提起诉讼","ja":"集会の決議に基づき管理者が訴訟を提起する場合"},{"zh":"不需另行通知各区分所有者","ja":"各区分所有者への通知は不要"}],[{"zh":"管理者依规约提起诉讼","ja":"規約に基づき管理者が訴訟を提起する場合"},{"zh":"必须无迟延通知各区分所有者","ja":"遅滞なく各区分所有者に通知しなければならない"}],[{"zh":"集会召集权门槛（无管理者时）","ja":"集会招集権の要件（管理者不在時）"},{"zh":"区分所有者及议决权各1/5以上，规约可以下调，不能上调","ja":"区分所有者及び議決権の各5分の1以上——規約で減じることはできるが増やすことはできない"}],[{"zh":"管理者选任","ja":"管理者の選任"},{"zh":"普通决议（出席者及议决权各过半数）","ja":"普通決議（出席者及び議決権の各過半数）"}],[{"zh":"管理组合法人化","ja":"管理組合の法人化"},{"zh":"特别决议（出席者及议决权各3/4以上）+登记","ja":"特別決議（出席者及び議決権の各4分の3以上）＋登記"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"集会决议提起诉讼\\"和\\"规约授权提起诉讼\\"的通知义务正好相反——决议不用通知（大家在场都知道），规约要通知（大家不一定知道），考试常把这一点说反。","ja":"「集会の決議による訴訟提起」と「規約による訴訟提起」の通知義務は正反対——決議の場合は不要（出席者は知っている）、規約の場合は必要（知らない可能性がある）。この逆転が典型的な出題パターン。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t31', '{"id":"t31","tag":"民法","title":{"zh":"意思能力・公序良俗・诈欺强迫・他人物买卖","ja":"意思能力・公序良俗・詐欺強迫・他人物売買"},"source":"令和6年 問1","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"意思能力欠缺","ja":"意思能力の欠如"},{"zh":"法律行为无效（民法3条の2），与是否未成年、是否被许可营业无关","ja":"法律行為は無効（民法3条の2）——未成年か、営業許可の有無かとは無関係"}],[{"zh":"公序良俗违反","ja":"公序良俗違反"},{"zh":"绝对无效（民法90条），不能靠合意或追认补正","ja":"絶対的に無効（民法90条）——合意や追認によって有効にはならない"}],[{"zh":"诈欺 vs 强迫","ja":"詐欺と強迫"},{"zh":"两者都是\\"可撤销\\"，撤销后溯及无效——规则一致","ja":"いずれも「取消し可能」であり、取消し後に遡って無効となる——両者の効力構造は同一"}],[{"zh":"他人物买卖","ja":"他人物売買"},{"zh":"契约本身有效（民法561条），出卖人负有取得标的物再移转的义务","ja":"契約自体は有効（民法561条）——売主は目的物を取得して買主に移転する義務を負う"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"意思能力\\"和\\"行为能力\\"是两条不同的线，容易被出题者故意混在一起；\\"强迫=不用撤销当然无效\\"是常见错误说法，实际上诈欺和强迫规则完全一致，都要撤销才溯及无效。","ja":"「意思能力」と「行為能力」は別の概念であり、混同させる出題が多い。「強迫は取消し不要で当然無効」というのはよくある誤り——詐欺と強迫は効力構造が同一で、いずれも取消しによって遡及的に無効となる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t32', '{"id":"t32","tag":"民法","title":{"zh":"抵当权 vs 根抵当权","ja":"抵当権と根抵当権"},"source":"平成26年 問4","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"抵当权","ja":"抵当権"},{"zh":"根抵当权（元本确定前）","ja":"根抵当権（元本確定前）"}],"rows":[[{"zh":"被担保债权","ja":"被担保債権"},{"zh":"必须特定","ja":"特定しなければならない"},{"zh":"限定范围内的不特定债权，极度额为限","ja":"一定の範囲内の不特定債権——極度額を限度とする"}],[{"zh":"对抗第三人","ja":"第三者対抗要件"},{"zh":"登记即可","ja":"登記のみ"},{"zh":"登记即可（不需债务人承诺）","ja":"登記のみ（債務者の承諾は不要）"}],[{"zh":"物上保证人的催告抗辩权","ja":"物上保証人の催告の抗弁権"},{"zh":"没有","ja":"なし"},{"zh":"同样没有","ja":"同様になし"}],[{"zh":"顺位让与","ja":"順位の譲渡"},{"zh":"可以（民法376条）","ja":"可能（民法376条）"},{"zh":"不可以","ja":"不可"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"根抵当权的不特定债权是\\"限定范围内\\"的，不是\\"来者不拒\\"；顺位让与是普通抵当权独有的处分方式，元本确定前的根抵当权做不到。","ja":"根抵当権の不特定債権は「一定の範囲内」のものに限られ、無制限ではない。順位の譲渡は普通抵当権に特有の処分方法であり、元本確定前の根抵当権にはできない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t33', '{"id":"t33","tag":"民法","title":{"zh":"连带债务・绝对效与相对效","ja":"連帯債務・絶対効と相対効"},"source":"令和7年 問9","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"事由","ja":"事由"},{"zh":"效力","ja":"効力"}],"rows":[[{"zh":"履行请求","ja":"履行の請求"},{"zh":"相对效（新民法改正后，不影响其他人）","ja":"相対効（改正民法により他の連帯債務者に影響しない）"}],[{"zh":"混同","ja":"混同"},{"zh":"绝对效","ja":"絶対効"}],[{"zh":"相殺","ja":"相殺"},{"zh":"绝对效","ja":"絶対効"}],[{"zh":"更改","ja":"更改"},{"zh":"绝对效","ja":"絶対効"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"旧民法下\\"履行请求\\"是绝对效，新民法改成了相对效——这个新旧法变化是最常考的陷阱，容易凭旧知识答错。","ja":"旧民法では「履行の請求」は絶対効だったが、改正民法で相対効に変更された——この新旧法の変化が最も出題されやすい落とし穴であり、旧知識のまま答えると誤る。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t34', '{"id":"t34","tag":"民法","title":{"zh":"承揽人的修理费用与出租人・承租人关系","ja":"請負人の修理費用と賃貸人・賃借人の関係"},"source":"令和7年 問7","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"承揽人（C）和出租人（A）没有直接契约关系，不能援引\\"事务管理\\"向A请求费用","ja":"請負人（C）と賃貸人（A）の間に直接の契約関係はなく、「事務管理」を根拠にAへ費用を請求することはできない"},{"zh":"承租人的\\"必要费\\"可以立即请求偿还，不需等契约终了（跟\\"有益费\\"不同）","ja":"賃借人の「必要費」は直ちに償還請求できる——契約終了を待つ必要はない（「有益費」とは異なる）"},{"zh":"不动产工事先取特权只保护\\"增值\\"部分的工程，不保护单纯\\"保存性\\"修理","ja":"不動産工事の先取特権は「価格の増加」部分にのみ及び、単なる保存的な修理には及ばない"},{"zh":"契约里本该由承租人负担的修理费，出租人没有不当得利，承揽人不能向出租人主张不当得利返还","ja":"契約上もともと賃借人が負担すべき修理費であれば、賃貸人に不当利得は生じず、請負人は賃貸人に不当利得返還を請求できない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"必要费\\"和\\"有益费\\"请求偿还的时点不同：必要费立即可以要，有益费要等到契约终了——两者极易混淆。","ja":"「必要費」と「有益費」では償還請求できる時期が異なる——必要費は直ちに請求可能だが、有益費は契約終了時まで待つ必要がある。両者は混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t35', '{"id":"t35","tag":"民法","title":{"zh":"代袭继承——直系卑属 vs 兄弟姐妹系","ja":"代襲相続——直系卑属系と兄弟姉妹系"},"source":"令和2年10月 問8","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"继承线","ja":"相続の系統"},{"zh":"代袭规则","ja":"代襲のルール"}],"rows":[[{"zh":"子女（直系卑属）","ja":"子（直系卑属）"},{"zh":"没有代数限制，可以一直再代袭（子→孙→曾孙……）","ja":"代数の制限なし——何代でも再代襲できる（子→孫→曾孫……）"}],[{"zh":"兄弟姐妹","ja":"兄弟姉妹"},{"zh":"只能代袭一代（到甥/侄为止），不能再代袭给甥侄的子女","ja":"代襲は一代限り（甥・姪まで）——甥・姪の子には再代襲されない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"两条继承线的代袭规则不对称，是出题重灾区：子女这条线可以无限再代袭，兄弟姐妹这条线只能代袭一次。","ja":"2つの相続系統の代襲ルールは非対称であり、出題されやすい——子の系統は無制限に再代襲できるが、兄弟姉妹の系統は一代限り。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t36', '{"id":"t36","tag":"借地借家法","title":{"zh":"建筑物赁贷借契约综合——更新・解约・对抗・造作买取","ja":"建物賃貸借契約総合——更新・解約・対抗・造作買取"},"source":"平成27年 問11","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"法定更新后的期间","ja":"法定更新後の期間"},{"zh":"变成\\"没有期限\\"，不是延续原期限","ja":"「期間の定めのない」契約となる——従前の期間を引き継がない"}],[{"zh":"无期限契约的解约通知","ja":"期間の定めのない契約の解約申入れ"},{"zh":"房东6个月后生效，房客3个月后生效（不对称）","ja":"貸主からは6か月後、借主からは3か月後に終了（非対称）"}],[{"zh":"对抗要件","ja":"対抗要件"},{"zh":"\\"契约谁先签\\"不等于\\"对抗力谁先有\\"，要看是否登记/受领引渡","ja":"「契約締結の先後」＝「対抗力の先後」ではない——登記又は引渡しの有無で判断"}],[{"zh":"造作买取请求权","ja":"造作買取請求権"},{"zh":"只在期满/解约终了时能用，因欠租（债务不履行）解除时不能用","ja":"期間満了・解約申入れによる終了時のみ行使可——賃料不払等の債務不履行解除では行使不可"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"房东/房客解约通知期限不对称（6个月/3个月）；造作买取请求权因\\"终了原因\\"而定，欠租解除时用不了，容易被忽略这个前提条件。","ja":"貸主・借主の解約申入れ期間は非対称（6か月／3か月）。造作買取請求権は「終了原因」によって可否が決まり、賃料不払による解除では行使できないという前提条件を見落としやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t37', '{"id":"t37","tag":"不动产登记法","title":{"zh":"表示登记的变更申请义务——床面积 vs 住所（含2026年法改正）","ja":"表示登記の変更申請義務——床面積と住所（2026年法改正を含む）"},"source":"平成30年 問14","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"变更事项","ja":"変更事項"},{"zh":"申请义务与期限","ja":"申請義務と期限"}],"rows":[[{"zh":"建筑物床面积变更","ja":"建物の床面積の変更"},{"zh":"强制申请，变更之日起1个月内","ja":"申請義務あり——変更の日から1か月以内"}],[{"zh":"所有权登记名义人住所变更（2026年4月前）","ja":"所有権登記名義人の住所変更（2026年4月改正前）"},{"zh":"没有强制义务，属任意申请","ja":"申請義務なし——任意申請事項だった"}],[{"zh":"所有权登记名义人住所变更（2026年4月起，现行法）","ja":"所有権登記名義人の住所変更（2026年4月以降・現行法）"},{"zh":"变成强制义务，2年内必须申请，违反可处5万日元以下过料","ja":"申請義務化——2年以内に申請必須、違反時は5万円以下の過料（不動産登記法76条の5・164条2項）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"这道题原是平成30年（2018年）的题，当年答案\\"住所变更没有强制期限\\"已经过时——2026年4月起住所变更登记也义务化了，但期限是2年，不是像床面积那样的1个月，备考时要用最新法规版本记忆。","ja":"この問題は平成30年（2018年）出題当初は「住所変更に申請義務なし」が正解の根拠だったが、2026年4月以降は住所変更登記も義務化された。ただし期限は床面積変更の「1か月」とは異なり「2年」である点に注意——最新の法改正内容で覚える必要がある。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t38', '{"id":"t38","tag":"国土利用计画法","title":{"zh":"事后申报制——面积门槛・游休土地・一团土地・劝告","ja":"事後届出制——面積要件・遊休土地・一団の土地・勧告"},"source":"令和3年12月 問22","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"地上权/赁借权设定契约","ja":"地上権・賃借権の設定契約"},{"zh":"有对价（权利金）才算\\"土地买卖等契约\\"","ja":"対価（権利金）があって初めて「土地売買等の契約」に該当"}],[{"zh":"都市计画区域外面积门槛","ja":"都市計画区域外の面積要件"},{"zh":"1万㎡以上","ja":"10,000㎡以上"}],[{"zh":"游休土地利用计划申报期限","ja":"遊休土地の利用計画の届出期限"},{"zh":"通知之日起6周内，不是1个月","ja":"通知の日から6週間以内——1か月ではない"}],[{"zh":"分割顺次购买（买入一团土地）","ja":"分割して順次購入（買いの一団の土地）"},{"zh":"按计划整体判断，不能靠拆分规避申报门槛","ja":"計画に従った一体のものとして判断——分割による届出回避は不可"}],[{"zh":"知事对不遵从劝告者的公表","ja":"勧告に従わない者への公表"},{"zh":"\\"可以\\"公表，不是\\"必须\\"公表","ja":"公表することが「できる」——「しなければならない」ではない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"游休土地申报期限（6周）和一般契约事后申报期限（2周）容易混淆；知事的\\"劝告\\"和\\"公表\\"都是裁量权（可以做），不是强制义务，选项常把\\"可以\\"偷换成\\"必须\\"。","ja":"遊休土地の届出期限（6週間）と通常の事後届出期限（2週間）は混同しやすい。知事の「勧告」も「公表」も裁量権（できる）であり義務ではない——「できる」を「しなければならない」にすり替える出題が多い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t39', '{"id":"t39","tag":"都市计画法","title":{"zh":"开发许可の面积门槛——制度性豁免与地域别差异","ja":"開発許可の面積要件——制度的な適用除外と地域差"},"source":"令和3年10月 問16","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"区域/类型","ja":"区域・類型"},{"zh":"面积门槛/规则","ja":"面積要件・ルール"}],"rows":[[{"zh":"公益上必要建筑物（如公园设施）","ja":"公益上必要な建築物（公園施設等）"},{"zh":"不管区域和规模，一律不需要许可","ja":"区域・規模を問わず許可不要"}],[{"zh":"土地区划整理事业实施的开发","ja":"土地区画整理事業の施行として行う開発"},{"zh":"不管区域和规模，一律不需要许可","ja":"区域・規模を問わず許可不要"}],[{"zh":"普通市街化区域","ja":"通常の市街化区域"},{"zh":"1,000㎡以上需要许可","ja":"1,000㎡以上で許可必要"}],[{"zh":"三大都市圏既成市街地等特定市街化区域","ja":"三大都市圏の既成市街地等の特定市街化区域"},{"zh":"门槛更严格，500㎡以上需要许可","ja":"より厳格——500㎡以上で許可必要"}],[{"zh":"准都市计画区域","ja":"準都市計画区域"},{"zh":"3,000㎡以上需要许可","ja":"3,000㎡以上で許可必要"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"三大都市圏既成市街地的门槛（500㎡）比普通市街化区域（1,000㎡）更严格——数字更小代表管得更严，容易被误以为是打字错误而记反。","ja":"三大都市圏の既成市街地の面積要件（500㎡）は通常の市街化区域（1,000㎡）より厳しい——数字が小さいほど規制が厳しいという点を誤って逆に覚えやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t40', '{"id":"t40","tag":"宅建业法","title":{"zh":"契约不适合担保责任特约的合法边界（含复数解真题）","ja":"契約不適合担保責任の特約の適法範囲（複数解の実例含む）"},"source":"令和2年10月 問42","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"宅建业法允许的唯一例外特约","ja":"宅建業法が認める唯一の例外特約"},{"zh":"把\\"通知期间\\"定为引渡后2年以上","ja":"「通知期間」を引渡しから2年以上とすること"}],[{"zh":"把\\"消灭时效期间\\"另行约定（如知道起2年）","ja":"「消滅時効期間」を別途定める（例：知った時から2年）"},{"zh":"无效——这不是被允许的例外","ja":"無効——認められた例外に当たらない"}],[{"zh":"特约\\"完全不负责任\\"无效后的退回规则","ja":"「一切責任を負わない」特約が無効となった後の原則適用"},{"zh":"退回民法：客观时效10年（引渡起算）、主观时效5年（知道起算）","ja":"民法の原則に戻る：客観的消滅時効10年（引渡しから）・主観的消滅時効5年（知った時から）"}],[{"zh":"8种制限的适用前提","ja":"8種制限の適用前提"},{"zh":"买方必须是非宅建业者，业者间交易完全不适用","ja":"買主が宅建業者でないことが前提——業者間取引には一切適用されない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"通知期间\\"和\\"消灭时效期间\\"是两个不同概念，宅建业法只允许对\\"通知期间\\"做例外约定；特约无效后不能想当然套用\\"2年\\"这个数字，要退回到真正的民法时效规则（10年/5年）。本题也是提醒：真题偶尔会出现官方公认的复数解，遇到类似情况要以官方公告为准。","ja":"「通知期間」と「消滅時効期間」は別概念であり、宅建業法が例外を認めるのは「通知期間」のみ。特約が無効になった後、安易に「2年」という数字に飛びつかず、本来の民法上の時効ルール（10年・5年）に戻って考える必要がある。また本問は、公式に複数解が認定された実例でもあり、そうしたケースでは公式発表を優先する。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t41', '{"id":"t41","tag":"土地区画整理法","title":{"zh":"换地处分、换地计划保留地与假换地指定的同意规则","ja":"換地処分・換地計画の保留地・仮換地指定の同意ルール"},"source":"平成25年 問20","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"换地处分的时点","ja":"換地処分の時期"},{"zh":"原则全部工程完工后，但基准/规约/章程有约定可提前","ja":"原則は工事完了後——基準・規約・規程に別段の定めがあれば工事完了前でも可"}],[{"zh":"换地处分的方式","ja":"換地処分の方法"},{"zh":"施行者\\"通知\\"权利人，不是公告","ja":"施行者が権利者に「通知」する——「公告」ではない"}],[{"zh":"个人施行者设定保留地","ja":"個人施行者による保留地の設定"},{"zh":"需从前宅地所有者同意，不是审议会同意","ja":"従前の宅地の所有者の同意が必要——審議会の同意ではない"}],[{"zh":"个人施行者指定假换地","ja":"個人施行者による仮換地の指定"},{"zh":"需从前宅地所有者+假换地宅地所有者双方同意","ja":"従前の宅地の所有者と仮換地となるべき宅地の所有者の双方の同意が必要"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"换地处分是\\"通知\\"不是\\"公告\\"；假换地指定要双方同意，容易被出题者只提一方来混淆。","ja":"換地処分は「通知」であり「公告」ではない。仮換地の指定は双方の同意が必要であり、一方のみを挙げて混同させる出題が多い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t42', '{"id":"t42","tag":"登録免许税","title":{"zh":"住宅用家屋所有权移转登记的税率减轻措施","ja":"住宅用家屋の所有権移転登記に係る登録免許税の軽減措置"},"source":"平成26年 問23","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"适用范围","ja":"適用範囲"},{"zh":"只覆盖住宅家屋本体，不含所在土地","ja":"住宅用家屋本体のみ——敷地は対象外"}],[{"zh":"用途要求","ja":"用途要件"},{"zh":"取得人自己居住，公司社宅不适用","ja":"取得者自身の居住用に限る——社宅は不可"}],[{"zh":"适用次数","ja":"適用回数"},{"zh":"无限制，只要每次满足要件即可反复适用","ja":"回数制限なし——要件を満たせば繰り返し適用可"}],[{"zh":"床面积要求","ja":"床面積要件"},{"zh":"50㎡以上，独立门槛，不因耐火/建筑年数达标而豁免","ja":"50㎡以上——独立要件であり、耐火性能や築年数の要件を満たしても免除されない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"床面积50㎡是独立门槛，跟耐火建筑物/建筑年数要件互不替代，四个条件全满足才能适用。","ja":"床面積50㎡は独立した要件であり、耐火建築物・築年数要件とは代替関係にない——4つの要件をすべて満たして初めて適用される。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t43', '{"id":"t43","tag":"不动产取得税","title":{"zh":"不动产取得税四大易错点（免税点/控除/课税标准/みなし取得）","ja":"不動産取得税の4つの重要ポイント（免税点・控除・課税標準・みなし取得）"},"source":"平成24年 問24","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"免税点","ja":"免税点"},{"zh":"土地16万/建筑家屋66万/其他家屋34万日元","ja":"土地16万円／建築家屋66万円／その他家屋34万円"}],[{"zh":"新住宅1,200万控除","ja":"新築住宅1,200万円控除"},{"zh":"床面积40㎡～240㎡区间才适用","ja":"床面積40㎡～240㎡の範囲でのみ適用"}],[{"zh":"宅地课税标准","ja":"宅地の課税標準"},{"zh":"宅地价格的1/2","ja":"宅地の価格の2分の1"}],[{"zh":"家屋みなし取得","ja":"家屋のみなし取得"},{"zh":"新建后6个月未使用/转让即视为取得","ja":"新築から6か月経過して未使用・未譲渡なら取得とみなす"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"免税点三个数字（16万/66万/34万）容易被相互调换；みなし取得的\\"6个月\\"容易被换成\\"2年\\"或\\"3年\\"来混淆。","ja":"免税点の3つの数字（16万・66万・34万）は入れ替えられやすい。みなし取得の「6か月」は「2年」や「3年」に置き換えて混同させる出題が多い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t44', '{"id":"t44","tag":"不动产鉴定评价基准","title":{"zh":"最有効使用の原則 vs 適合の原則","ja":"最有効使用の原則と適合の原則"},"source":"令和6年 問25","sections":[{"heading":"两个原则的区分","blocks":[{"type":"table","headers":[{"zh":"原则","ja":"原則"},{"zh":"定义","ja":"定義"}],"rows":[[{"zh":"最有効使用の原則","ja":"最有効使用の原則"},{"zh":"以效用发挥到最高程度的使用方式为前提把握价格标准","ja":"効用が最高度に発揮される使用を前提として価格を把握する基準"}],[{"zh":"適合の原則","ja":"適合の原則"},{"zh":"不动产要适合周边环境，收益性/舒适性才能最大化","ja":"不動産がその環境に適合することで収益性・快適性が最大限発揮される"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"两个原则的定义常被张冠李戴地互换，看到\\"效用最高度发挥\\"要对应\\"最有效使用\\"，不是\\"适合\\"。","ja":"2つの原則の定義は入れ替えて出題されやすい——「効用が最高度に発揮される」という記述は「最有効使用」に対応し、「適合」ではない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t45', '{"id":"t45","tag":"宅建业法","title":{"zh":"复数业者报酬合计上限的计算规则","ja":"複数業者が関与する場合の報酬合計限度額の計算ルール"},"source":"平成25年 問37","sections":[{"heading":"计算步骤","blocks":[{"type":"list","style":"ordered","items":[{"zh":"先求物件税前总价（土地不含税，建筑物部分要把消费税抽出来还原）","ja":"まず物件の税抜き総額を求める（土地は非課税、建物部分は消費税を除いて還元する）"},{"zh":"媒介方报酬上限＝（税前总价×3%+6万）×1.1（含税）","ja":"媒介の報酬限度額＝（税抜き総額×3%＋6万円）×1.1（税込）"},{"zh":"代理方报酬上限＝媒介方上限×2","ja":"代理の報酬限度額＝媒介の限度額×2"},{"zh":"多个业者分别收报酬时，合计不能超过\\"代理方上限\\"这个总天花板","ja":"複数業者がそれぞれ報酬を受け取る場合、合計額は「代理の限度額」という総枠を超えてはならない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"单独看每个业者的报酬都合格，不代表合计也合格——合计不能超过代理方上限这个总天花板，这是本类题目的核心陷阱。依赖者特别依赖产生的费用（如远地现场调查实费）可以在报酬上限外另行收取。","ja":"各業者の報酬額が単独で上限内でも、合計が「代理の限度額」を超えれば違反となる——これがこの種の問題の核心的な落とし穴。依頼者の特別の依頼による費用（遠隔地の現地調査実費など）は報酬限度額とは別に受領できる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t46', '{"id":"t46","tag":"宅建业法","title":{"zh":"宅建业免许要否的判断口诀","ja":"宅建業の免許要否を判断するルール"},"source":"平成26年 問26","sections":[{"heading":"判断表","blocks":[{"type":"table","headers":[{"zh":"","ja":""},{"zh":"自己作为当事者","ja":"自ら当事者"},{"zh":"媒介・代理","ja":"媒介・代理"}],"rows":[[{"zh":"买卖・交换","ja":"売買・交換"},{"zh":"算宅建业","ja":"宅建業に該当"},{"zh":"算宅建业","ja":"宅建業に該当"}],[{"zh":"贷借（含转租）","ja":"貸借（転貸を含む）"},{"zh":"不算宅建业","ja":"宅建業に該当しない"},{"zh":"算宅建业","ja":"宅建業に該当"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"委托代理/媒介不能替委托人本人免除免许义务；卖地理由（还债等）跟是否需要免许完全无关；对方是国家等免适用主体，不代表自己（买方）也免适用。","ja":"代理・媒介を依頼しても、依頼者本人の免許義務は免除されない。売却の理由（借金返済など）は免許の要否と無関係。相手方が国等の適用除外主体であっても、自分（買主）が免許不要になるわけではない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t47', '{"id":"t47","tag":"民法","title":{"zh":"消灭时效的援用权人范围","ja":"消滅時効の援用権者の範囲"},"source":"平成30年 問4","sections":[{"heading":"判断标准","blocks":[{"type":"text","content":{"zh":"能否援用消灭时效，关键看这个人是否因时效消灭而直接受益，间接受益不算数。","ja":"消滅時効を援用できるかは、時効消滅によって直接的な利益を受けるかどうかで判断する——間接的な利益では足りない。"}},{"type":"table","headers":[{"zh":"身份","ja":"立場"},{"zh":"能否援用","ja":"援用の可否"}],"rows":[[{"zh":"保证人（不受主债务人处分影响）","ja":"保証人（主債務者の処分の影響を受けない）"},{"zh":"能援用","ja":"援用できる"}],[{"zh":"诈害行为受益者","ja":"詐害行為の受益者"},{"zh":"能援用","ja":"援用できる"}],[{"zh":"后顺位抵当权人（只是间接得利）","ja":"後順位抵当権者（間接的利益にすぎない）"},{"zh":"不能援用","ja":"援用できない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"不知情下做了债务承认，之后不能反悔援用时效（诚信原则）——容易忽略这条附加规则。","ja":"時効完成を知らずに債務を承認した場合、その後は信義則上、援用が許されない——この付随ルールを見落としやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t48', '{"id":"t48","tag":"民法","title":{"zh":"让渡制限特约——判断对抗力要看当事人本人","ja":"譲渡制限の意思表示——対抗力の判断は当事者本人による"},"source":"平成30年 問7","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"债务人能否拒绝向某人履行，要看这个人本人（不是他的前手）是善意无重过失还是恶意/重大过失，这个判断标准逐层单独适用。","ja":"債務者がある者への履行を拒めるかは、その者自身（前主ではなく）が善意無重過失か悪意・重過失かで判断し、各当事者ごとに個別に適用する。"}},{"type":"list","style":"unordered","items":[{"zh":"受让人恶意/重过失时，债务人可拒绝履行","ja":"譲受人が悪意・重過失のとき、債務者は履行を拒める"},{"zh":"转得者若自己善意无重过失，即使前手恶意，转得者依然能对抗债务人","ja":"転得者自身が善意無重過失であれば、前主が悪意でも転得者は債務者に対抗できる"},{"zh":"质权设定同样准用这套规则","ja":"質権設定にも同様のルールが準用される"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"不能因为前手（最初受让人）是恶意，就推定后面的转得者也不能对抗债务人——每个人的主观态样要单独判断。","ja":"前主（最初の譲受人）が悪意だからといって、転得者も当然に対抗できなくなるわけではない——各当事者の主観的態様は個別に判断する。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t49', '{"id":"t49","tag":"民法","title":{"zh":"保证的附从性——单向变动规则","ja":"保証の付従性——片面的な変動ルール"},"source":"令和2年10月 問7","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"情形","ja":"場面"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"主债务缔约后加重","ja":"主債務が契約後に加重"},{"zh":"保证人负担不加重","ja":"保証人の負担は加重されない"}],[{"zh":"主债务减轻","ja":"主債務が軽減"},{"zh":"保证人负担跟着减轻","ja":"保証人の負担も軽減される"}],[{"zh":"主债务人放弃时效利益","ja":"主債務者が時効の利益を放棄"},{"zh":"效力不及保证人（含连带保证人）","ja":"保証人（連帯保証人含む）には及ばない"}],[{"zh":"受托保证人清偿前","ja":"委託を受けた保証人が弁済する前"},{"zh":"必须通知主债务人，否则求偿受限","ja":"主債務者への通知が必要——怠ると求償が制限されうる"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"附从性是单向的——只在主债务减轻方向联动，加重方向不联动，这是最容易被出题者说反的点。","ja":"付従性は片面的——主債務が軽くなる方向にのみ連動し、重くなる方向には連動しない。これが最も逆に出題されやすいポイント。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t50', '{"id":"t50","tag":"民法","title":{"zh":"连带债务的绝对效与求偿权","ja":"連帯債務の絶対効と求償権"},"source":"平成29年 問8","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"连带债务中绝对效只有三种：相殺、更改、混同。除此之外一律相对效。","ja":"連帯債務における絶対効は「相殺・更改・混同」の3つのみ。それ以外は原則相対効。"}},{"type":"text","content":{"zh":"求偿权：只要有清偿，不管金额是否超过自己的负担部分，都能在清偿额范围内立即求偿。","ja":"求償権：弁済額が自己の負担部分を超えているかにかかわらず、弁済した範囲で直ちに求償できる。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"履行请求在新民法下已改为相对效，容易用旧知识误答；求偿权不需要等超过负担部分才能主张，这也是常见误解。","ja":"履行の請求は改正民法で相対効に変更された——旧知識で誤答しやすい。求償権も負担部分を超えるまで待つ必要はなく、これもよくある誤解。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t51', '{"id":"t51","tag":"借地借家法","title":{"zh":"定期建物赁贷借成立要件・法定更新期限・转租对抗要件","ja":"定期建物賃貸借の成立要件・法定更新期限・転貸借の対抗要件"},"source":"令和元年 問12","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"定期建物赁贷借成立","ja":"定期建物賃貸借の成立"},{"zh":"书面契约+另行书面说明，两步骤缺一不可","ja":"書面契約＋別途の書面説明の2ステップが必要"}],[{"zh":"定期建物赁贷借用途限制","ja":"定期建物賃貸借の用途制限"},{"zh":"无限制，居住用也可以","ja":"制限なし——居住用でも可"}],[{"zh":"普通建物赁贷借法定更新期限","ja":"普通建物賃貸借の法定更新期限"},{"zh":"期满前1年～6个月之间不通知即法定更新","ja":"満了の1年前～6か月前の間に通知なければ法定更新"}],[{"zh":"转租情形贷主对转租人的对抗","ja":"転貸借における貸主の転借人への対抗"},{"zh":"须通知转租人，通知后6个月生效","ja":"転借人への通知が必要——通知後6か月で効力発生"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"定期建物赁贷借容易被误以为\\"书面契约就够了\\"，实际还要另外的书面说明；不通知更新拒绝的期限常被换成\\"3个月前\\"这种错误数字。","ja":"定期建物賃貸借は「書面契約だけで足りる」と誤解しやすいが、別途の書面説明が必要。更新拒絶の通知期限は「3か月前」のような誤った数字にすり替えられやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t52', '{"id":"t52","tag":"不动产登记法","title":{"zh":"共同申请原则的例外——假登记的抹消","ja":"共同申請の原則の例外——仮登記の抹消"},"source":"平成23年 問14","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"登记原则上须登记权利者+登记义务者共同申请（不动产登记法60条），但法律针对特定场景开了单独申请的例外——假登记的抹消就是其中之一。","ja":"登記は原則として登記権利者・登記義務者の共同申請による（不動産登記法60条）が、特定の場面については単独申請の例外が認められている——仮登記の抹消もその一つ。"}},{"type":"table","headers":[{"zh":"假登记抹消的申请方式","ja":"仮登記抹消の申請方法"},{"zh":"依据","ja":"根拠"}],"rows":[[{"zh":"登记权利者+登记义务者共同申请（原则）","ja":"登記権利者・登記義務者の共同申請（原則）"},{"zh":"不动产登记法60条","ja":"不動産登記法60条"}],[{"zh":"假登记名义人单独申请","ja":"仮登記名義人による単独申請"},{"zh":"不动产登记法110条前段","ja":"不動産登記法110条前段"}],[{"zh":"利害关系人经假登记名义人承诺后单独申请","ja":"利害関係人が仮登記名義人の承諾を得て単独申請"},{"zh":"不动产登记法110条后段","ja":"不動産登記法110条後段"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"看到\\"XX登记必须共同申请\\"这种绝对化表述要多留意，很可能是出题陷阱——不动产登记法里有不少单独申请的例外场景。","ja":"「〇〇の登記は共同申請でなければならない」という言い切りには要注意——不動産登記法には単独申請が認められる例外場面が複数存在する。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t53', '{"id":"t53","tag":"国土利用计画法","title":{"zh":"事后申报制的四个独立考点","ja":"事後届出制の4つの独立論点"},"source":"令和3年10月 問22","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"申报期限","ja":"届出期限"},{"zh":"契约缔结之日起算2周内","ja":"契約締結日から起算して2週間以内"}],[{"zh":"知事助言/劝告对象","ja":"知事の助言・勧告の対象"},{"zh":"只限利用目的，对价额不在此列","ja":"利用目的のみ——対価の額は対象外"}],[{"zh":"没申报的罚则","ja":"届出をしなかった場合の罰則"},{"zh":"直接构成犯罪，不需要先劝告","ja":"直ちに罰則の対象——勧告を経る必要はない"}],[{"zh":"一团土地的判断基准","ja":"一団の土地の判断基準"},{"zh":"按权利取得者一方判断，不是让渡人","ja":"権利取得者を基準に判断——譲渡人ではない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"申报期限的\\"2周\\"容易被换成\\"3周\\"；\\"劝告\\"只针对已申报但内容不当的情形，对压根没申报的人是直接罚则，容易搞混两种处置流程。","ja":"届出期限の「2週間」は「3週間」にすり替えられやすい。「勧告」は届出済みで内容が不適切な場合にのみ適用され、届出自体をしていない場合は直接罰則の対象——2つの処理フローを混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t54', '{"id":"t54","tag":"建筑基准法","title":{"zh":"数字与构造类型的常见混淆陷阱","ja":"数字と構造類型の混同しやすい罠"},"source":"令和3年10月 問17","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"甲醛使用限制","ja":"ホルムアルデヒドの使用制限"},{"zh":"按等级区分（第1种禁止~第4种无限制），不是全面禁止","ja":"等級による区分（第1種禁止～第4種制限なし）——全面禁止ではない"}],[{"zh":"特殊建筑物避难通路宽度","ja":"特殊建築物の避難通路幅員"},{"zh":"1.5米以上","ja":"1.5m以上"}],[{"zh":"外墙紧贴邻地境界线的条件","ja":"外壁を隣地境界線に接して設けられる条件"},{"zh":"耐火构造（不是防火构造）","ja":"耐火構造（防火構造ではない）"}],[{"zh":"检查済证交付前使用","ja":"検査済証交付前の使用"},{"zh":"特定行政厅认定安全等无问题时可仮使用","ja":"特定行政庁が安全性等に問題なしと認めれば仮使用可"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"耐火构造（防内部倒塌）和防火构造（防外部延烧）是两个不同概念，出题者常故意互换。","ja":"耐火構造（内部倒壊防止）と防火構造（外部延焼防止）は異なる概念であり、出題者が意図的に入れ替えることが多い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t55', '{"id":"t55","tag":"建筑基准法","title":{"zh":"都市再生特别地区・用途地域面积上限・建筑协定承继效・容积率突破许可","ja":"都市再生特別地区・用途地域の面積上限・建築協定の承継効・容積率超過の許可"},"source":"令和7年 問18","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"都市再生特别地区","ja":"都市再生特別地区"},{"zh":"容积率/建蔽率/建筑面积/高度全部按都市计画规定，不受法56条限制","ja":"容積率・建蔽率・建築面積・高さすべて都市計画による——法56条の制限は適用されない"}],[{"zh":"店铺/饮食店面积上限","ja":"店舗・飲食店の面積上限"},{"zh":"低层住居专用系150㎡、中高层住居专用500㎡、工业专用原则禁止、田园比照低层","ja":"低層住居専用系150㎡、中高層住居専用500㎡、工業専用は原則禁止、田園住居は低層に準ずる"}],[{"zh":"建筑协定的承继效","ja":"建築協定の承継効"},{"zh":"自动适用于公告后的新所有者，不需要额外全员合意","ja":"公告後の新所有者に自動的に及ぶ——追加の全員合意は不要"}],[{"zh":"容积率突破（节能改修）","ja":"容積率超過（省エネ改修）"},{"zh":"必须经特定行政厅许可，不因公益性高而豁免","ja":"特定行政庁の許可が必要——公益性が高くても免除されない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"这是官方公认的超难题（正解率约25%），四个考点都很冷门，逐一核对法条依据是唯一稳妥的做法。","ja":"この問題は公式に難問と認定されており（正答率約25%）、4つの論点すべてがマイナーな内容——一つずつ条文の根拠を確認するのが唯一の確実な対処法。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t56', '{"id":"t56","tag":"盛土规制法","title":{"zh":"区域指定时既有工程的处理——申报制 vs 许可制","ja":"区域指定時の既存工事の扱い——届出制と許可制"},"source":"平成27年 問19","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"区域指定时正在进行的工程，不需要重新取得许可，只需要在指定之日起21日内向知事申报——法律为避免让在建工程被迫中断造成过大不利益，采用申报制而不是许可制。","ja":"区域指定の際に既に着手されている工事は、改めて許可を受ける必要はなく、指定日から21日以内に知事へ届け出ればよい——工事の中断による過大な不利益を避けるため、届出制が採用されている。"}},{"type":"list","style":"unordered","items":[{"zh":"变更工程施工者，属于\\"轻微变更\\"，只需无迟延申报，不需重新许可","ja":"工事施行者の変更は「軽微な変更」に該当し、遅滞なく届け出れば足り、改めて許可は不要"},{"zh":"需要许可的门槛：切土超过2米，或切土/盛土面积超过500㎡","ja":"許可が必要な基準：切土が2mを超える、又は切土・盛土の面積が500㎡を超える"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"看到\\"区域指定时已经在做的工程还要重新许可\\"这种说法，基本可以判断是错误陷阱；面积/高度门槛数字若刚好等于基准值（不是超过），不需要许可。","ja":"「区域指定時に既に行われている工事にも改めて許可が必要」という記述は誤りの罠と判断してよい。面積・高さが基準値と「ちょうど同じ」（超えていない）場合は許可不要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t57', '{"id":"t57","tag":"土地区画整理法","title":{"zh":"土地区划整理组合的四个考点","ja":"土地区画整理組合の4つの論点"},"source":"令和2年10月 問20","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"未登记借地权人的同意","ja":"未登記の借地権者の同意"},{"zh":"同样算数，只要申告即可成为组合员","ja":"同様にカウントされる——申告すれば組合員になれる"}],[{"zh":"总会开会门槛","ja":"総会開催の要件"},{"zh":"组合员半数以上出席（定款可另定）","ja":"組合員の半数以上の出席（定款で別段の定め可）"}],[{"zh":"赋课金分摊","ja":"賦課金の按分"},{"zh":"按地积等受益程度分摊，不能一律相同","ja":"地積等の受益に応じて按分——一律ではない"}],[{"zh":"参加组合员资格","ja":"参加組合員の資格"},{"zh":"限定为地方住宅供给公社等特定主体","ja":"地方住宅供給公社等の一定の者に限定"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"参加组合员不是有资力信用就能当，主体资格有明确限定——容易被出题者用\\"资力信用\\"这个合理条件掩盖\\"主体限定\\"这个真正的门槛。","ja":"参加組合員は資力・信用があれば誰でもなれるわけではなく、主体資格に明確な限定がある——「資力・信用」という一見もっともらしい条件で、本当の要件である「主体の限定」を覆い隠す出題が多い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t58', '{"id":"t58","tag":"农地法","title":{"zh":"假登记 vs 本登记的许可要件区别","ja":"仮登記と本登記の許可要件の違い"},"source":"令和6年 問21","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"农地权利移转的本登记（真正让所有权移转生效）必须先取得3条许可；但假登记只是为了在许可正式下发前先占住登记顺位、防止第三方抢先登记的临时手段，依附于已经申请许可这个事实，本身不需要再取得一次许可。","ja":"農地の権利移転の本登記（実際に所有権移転の効力を生じさせるもの）には3条許可が必要だが、仮登記はあくまで許可が正式に下りる前に登記上の順位を確保し第三者に先んじられることを防ぐための暫定的な手段であり、「既に許可を申請している」という事実に付随するもので、仮登記自体に別途の許可は不要である。"}},{"type":"list","style":"unordered","items":[{"zh":"5条许可申请书原则需当事人连署，民事调停成立等情形除外","ja":"5条許可申請書は原則として当事者の連署が必要——民事調停成立等の場合は除く"},{"zh":"农地赁贷借法定更新期限：期满前1年～6个月之间不通知即法定更新","ja":"農地賃貸借の法定更新期限：満了の1年前～6か月前に通知しなければ法定更新"},{"zh":"农地赁贷借的解除/解约/合意解约/更新拒绝，原则需知事许可","ja":"農地賃貸借の解除・解約・合意解約・更新拒絶には原則として知事の許可が必要"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"把许可要件错误套用到假登记这个不同行为上是本题陷阱——假登记是为了保全顺位，不是又一道许可关卡（正解率仅37%的难题）。","ja":"許可要件を「仮登記」という別の行為に誤って当てはめるのが本問の罠——仮登記は順位保全のためのものであり、別途の許可要件ではない（正答率わずか37%の難問）。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t59', '{"id":"t59","tag":"赠与税","title":{"zh":"直系尊属住宅资金赠与税非课税特例的四要件","ja":"直系尊属からの住宅取得等資金贈与税非課税特例の4要件"},"source":"平成27年 問23","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"要件","ja":"要件"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"赠与标的物","ja":"贈与の対象"},{"zh":"必须是资金（钱），不是房子本身","ja":"資金（金銭）に限る——家屋そのものではない"}],[{"zh":"房屋所在地","ja":"家屋の所在地"},{"zh":"必须在日本国内","ja":"日本国内に限る"}],[{"zh":"赠与者年龄","ja":"贈与者の年齢"},{"zh":"没有限制","ja":"制限なし"}],[{"zh":"受赠者所得","ja":"受贈者の所得"},{"zh":"合计所得金额须2,000万日元以下","ja":"合計所得金額2,000万円以下が要件"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"赠与者年龄没有限制这一点最容易被误判——因为其他一些赠与/相続相关税制（如相続時精算课税制度）确实卡60岁，容易张冠李戴。","ja":"贈与者に年齢制限がない点が最も誤解されやすい——相続時精算課税制度など他の贈与・相続関連税制には60歳要件があるため、混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t60', '{"id":"t60","tag":"不动产鉴定评价基准","title":{"zh":"原价法的适用范围——不限于\\"建物+土地\\"套装","ja":"原価法の適用範囲——「建物＋土地」のセットに限らない"},"source":"令和2年10月 問25","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"原价法的核心判断标准不是看对象不动产是不是纯土地，而是看再调达原价能不能算出来——只要能算出再调达原价（重新取得/再造成这块地要花多少钱），单独的土地（如造成地、填埋地）也可以用原价法。","ja":"原価法の核心的な判断基準は、対象不動産が土地のみかどうかではなく、再調達原価を把握できるかどうかである——再調達原価（その土地を改めて取得・造成するのにいくらかかるか）が把握できれば、土地単独（造成地・埋立地等）でも原価法は適用できる。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"土地单独就不能用原价法\\"是直觉性但错误的绝对化表述，容易被出题者利用这种\\"看似合理\\"的直觉设置陷阱。","ja":"「土地のみでは原価法を適用できない」というのは直感的だが誤った言い切りであり、出題者がこの「もっともらしい」直感を利用して罠を仕掛けやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t61', '{"id":"t61","tag":"宅建业法","title":{"zh":"免许制度的四个细节——取消事由・届出期限・跨県判定・免许换え","ja":"免許制度の4つの細部——取消事由・届出期限・県またぎ判定・免許換え"},"source":"令和7年 問41","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"1年不开业/连续休止1年","ja":"1年不開業・引き続き1年休止"},{"zh":"必要的取消事由（必须取消）","ja":"必要的取消事由（取り消さなければならない）"}],[{"zh":"廃业等届出期限","ja":"廃業等の届出期限"},{"zh":"一律30日内（不是60日）","ja":"一律30日以内（60日ではない）"}],[{"zh":"本店是否算事务所","ja":"本店は事務所に当たるか"},{"zh":"只要有分店做宅建业，本店也算事务所","ja":"支店が宅建業を営めば本店も事務所とみなされる"}],[{"zh":"免许换え流程","ja":"免許換えの手続"},{"zh":"直接向新知事申请，旧免许自动失效，不需旧知事廃业届出","ja":"新しい知事に直接申請——旧免許は自動失効し、旧知事への廃業届出は不要"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"本店不直接做宅建业≠本店不算事务所——只要任一分支机构做宅建业，本店照样算事务所，这是判断跨都道府県免许最容易漏掉的隐藏规则；免许换え流程里\\"多此一举\\"的廃业届出陷阱在历年真题反复出现（H06、H08、H20等）。","ja":"本店が直接宅建業を営んでいない＝事務所に当たらない、ではない——いずれかの支店が宅建業を営んでいれば本店も事務所とみなされる。これは県またぎ免許の判断で見落としやすい隠れたルール。免許換え手続における「余計な」廃業届出の罠は過去問で繰り返し出題されている（H06・H08・H20等）。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t62', '{"id":"t62","tag":"宅建业法","title":{"zh":"免许欠格事由的传导与解除规则","ja":"免許欠格事由の連動と解消のルール"},"source":"令和7年 問34","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"场景","ja":"場面"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"政令使用人本人有欠格事由","ja":"政令使用人本人に欠格事由がある場合"},{"zh":"传导给所属法人，法人不能取得免许","ja":"所属法人に連動し、法人は免許を受けられない"}],[{"zh":"不正手段被取消免许法人的\\"抢跑廃业\\"役员","ja":"不正の手段による免許取消しに係る法人の「先んじて廃業」した役員"},{"zh":"公示日前60日内在任者，须等廃业届出满5年","ja":"公示日前60日以内の在任者は、廃業届出から5年の経過が必要"}],[{"zh":"未成年人的欠格判断","ja":"未成年者の欠格判断"},{"zh":"看法定代理人是否欠格，会传导给未成年人本人","ja":"法定代理人の欠格が本人に連動する"}],[{"zh":"破产人复权","ja":"破産者の復権"},{"zh":"复权即时解除欠格，不需要等5年","ja":"復権により欠格状態は直ちに解消——5年待つ必要はない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"复权\\"和\\"5年等待期\\"是两个不同的免许欠格解除机制，容易被混用——复权是即时的，因犯罪服刑需要的是5年等待期，两者逻辑不同。","ja":"「復権」と「5年の待機期間」は異なる欠格解消メカニズムであり混同しやすい——復権は即時だが、犯罪による服役後は5年の待機が必要という異なる論理である。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t63', '{"id":"t63","tag":"宅建业法","title":{"zh":"宅建士登録制度——提出对象・欠格连动・登録移转・变更登録","ja":"宅建士登録制度——提出先・欠格連動・登録移転・変更登録"},"source":"令和3年10月 問35","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"宅建士证提出对象","ja":"宅建士証の提出先"},{"zh":"交付方知事，不是处分方","ja":"交付した知事——処分をした知事ではない"}],[{"zh":"事务禁止期间内注销登录","ja":"事務禁止期間中の登録消除"},{"zh":"重新合格考试也不解除欠格，须等原禁止期间满","ja":"再合格しても欠格は解消されず、元の禁止期間の満了を待つ"}],[{"zh":"登録の移転触发条件","ja":"登録の移転のトリガー"},{"zh":"去别的都道府县宅建业者事务所工作，不是住所变更","ja":"他都道府県の宅建業者事務所での勤務——住所変更ではない"}],[{"zh":"本籍变更","ja":"本籍の変更"},{"zh":"走变更登録，无迟延申请","ja":"変更登録の手続き、遅滞なく申請"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"登録の移転的唯一触发条件是\\"去别的都道府县宅建业者处工作\\"，选项常用\\"住所变更\\"冒充这个条件——两者容易混淆。","ja":"登録の移転の唯一のトリガーは「他都道府県の宅建業者での勤務」であり、選択肢は「住所変更」をこの条件であるかのように見せかけることが多い——両者を混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t64', '{"id":"t64","tag":"宅建业法","title":{"zh":"取引态样明示义务的触发频率与广告费收取条件","ja":"取引態様明示義務の発生頻度と広告料金の受領条件"},"source":"令和7年 問38","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"取引态样明示，广告时和接受订单时都要分别明示，不能省略任一环节","ja":"取引態様の明示は、広告時・注文受領時それぞれで必要——どちらも省略不可"},{"zh":"分批广告，每一次都要重新明示取引态样","ja":"分割広告でも、その都度取引態様を明示する必要がある"},{"zh":"夸大广告是行为犯，做了就违法，不看是否成交","ja":"誇大広告は行為犯——表示自体で違法となり、契約成立の有無は無関係"},{"zh":"广告费能否另收，关键看是否依赖者主动要求","ja":"広告料金の別途受領可否は、依頼者からの依頼によるかどうかがポイント"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"广告时明示过就不用接单时再明示\\"是常见错误直觉——两个环节的明示义务是独立的，缺一不可。","ja":"「広告時に明示済みなら注文時は不要」という直感は誤り——2つの場面の明示義務はそれぞれ独立しており、いずれも省略できない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t65', '{"id":"t65","tag":"宅建业法","title":{"zh":"手付金等保全措施——完成/未完成物件门槛与保证期间","ja":"手付金等の保全措置——完成／未完成物件の基準と保証期間"},"source":"平成30年 問38","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"完成物件","ja":"完成物件"},{"zh":"未完成物件","ja":"未完成物件"}],"rows":[[{"zh":"免除保全措施门槛","ja":"保全措置不要の基準"},{"zh":"代金10%以下（且≤1000万）","ja":"代金の10%以下（かつ1,000万円以下）"},{"zh":"代金5%以下（且≤1000万）","ja":"代金の5%以下（かつ1,000万円以下）"}],[{"zh":"保全措施方式","ja":"保全措置の方法"},{"zh":"保证/保险/保管三种皆可","ja":"保証・保険・保管のいずれも可"},{"zh":"只能保证或保险，不能保管","ja":"保証・保険のみ——保管は不可"}]]},{"type":"text","content":{"zh":"门槛判断基准是累计已收金额（手付金+中间金），不是单看手付金；银行保证委托契约的保证期间要覆盖到住宅引渡为止，不是工事完成为止。","ja":"基準の判断は累計受領額（手付金＋中間金）による——手付金単体ではない。銀行の保証委託契約の保証期間は住宅の引渡しまでをカバーする必要があり、工事完了までではない。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"完成/未完成物件的门槛（10% vs 5%）和保全措施方式（三种 vs 两种）容易混着记，一定要按完成/未完成分组记忆。","ja":"完成／未完成物件の基準（10%対5%）と保全措置の方法（3種対2種）は混同しやすいため、完成／未完成でグループ分けして覚える。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t66', '{"id":"t66","tag":"宅建业法","title":{"zh":"住宅瑕疵担保履行法——担保范围与契约缔结主体","ja":"住宅瑕疵担保履行法——担保範囲と契約締結主体"},"source":"令和2年12月 問45","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"合计户数换算门槛：床面积55㎡以下2户算1户（与h28-45相同考点）","ja":"合計戸数の換算基準：床面積55㎡以下は2戸をもって1戸（h28-45と同一論点）"},{"zh":"转卖不影响保险契约效力，业者不能据此解约（与h28-45相同考点）","ja":"転売は保険契約の効力に影響せず、業者は解約できない（h28-45と同一論点）"},{"zh":"担保范围只有构造耐力上主要部分+雨水侵入防止部分，不含给排水/瓦斯设备","ja":"担保範囲は構造耐力上主要な部分＋雨水浸入防止部分のみ——給排水・ガス設備は含まない"},{"zh":"契约缔结方和保险费负担方都是卖方业者，买方既不签约也不直接付保险费","ja":"契約締結者も保険料負担者も売主業者であり、買主は締結せず保険料も直接支払わない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"这个板块考点分散在多道题里，建议把h28-45和本题知识点合并记忆，形成完整的住宅瑕疵担保履行法速查表。","ja":"この分野の論点は複数の問題に分散しているため、h28-45と本問の知識点を合わせて住宅瑕疵担保履行法のチェックリストとしてまとめて覚えるとよい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t67', '{"id":"t67","tag":"都市计画法","title":{"zh":"地区计画的适用范围——不限于已划用途地域的区域","ja":"地区計画の適用範囲——用途地域指定区域に限られない"},"source":"令和6年 問15","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"地区计画不是只能在已划用途地域的区域规定——没有划用途地域的区域，只要满足一定要件（如已经/正在进行的住宅市街地开发、无秩序建筑担忧区域等），同样可以规定地区计画。","ja":"地区計画は「用途地域が定められている区域のみ」に限られるわけではない——用途地域が定められていない区域でも、一定の要件（住宅市街地の開発事業が行われる/行われた区域、無秩序な建築のおそれがある区域等）を満たせば地区計画を定めることができる。"}},{"type":"list","style":"unordered","items":[{"zh":"都市设施原则在都市计画区域内规定，特别有必要时也可以在区域外规定","ja":"都市施設は原則都市計画区域内に定めるが、特に必要があるときは区域外にも定めることができる"},{"zh":"准都市计画区域内能规定的都市计画种类是固定的8项，不含市街地开发事业","ja":"準都市計画区域に定められる都市計画は固定された8種類のみ——市街地開発事業は含まれない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"\\"能不能划入某种区域\\"和\\"能不能划入某种用途地域\\"是两条不同的判断线，容易被出题者放在同一题里制造混淆。","ja":"「どの区域に定められるか」と「どの用途地域に定められるか」は別の判断軸であり、同一問題内で組み合わせて混同を誘う出題が多い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t68', '{"id":"t68","tag":"土地区画整理法","title":{"zh":"仮换地指定 vs 换地处分公告——登记限制的触发点","ja":"仮換地指定と換地処分の公告——登記制限のトリガー"},"source":"令和7年 問20","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"时间节点","ja":"時点"},{"zh":"法律效果","ja":"法的効果"}],"rows":[[{"zh":"仮换地指定","ja":"仮換地の指定"},{"zh":"权利人可先使用仮换地，但处分权依然留在从前宅地，从前宅地可正常登记","ja":"権利者は仮換地を先行使用できるが、処分権は従前の宅地に残り、従前の宅地は通常どおり登記できる"}],[{"zh":"换地处分公告","ja":"換地処分の公告"},{"zh":"权利关系正式变动，公告后到变动登记完成前限制其他登记","ja":"権利関係が正式に変動——公告後から変動登記完了までの間、他の登記が制限される"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"登记限制规则的触发点常被从换地处分公告偷换成仮换地指定，这道题历年反复出题（R01-20-1和本题几乎一字不差），是经典必考混淆点。","ja":"登記制限のトリガーが「換地処分の公告」から「仮換地の指定」にすり替えられることが多い。この論点は過去に繰り返し出題されており（R01-20-1と本問はほぼ同一）、典型的な頻出混同ポイント。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t69', '{"id":"t69","tag":"建筑基准法","title":{"zh":"非常用进入口・建筑确认豁免条件・阳台扶手高度・既存不适格建筑物","ja":"非常用進入口・建築確認の免除条件・バルコニー手すり高さ・既存不適格建築物"},"source":"平成30年 問18","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"非常用进入口","ja":"非常用進入口"},{"zh":"高度31米以下部分的3层以上楼层需要设置，不是全部楼层","ja":"高さ31m以下の部分の3階以上の階に必要——全ての階ではない"}],[{"zh":"增改建确认豁免","ja":"増改築の確認免除"},{"zh":"防火/准防火地域以外+面积≤10㎡才豁免","ja":"防火・準防火地域以外＋面積10㎡以内でのみ免除"}],[{"zh":"阳台安全扶手","ja":"バルコニーの安全手すり"},{"zh":"高度1.1米以上","ja":"高さ1.1m以上"}],[{"zh":"既存不适格建筑物","ja":"既存不適格建築物"},{"zh":"法改正后不用强制立即改造合规","ja":"法改正後も強制的に即時適合させる義務はない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"既存不适格建筑物制度容易被误以为要求所有者尽快改造合规，实际上恰好相反，是法不溯及既往的体现。","ja":"既存不適格建築物制度は所有者に速やかな適合を求めると誤解されやすいが、実際は正反対——法の不遡及の表れである。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t70', '{"id":"t70","tag":"都市计画法","title":{"zh":"地区计画三层次——必须定/努力义务/地区整备计画可定（重点关注题）","ja":"地区計画の3層構造——必須事項・努力義務・地区整備計画で定められる事項（重点論点）"},"source":"令和3年10月 問15","sections":[{"heading":"三层结构","blocks":[{"type":"table","headers":[{"zh":"层次","ja":"レベル"},{"zh":"内容","ja":"内容"},{"zh":"义务程度","ja":"義務の程度"}],"rows":[[{"zh":"地区计画必须定","ja":"地区計画の必須事項"},{"zh":"种类・名称・位置・区域；地区设施・地区整备计画","ja":"種類・名称・位置・区域／地区施設・地区整備計画"},{"zh":"必须（定めるものとする）","ja":"必須（定めるものとする）"}],[{"zh":"地区计画努力义务","ja":"地区計画の努力義務事項"},{"zh":"区域面积、目标、整备开发保全方针","ja":"区域の面積、目標、整備・開発・保全に関する方針"},{"zh":"努力义务（定めるよう努める）","ja":"努力義務（定めるよう努める）"}],[{"zh":"地区整备计画可定","ja":"地区整備計画で定められる事項"},{"zh":"建蔽率、容积率、高度限制等具体建筑规制","ja":"建蔽率・容積率・高さ制限等の具体的な建築規制"},{"zh":"可以定（定めることができる）","ja":"可能（定めることができる）"}]]}]},{"heading":"易错陷阱（本题重复提交，重点关注）","blocks":[{"type":"trap","content":{"zh":"①②看起来像\\"必须\\"，容易被\\"定める\\"这个词误导——其实原文本来就是弱义务表述；③的陷阱在\\"规模层级\\"不在字面内容——区域区分是都市计画区域整体层面的宏观事项，地区整备计画只能管建筑细节层面的微观规制，两者不是一个量级，地区整备计画根本没资格决定区域区分。","ja":"①②は「定める」という語に惑わされて「必須」と誤解しやすいが、実際は弱い義務の表現である。③の罠は「規模のレベル」にある——区域区分は都市計画区域全体レベルのマクロな事項であり、地区整備計画は建築の細部レベルのミクロな規制しか扱えない。両者は次元が異なり、地区整備計画には区域区分を決める権限がない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t71', '{"id":"t71","tag":"建筑基准法","title":{"zh":"特殊建筑物・大型建筑物的判断标准与建筑确认适用行为对照","ja":"特殊建築物・大型建築物の判断基準と建築確認の適用行為対照表"},"source":"平成29年 問18","sections":[{"heading":"判断标准","blocks":[{"type":"table","headers":[{"zh":"类型","ja":"類型"},{"zh":"判断标准","ja":"判断基準"}],"rows":[[{"zh":"特殊建筑物","ja":"特殊建築物"},{"zh":"看用途（共同住宅、电影院、宾馆、酒吧、饮食店、店铺、仓库、车库算，独栋住宅、事务所不算）","ja":"用途で判断（共同住宅・映画館・ホテル・バー・飲食店・物品販売店舗・倉庫・自動車車庫は該当、戸建住宅・事務所は非該当）"}],[{"zh":"大型建筑物","ja":"大型建築物"},{"zh":"看层数或面积（2层以上，或延面积超200㎡，跟构造材质无关）","ja":"階数又は面積で判断（2階建て以上、又は延べ面積200㎡超——構造材質は無関係）"}]]},{"type":"text","content":{"zh":"建筑确认适用行为：用途变更这个行为，只有特殊建筑物（面积超200㎡）才需要确认，大型建筑物和一般建筑物的用途变更都不需要。","ja":"建築確認の適用行為：用途変更という行為は、特殊建築物（面積200㎡超）のみ確認が必要で、大型建築物・一般建築物の用途変更は不要。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"宾馆和共同住宅都是特殊建筑物，容易被忽略——只要两者都是特殊建筑物且面积超200㎡，相互用途变更就需要确认。","ja":"ホテルと共同住宅がいずれも特殊建築物であることは見落とされやすい——両方とも特殊建築物で面積が200㎡を超えていれば、相互の用途変更には確認が必要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t72', '{"id":"t72","tag":"土地区画整理法","title":{"zh":"土地区划整理事业的地域限定与施行障碍建筑许可","ja":"土地区画整理事業の地域限定と施行障害建築物の許可"},"source":"平成30年 問21","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"土地区划整理事业只能在都市计画区域内进行，不含区域外（法2条1项）。施行障碍建筑新建的许可权者是知事等——市的区域内是市长，町村的区域内是知事，不是都道府県知事和市町村长双方（法76条1项）。","ja":"土地区画整理事業は都市計画区域内でのみ行われ、区域外は含まない（法2条1項）。施行障害となる建築物の新築の許可権者は「知事等」——市の区域内は市長、町村の区域内は知事であり、都道府県知事と市町村長の両方ではない（法76条1項）。"}},{"type":"list","style":"unordered","items":[{"zh":"仮换地指定后，从前宅地上的建筑物施行者可以移转/除却（法77条1项）","ja":"仮換地指定後、従前の宅地の建築物は施行者が移転・除却できる（法77条1項）"},{"zh":"仮换地的使用收益开始日可以另定，不是必须跟效力发生日同一天（法99条2项）","ja":"仮換地の使用収益開始日は別に定めることができ、効力発生日と同一である必要はない（法99条2項）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"施行障碍建筑许可的许可权者容易被说成都道府県知事和市町村长双方同意，实际按市/町村分别归口，不是两者都要。","ja":"施行障害建築物の許可権者は「都道府県知事及び市町村長の両方」と誤って記述されやすいが、実際は市・町村ごとに管轄が分かれ、両方の同意は不要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t73', '{"id":"t73","tag":"建筑基准法","title":{"zh":"采光面积・建筑确认对象・避雷设备与非常用进入口高度对比・不燃材料义务地域限定","ja":"採光面積・建築確認の対象・避雷設備と非常用進入口の高さ対比・不燃材料義務の地域限定"},"source":"平成26年 問17","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"住宅居室采光面积","ja":"住宅居室の採光面積"},{"zh":"原则床面积7分之1以上，可放宽到10分之1","ja":"原則床面積の7分の1以上——10分の1まで緩和可能"}],[{"zh":"建筑确认对象","ja":"建築確認の対象"},{"zh":"建筑（含新建・增改建・移转）、大规模修缮、大规模模样替，移转也算","ja":"建築（新築・増改築・移転を含む）、大規模修繕、大規模模様替——移転も対象"}],[{"zh":"避雷设备门槛","ja":"避雷設備の基準"},{"zh":"高度超过20米","ja":"高さ20m超"}],[{"zh":"非常用进入口/升降机门槛","ja":"非常用進入口・昇降機の基準"},{"zh":"高度超过31米","ja":"高さ31m超"}],[{"zh":"不燃材料义务","ja":"不燃材料の義務"},{"zh":"只在防火地域，准防火地域没有这个义务","ja":"防火地域のみ——準防火地域には義務なし"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"避雷设备（20米）和非常用进入口/升降机（31米）这两个高度数字经常被混用，务必分开记；防火地域和准防火地域一字之差，义务范围完全不同。","ja":"避雷設備（20m）と非常用進入口・昇降機（31m）の高さの数字は混同されやすく、分けて覚える必要がある。防火地域と準防火地域は一字違いだが、義務の範囲はまったく異なる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t74', '{"id":"t74","tag":"国土利用计画法","title":{"zh":"事后申报制——国等免申报・申报事项・一团土地判断・违反劝告的处置","ja":"事後届出制——国等の免除・届出事項・一団の土地の判断・勧告違反時の対応"},"source":"令和4年 問22","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"当事人一方是国等","ja":"当事者の一方が国等"},{"zh":"免申报，不管面积多大","ja":"届出不要——面積の大小を問わない"}],[{"zh":"申报事项","ja":"届出事項"},{"zh":"利用目的+对价额，两项都要","ja":"利用目的＋対価の額——両方必要"}],[{"zh":"一团土地的判断","ja":"一団の土地の判断"},{"zh":"以最终购买者是否统一利用为准，不看原所有者","ja":"最終的な購入者による一体利用かどうかで判断——元の所有者は問わない"}],[{"zh":"违反劝告的处置","ja":"勧告違反時の対応"},{"zh":"只能公表，不能取消契约","ja":"公表することができるのみ——契約を取り消すことはできない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"一团土地要看最终购买者是否统一利用，不是看卖方是否为同一人——容易搞反判断主体。知事对违反劝告者只能公表，不能取消契约，这是保护交易安全的立法设计。","ja":"一団の土地は最終的な購入者が一体利用するかどうかで判断し、売主が同一人物かどうかではない——判断の主体を逆にしやすい。知事は勧告違反者に対して公表することしかできず、契約を取り消すことはできない——これは取引の安全を守るための立法設計。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t75', '{"id":"t75","tag":"土地区画整理法","title":{"zh":"施行区域 vs 施行地区・公的施行与民间施行的规模限制差异","ja":"施行区域と施行地区・公的施行と民間施行の規模制限の違い"},"source":"平成24年 問21","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"术语","ja":"用語"},{"zh":"定义","ja":"定義"}],"rows":[[{"zh":"施行区域","ja":"施行区域"},{"zh":"都市计画中规定的区域（法2条8项）","ja":"都市計画に定められた区域（法2条8項）"}],[{"zh":"施行地区","ja":"施行地区"},{"zh":"实际施行土地区划整理事业的区域（法2条4项）","ja":"実際に土地区画整理事業を施行する区域（法2条4項）"}]]},{"type":"text","content":{"zh":"公的施行（都道府県、市町村等）作为都市计画事业限定在施行区域内（且限市街化区域或非线引区域）；民间施行（个人、组合、区划整理会社）没有这个地域限定，都市计画区域内哪里都可以施行，甚至市街化调整区域内也可以。","ja":"公的施行（都道府県・市町村等）は都市計画事業として実施され、施行区域内（かつ市街化区域又は非線引区域に限定）に制限される。民間施行（個人・組合・区画整理会社）にはこの地域限定がなく、都市計画区域内であればどこでも施行でき、市街化調整区域内でも施行可能。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"施行区域和施行地区是两个不同概念，容易混淆；民间施行（含土地区划整理组合）没有施行区域的地域限定，这是本题最容易搞混的知识点。","ja":"施行区域と施行地区は異なる概念であり混同しやすい。民間施行（土地区画整理組合を含む）には施行区域の地域限定がないという点が本問で最も混同しやすいポイント。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t76', '{"id":"t76","tag":"都市计画法","title":{"zh":"开发许可判断三步走——公益豁免・农林渔业特例・面积门槛","ja":"開発許可判断の3ステップ——公益免除・農林漁業特例・面積基準"},"source":"平成24年 問17","sections":[{"heading":"判断流程","blocks":[{"type":"list","style":"ordered","items":[{"zh":"先看是不是公益上必要建筑物清单内的（图书馆、公民馆等无条件豁免）","ja":"まず「公益上必要な建築物」リストに該当するか確認（図書館・公民館等は無条件免除）"},{"zh":"再看是不是农林渔业用建筑物且在市街化区域以外（这个特例只在市街化区域以外适用）","ja":"次に農林漁業用建築物で市街化区域以外かを確認（この特例は市街化区域以外にのみ適用）"},{"zh":"最后按所在区域的面积门槛判断（市街化区域1,000㎡、准都市计画区域3,000㎡等）","ja":"最後に所在区域の面積基準で判断（市街化区域1,000㎡、準都市計画区域3,000㎡等）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"医院、学校不在公益上必要建筑物清单内，容易被误以为跟图书馆一样无条件豁免；农林渔业用建筑物特例只适用于市街化区域以外，市街化区域内没有这个豁免。","ja":"病院・学校は「公益上必要な建築物」リストに含まれず、図書館と同様に無条件免除されると誤解しやすい。農林漁業用建築物の特例は市街化区域以外にのみ適用され、市街化区域内にはこの免除はない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t77', '{"id":"t77","tag":"都市计画法","title":{"zh":"用途地域定义中的住居环境保护条款与特定用途制限地域","ja":"用途地域の定義における住居環境保護条項と特定用途制限地域"},"source":"令和3年12月 問15","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"只有住居系8个地域（第一种低层住居专用地域～田园住居地域）的定义里才有与之调和的住居环境保护这句话，商业系（近隣商业・商业）和工业系（准工业・工业・工业专用）地域的定义里都没有这句话。","ja":"住居系8地域（第一種低層住居専用地域～田園住居地域）の定義にのみ「これと調和した住居の環境を保護する」という文言があり、商業系（近隣商業・商業）と工業系（準工業・工業・工業専用）地域の定義にはこの文言がない。"}},{"type":"table","headers":[{"zh":"地域","ja":"地域"},{"zh":"能定的都市计画","ja":"定められる都市計画"}],"rows":[[{"zh":"特定用途制限地域","ja":"特定用途制限地域"},{"zh":"只能定在没有划用途地域的区域（不含市街化调整区域）","ja":"用途地域が定められていない区域にのみ（市街化調整区域を除く）"}],[{"zh":"高层住居诱导地区","ja":"高層住居誘導地区"},{"zh":"第一种/第二种住居地域、准住居地域、近隣商业地域、准工业地域","ja":"第一種・第二種住居地域、準住居地域、近隣商業地域、準工業地域"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"特定用途制限地域（只能定在没划用途地域的区域）和特别用途地区（用来补充/加强已有用途地域的限制）两者名字相近但适用条件完全不同，容易混淆。","ja":"特定用途制限地域（用途地域が定められていない区域にのみ）と特別用途地区（既存の用途地域の制限を補完・強化）は名称が似ているが適用条件はまったく異なり、混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t78', '{"id":"t78","tag":"土地区画整理法","title":{"zh":"仮换地指定 vs 换地处分公告（第二例，与r07-20对照记忆）","ja":"仮換地指定と換地処分の公告（第2例、r07-20と対照記憶）"},"source":"令和元年 問20","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"限制其他登记的触发点是换地处分公告之后，不是仮换地指定之后。仮换地指定后，土地的处分权依然留在从前的土地上，从前的土地依然可以正常登记；只有换地处分公告后到变动登记完成前，才会限制其他登记的办理。","ja":"他の登記を制限するトリガーは換地処分の公告後であり、仮換地の指定後ではない。仮換地指定後も土地の処分権は従前の土地に残り、従前の土地は通常どおり登記できる。換地処分の公告後から変動登記完了までの間のみ、他の登記が制限される。"}},{"type":"list","style":"unordered","items":[{"zh":"换地计画认可：个人施行者、组合、区划整理会社、市町村、都市再生机构、地方住宅供给公社需要知事认可；都道府県、国土交通大臣不需要","ja":"換地計画の認可：個人施行者・組合・区画整理会社・市町村・都市再生機構・地方住宅供給公社は知事の認可が必要／都道府県・国土交通大臣は不要"},{"zh":"个人施行者以外的施行者，换地计画须公开縦覧2周","ja":"個人施行者以外の施行者は、換地計画を2週間公衆の縦覧に供する必要がある"},{"zh":"换地处分公告后：定了换地的视为从前宅地，没定换地的权利消灭","ja":"換地処分の公告後：換地が定められた土地は従前の宅地とみなされ、換地が定められなかった権利は消滅する"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"这道题跟令和7年問20（t68）考的是完全相同的知识点，建议对照复习，两道题几乎一字不差，反复考的核心陷阱是把换地处分公告偷换成仮换地指定。","ja":"この問題は令和7年問20（t68）とまったく同一の論点であり、対照して復習するとよい。2問はほぼ同一の文言で、換地処分の公告を仮換地の指定にすり替えるのが繰り返し出題される核心の罠である。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t79', '{"id":"t79","tag":"民法","title":{"zh":"诉讼与时效更新——权利是否被最终确定是判断标准","ja":"訴訟と時効の更新——権利が最終的に確定したかが判断基準"},"source":"令和元年 問9","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"情形","ja":"場面"},{"zh":"是否发生时效更新","ja":"時効更新の有無"}],"rows":[[{"zh":"撤诉","ja":"訴えの取り下げ"},{"zh":"不发生（只有完成猶予6个月）","ja":"生じない（完成猶予6か月のみ）"}],[{"zh":"驳回起诉判决确定","ja":"却下判決の確定"},{"zh":"不发生","ja":"生じない"}],[{"zh":"败诉（请求棄却）判决确定","ja":"請求棄却判決の確定"},{"zh":"不发生","ja":"生じない"}],[{"zh":"裁判上的和解成立","ja":"裁判上の和解の成立"},{"zh":"发生（和解调书与确定判决同等效力）","ja":"生じる（和解調書は確定判決と同一の効力）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"裁判上的和解不是判决，容易被误以为不发生更新效力，实际上法律特别赋予它跟确定判决同等的效力，同样触发时效更新。","ja":"裁判上の和解は判決ではないため更新効果が生じないと誤解されやすいが、法律により確定判決と同一の効力が特別に与えられており、同様に時効更新のトリガーとなる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t80', '{"id":"t80","tag":"民法","title":{"zh":"遗言制度四细节——财产目录、证人欠格、口头遗言、遗赠沉默的效果","ja":"遺言制度の4つの細部——財産目録・証人欠格・口頭遺言・遺贈における沈黙の効果"},"source":"令和3年12月 問7","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"自筆证书遗言的财产目录","ja":"自筆証書遺言の財産目録"},{"zh":"可以不亲笔书写，每页签名盖章即可（2019年新规）","ja":"自書不要——毎葉に署名押印すればよい（2019年施行の改正）"}],[{"zh":"公正证书遗言的证人欠格","ja":"公正証書遺言の証人欠格"},{"zh":"推定继承人不论年龄都不能当证人","ja":"推定相続人は年齢を問わず証人になれない"}],[{"zh":"死亡危急时的遗言","ja":"死亡の危急に迫った者の遺言"},{"zh":"证人2人以上在场可以口头进行","ja":"証人2人以上の立会いで口頭により可能"}],[{"zh":"受遗赠人沉默的效果","ja":"受遺者が沈黙した場合の効果"},{"zh":"视为承认（不是放弃）","ja":"承認とみなされる（放棄ではない）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"受遗赠人沉默的默认结果是承认，不是放弃——这跟相続放棄需要主动表示的逻辑正好相反，遗赠这边沉默等于接受。","ja":"受遺者が沈黙した場合のデフォルトは承認であり放棄ではない——相続放棄が積極的な意思表示を要するのとは逆に、遺贈では沈黙が承認とみなされる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t81', '{"id":"t81","tag":"民法","title":{"zh":"占有回收之诉的要件与占有的当然继承","ja":"占有回収の訴えの要件と占有の当然承継"},"source":"令和6年 問7","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"占有回收之诉的要件是占有被夺走（违反本人意思），被骗后自愿交出占有不算被夺走","ja":"占有回収の訴えの要件は占有が奪われたこと（本人の意思に反する）——騙されて任意に引き渡した占有は該当しない"},{"zh":"占有回收之诉针对第三者的侵夺，占有权本人不构成侵夺对象","ja":"占有回収の訴えは第三者による侵奪を対象とし、占有権者本人は対象とならない"},{"zh":"占有的继承是当然、自动的，不以知情为前提","ja":"占有の承継は当然かつ自動的であり、知情を前提としない"},{"zh":"赁贷借契约不因当事人死亡而当然终止，权利义务由继承人承继","ja":"賃貸借契約は当事者の死亡によって当然には終了せず、権利義務は相続人が承継する"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"被骗后自愿交出占有，容易被误以为等同于被夺走，实际上法律区分严格，只有违反本人意思的强制剥夺才算被夺走。","ja":"騙されて任意に占有を引き渡した場合、「奪われた」ことと同視されやすいが、法律上の区別は厳格で、本人の意思に反する強制的な剥奪のみが該当する。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t82', '{"id":"t82","tag":"民法","title":{"zh":"留置权的两大成立要件——占有合法性与牵连关系","ja":"留置権の2つの成立要件——占有の適法性と牽連関係"},"source":"平成25年 問4","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"要件","ja":"要件"},{"zh":"内容","ja":"内容"}],"rows":[[{"zh":"占有开始须合法","ja":"占有の開始が適法であること"},{"zh":"不法占有开始后产生的费用不能留置","ja":"不法占有開始後に生じた費用は留置できない"}],[{"zh":"债权与标的物须有牵连关系","ja":"債権と目的物に牽連関係があること"},{"zh":"债权须是因该物本身产生的费用性债权","ja":"債権はその物自体について生じた費用性の債権であること"}],[{"zh":"留置权效力范围","ja":"留置権の効力範囲"},{"zh":"只及于债权直接对应的物本身，不自动扩展到相关的其他物（如建物的留置权不及于第三者所有的敷地）","ja":"債権が直接対応する物自体に限られ、関連する他の物には当然に及ばない（建物の留置権は第三者所有の敷地には及ばない）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"造作买取请求权、双重买卖的损害赔偿请求权，都是常见的牵连关系不成立的典型例子，容易被误以为可以留置。","ja":"造作買取請求権、二重売買の損害賠償請求権はいずれも牽連関係が成立しない典型例であり、留置できると誤解されやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t83', '{"id":"t83","tag":"民法","title":{"zh":"保证人与物上保证人间的代位/求偿——头数分摊原则","ja":"保証人と物上保証人間の代位・求償——頭数按分の原則"},"source":"平成25年 問6","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"保证人和物上保证人之间的代位/求偿，按头数（人数）平均分摊，不问各自的保证额/担保物价值大小（民法501条3项4号）。从物上保证人处买下担保物的第三取得者，视为等同于物上保证人，同样适用这套规则。","ja":"保証人と物上保証人との間の代位・求償は、各自の保証額や担保物の価値にかかわらず頭数で均等に按分する（民法501条3項4号）。物上保証人から担保物を譲り受けた第三取得者は物上保証人とみなされ、同様のルールが適用される。"}},{"type":"text","content":{"zh":"保证人与物上保证人间的代位，不需要办理代位的付记登记手续。","ja":"保証人と物上保証人間の代位には、代位の付記登記は不要である。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"这道题的正解（肢4）官方公布时曾有争议，因为很难找到直接对应的判例支持，属于依据略薄弱的难题，做错不用太自责。核心还是要记住头数分摊原则的计算方法。","ja":"この問題の正解（肢4）は公式発表時に議論があった——対応する明確な判例が見当たらず、根拠がやや薄い難問である。核心は頭数按分の原則の計算方法を押さえること。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t84', '{"id":"t84","tag":"民法","title":{"zh":"借地权人的救济路径与债务不履行解除对转租人的效力","ja":"借地権者の救済手段と債務不履行解除の転借人への効力"},"source":"平成26年 問7","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"出租建筑物≠转租土地，借地人自己占有使用土地的事实不受影响","ja":"建物の賃貸≠土地の転貸——借地人が自ら土地を占有利用する事実には影響しない"},{"zh":"借地权人面对第三人妨害有两条救济路径：代位行使所有权人的妨害排除请求权 + 直接行使自己赁借权的妨害排除请求权","ja":"借地権者は第三者の妨害に対し2つの救済手段を持つ：所有権者の妨害排除請求権の代位行使＋自己の賃借権に基づく妨害排除請求権"},{"zh":"适法转贷时，债务不履行解除能对抗转租人（跟合意解除的规则相反）","ja":"適法転貸の場合、債務不履行解除は転借人に対抗できる（合意解除のルールとは逆）"},{"zh":"赁料支付原则是后払い（当月末付当月租）","ja":"賃料の支払いは原則後払い（当月末に当月分を支払う）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"债务不履行解除和合意解除对转租人的效力正好相反，容易混淆——债务不履行能对抗，合意解除不能对抗。","ja":"債務不履行解除と合意解除の転借人への効力は正反対であり混同しやすい——債務不履行解除は対抗できるが、合意解除は対抗できない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t85', '{"id":"t85","tag":"民法","title":{"zh":"法定监督义务者不等于同居家人——JR东海事件判例","ja":"法定の監督義務者＝同居家族ではない——JR東海事件判例"},"source":"令和2年12月 問1","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"责任无能力者（如重度认知症患者）造成损害时，负赔偿责任的是法定的监督义务者——单纯同居的配偶者这个身份本身不当然构成法定监督义务者，需要综合考量实际监护状况等因素来判断（最判平28.3.1，JR东海事件）。","ja":"責任無能力者（重度の認知症患者等）が損害を与えた場合、賠償責任を負うのは法定の監督義務者——単に同居する配偶者であるというだけでは当然に法定監督義務者に当たらず、実際の介護状況等を総合的に考慮して判断される（最判平28.3.1、JR東海事件）。"}},{"type":"list","style":"unordered","items":[{"zh":"建物基本安全性缺陷的责任可以延伸到无契约关系的第三人（居住者）","ja":"建物の基本的安全性の欠陥による責任は契約関係にない第三者（居住者）にも及ぶ"},{"zh":"被用者向使用者的逆求偿被2020年新判例承认","ja":"被用者から使用者への逆求償は2020年の新判例で認められた"},{"zh":"人身伤害的不法行为消灭时效主观期间是5年（不是一般的3年）","ja":"人身傷害の不法行為の消滅時効の主観的期間は5年（通常の3年ではない）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"同居配偶不代表当然构成法定监督义务者，这是重要判例规则，容易被出题者用身份直接推定责任来混淆。","ja":"同居配偶者は当然に法定監督義務者に該当するわけではない——これは重要な判例ルールであり、身分から直接責任を推定させる出題で混同を誘われやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t86', '{"id":"t86","tag":"不动产登记法","title":{"zh":"敷地权附区分建物・仮登记本登记・代位申请通知对象・配偶者居住权登记","ja":"敷地権付き区分建物・仮登記の本登記・代位申請の通知対象・配偶者居住権の登記"},"source":"令和2年10月 問14","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"敷地权附区分建物所有权保存登记","ja":"敷地権付き区分建物の所有権保存登記"},{"zh":"须取得敷地权登记名义人承诺","ja":"敷地権の登記名義人の承諾が必要"}],[{"zh":"仮登记的本登记","ja":"仮登記の本登記"},{"zh":"有利害关系第三者时须获得其承诺","ja":"利害関係を有する第三者があるときはその承諾が必要"}],[{"zh":"代位申请登记的识别信息通知对象","ja":"代位申請登記の登記識別情報の通知先"},{"zh":"最终登记名义人，不是代位申请人","ja":"最終的な登記名義人——代位申請者ではない"}],[{"zh":"配偶者居住权","ja":"配偶者居住権"},{"zh":"可以登记","ja":"登記できる"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"仮登记的本登记需要利害关系人承诺，跟仮登记的抹消可以单独申请（不需要承诺）是不同的场景，容易混淆。","ja":"仮登記の本登記には利害関係人の承諾が必要——仮登記の抹消は単独申請可能（承諾不要）とは異なる場面であり混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t87', '{"id":"t87","tag":"农地法","title":{"zh":"农地法的身份限定、取得与借入的区别、许可效力、地域特例","ja":"農地法における身分限定・取得と借入の違い・許可の効力・地域特例"},"source":"平成28年 問22","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"继承相关许可豁免","ja":"相続関連の許可免除"},{"zh":"继承/包括遗赠/对继承人的特定遗赠不需要3条许可，对非继承人的特定遗赠依然需要","ja":"相続・包括遺贈・相続人への特定遺贈は3条許可不要、相続人以外への特定遺贈は必要"}],[{"zh":"不适格法人","ja":"要件を満たさない法人"},{"zh":"不能取得所有权，但满足条件可以借入","ja":"所有権は取得不可、要件を満たせば借入は可能"}],[{"zh":"未经许可的农地买卖","ja":"許可を受けない農地売買"},{"zh":"所有权移转不发生效力","ja":"所有権移転の効力は生じない"}],[{"zh":"申报代替许可的特例","ja":"届出で許可に代える特例"},{"zh":"只限市街化区域内，市街化调整区域没有","ja":"市街化区域内に限られ、市街化調整区域にはない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"对非继承人的特定遗赠容易被误以为跟继承一样豁免许可，实际上继承人这个身份限定是关键；市街化调整区域没有申报代替许可的特例，容易被误以为所有区域都能靠申报解决。","ja":"相続人以外への特定遺贈は相続と同様に許可免除と誤解されやすいが、実際は相続人という身分の限定が鍵。市街化調整区域には届出で許可に代える特例はなく、すべての区域で届出だけで済むと誤解されやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t88', '{"id":"t88","tag":"印纸税","title":{"zh":"覚书/仮契约书的课税判断与多项金额记载的三套取值规则","ja":"覚書・仮契約書の課税判断と複数金額記載の3つの取扱いルール"},"source":"平成23年 問23","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"情形","ja":"場面"},{"zh":"取值规则","ja":"取扱いルール"}],"rows":[[{"zh":"覚书/仮契约书（证明契约成立或内容变更补充）","ja":"覚書・仮契約書（契約成立又は内容変更・補充を証する）"},{"zh":"算契约书，须课税","ja":"契約書に該当し課税される"}],[{"zh":"同种契约多项金额","ja":"同種契約の複数金額"},{"zh":"合计相加","ja":"合算する"}],[{"zh":"不同种契约多项金额（如土地讓渡+建筑请负）","ja":"異種契約の複数金額（土地譲渡＋建物請負等）"},{"zh":"取较高者","ja":"高い方を採用"}],[{"zh":"交换契约书（双方都记载金额）","ja":"交換契約書（双方の金額を記載）"},{"zh":"取较高者","ja":"高い方を採用"}],[{"zh":"交换契约书（只记载差额）","ja":"交換契約書（差額のみ記載）"},{"zh":"用差额","ja":"差額を採用"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"以后要另作正式合同这个说法不能让覚书/仮契约书免税；同种契约合计、异种契约取高、交换契约看是否记载双方金额，三套规则容易混着记。","ja":"「後日正式契約を作成する」という記載は覚書・仮契約書の免税事由にならない。同種契約は合算、異種契約は高い方、交換契約は双方記載の有無で判断——3つのルールは混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t89', '{"id":"t89","tag":"宅建业法","title":{"zh":"免许证返还情形・业务停止与更新・法人破产申报・みなし业者","ja":"免許証の返納場面・業務停止と更新・法人破産の届出・みなし業者"},"source":"平成28年 問35","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"免许证返还的情形","ja":"免許証の返納場面"},{"zh":"免许换え、取消、拾获遗失证件、廃业届出——有效期满了不算","ja":"免許換え、取消し、遺失証明書発見、廃業届出——有効期間満了は含まれない"}],[{"zh":"业务停止处分与免许更新","ja":"業務停止処分と免許更新"},{"zh":"处分期间依然可以申请更新","ja":"処分期間中でも更新申請は可能"}],[{"zh":"法人破产的申报义务人","ja":"法人破産の届出義務者"},{"zh":"破产管财人，不是役员","ja":"破産管財人——役員ではない"}],[{"zh":"个人业者死亡后","ja":"個人業者の死亡後"},{"zh":"继承人在取引结了范围内视为宅建业者（みなし业者）","ja":"相続人は取引結了の範囲内で宅建業者とみなされる（みなし業者）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"自然失效（有效期满）容易被误以为跟免许换え/取消一样需要返还证件，实际上不需要。","ja":"自然失効（有効期間満了）は免許換え・取消しと同様に証明書の返納が必要と誤解されやすいが、実際は不要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t90', '{"id":"t90","tag":"宅建业法","title":{"zh":"35条书面——法令上的制限 vs 灾害危险性物件","ja":"35条書面——法令上の制限と災害の危険性がある物件"},"source":"令和2年12月 問32","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"分类","ja":"分類"},{"zh":"说明规则","ja":"説明ルール"},{"zh":"例","ja":"例"}],"rows":[[{"zh":"灾害危险性物件","ja":"災害の危険性がある物件"},{"zh":"不分买卖贷借、宅地建物，一律说明","ja":"売買・貸借、宅地・建物を問わず一律説明"},{"zh":"土砂灾害警戒区域、津波灾害警戒区域、造成宅地防灾区域","ja":"土砂災害警戒区域、津波災害警戒区域、造成宅地防災区域"}],[{"zh":"法令上的制限","ja":"法令上の制限"},{"zh":"建物贷借几乎全部免说明","ja":"建物の貸借はほぼ全て説明不要"},{"zh":"急傾斜地限制、重要文化财讓渡限制、津波防护设施区域限制","ja":"急傾斜地の制限、重要文化財の譲渡制限、津波防護施設区域の制限"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"津波防护设施区域（法令限制，建物贷借免说明）和津波灾害警戒区域（灾害危险物件，不分交易类型都要说明）名字很像但规则不同，是常见出题陷阱。","ja":"津波防護施設区域（法令上の制限、建物貸借は説明不要）と津波災害警戒区域（災害危険性物件、取引種類を問わず説明必要）は名称が似ているがルールが異なり、頻出のひっかけポイント。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t91', '{"id":"t91","tag":"宅建业法","title":{"zh":"37条书面——多业者记名义务・交付双方・自己贷借不算取引","ja":"37条書面——複数業者の記名義務・双方交付・自ら貸借は取引に非該当"},"source":"令和3年12月 問40","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"多个宅建业者关与同一交易时，每个业者都要独立负记名义务","ja":"複数の宅建業者が同一取引に関与する場合、各業者が独立して記名義務を負う"},{"zh":"37条书面须交付契约双方当事人，不只是交给客户","ja":"37条書面は契約当事者双方に交付が必要——顧客だけではない"},{"zh":"自己做买卖算取引，自己做贷借不算取引，媒介/代理不管买卖贷借都算取引","ja":"自ら売買は取引に該当、自ら貸借は取引に非該当、媒介・代理は売買・貸借を問わず取引に該当"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"自己作为贷主/买主的贷借行为不算宅建业法上的取引，容易被误以为跟买卖一样受规制。","ja":"自ら貸主・買主となる貸借行為は宅建業法上の取引に該当しないが、売買と同様に規制を受けると誤解されやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t92', '{"id":"t92","tag":"宅建业法","title":{"zh":"37条书面——买卖贷借共通事项 vs 买卖专属事项","ja":"37条書面——売買・貸借共通事項と売買専属事項"},"source":"平成30年 問34","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"分类","ja":"分類"},{"zh":"事项","ja":"事項"}],"rows":[[{"zh":"共通事项（买卖贷借都要记）","ja":"共通事項（売買・貸借とも記載）"},{"zh":"当事人姓名住所、宅地建物特定表示、代金/借賃額及支付方式、引渡时期","ja":"当事者の氏名住所、宅地建物の特定表示、代金・借賃の額及び支払方法、引渡しの時期"}],[{"zh":"买卖专属事项（贷借不用记）","ja":"売買専属事項（貸借は記載不要）"},{"zh":"移转登记申请时期、契约不适合担保责任、建物构造耐力双方确认事项","ja":"移転登記の申請時期、契約不適合担保責任、建物構造耐力の当事者双方確認事項"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"涉及所有权移转或物件质量担保相关的事项，基本都是买卖专属，贷借用不上，容易被误以为贷借也要记。","ja":"所有権移転や物件の品質担保に関わる事項は基本的に売買専属であり、貸借には不要——貸借にも記載が必要と誤解されやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t93', '{"id":"t93","tag":"宅建业法","title":{"zh":"低廉空家等特例——800万円门槛、33万円上限、只限买卖","ja":"低廉な空家等の特例——800万円基準、33万円上限、売買限定"},"source":"平成30年 問31","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"代金800万円以下（税别）+说明合意+报酬合计不超33万円（税込）+卖买双方均可适用","ja":"代金800万円以下（税別）＋説明・合意＋報酬合計33万円以内（税込）＋売主・買主双方に適用可"},{"zh":"代金超过800万円，退回正常阶梯公式（3%+6万等）","ja":"代金が800万円を超える場合は通常の階段式計算式（3%＋6万等）に戻る"},{"zh":"特例只适用于买卖，不适用贷借（贷借走借賃×月数规则）","ja":"特例は売買にのみ適用——貸借には適用されない（貸借は借賃×月数のルール）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"代金在800万円以内时，容易忘记套用特例、继续用正常公式算出偏低的错误答案；特例不能用在贷借场景。","ja":"代金が800万円以内の場合、特例の適用を忘れて通常計算のまま低い金額を答えてしまいやすい。特例は貸借の場面には使えない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t94', '{"id":"t94","tag":"宅建业法","title":{"zh":"クーリング・オフ告知书面——撤回解除除外条件的完整表述","ja":"クーリング・オフ告知書面——撤回・解除の除外条件の正確な記載"},"source":"平成28年 問44","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"撤回/解除的除外条件是受领引渡且支付全部代金，两个条件须同时满足才失去クーリング・オフ的权利——只写支付全部代金、漏掉受领引渡就是不完整的错误表述。","ja":"撤回・解除の除外条件は「引渡しを受け、かつ、代金全部を支払った」の両方を満たすことが必要——「代金全部を支払った」のみでは記載として不完全であり誤り。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"法定应记载事项要求逐字完整，文字表面看起来差不多对，实际漏掉一个条件就构成错误。","ja":"法定記載事項は逐語的な正確さが求められる——一見似ているようでも条件が一つ欠けていれば誤りとなる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t95', '{"id":"t95","tag":"宅建业法","title":{"zh":"宅建士证更新讲习的指定主体——都道府県知事","ja":"宅建士証更新講習の指定主体——都道府県知事"},"source":"令和4年 問29","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"宅建士证更新须受讲的是都道府県知事指定的讲习，不是国土交通大臣；有效期5年。","ja":"宅建士証の更新講習は都道府県知事が指定するものであり、国土交通大臣ではない。有効期間は5年。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"都道府県知事和国土交通大臣容易在各种由谁指定/由谁颁发的考点里被混用，这跟大臣免许vs知事免许的业者分类是不同概念。","ja":"都道府県知事と国土交通大臣は「誰が指定するか」等の論点で混同されやすいが、大臣免許・知事免許という業者の免許区分とは別の概念。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t96', '{"id":"t96","tag":"住宅瑕疵担保履行法","title":{"zh":"三个易混淆的时间节点——基准日・50日宽限・引渡起10年","ja":"3つの混同しやすい時点——基準日・50日の猶予・引渡しから10年"},"source":"平成24年 問45","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"申报期限起算点","ja":"届出期限の起算点"},{"zh":"基准日（毎年3月31日），不是引渡日","ja":"基準日（毎年3月31日）——引渡しの日ではない"}],[{"zh":"未申报的宽限期","ja":"未届出の猶予期間"},{"zh":"基准日翌日起算50日","ja":"基準日の翌日から起算して50日"}],[{"zh":"保险有效期起算点","ja":"保険契約の有効期間の起算点"},{"zh":"引渡时起10年，不是契约締結日起5年","ja":"引渡し時から10年——契約締結日から5年ではない"}],[{"zh":"供托所说明时点","ja":"供託所の説明時期"},{"zh":"契约缔结前，不是引渡前","ja":"契約締結前——引渡し前ではない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"这几个时间点在历年真题里反复出题、反复被替换成错误的数字/起算点，是宅建业法这块的重灾区，务必分开准确记忆。","ja":"これらの時点は過去問で繰り返し出題され、誤った数字・起算点にすり替えられやすい——宅建業法の頻出の罠であり、正確に区別して覚える必要がある。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t97', '{"id":"t97","tag":"民法","title":{"zh":"占有制度四细节——成立要件・推定规定・占有代理人・特定承继人","ja":"占有制度の4つの細部——成立要件・推定規定・占有代理人・特定承継人"},"source":"平成27年 問5","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"占有的成立不要求物理上锁，持续监视/实际控制也算占有","ja":"占有の成立に施錠は不要——継続的な監視・事実的支配も占有に当たる"},{"zh":"民法188条推定只管权利适法，不管权利变动","ja":"民法188条の推定は権利の適法性のみ——権利変動は推定しない"},{"zh":"占有代理人同样享有占有保护请求权（占有保持之诉）","ja":"占有代理人も占有保護請求権（占有保持の訴え）を有する"},{"zh":"占有回收之诉对特定承继人，只有恶意时才能提起，不是当然可以","ja":"占有回収の訴えは特定承継人に対しては悪意の場合に限り提起可——当然にではない"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"跟h25-4留置权题里占有开始需合法是不同但相关的占有法知识点，可以对照记忆整个占有制度体系。","ja":"h25-4の留置権（占有開始の適法性）とは異なるが関連する論点であり、占有制度全体を対照して覚えるとよい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t98', '{"id":"t98","tag":"民法","title":{"zh":"意思表示瑕疵四类型——效力与对抗要件对照表","ja":"意思表示の瑕疵4類型——効力と対抗要件の対照表"},"source":"令和7年 問3","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"类型","ja":"類型"},{"zh":"效力","ja":"効力"},{"zh":"对抗要件","ja":"対抗要件"}],"rows":[[{"zh":"心裡留保","ja":"心裡留保"},{"zh":"原则有效，相对方明知/可得而知则无效","ja":"原則有効——相手方が知り又は知り得たときは無効"},{"zh":"—","ja":"—"}],[{"zh":"虚偽表示","ja":"虚偽表示"},{"zh":"无效","ja":"無効"},{"zh":"不能对抗善意第三人（不问过失）","ja":"善意の第三者に対抗できない（過失は無関係）"}],[{"zh":"错误（重要）","ja":"錯誤（重要なもの）"},{"zh":"可撤销（不是无效）","ja":"取消し可能（無効ではない）"},{"zh":"不能对抗善意无过失第三人","ja":"善意無過失の第三者に対抗できない"}],[{"zh":"诈欺","ja":"詐欺"},{"zh":"可撤销","ja":"取消し可能"},{"zh":"不能对抗撤销前善意无过失第三人","ja":"取消し前の善意無過失の第三者に対抗できない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"错误在新民法改正后是取消不是无效，容易用旧知识误答；虚偽表示的善意第三人保护不问过失，容易被加上不存在的过失条件。","ja":"錯誤は改正民法下では取消しであり無効ではない——旧知識で誤答しやすい。虚偽表示の善意第三者保護は過失を問わない——存在しない過失要件を付け加える出題に注意。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t99', '{"id":"t99","tag":"民法","title":{"zh":"代理权濫用・双方代理・代理权消滅事由的时间顺序","ja":"代理権の濫用・双方代理・代理権消滅事由の時系列"},"source":"平成30年 問2","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"代理权濫用/双方代理","ja":"代理権の濫用・双方代理"},{"zh":"视为无权代理（不是无效），本人许诺时有效","ja":"無権代理とみなされる（無効ではない）——本人の許諾があれば有効"}],[{"zh":"先有欠格（补助审判）后授权","ja":"先に欠格（補助審判）、後に授権"},{"zh":"有效取得代理权（代理人不要求行为能力）","ja":"有効に代理権を取得（代理人に行為能力は不要）"}],[{"zh":"先授权后有欠格（后见开始审判）","ja":"先に授権、後に欠格（後見開始審判）"},{"zh":"代理权消灭，之后行为构成无权代理","ja":"代理権消滅——その後の行為は無権代理"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"补助开始审判和后见开始审判在授权前后发生，法律效果完全不同，要看时间顺序。","ja":"補助開始審判と後見開始審判は授権の前後で法的効果がまったく異なり、時系列を確認する必要がある。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t100', '{"id":"t100","tag":"民法","title":{"zh":"四种辞任制度——许可机关统一为家庭裁判所","ja":"4つの辞任制度——許可機関は家庭裁判所で統一"},"source":"令和4年 問9","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"身份","ja":"立場"},{"zh":"辞任许可要件","ja":"辞任の許可要件"}],"rows":[[{"zh":"受托代理人（委任）","ja":"受任者（委任）"},{"zh":"无需许可，随时可解除","ja":"許可不要——いつでも解除可能"}],[{"zh":"亲权者","ja":"親権者"},{"zh":"须经家庭裁判所许可","ja":"家庭裁判所の許可が必要"}],[{"zh":"后见人","ja":"後見人"},{"zh":"须经家庭裁判所许可","ja":"家庭裁判所の許可が必要"}],[{"zh":"遗言执行者","ja":"遺言執行者"},{"zh":"须经家庭裁判所许可","ja":"家庭裁判所の許可が必要"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"选项常把许可主体换成法务局/后见监督人/相续人，真正的许可方永远是家庭裁判所。","ja":"選択肢は許可主体を法務局・後見監督人・相続人にすり替えることが多いが、真の許可権者は常に家庭裁判所。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t101', '{"id":"t101","tag":"民法","title":{"zh":"抵当权效力及于借地赁借权（对比留置权不及于敷地）","ja":"抵当権の効力は敷地の賃借権に及ぶ（留置権が敷地に及ばないのと対比）"},"source":"平成25年 問5","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"赁料债权物上代位，同样要求被担保债权弁済期已到来","ja":"賃料債権への物上代位も被担保債権の弁済期到来が必要"},{"zh":"借地上建筑物的抵当权效力及于敷地赁借权（民法370条，最判昭40.5.4）","ja":"借地上建物の抵当権の効力は敷地の賃借権にも及ぶ（民法370条、最判昭40.5.4）"},{"zh":"抵当权人可代位行使设定者对不法占有者的妨害排除请求权","ja":"抵当権者は設定者の不法占有者への妨害排除請求権を代位行使できる"},{"zh":"抵当权顺位登记后依然可以合意变更","ja":"抵当権の順位は登記後も合意により変更可能"}]}]},{"heading":"易错陷阱（对比记忆）","blocks":[{"type":"trap","content":{"zh":"留置权不延伸到第三者所有的敷地（h25-4），但抵当权延伸到借地赁借权（h25-5）——两者结论相反，容易混淆，建议对照复习。","ja":"留置権は第三者所有の敷地には及ばない（h25-4）が、抵当権は借地の賃借権に及ぶ（h25-5）——結論が逆であり混同しやすい。対照して復習するとよい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t102', '{"id":"t102","tag":"民法","title":{"zh":"保证责任的范围——覆盖赁贷借关系产生的一切债务","ja":"保証責任の範囲——賃貸借関係から生じる債務全般"},"source":"平成25年 問7","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"有期限建筑物赁贷借的保证人，原则上对更新后产生的承租人债务同样负责，不需要更新时重新确认保证意思，但两个例外：有相反特殊情形、房东追及责任违反信义则时不负责。保证责任覆盖赁贷借关系产生的一切债务，不只是欠租，含故意/过失损坏建筑物的损害赔偿。","ja":"期間の定めのある建物賃貸借の保証人は、原則として更新後の賃借人の債務も保証する——更新時の再確認は不要。例外は特段の事情がある場合と、賃貸人の請求が信義則に反する場合。保証責任は賃貸借関係から生じる債務全般に及び、未払賃料だけでなく故意・過失による建物損傷の損害賠償も含む。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"容易把保证责任范围局限在欠租上，忽略损害赔偿债务也在覆盖范围内。","ja":"保証責任の範囲を未払賃料に限定しがちだが、損害賠償債務も範囲に含まれる点を見落としやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t103', '{"id":"t103","tag":"借地借家法","title":{"zh":"借地权契约方式与期限规则综合","ja":"借地権契約の方式・期間ルール総合"},"source":"平成30年 問11 / 令和5年 問11","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"正确规则","ja":"正しいルール"}],"rows":[[{"zh":"公正证书要求","ja":"公正証書の要否"},{"zh":"只有事业用定期借地权需要，普通借地权不需要","ja":"事業用定期借地権のみ必要——普通借地権は不要"}],[{"zh":"定期借地权类型选择","ja":"定期借地権の類型選択"},{"zh":"看用途是不是居住用，居住用只能一般定期借地权","ja":"用途が居住用かどうかで判断——居住用は一般定期借地権のみ"}],[{"zh":"存续期间不满30年/不许更新","ja":"存続期間30年未満・更新不可の定め"},{"zh":"对借地人不利，一律无效","ja":"借地権者に不利な特約として無効"}],[{"zh":"地代不减额特约","ja":"地代の不減額特約"},{"zh":"无效（不增额特约有效）","ja":"無効（不増額特約は有効）"}],[{"zh":"建物买取请求权","ja":"建物買取請求権"},{"zh":"只在期间满了终了时适用，债务不履行解除不适用","ja":"期間満了による終了時のみ適用——債務不履行解除には不適用"}],[{"zh":"对抗要件的替代（登记建物）","ja":"対抗要件の代替（建物登記）"},{"zh":"登记名义人必须是借地权人本人","ja":"登記名義人は借地権者本人でなければならない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"事业用途容易被直接联想成事业用定期借地权，忽略居住性质（如出租公寓）实际只能用一般定期借地权。","ja":"事業用途と見ると事業用定期借地権を連想しがちだが、居住性質（賃貸アパート等）は一般定期借地権しか使えない点に注意。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t104', '{"id":"t104","tag":"建筑基準法","title":{"zh":"用途制限的过半主义 vs 建蔽率容积率的加重平均主义","ja":"用途制限の過半主義と建蔽率・容積率の加重平均主義"},"source":"令和3年12月 問18","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"判断规则","ja":"判断ルール"}],"rows":[[{"zh":"用途制限","ja":"用途制限"},{"zh":"按基地过半所属地域决定（过半主义）","ja":"敷地の過半が属する地域で決定（過半主義）"}],[{"zh":"建蔽率/容积率","ja":"建蔽率・容積率"},{"zh":"按各地域面积比例加权平均（加重平均主义）","ja":"各地域の面積比で加重平均（加重平均主義）"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"容易把建蔽率也当成过半主义处理，实际建蔽率/容积率是加重平均，只有用途制限才是过半主义。","ja":"建蔽率も過半主義で判断しがちだが、実際は加重平均——過半主義なのは用途制限のみ。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t105', '{"id":"t105","tag":"民法","title":{"zh":"相殺制度四细节——弁済期・不法行为债权方向性・时效消滅・差押前后","ja":"相殺制度の4つの細部——弁済期・不法行為債権の方向性・時効消滅・差押の前後"},"source":"平成16年 問8","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"自働债权须已到弁済期，敷金返还请求权赁贷借终了前不存在这个弁済期","ja":"自働債権は弁済期到来が必要——敷金返還請求権は賃貸借終了前は弁済期にない"},{"zh":"恶意不法行为损害赔偿债权不能做受働债权，但能做自働债权（方向性）","ja":"悪意不法行為の損害賠償債権は受働債権にできないが、自働債権にはできる（方向性に注意）"},{"zh":"时效消滅的债权，消滅前处于相殺适状时依然可以相殺","ja":"時効消滅した債権も、消滅前に相殺適状にあれば相殺できる"},{"zh":"反对债权差押前取得的，可对抗差押（不问弁済期先后）","ja":"反対債権が差押前に取得されていれば差押に対抗できる（弁済期の先後は問わない）"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"不法行为债权能否做自働/受働债权的方向性最容易搞反。","ja":"不法行為債権を自働・受働債権にできるかの方向性が最も混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t106', '{"id":"t106","tag":"民法","title":{"zh":"使用者责任综合——连带相对效・慰藉料继承・求偿限制・过失相殺","ja":"使用者責任総合——連帯相対効・慰謝料相続・求償制限・過失相殺"},"source":"平成24年 問9","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"使用者和被用者的赔偿债务是连带债务、相对效","ja":"使用者と被用者の賠償債務は連帯債務・相対効"},{"zh":"即死被害人的慰藉料请求权同样可以被继承","ja":"即死の被害者の慰謝料請求権も相続できる"},{"zh":"使用者对被用者的求偿受信义则限制，不是全额保证能拿回","ja":"使用者から被用者への求償は信義則上相当な限度に制限される"},{"zh":"过失相殺看被害者側（含监护人），幼儿本身无过失不代表不能相殺","ja":"過失相殺は被害者側（保護者等含む）を考慮——幼児本人に過失がなくても相殺され得る"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"容易以为幼儿受害就绝对不能过失相殺，实际上被害者側的过失依然要考虑。","ja":"幼児が被害者だから過失相殺は一切考慮されないと誤解しやすいが、被害者側の過失は考慮される。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t107', '{"id":"t107","tag":"民法","title":{"zh":"赁贷借 vs 使用贷借——转贷・解约返还・对抗力・相续系统对照","ja":"賃貸借と使用貸借——転貸・解約返還・対抗力・相続の系統的対照"},"source":"平成21年 問12","sections":[{"heading":"对照表","blocks":[{"type":"table","headers":[{"zh":"维度","ja":"側面"},{"zh":"赁贷借（有偿）","ja":"賃貸借（有償）"},{"zh":"使用贷借（无偿）","ja":"使用貸借（無償）"}],"rows":[[{"zh":"无断转贷","ja":"無断転貸"},{"zh":"无背信情形不能解除","ja":"背信性なければ解除不可"},{"zh":"可以解除","ja":"解除可能"}],[{"zh":"解约/返还","ja":"解約・返還"},{"zh":"须正当事由","ja":"正当事由が必要"},{"zh":"约定使用目的时须等客观期间经过","ja":"使用目的の定めがあれば客観的期間経過まで不可"}],[{"zh":"对抗力","ja":"対抗力"},{"zh":"受领引渡即可对抗新所有者","ja":"引渡しを受ければ新所有者に対抗可"},{"zh":"无对抗方法","ja":"対抗手段なし"}],[{"zh":"借用人死亡","ja":"借主の死亡"},{"zh":"不终止，可被继承","ja":"終了せず、相続される"},{"zh":"当然终止，不被继承","ja":"当然に終了し、相続されない"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"使用贷借没约定返还时期≠随时能要回，若约定了使用目的，须等客观期间经过。","ja":"使用貸借で返還時期の定めがない＝いつでも返還請求できる、ではない——使用目的の定めがあれば客観的期間の経過が必要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t108', '{"id":"t108","tag":"区分所有法","title":{"zh":"规约的保管・阅览・保管场所公示三件事","ja":"規約の保管・閲覧・保管場所の掲示の3つの義務"},"source":"平成19年 問15","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"事项","ja":"事項"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"保管","ja":"保管"},{"zh":"管理者（无管理者时按规约/决议指定）","ja":"管理者（いないときは規約・決議で定める者）"}],[{"zh":"阅览","ja":"閲覧"},{"zh":"利害关系人请求，无正当理由不能拒绝","ja":"利害関係人の請求——正当理由なければ拒否不可"}],[{"zh":"保管场所","ja":"保管場所"},{"zh":"建筑物内显眼处掲示，不要求個別通知","ja":"建物内の見やすい場所に掲示——個別通知は不要"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"保管场所只需要掲示，选项常凭空加上通知这个不存在的义务。","ja":"保管場所は掲示のみで足り、選択肢は存在しない「通知」義務を付け加えることが多い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t109', '{"id":"t109","tag":"不动产登记法","title":{"zh":"单独申请例外场景——按表示登记/权利登记分类","ja":"単独申請の例外場面——表示登記・権利登記別分類"},"source":"令和3年10月 問14","sections":[{"heading":"分类表","blocks":[{"type":"table","headers":[{"zh":"类型","ja":"類型"},{"zh":"场景","ja":"場面"},{"zh":"能否单独申请","ja":"単独申請の可否"}],"rows":[[{"zh":"表示登记","ja":"表示登記"},{"zh":"新产生土地/无表题登记土地的表题登记","ja":"新たに生じた土地・表題登記のない土地の表題登記"},{"zh":"可以","ja":"可"}],[{"zh":"表示登记","ja":"表示登記"},{"zh":"区分建物新建，原所有者已死亡，继承人申请","ja":"区分建物新築時、旧所有者死亡後の相続人申請"},{"zh":"可以","ja":"可"}],[{"zh":"权利登记","ja":"権利登記"},{"zh":"所有权保存登记（无移转登记时）","ja":"所有権保存登記（移転登記なし）"},{"zh":"可以","ja":"可"}],[{"zh":"权利登记","ja":"権利登記"},{"zh":"所有权抹消登记（有移转登记时）","ja":"所有権抹消登記（移転登記あり）"},{"zh":"不可以","ja":"不可"}],[{"zh":"权利登记","ja":"権利登記"},{"zh":"所有权抹消登记（无移转登记时）","ja":"所有権抹消登記（移転登記なし）"},{"zh":"可以","ja":"可"}],[{"zh":"权利登记","ja":"権利登記"},{"zh":"法人合并的权利移转登记","ja":"法人合併による権利移転登記"},{"zh":"可以","ja":"可"}],[{"zh":"权利登记","ja":"権利登記"},{"zh":"信托登记","ja":"信託の登記"},{"zh":"可以（受托者单独）","ja":"可（受託者単独）"}],[{"zh":"权利登记","ja":"権利登記"},{"zh":"仮登记（义务者承诺时）","ja":"仮登記（義務者の承諾がある場合）"},{"zh":"可以","ja":"可"}],[{"zh":"权利登记","ja":"権利登記"},{"zh":"仮登记的抹消","ja":"仮登記の抹消"},{"zh":"可以","ja":"可"}],[{"zh":"权利登记","ja":"権利登記"},{"zh":"判决取得的登记","ja":"判決による登記"},{"zh":"可以（胜诉方单独）","ja":"可（勝訴者単独）"}]]}]},{"heading":"记忆口诀","blocks":[{"type":"mnemonic","content":{"zh":"默认规则是共同申请，但只要满足①对方已经不存在对立利益（法人合并、信托受托者本身、判决已经确定）或②这本来就是单方义务性登记（表题登记、无移转的保存/抹消），就可以单独申请。","ja":"デフォルトは共同申請だが、①相手方に対立利益がもはや存在しない（法人合併、信託受託者本人、判決確定済み）、②本来単独の義務的登記である（表題登記、移転を伴わない保存・抹消）のいずれかを満たせば単独申請が可能。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"登记申请代理人的权限不因本人死亡而消滅，这是不动产登记法对民法一般规则的特例覆盖，容易用民法101条的一般规则误答。","ja":"登記申請代理人の権限は本人の死亡によって消滅しない——これは不動産登記法が民法101条の一般原則に優先する特例であり、一般原則で誤答しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t110', '{"id":"t110","tag":"农地法","title":{"zh":"农地赁贷借对抗要件・原状回复命令对象范围・面积认定","ja":"農地賃貸借の対抗要件・原状回復命令の対象範囲・面積認定"},"source":"令和4年 問21","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"农地赁贷借凭引渡对抗第三人，使用贷借没有这个特例","ja":"農地賃貸借は引渡しで第三者に対抗可——使用貸借にはこの特例なし"},{"zh":"农地所有适格法人以外的法人不能所有但可以借入农地（历年高频重复选项）","ja":"農地所有適格法人以外の法人は所有不可だが借入は可能（頻出の繰り返し選択肢）"},{"zh":"原状回复命令对象含工程承包人/下承包人，不限于转用行为人本身","ja":"原状回復命令の対象には工事請負人・下請人も含まれ、転用行為者本人に限られない"},{"zh":"土地面积原则依登记簿地积，例外时依实测+农委会认定","ja":"土地面積は原則登記簿の地積、例外時は実測+農業委員会の認定による"}]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"农地所有适格法人以外的法人不能借入农地这个错误选项已反复出现三次（R04-21、H30-22、H28-22），是最经典的重复陷阱。","ja":"「借入不可」という誤った選択肢はR04-21・H30-22・H28-22で3回繰り返し出題されている最も典型的な罠。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t111', '{"id":"t111","tag":"税相关法令","title":{"zh":"税相关法令常考数字速查表（不动产取得税/登録免许税/印纸税/赠与税/所得税/报酬）","ja":"税関連法令の頻出数字一覧（不動産取得税・登録免許税・印紙税・贈与税・所得税・報酬）"},"source":"平成16年 問26（综合整理）","sections":[{"heading":"不动产取得税","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"数字/规则","ja":"数字・ルール"}],"rows":[[{"zh":"征税主体","ja":"課税主体"},{"zh":"都道府県税（不是市町村税）","ja":"都道府県税（市町村税ではない）"}],[{"zh":"宅地课税标准","ja":"宅地の課税標準"},{"zh":"宅地价格×1/2","ja":"宅地価格×1/2"}],[{"zh":"免税点（土地）","ja":"免税点（土地）"},{"zh":"16万円未满","ja":"16万円未満"}],[{"zh":"免税点（建筑・新建）","ja":"免税点（家屋・建築）"},{"zh":"每户66万円未满","ja":"1戸につき66万円未満"}],[{"zh":"免税点（建筑・其他）","ja":"免税点（家屋・その他）"},{"zh":"每户34万円未满","ja":"1戸につき34万円未満"}],[{"zh":"相邻土地合并判定期限","ja":"隣接地の合算判定期限"},{"zh":"1年内取得相邻土地须合并计算","ja":"1年以内に隣接地取得で合算"}],[{"zh":"新住宅控除额","ja":"新築住宅の控除額"},{"zh":"1,200万円","ja":"1,200万円"}],[{"zh":"新住宅控除面积区间","ja":"控除対象の床面積"},{"zh":"40㎡~240㎡","ja":"40㎡~240㎡"}],[{"zh":"家屋みなし取得期限","ja":"家屋のみなし取得"},{"zh":"新建后6个月未使用/未讓渡即视为取得","ja":"新築後6か月経過で取得とみなす"}]]}]},{"heading":"登録免许税・印纸税・赠与税・所得税・报酬","blocks":[{"type":"table","headers":[{"zh":"税种/制度","ja":"税目・制度"},{"zh":"关键数字/规则","ja":"重要な数字・ルール"}],"rows":[[{"zh":"登録免许税・住宅家屋减轻・面积","ja":"登録免許税・住宅家屋軽減・面積"},{"zh":"50㎡以上，可反复适用，只限家屋不含土地","ja":"50㎡以上、繰り返し適用可、家屋のみ土地含まず"}],[{"zh":"印纸税・同种契约多项金额","ja":"印紙税・同種契約の複数金額"},{"zh":"合计相加","ja":"合算"}],[{"zh":"印纸税・不同种契约/交换契约（双方记载）","ja":"印紙税・異種契約/交換契約（双方記載）"},{"zh":"取较高者","ja":"高い方を採用"}],[{"zh":"印纸税・交换契约（只记载差额）","ja":"印紙税・交換契約（差額のみ記載）"},{"zh":"用差额","ja":"差額を採用"}],[{"zh":"赠与税・住宅资金特例・受赠者所得","ja":"贈与税・住宅資金特例・受贈者所得"},{"zh":"2,000万円以下，赠与者年龄无限制","ja":"2,000万円以下、贈与者の年齢制限なし"}],[{"zh":"所得税・继承取得资产讓渡","ja":"所得税・相続取得資産の譲渡"},{"zh":"承继被继承人的取得费和取得时点","ja":"被相続人の取得費・取得時期を引き継ぐ"}],[{"zh":"宅建业法报酬・低廉空家特例","ja":"宅建業法報酬・低廉空家特例"},{"zh":"代金800万円以下（现行法），上限33万円（税込），只限买卖","ja":"代金800万円以下（現行法）、上限33万円（税込）、売買限定"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"各税种的免税点、控除额、面积区间数字容易相互混淆（如不动产取得税的16万/66万/34万），建议按税种分类单独记忆，不要交叉混用。","ja":"各税目の免税点・控除額・面積区間の数字は混同しやすい（不動産取得税の16万・66万・34万等）——税目ごとに分類して個別に覚え、混同しないようにする。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t112', '{"id":"t112","tag":"宅建业法","title":{"zh":"宅地贷借≠建物贷借——法令上制限说明义务的例外事项","ja":"宅地の貸借≠建物の貸借——法令上の制限説明義務の例外事項"},"source":"平成27年 問31","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"法令上的制限说明豁免只针对建物贷借，宅地贷借依然要按一般规则说明；建物贷借的免说明也不是绝对的，新住宅市街地开发法32条1项的使用收益权限制是明文列举的例外，即使是建物贷借也要说明。","ja":"法令上の制限の説明免除は建物の貸借のみに適用され、宅地の貸借は一般規則どおり説明が必要。建物の貸借の説明免除も絶対ではなく、新住宅市街地開発法32条1項の使用収益権制限は明文の例外として、建物の貸借でも説明が必要。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"针对建造行为的规制（如准防火地域内建筑构造规制），对已建成建物的贷借没有实际意义，不需要说明——规制性质决定说明必要性。","ja":"建築行為を対象とする規制（準防火地域内の建築構造規制等）は、既存建物の貸借には実益がなく説明不要——規制の性質が説明の要否を決める。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t113', '{"id":"t113","tag":"宅建业法","title":{"zh":"35条书面 vs 37条书面记载事项对照表","ja":"35条書面と37条書面の記載事項対照表"},"source":"平成29年 問38","sections":[{"heading":"基本定位区别","blocks":[{"type":"table","headers":[{"zh":"文件","ja":"書面"},{"zh":"性质","ja":"性質"},{"zh":"交付时点","ja":"交付時期"}],"rows":[[{"zh":"35条书面（重要事项说明书）","ja":"35条書面（重要事項説明書）"},{"zh":"缔约前告知风险","ja":"契約前のリスク説明"},{"zh":"契约缔结前","ja":"契約締結前"}],[{"zh":"37条书面（契约内容确认书）","ja":"37条書面（契約内容確認書）"},{"zh":"确认契约条款本身","ja":"契約条項自体の確認"},{"zh":"契约成立后遅滞なく","ja":"契約成立後遅滞なく"}]]}]},{"heading":"记载事项对照","blocks":[{"type":"table","headers":[{"zh":"事项","ja":"事項"},{"zh":"35条书面","ja":"35条書面"},{"zh":"37条书面","ja":"37条書面"}],"rows":[[{"zh":"手付金等保全措施的概要/内容","ja":"手付金等の保全措置の概要・内容"},{"zh":"记载事项","ja":"記載事項"},{"zh":"不是记载事项","ja":"記載事項ではない"}],[{"zh":"代金/借賃的额及支付时期方法","ja":"代金・借賃の額及び支払時期・方法"},{"zh":"—","ja":"—"},{"zh":"共通必要记载事项","ja":"共通の必要的記載事項"}],[{"zh":"契约解除相关定め","ja":"契約解除に関する定め"},{"zh":"记载事项（有约定时）","ja":"記載事項（定めがある場合）"},{"zh":"任意记载事项（有约定时）","ja":"任意的記載事項（定めがある場合）"}],[{"zh":"契约不适合担保责任特约","ja":"契約不適合担保責任の特約"},{"zh":"记载事项（有约定时）","ja":"記載事項（定めがある場合）"},{"zh":"任意记载事项（有约定时，不因对方是业者而免除）","ja":"任意的記載事項（業者相手でも免除されない）"}],[{"zh":"对业者相对方能否省略","ja":"業者相手への省略可否"},{"zh":"部分说明事项可省略","ja":"一部説明事項は省略可"},{"zh":"不能省略，一律记载","ja":"省略不可、一律記載"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"手付金等保全措施容易被误以为也要写进37条书面，实际上这只是35条书面的记载事项；37条书面对业者相对方不能像35条书面那样省略部分记载内容，这是两份文件对待专业相对方态度不同的关键区别。","ja":"手付金等の保全措置は37条書面にも記載が必要と誤解しやすいが、実際は35条書面の記載事項に限られる。37条書面は業者相手でも35条書面のように一部省略できない——専門的な相手方への扱いが異なる点が両書面の重要な違い。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t110b', '{"id":"t110b","tag":"民法","title":{"zh":"保证关系的单向传导——附从性 vs 相対効","ja":"保証関係の一方向的連動——付従性と相対効"},"source":"平成20年 問6","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"主债务人的事由（履行请求、免除、时効完成）会因附从性传导给保证人（457条明文规定）；保证人自己的事由不会反向传导给主债务人（458条準用441条相対効原则，因为保证人没有负担部分）。","ja":"主債務者の事由（履行請求・免除・時効完成）は付従性により保証人に連動する（457条明文）が、保証人自身の事由は主債務者に逆連動しない（458条準用441条の相対効原則——保証人には負担部分がないため）。"}}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"容易忽略连带债务人之间是完全独立的相対効，跟保证关系的单向传导规则搞混。","ja":"連帯債務者間は完全に独立した相対効であることを見落とし、保証関係の一方向的連動ルールと混同しやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t111b', '{"id":"t111b","tag":"民法","title":{"zh":"共有物的保存行为 vs 损害赔偿请求","ja":"共有物の保存行為と損害賠償請求"},"source":"平成18年 問4","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"行为","ja":"行為"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"不法占有明渡请求","ja":"不法占有の明渡請求"},{"zh":"保存行为，可单独主张全部","ja":"保存行為——単独で全部請求可"}],[{"zh":"不法占有损害赔偿请求","ja":"不法占有の損害賠償請求"},{"zh":"非保存行为，只能按持分比例单独请求","ja":"保存行為ではない——持分割合に応じてのみ単独請求可"}]]}]},{"heading":"易错陷阱","blocks":[{"type":"trap","content":{"zh":"容易把损害赔偿请求也当成保存行为，误以为可以单独请求全额。","ja":"損害賠償請求も保存行為と誤解し、全額を単独請求できると誤りやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t112b', '{"id":"t112b","tag":"民法","title":{"zh":"买卖契约综合——手付解除、买戻特约、他人物买卖、契约不适合担保责任例外","ja":"売買契約総合——手付解除・買戻特約・他人物売買・契約不適合担保責任の例外"},"source":"令和3年12月 問4","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"手付解除的判断基准是相对方着手履行，不是交付目的物","ja":"手付解除の基準は相手方の履行の着手であり、目的物の引渡しではない"},{"zh":"买戻特约没约定期间时退回法定5年，不是特约整体无效","ja":"買戻特約に期間の定めがない場合は法定5年に戻る——特約全体が無効になるわけではない"},{"zh":"他人物买卖契约本身有效（跟r06-1同一考点）","ja":"他人物売買契約自体は有効（r06-1と同一論点）"},{"zh":"卖方明知不适合却隐瞒时，1年内通知期限不适用","ja":"売主が不適合を知りながら隠していた場合、1年以内の通知期限は適用されない"}]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t113b', '{"id":"t113b","tag":"借地借家法","title":{"zh":"解约申告正当事由——立退料只是辅助因素","ja":"解約申入れの正当事由——立退料はあくまで補助的要素"},"source":"平成28年 問12","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"房东解约申告须有正当事由，立退料（财产给付）只是补充性考量因素，房东自身使用必要性才是核心要素。","ja":"貸主の解約申入れには正当事由が必要——立退料（財産給付）は補充的考慮要素にすぎず、貸主自身の使用の必要性こそが核心要素。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t114b', '{"id":"t114b","tag":"不动产登记法","title":{"zh":"仮登记单独申请 vs 仮登记本登记的利害关系人承诺","ja":"仮登記の単独申請と仮登記本登記の利害関係人承諾"},"source":"平成20年 問16","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"场景","ja":"場面"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"仮登记本身的申请","ja":"仮登記自体の申請"},{"zh":"义务者承诺后权利者可单独申请","ja":"義務者の承諾があれば権利者は単独申請可"}],[{"zh":"仮登记的本登记","ja":"仮登記の本登記"},{"zh":"须获利害关系第三者承诺","ja":"利害関係第三者の承諾が必要"}]]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t115b', '{"id":"t115b","tag":"都市计画法","title":{"zh":"农林渔业用建筑物豁免的双重限定","ja":"農林漁業用建築物免除の二重限定"},"source":"平成15年 問18","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"农林渔业用建筑物豁免须同时满足市街化区域以外+确属法定列举的建筑物类型（畜舎、温室、干燥场等），加工设施不算。这跟公益上必要建筑物（图书馆/公民馆，不看区域规模）是不同的豁免类型。","ja":"農林漁業用建築物の免除は市街化区域以外＋法定列挙の建築物類型（畜舎・温室・乾燥場等）の両方を満たす必要があり、加工施設は該当しない。公益上必要な建築物（図書館・公民館、区域規模を問わない）とは異なる免除類型。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t116b', '{"id":"t116b","tag":"土地区画整理法","title":{"zh":"民间施行没有施行区域地域限定（第二例）","ja":"民間施行には施行区域の地域限定がない（第2例）"},"source":"平成12年 問21","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"只有公的施行才限定在施行区域内，民间施行（个人、组合、区划整理会社）没有这个地域限定，包括市街化调整区域都可以施行——跟h24-21是同一考点，历年反复出题。","ja":"施行区域に限定されるのは公的施行のみ——民間施行（個人・組合・区画整理会社）にはこの地域限定がなく、市街化調整区域でも施行可能。h24-21と同一論点であり、過去に繰り返し出題されている。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t117b', '{"id":"t117b","tag":"农地法","title":{"zh":"5条许可的一站式性质","ja":"5条許可の一本化された性質"},"source":"平成22年 問22","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"权利移动+转用同时发生的场景（如转用为宅地），农地法设计了5条许可这一个统一制度，不能拆成3条+4条两道许可分别申请。","ja":"権利移動と転用が同時に発生する場面（宅地への転用等）には、農地法が5条許可という一本化された制度を用意しており、3条＋4条の2つに分けて申請することはできない。"}}]},{"heading":"关联规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"法人违反4条有两罚规定（行为人+法人都罚）","ja":"法人が4条に違反した場合は両罰規定（行為者＋法人）"},{"zh":"农地赁贷借存续期间2020年改正后延长到50年","ja":"農地賃貸借の存続期間は2020年改正で50年に延長"}]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t118b', '{"id":"t118b","tag":"登録免许税","title":{"zh":"登録免许税四要素——税率/课税标准/纳期限/纳税义务人","ja":"登録免許税の4要素——税率・課税標準・納期限・納税義務者"},"source":"平成14年 問27","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"要素","ja":"要素"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"税率","ja":"税率"},{"zh":"按登记原因不同而不同（相続/合并4/1000、买卖10/1000）","ja":"登記原因により異なる（相続・合併4/1000、売買10/1000）"}],[{"zh":"课税标准","ja":"課税標準"},{"zh":"固定资产课税台帳价额，不是实际成交价","ja":"固定資産課税台帳の価額——実際の成約価格ではない"}],[{"zh":"纳期限","ja":"納期限"},{"zh":"登记申请手续时","ja":"登記の申請手続の時"}],[{"zh":"纳税义务人","ja":"納税義務者"},{"zh":"取得者（买方），不是讓渡人","ja":"取得者（買主）——譲渡人ではない"}]]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t119b', '{"id":"t119b","tag":"固定资产税","title":{"zh":"固定资产税四细节——不服申立通道/调查主体/阅览权/独立行政法人免税","ja":"固定資産税の4つの細部——不服申立ルート・調査主体・閲覧権・独立行政法人の非課税"},"source":"平成23年 問24","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"减免不许可不服申立","ja":"減免不許可の不服申立"},{"zh":"向市町村长（不是评价审查委员会）","ja":"市町村長へ（評価審査委員会ではない）"}],[{"zh":"价格不服申立","ja":"価格の不服申立"},{"zh":"向固定资产评价审查委员会","ja":"固定資産評価審査委員会へ"}],[{"zh":"实地调查主体","ja":"実地調査の主体"},{"zh":"固定资产评价员/补助员（不是不动产鉴定士）","ja":"固定資産評価員・評価補助員（不動産鑑定士ではない）"}],[{"zh":"赁借人阅览权","ja":"賃借人の閲覧権"},{"zh":"可阅览与自己权利相关的部分","ja":"自己の権利に関連する部分を閲覧可"}],[{"zh":"独立行政法人免税","ja":"独立行政法人の非課税"},{"zh":"限定列举，不是全部免税","ja":"限定列挙——すべてが非課税ではない"}]]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t120b', '{"id":"t120b","tag":"宅建业法","title":{"zh":"信托受益权说明豁免与宅地买卖法令限制说明","ja":"信託受益権の説明免除と宅地売買の法令制限説明"},"source":"令和7年 問43","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"信托受益权销售时，若目论见书已含全部法定说明事项，可省略重要事项说明书。宅地买卖（不是建物贷借）须正常说明法令上的制限，与t112的框架呼应。","ja":"信託受益権の売却で目論見書に法定説明事項がすべて記載されていれば重要事項説明書を省略できる。宅地の売買（建物の貸借ではない）は法令上の制限を通常どおり説明する必要があり、t112の枠組みと呼応する。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t121', '{"id":"t121","tag":"民法","title":{"zh":"履行迟滞起算点四情形对照","ja":"履行遅滞の起算点——4類型の対照"},"source":"令和6年 問5","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"债务类型","ja":"債務類型"},{"zh":"迟滞起算点","ja":"遅滞の起算点"}],"rows":[[{"zh":"不法行为损害赔偿","ja":"不法行為に基づく損害賠償"},{"zh":"不法行为发生时","ja":"不法行為時"}],[{"zh":"善意受益者不当得利返还","ja":"善意受益者の不当利得返還"},{"zh":"收到履行请求时","ja":"履行の請求を受けた時"}],[{"zh":"相殺后报酬残债务","ja":"相殺後の報酬残債務"},{"zh":"相殺意思表示翌日","ja":"相殺の意思表示をした日の翌日"}],[{"zh":"不确定期限债务","ja":"不確定期限のある債務"},{"zh":"期限到来后被请求或知道期限到来，两者较早者","ja":"期限到来後の請求又は期限到来を知った時のいずれか早い方"}]]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t122', '{"id":"t122","tag":"民法","title":{"zh":"混同的例外规则——第三者权利标的不消滅","ja":"混同の例外——第三者の権利の目的である場合は消滅しない"},"source":"令和6年 問6","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"同一物上所有权和其他物权归于同一人时原则消滅（民法179条1项），但该物权是第三者权利标的时不消滅——取得所有权的方式（买卖/相续/代物弁済/赠与）不影响这个结论。","ja":"同一物について所有権と他の物権が同一人に帰属すれば原則消滅する（民法179条1項）が、その物権が第三者の権利の目的であるときは消滅しない——所有権取得の方法（売買・相続・代物弁済・贈与）は結論に影響しない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t123', '{"id":"t123","tag":"民法","title":{"zh":"隔地者间契约成立——2020年改正废除发信主义","ja":"隔地者間の契約成立——2020年改正で発信主義廃止"},"source":"令和6年 問8","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"隔地者间契约成立时点，现行民法采到达主义（承诺到达相对方时成立），旧法的发信主义特例已被2020年改正废除。","ja":"隔地者間の契約成立時点は現行民法では到達主義（承諾が相手方に到達した時に成立）——旧法の発信主義の特例は2020年改正で廃止された。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t124', '{"id":"t124","tag":"区分所有法","title":{"zh":"共用部分持分的默认基准——床面积比例不是人数","ja":"共用部分の持分の原則——床面積割合であり人数ではない"},"source":"令和6年 問13","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"共用部分的持分份额，原则依据各区分所有者所有的专有部分床面积比例来定，规约可以另行约定，不是按人数均分（区分所有法14条1项）。","ja":"共用部分の持分は原則として各区分所有者の専有部分の床面積の割合による——規約で別段の定め可、人数での均等割りではない（区分所有法14条1項）。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t125', '{"id":"t125","tag":"建筑基準法","title":{"zh":"电影院面积门槛・特定用途诱导地区高度例外・天空率方向・建蔽率8/10组合","ja":"映画館の面積基準・特定用途誘導地区の高さ例外・天空率の方向・建蔽率8/10の組合せ"},"source":"令和6年 問18","sections":[{"heading":"核心规则速查","blocks":[{"type":"table","headers":[{"zh":"考点","ja":"ポイント"},{"zh":"规则","ja":"ルール"}],"rows":[[{"zh":"电影院/剧场面积门槛","ja":"映画館・劇場の面積基準"},{"zh":"200㎡以上只能建在商业/近隣商业/准工业地域","ja":"200㎡以上は商業・近隣商業・準工業地域のみ"}],[{"zh":"特定用途诱导地区高度限制","ja":"特定用途誘導地区の高さ制限"},{"zh":"特定行政厅认定不得已理由可许可超过","ja":"特定行政庁がやむを得ないと認めれば超過を許可可能"}],[{"zh":"天空率适用除外方向","ja":"天空率の適用除外の方向"},{"zh":"计画建筑物天空率≥制限建筑物天空率","ja":"計画建築物の天空率が制限適合建築物の天空率「以上」"}],[{"zh":"建蔽率8/10地域内+防火+耐火","ja":"建蔽率8/10地域内＋防火＋耐火"},{"zh":"建蔽率规定不适用，不需许可","ja":"建蔽率規定自体が不適用——許可不要"}]]}]},{"heading":"关联对照","blocks":[{"type":"trap","content":{"zh":"本题④（8/10地域内不受限制）与h26-18④（8/10地域外+1/10加算）是完全不同的情形，两题对照复习能搞清建蔽率完整规则。","ja":"本問④（8/10地域内は制限なし）とh26-18④（8/10地域外で1/10加算）は異なる場面——両問を対照すると建蔽率の全体像が理解できる。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t126', '{"id":"t126","tag":"土地区画整理法","title":{"zh":"换地处分后的申报与公告主体区分","ja":"換地処分後の届出主体と公告主体の区別"},"source":"令和6年 問20","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"不管是国土交通大臣、都道府県还是市町村（含个人、组合等）施行，换地处分后都要向都道府県知事申报，公告由都道府県知事进行，不是施行者自己公告。","ja":"国土交通大臣・都道府県・市町村（個人・組合等含む）いずれの施行でも、換地処分後は都道府県知事に届け出る——公告は都道府県知事が行い、施行者自身が公告するのではない。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t127', '{"id":"t127","tag":"国土利用计画法","title":{"zh":"事后申报 vs 监视区域事前申报","ja":"事後届出と監視区域の事前届出"},"source":"令和6年 問22","sections":[{"heading":"核心规则对照","blocks":[{"type":"table","headers":[{"zh":"制度","ja":"制度"},{"zh":"申报时点","ja":"届出時期"},{"zh":"面积门槛","ja":"面積基準"}],"rows":[[{"zh":"一般事后申报","ja":"通常の事後届出"},{"zh":"契约缔结后2周内","ja":"契約締結後2週間以内"},{"zh":"市街化区域2,000㎡等一般基准","ja":"市街化区域2,000㎡等の通常基準"}],[{"zh":"监视区域事前申报","ja":"監視区域の事前届出"},{"zh":"契约缔结前至少6周","ja":"契約締結の少なくとも6週間前"},{"zh":"比一般基准更严格，知事规则另定","ja":"通常基準より厳格——知事規則で別途定める"}]]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t128', '{"id":"t128","tag":"宅建业法","title":{"zh":"免税事业者报酬换算系数1.04","ja":"免税事業者の報酬換算係数1.04"},"source":"令和6年 問28","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"课税事业者报酬计算乘以1.1，免税事业者乘以1.04——这是容易被忽略的税务身份差异，权利金授受型取权利金转代金算法和借賃基准算法中较高者作为上限。","ja":"課税事業者の報酬計算は1.1倍、免税事業者は1.04倍——見落とされやすい税務上の身分差異。権利金授受型は権利金換算と借賃基準のいずれか高い方を上限とする。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t129', '{"id":"t129","tag":"宅建业法","title":{"zh":"监督处分升级链条——指示・停业・取消的公开与义务程度","ja":"監督処分の段階——指示・業務停止・取消の公開と義務の程度"},"source":"令和6年 問31","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"处分","ja":"処分"},{"zh":"性质","ja":"性質"},{"zh":"公告","ja":"公告"}],"rows":[[{"zh":"指示处分","ja":"指示処分"},{"zh":"—","ja":"—"},{"zh":"不需要公告","ja":"公告不要"}],[{"zh":"业务停止处分","ja":"業務停止処分"},{"zh":"不遵从指示时任意命令","ja":"指示不服従時に任意で命令可"},{"zh":"须公告","ja":"公告必要"}],[{"zh":"免许取消处分","ja":"免許取消処分"},{"zh":"违反业务停止时必须取消","ja":"業務停止違反時は必ず取消"},{"zh":"须公告，且须聴聞（原则公开）","ja":"公告必要、聴聞も必要（原則公開）"}]]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t130', '{"id":"t130","tag":"宅建业法","title":{"zh":"37条书面电磁化提供的规则","ja":"37条書面の電磁的方法による提供のルール"},"source":"令和6年 問35","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"电磁化提供不需要宅建士说明（37条书面本身不要求说明）","ja":"電磁的提供に宅建士の説明は不要（37条書面はそもそも説明不要）"},{"zh":"电磁化方法须明示记名宅建士","ja":"電磁的方法は記名宅建士が明示されるものでなければならない"},{"zh":"承诺可以事后被撤回","ja":"承諾は事後に撤回可能"},{"zh":"电磁化提供后不需要再交付纸质书面","ja":"電磁的提供後は改めて紙の書面を交付する必要はない"}]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t131', '{"id":"t131","tag":"宅建业法","title":{"zh":"营业保证金取回须公告的例外情形","ja":"営業保証金取戻しの公告不要となる例外場面"},"source":"令和6年 問36","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"营业保证金取回原则须公告，例外不需要公告的只有三种：主事务所移转二重供托后取回旧供托所部分、事由发生后经过10年、加入保证协会——一部事务所废止不在此列，依然须公告。","ja":"営業保証金の取戻しは原則公告が必要——例外は3つのみ：主たる事務所移転による二重供託後の旧供託所分の取戻し、事由発生から10年経過、保証協会加入——一部事務所の廃止はこれに該当せず公告が必要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t132', '{"id":"t132","tag":"宅建业法","title":{"zh":"免许效力及于全国、免许可附条件（对照宅建士证不可）","ja":"免許の効力は全国に及ぶ、免許には条件を付せる（宅建士証とは対照）"},"source":"令和6年 問38","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"都道府県知事免许的效力及于全国，不受业务发生地影响；免许更新时可以附条件（跟h12-32讨论的宅建士证没有附条件规定形成对照）。","ja":"都道府県知事免許の効力は全国に及び、業務発生地には左右されない。免許更新時には条件を付すことができる（h12-32で扱った宅建士証には条件を付せないという点と対照）。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t133', '{"id":"t133","tag":"宅建业法","title":{"zh":"宅建士证的隐私保护与旧姓并记新规则","ja":"宅建士証のプライバシー保護と旧姓併記の新ルール"},"source":"令和6年 問43","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"出示证件时可贴贴纸遮挡住所栏（隐私保护）","ja":"証の提示時に住所欄にシールを貼って隠すことができる（プライバシー保護）"},{"zh":"可以在证上并记旧姓","ja":"旧姓を併記することができる"},{"zh":"登録本身跟是否持有证书独立——没证也要办理住所变更登録","ja":"登録自体は証の保有と独立——証がなくても住所変更登録は必要"}]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t134', '{"id":"t134","tag":"民法","title":{"zh":"解除后 vs 撤销后第三人保护规则的差异","ja":"解除後と取消し後の第三者保護ルールの違い"},"source":"令和7年 問1","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"契约解除后第三人保护，不问解除时点前后，只看是否具备登记（对抗要件）；契约被撤销（如强迫）后第三人保护，是二重讓渡对抗关系，看谁先登记，跟撤销事由本身及第三人是否善意无过失无关（这跟诈欺撤销不同）。","ja":"契約解除後の第三者保護は、解除の前後を問わず登記（対抗要件）の有無で判断する。契約が取消し（強迫等）された後の第三者保護は二重譲渡の対抗関係であり、先に登記を備えた者が優先——取消事由自体や第三者の善意無過失とは無関係（詐欺取消しとは異なる）。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t135', '{"id":"t135","tag":"民法","title":{"zh":"他人物买卖后取得所有权的时点、虚偽登记转卖、时効取得对继承人、立木独立交易","ja":"他人物売買後の所有権取得時点・虚偽登記の転売・時効取得と相続人・立木の独立取引"},"source":"令和7年 問6","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"他人物买卖后卖方取得所有权，买方取得的时点是卖方取得之时，不溯及最初买卖契约时点","ja":"他人物売買後に売主が所有権を取得した場合、買主の取得時点は売主取得時であり、当初の売買契約時に遡らない"},{"zh":"虚偽登记名义人转卖不能让受让人取得真实权利，真正权利人的后续讓渡对象可以对抗","ja":"虚偽登記名義人の転売は真の権利を取得させず、真の権利者の後続の譲渡先が対抗できる"},{"zh":"时効取得对原所有者及其单纯继承人无须登记（继承人视为同一人）","ja":"時効取得は元の所有者及びその単純な相続人には登記不要で対抗できる（相続人は同一人物とみなす）"},{"zh":"立木须靠登记或明认方法才能独立于土地交易","ja":"立木は登記又は明認方法を備えて初めて土地と独立して取引対象となる"}]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t136', '{"id":"t136","tag":"民法","title":{"zh":"契约不适合责任——卖方明知隐瞒时特约一律失效，不问身份","ja":"契約不適合責任——売主が知って隠していた場合は特約が一律失効、身分を問わない"},"source":"令和7年 問10","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"卖方明知却隐瞒不告知不适合的情形，1年内通知等限制特约根据民法566条但书对任何卖方一律不适用，不受是否宅建业者身份影响；而完全免责特约则受身份影响（非业者有效、业者无效）。","ja":"売主が不適合を知りながら告げなかった場合、1年以内通知等の制限特約は民法566条ただし書きにより業者か否かを問わず一律に適用されない。一方、一切責任を負わない特約は身分の影響を受ける（非業者は有効、業者は無効）。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t137', '{"id":"t137","tag":"区分所有法","title":{"zh":"议事录书面签名人数——议长+2人不是全员","ja":"議事録の署名人数——議長＋2人であり全員ではない"},"source":"令和7年 問13","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"议事录书面作成时，须签名的是议长及出席集会的区分所有者2人（代表性签名），不是全员出席者都要签。","ja":"議事録を書面で作成する場合、署名するのは議長及び出席した区分所有者2人（代表署名）であり、出席者全員の署名は不要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t138', '{"id":"t138","tag":"都市计画法","title":{"zh":"生产绿地地区 vs 田园住居地域定义互换","ja":"生産緑地地区と田園住居地域の定義のすり替え"},"source":"令和7年 問15","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"制度","ja":"制度"},{"zh":"定义","ja":"定義"}],"rows":[[{"zh":"田园住居地域（用途地域）","ja":"田園住居地域（用途地域）"},{"zh":"农业利便+低层住居环境协调保护","ja":"農業利便＋低層住居環境の調和保護"}],[{"zh":"生产绿地地区（地域地区）","ja":"生産緑地地区（地域地区）"},{"zh":"计划性保全市街化区域内农地，维护都市环境","ja":"市街化区域内農地の計画的保全、都市環境の維持"}]]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t139', '{"id":"t139","tag":"都市计画法","title":{"zh":"学校非公益建筑物清单、高尔夫球场不受面积限制、灾害危险区域限定","ja":"学校は公益建築物リスト外・ゴルフ場は面積無制限・災害危険区域の限定"},"source":"令和7年 問16","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"学校不在公益上必要建筑物清单内（跟h24-17图书馆/医院框架一致）","ja":"学校は公益上必要な建築物リストに含まれない（h24-17の図書館・病院と同じ枠組み）"},{"zh":"特定工作物（含高尔夫球场）建设不受面积限制，一律算开发行为","ja":"特定工作物（ゴルフ場含む）の建設は面積を問わず開発行為に該当"},{"zh":"非线引区域开发许可门槛3,000㎡","ja":"非線引き区域の開発許可基準は3,000㎡"},{"zh":"灾害危险区域内土地原则不能纳入开发区域，仅自己居住用住宅建设有豁免","ja":"災害危険区域内の土地は原則開発区域に含められない——自己居住用住宅建設のみ例外"}]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t140', '{"id":"t140","tag":"建筑基準法","title":{"zh":"2026年法改正——木造区别废除，统一按大规模建筑物标准判断确认要否","ja":"2026年法改正——木造区別廃止、大規模建築物基準で確認要否を統一判断"},"source":"令和7年 問17","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"2026年法改正后木造和非木造区别废除，统一按2层以上或延面积超200㎡判断，新建/增建/改建/移转/大规模修缮模样替只要符合这个标准都需要建筑确认。","ja":"2026年法改正により木造・非木造の区別が廃止され、2階建て以上又は延べ面積200㎡超で統一判断——新築・増築・改築・移転・大規模修繕/模様替のいずれもこの基準を満たせば建築確認が必要。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t141', '{"id":"t141","tag":"盛土规制法","title":{"zh":"常时安全维持义务主体 vs 劝告对象范围","ja":"常時安全維持義務の主体と勧告対象の範囲"},"source":"令和7年 問19","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"义务/权限","ja":"義務・権限"},{"zh":"主体范围","ja":"対象範囲"}],"rows":[[{"zh":"常时安全维持努力义务","ja":"常時安全維持の努力義務"},{"zh":"所有者・管理者・占有者","ja":"所有者・管理者・占有者"}],[{"zh":"知事的劝告对象","ja":"知事の勧告対象"},{"zh":"所有者・管理者・占有者・工事主・工事施行者（更广）","ja":"所有者・管理者・占有者・工事主・工事施行者（より広い）"}]]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t142', '{"id":"t142","tag":"登録免许税","title":{"zh":"土地买卖税率减轻——无面积/价格/法人身份限定","ja":"土地売買の税率軽減——面積・価格・法人身分の限定なし"},"source":"令和7年 問23","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"土地买卖所有权移转登记税率减轻措施本身没有面积、价格、法人/个人身份的任何限定条件，跟地目也无关——这跟住宅家屋税率减轻（有面积要件）是不同的制度，不要混淆。","ja":"土地売買の所有権移転登記税率軽減措置自体には面積・価格・法人個人の身分の限定条件がなく、地目も問わない——住宅家屋の税率軽減（面積要件あり）とは異なる制度であり混同しないこと。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t143', '{"id":"t143","tag":"不动产鉴定评价基准","title":{"zh":"一般的要因 vs 个别的要因定义互换（与最有効使用/適合原则同类型）","ja":"一般的要因と個別的要因の定義のすり替え（最有効使用・適合の原則と同類型）"},"source":"令和7年 問25","sections":[{"heading":"核心规则","blocks":[{"type":"table","headers":[{"zh":"要因","ja":"要因"},{"zh":"定义","ja":"定義"}],"rows":[[{"zh":"一般的要因","ja":"一般的要因"},{"zh":"宏观社会经济层面，影响不动产整体存在方式和价格水平（自然/社会/经济/行政四分类）","ja":"マクロな社会経済レベル——不動産全体のあり方と価格水準に影響（自然的・社会的・経済的・行政的の4分類）"}],[{"zh":"个别的要因","ja":"個別的要因"},{"zh":"微观，针对具体标的物，产生个别性从而个别形成价格","ja":"ミクロ——対象不動産固有の特性から個別性を生じさせ価格を個別的に形成"}]]}]},{"heading":"关联","blocks":[{"type":"trap","content":{"zh":"跟r06-25（最有効使用の原則 vs 適合の原則）是同一类型的定义互换陷阱，不动产鉴定评价基准里成对出现的术语经常被故意互换。","ja":"r06-25（最有効使用の原則と適合の原則）と同一類型の定義すり替えの罠——不動産鑑定評価基準の対になる用語は意図的に入れ替えられやすい。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t144', '{"id":"t144","tag":"宅建业法","title":{"zh":"8种制限的适用前提——买方非业者；卖买建筑确认前广告契约都禁止","ja":"8種規制の適用前提——買主が非業者であること；売買は建築確認前は広告も契約も禁止"},"source":"令和7年 問28","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"8种制限（含手付金保全措施）只适用于买方非业者，业者相互间交易不适用","ja":"8種規制（手付金保全措置含む）は買主が非業者の場合にのみ適用——業者間取引は不適用"},{"zh":"卖买在建筑确认前，广告和契约都被禁止（贷借则可以在确认前缔结契约）","ja":"売買は建築確認前は広告も契約も禁止（貸借は確認前でも契約締結可）"},{"zh":"取引态样不明示只受监督处分不受罚则，夸大广告受罚则+监督处分双重制裁","ja":"取引態様不明示は監督処分のみ、誇大広告は罰則＋監督処分の両方"},{"zh":"专属专任媒介契约登録期限5日，专任媒介契约是7日","ja":"専属専任媒介契約の登録期限は5日、専任媒介契約は7日"}]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t145', '{"id":"t145","tag":"宅建业法","title":{"zh":"业务规制四大基础红线","ja":"業務規制の4つの基本レッドライン"},"source":"令和7年 問31","sections":[{"heading":"核心规则","blocks":[{"type":"list","style":"unordered","items":[{"zh":"电话劝诱须告知业者名称+勧诱者姓名+勧诱目的三项，缺一不可","ja":"電話勧誘は業者名称＋勧誘者氏名＋勧誘目的の3つを告知——一つでも欠けば違反"},{"zh":"威迫行为绝对禁止，不因最终结果改变违法性","ja":"威迫行為は絶対的禁止——結果にかかわらず違法"},{"zh":"从业者证明书携带义务对临时/兼职人员同样适用","ja":"従業者証明書の携帯義務は臨時・アルバイトにも適用"},{"zh":"断定性判断提供一律禁止，不问内容真假","ja":"断定的判断の提供は内容の真偽を問わず一律禁止"}]}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('t146', '{"id":"t146","tag":"宅建业法","title":{"zh":"35条/37条书面职责边界再强化（令和7年真题重点方向）","ja":"35条・37条書面の役割分担の再強化（令和7年本試験の重点方向）"},"source":"令和7年 問33","sections":[{"heading":"核心规则","blocks":[{"type":"text","content":{"zh":"引渡时期35条不要求说明但37条须记载；契约解除事项和抵当权内容各有分工，不能一概而论；37条书面本身不要求宅建士说明，只要求记名——这是贯穿令和7年真题多题（問29、33、35）的重点考点。","ja":"引渡し時期は35条書面では説明不要だが37条書面には記載必要；契約解除事項と抵当権内容はそれぞれ異なる扱いがあり一概には言えない；37条書面自体は宅建士の説明を要さず記名のみ——これは令和7年本試験の複数問（問29・33・35）にわたる重点論点。"}}]}]}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('trap-rights-numbers', '{"id":"trap-rights-numbers","tag":"权利关系・数字陷阱汇总","title":{"zh":"权利关系常见数字陷阱汇总"},"source":"个人复习笔记 · 数字陷阱整理","sections":[{"heading":"易混淆数字对照","blocks":[{"type":"table","headers":[{"zh":"考点"},{"zh":"正确数字"},{"zh":"容易混淆的数字"}],"rows":[[{"zh":"人身伤害不法行为消灭时效（主观）"},{"zh":"5年"},{"zh":"一般不法行为是3年，别混用"}],[{"zh":"代袭相续——直系卑属"},{"zh":"无限再代袭"},{"zh":"子→孙→曾孙都可以"}],[{"zh":"代袭相续——兄弟姐妹"},{"zh":"只代袭一代（到甥侄为止）"},{"zh":"甥侄的子女不能再代袭"}],[{"zh":"借地借家法法定更新通知期限"},{"zh":"1年前～6个月前"},{"zh":"别记成“3个月前”"}],[{"zh":"抵当权/留置权——避雷设备高度"},{"zh":"超过20米"},{"zh":"非常用进入口/升降机是超过31米，两个数字常被混用"}],[{"zh":"采光有效面积"},{"zh":"床面积的7分之1"},{"zh":"有照明设备可放宽到10分之1"}]]}]}],"examSprint":true}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('trap-restriction-numbers', '{"id":"trap-restriction-numbers","tag":"法令上的限制・数字陷阱汇总","title":{"zh":"法令上的限制常见数字陷阱汇总"},"source":"个人复习笔记 · 数字陷阱整理","sections":[{"heading":"跨法条数字门槛对照","blocks":[{"type":"table","headers":[{"zh":"考点"},{"zh":"正确数字"}],"rows":[[{"zh":"国土法一般事后申报期限"},{"zh":"契约缔结之日起2周内"}],[{"zh":"国土法监视区域事前申报期限"},{"zh":"契约缔结至少6周前"}],[{"zh":"国土法事后申报面积门槛"},{"zh":"市街化区域2,000㎡、非线引/市街化调整区域5,000㎡、区域外10,000㎡"}],[{"zh":"土地区划整理法——既有工程申报期限"},{"zh":"区域指定日起21日内"}],[{"zh":"都市计画法开发许可门槛"},{"zh":"市街化区域1,000㎡、准都市计画区域3,000㎡、区域外10,000㎡、三大都市圈既成市街地500㎡（更严格）"}],[{"zh":"建蔽率超过8/10+防火地域+耐火建筑物"},{"zh":"建蔽率不受限制（不需要许可）"}],[{"zh":"盛土规制法——切土/盛土面积门槛"},{"zh":"超过500㎡（切土超过2米也算）"}],[{"zh":"农地法罚则——个人 vs 法人"},{"zh":"个人3年以下拘禁刑/300万円以下，法人（两罚）1亿円以下"}]]}]}],"examSprint":true}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('trap-license-numbers', '{"id":"trap-license-numbers","tag":"宅地建物取引业法等・数字陷阱汇总","title":{"zh":"宅建业法等常见数字陷阱汇总"},"source":"个人复习笔记 · 数字陷阱整理","sections":[{"heading":"易混淆数字对照","blocks":[{"type":"table","headers":[{"zh":"考点"},{"zh":"关键数字"}],"rows":[[{"zh":"手付金保全措施门槛"},{"zh":"已完成物件代金10%（且1000万以下）；未完成物件代金5%（且1000万以下）"}],[{"zh":"报酬计算公式"},{"zh":"（代金×3%+6万）×税率系数"}],[{"zh":"报酬消费税系数"},{"zh":"课税事业者×1.1、免税事业者×1.04"}],[{"zh":"低廉空家等报酬特例"},{"zh":"代金800万円以下，报酬上限33万円（税込）"}],[{"zh":"住宅瑕疵担保履行法——合计户数换算"},{"zh":"床面积55㎡以下才2户算1户"}],[{"zh":"住宅瑕疵担保保险有效期"},{"zh":"引渡后10年"}],[{"zh":"住宅瑕疵担保未申报宽限期"},{"zh":"基准日翌日起50日"}],[{"zh":"免许证返还/废业等届出期限"},{"zh":"一律30日（别跟登録移转、申报等其他期限混）"}],[{"zh":"クーリング・オフ期限"},{"zh":"告知后8日"}]]}]}],"examSprint":true}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('trap-wording-logic', '{"id":"trap-wording-logic","tag":"宅建复习・文字与逻辑陷阱","title":{"zh":"常见文字/逻辑陷阱汇总"},"source":"个人复习笔记 · 文字与逻辑陷阱整理","sections":[{"heading":"“方向搞反”类陷阱","blocks":[{"type":"table","headers":[{"zh":"陷阱"},{"zh":"正确逻辑"}],"rows":[[{"zh":"不法行为损害赔偿债权能否做自働/受働债权"},{"zh":"能做自働债权，不能做受働债权（方向别搞反）"}],[{"zh":"保证关系的传导方向"},{"zh":"主债务人事由→传导给保证人（附从性）；保证人事由→不传导给主债务人（保证人无负担部分）"}],[{"zh":"「免许」vs「宅建士证」能否附条件"},{"zh":"免许可以附条件（3条の2）；宅建士证没有附条件规定"}],[{"zh":"占有回收之诉——被骗自愿交出占有"},{"zh":"不算“被夺走”，不能提起占有回收之诉"}],[{"zh":"留置权 vs 抵当权对“敷地”的效力"},{"zh":"留置权不延伸到第三者所有的敷地；抵当权延伸到借地赁借权"}]]}]},{"heading":"“范围/主体搞混”类陷阱","blocks":[{"type":"table","headers":[{"zh":"陷阱"},{"zh":"正确规则"}],"rows":[[{"zh":"共有物“保存行为”vs“损害赔偿请求”"},{"zh":"明渡请求=保存行为（可单独）；损害赔偿=非保存行为（按持分比例）"}],[{"zh":"连带债务绝对効范围"},{"zh":"只有相殺・更改・混同三个是绝对効，其余（含履行请求）现行法下都是相対効"}],[{"zh":"过半主义 vs 加重平均主义"},{"zh":"用途制限=过半主义（看基地过半所属地域）；建蔽率/容积率=加重平均主义（按面积比例）"}],[{"zh":"施行区域 vs 施行地区"},{"zh":"公的施行限定在施行区域内；民间施行（个人/组合/区划整理会社）没有这个地域限定"}],[{"zh":"土地区划整理——申报 vs 公告主体"},{"zh":"施行者向知事申报，知事负责公告（不是施行者自己公告）"}],[{"zh":"仮换地指定 vs 换地处分公告"},{"zh":"限制其他登记的触发点是换地处分公告后，不是仮换地指定后（仮换地指定后从前宅地依然可以正常登记）"}],[{"zh":"建物の贷借 vs 宅地の贷借——法令上的限制说明义务"},{"zh":"免说明特权只属于“建物贷借”，宅地贷借依然要正常说明"}],[{"zh":"35条书面 vs 37条书面记载事项"},{"zh":"手付金保全措施只在35条书面要求说明，37条书面不涉及"}],[{"zh":"单独申请の例外"},{"zh":"仮登记本身（义务者承诺后权利者可单独）≠仮登记的本登记（须获利害关系第三者承诺）"}]]}]},{"heading":"“效力被夸大/缩小”类陷阱","blocks":[{"type":"table","headers":[{"zh":"陷阱"},{"zh":"正确规则"}],"rows":[[{"zh":"公序良俗违反的法律行为"},{"zh":"绝对无效，不能靠合意/追认补正"}],[{"zh":"他人物买卖契约"},{"zh":"本身有效，不是无效后靠追认才生效"}],[{"zh":"意思表示瑕疵——错误（改正后）"},{"zh":"是可撤销，不是无效"}],[{"zh":"农地赁贷借对抗要件"},{"zh":"凭引渡即可对抗第三人，使用贷借没有这个特例"}],[{"zh":"建物买取请求权适用范围"},{"zh":"只在期间满了终了时适用，债务不履行解除时不适用"}],[{"zh":"契约不适合担保责任1年通知期限"},{"zh":"卖方明知却隐瞒时不适用这个限制"}]]}]}],"examSprint":true}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('trap-repeat-mistakes', '{"id":"trap-repeat-mistakes","tag":"宅建复习・反复出错清单","title":{"zh":"反复出错知识点清单"},"source":"个人错题追踪 · 重复提交题号统计","sections":[{"heading":"重复提交题号（说明反复卡壳）","blocks":[{"type":"table","headers":[{"zh":"题号"},{"zh":"考点"},{"zh":"重复次数"},{"zh":"核心结论"}],"rows":[[{"zh":"令和3年10月問15"},{"zh":"地区计画三层结构"},{"zh":"3次"},{"zh":"目标/面积=努力义务；区域区分是都市计画区域整体层面的事，地区整备计画只能管建蔽率/容积率/高度等具体建筑规制"}],[{"zh":"令和6年問1（r06-1）"},{"zh":"心裡留保/公序良俗/诈欺胁迫/他人物买卖"},{"zh":"2次"},{"zh":"诈欺和胁迫规则完全一致（都可撤销）；他人物买卖契约本身有效"}],[{"zh":"令和7年問7（r07-7）"},{"zh":"承揽人费用求偿"},{"zh":"2次"},{"zh":"承揽人和房东没有直接契约关系，援引事务管理行不通；必要费可立即请求偿还"}],[{"zh":"令和6年問25（r06-25）"},{"zh":"最有効使用 vs 適合の原則"},{"zh":"2次"},{"zh":"效用最高度发挥＝最有効使用；适合环境才能发挥收益性/舒适性＝適合の原則"}],[{"zh":"平成27年問5（h27-5）"},{"zh":"占有回收之诉"},{"zh":"2次"},{"zh":"被骗后自愿交出占有≠被夺走；占有代理人也有占有保持之诉"}]]},{"type":"mnemonic","content":{"zh":"共同规律：这五题都属于“规则本身不难，但表述细节容易被张冠李戴/方向搞反”的类型——不是不会，是记忆的锚点不够精确。"}},{"type":"trap","content":{"zh":"使用建议：考前最后阶段按这份清单做“错题重做”式自测——盖住“核心结论”那一列，只看考点名称，自己先说出规则，再对照检查，这比重新刷新题更能暴露记忆盲点。优先过一遍这 5 道重复错题，这是目前最明确的个人薄弱信号。"}}]}],"examSprint":true}') ON DUPLICATE KEY UPDATE id = id;
INSERT INTO `takken_topics` (id, data) VALUES ('trap-linked-network', '{"id":"trap-linked-network","tag":"宅建复习・高频关联考点","title":{"zh":"高频合并知识点网络"},"source":"个人复习笔记 · 相互关联考点整理","sections":[{"heading":"相互关联的考点组","blocks":[{"type":"list","style":"unordered","items":[{"zh":"①土地区划整理法三兄弟（h12-21、h24-21、r06-20 + r07-20、r01-20）：施行区域限定只针对公的施行；仮换地指定≠换地处分公告（登记限制触发点）；申报向知事、公告归知事做"},{"zh":"②农地法两罚金额陷阱（h22-22、r07-21）：个人300万円以下 vs 法人1亿円以下，容易被互换"},{"zh":"③意思表示瑕疵四类型（r07-3 + r06-1）：心裡留保（原则有效）/虚偽表示（无效，善意第三人可对抗）/错误（可撤销）/诈欺（可撤销）"},{"zh":"④免许/宅建士登録与证书的独立性（h12-32、r06-38、r06-43）：登録≠证书；免许可附条件≠证书不可附条件"},{"zh":"⑤保证与连带债务的单方向vs対等（h20-6、h25-6、h25-7、h29-8）：保证关系单向传导；连带债务人间対等独立"},{"zh":"⑥住宅瑕疵担保履行法三细节（h28-45、r02s-45）：55㎡换算门槛、转卖不解约、担保范围仅构造耐力+防水"},{"zh":"⑦建蔽率完整规则（h26-18④、r06-18④）：8/10地域外+防火+耐火→加算1/10；8/10地域内+防火+耐火→不受限制"}]}]}],"examSprint":true}') ON DUPLICATE KEY UPDATE id = id;
